// Second bounded research probe: find a Lavazza Crema e Gusto ground listing and
// published shipping policy on the candidate sources. One GET per URL, 8 s timeout.
import { writeFile } from 'node:fs/promises';

const CAP = 600 * 1024;
async function get(url) {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), 9000);
  try {
    const res = await fetch(url, {
      redirect: 'follow',
      signal: controller.signal,
      headers: {
        'user-agent': 'attention-shoppers-happy-hunting/0.1 (local research probe)',
        accept: 'text/html,application/xhtml+xml,application/json,text/plain;q=0.9,*/*;q=0.5'
      }
    });
    const reader = res.body?.getReader();
    const chunks = [];
    let size = 0;
    if (reader) {
      for (;;) {
        const { done, value } = await reader.read();
        if (done) break;
        chunks.push(value);
        size += value.length;
        if (size > CAP) { await reader.cancel(); break; }
      }
    }
    const text = Buffer.concat(chunks.map(c => Buffer.from(c))).toString('utf8');
    return { status: res.status, finalUrl: res.url, contentType: res.headers.get('content-type'), bytes: size, text };
  } catch (error) {
    return { status: 0, error: error?.name === 'AbortError' ? 'timeout' : (error?.message ?? String(error)), text: '' };
  } finally {
    clearTimeout(timer);
  }
}

const out = [];
async function probe(label, url, inspect) {
  const res = await get(url);
  const info = { label, url, status: res.status, finalUrl: res.finalUrl ?? null, bytes: res.bytes ?? 0, error: res.error ?? null, ...(inspect ? inspect(res.text ?? '') : {}) };
  out.push(info);
  console.log(JSON.stringify(info).slice(0, 700));
  return res;
}

// 1. Freshmarket robots + sitemap discovery.
const fmRobots = await get('https://www.freshmarket.co.il/robots.txt');
const fmSitemaps = [...fmRobots.text.matchAll(/Sitemap:\s*(\S+)/gi)].map(m => m[1]);
out.push({ label: 'freshmarket robots full', url: 'https://www.freshmarket.co.il/robots.txt', status: fmRobots.status, sitemaps: fmSitemaps, text: fmRobots.text.slice(0, 1200) });
console.log('freshmarket sitemaps:', fmSitemaps.join(' | '));

// 2. Shopify public products feed for espres.so, searching for Lavazza.
const espres = await get('https://us.espres.so/products.json?limit=250');
try {
  const products = JSON.parse(espres.text).products ?? [];
  const lavazza = products.filter(p => /lavazza/i.test(p.title)).map(p => ({ title: p.title, handle: p.handle, variants: p.variants.map(v => ({ title: v.title, price: v.price, available: v.available })) }));
  out.push({ label: 'espres products.json', url: 'https://us.espres.so/products.json?limit=250', status: espres.status, total: products.length, lavazza });
  console.log('espres lavazza:', JSON.stringify(lavazza).slice(0, 1500));
} catch {
  out.push({ label: 'espres products.json', status: espres.status, parseError: true, snippet: espres.text.slice(0, 300) });
}

// 3. Roastmarket product search via its public sitemap.
const rmRobots = await get('https://www.roastmarket.com/robots.txt');
const rmSitemaps = [...rmRobots.text.matchAll(/Sitemap:\s*(\S+)/gi)].map(m => m[1]);
console.log('roastmarket sitemaps:', rmSitemaps.join(' | '));
out.push({ label: 'roastmarket robots', status: rmRobots.status, sitemaps: rmSitemaps });
for (const sm of rmSitemaps.filter(u => /product/i.test(u)).slice(0, 2)) {
  const res = await get(sm);
  const lavazza = [...(res.text ?? '').matchAll(/<loc>([^<]*lavazza[^<]*)<\/loc>/gi)].map(m => m[1]).slice(0, 15);
  out.push({ label: `roastmarket sitemap ${sm}`, status: res.status, bytes: res.bytes ?? 0, lavazza });
  console.log('roastmarket lavazza urls:', lavazza.length, lavazza.slice(0, 5).join(' | '));
}

// 4. Coffeedesk search page (Magento).
const cd = await probe('coffeedesk search', 'https://www.coffeedesk.com/catalogsearch/result/?q=lavazza', text => ({
  hasLavazza: /lavazza/i.test(text), hasCremaGusto: /crema\s*e\s*gusto/i.test(text), snippet: text.slice(0, 200).replace(/\s+/g, ' ')
}));

await writeFile('/tmp/probe2.json', JSON.stringify(out, null, 2));
console.log('WROTE /tmp/probe2.json');

// Third bounded probe: product page + shipping policy evidence.
import { writeFile } from 'node:fs/promises';

const CAP = 2_500_000;
async function get(url, accept = 'text/html,application/xhtml+xml,application/xml,application/json,text/plain;q=0.9,*/*;q=0.5') {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), 9000);
  try {
    const res = await fetch(url, {
      redirect: 'follow',
      signal: controller.signal,
      headers: { 'user-agent': 'attention-shoppers-happy-hunting/0.1 (local research probe)', accept }
    });
    const reader = res.body?.getReader();
    const chunks = [];
    let size = 0;
    if (reader) {
      for (;;) {
        const { done, value } = await reader.read();
        if (done) break;
        chunks.push(value);
        size += value.length;
        if (size > CAP) { await reader.cancel(); break; }
      }
    }
    const text = Buffer.concat(chunks.map(c => Buffer.from(c))).toString('utf8');
    return { status: res.status, finalUrl: res.url, contentType: res.headers.get('content-type'), bytes: size, text };
  } catch (error) {
    return { status: 0, error: error?.name === 'AbortError' ? 'timeout' : (error?.message ?? String(error)), text: '' };
  } finally {
    clearTimeout(timer);
  }
}

const out = [];

// 1. Freshmarket sitemap: look for Lavazza product URLs.
const fm = await get('https://www.freshmarket.co.il/sitemap.xml', 'application/xml,text/xml,*/*');
out.push({ label: 'freshmarket sitemap', url: fm.finalUrl, status: fm.status, bytes: fm.bytes, head: fm.text.slice(0, 500).replace(/\s+/g, ' '), error: fm.error });
const fmLavazza = [...fm.text.matchAll(/<loc>([^<]*[Ll]avazza[^<]*)<\/loc>/g)].map(m => m[1]).slice(0, 10);
const fmSitemapLocs = [...fm.text.matchAll(/<loc>([^<]+)<\/loc>/g)].map(m => m[1]).slice(0, 20);
out.push({ label: 'freshmarket lavazza urls', count: fmLavazza.length, urls: fmLavazza, childSitemaps: fmSitemapLocs.filter(u => /sitemap/i.test(u)).slice(0, 10) });
console.log('freshmarket lavazza:', fmLavazza.length, fmLavazza.slice(0, 5).join(' | '));
console.log('freshmarket child sitemaps:', fmSitemapLocs.filter(u => /sitemap/i.test(u)).slice(0, 5).join(' | '));

// 2. Roastmarket Qualità Oro 20x250g product page.
const rm = await get('https://www.roastmarket.com/en-us/p/lavazza-qualita-oro-ground-coffee-value-pack-20x250g-9582');
const ld = [...rm.text.matchAll(/<script[^>]*application\/ld\+json[^>]*>([\s\S]*?)<\/script>/gi)].map(m => m[1]).slice(0, 4);
out.push({
  label: 'roastmarket product', url: rm.finalUrl, status: rm.status, bytes: rm.bytes,
  title: (rm.text.match(/<title[^>]*>([\s\S]{0,200}?)<\/title>/i)?.[1] ?? '').trim(),
  ldSnippets: ld.map(s => s.replace(/\s+/g, ' ').slice(0, 700)),
  hasIsrael: /israel|ישראל/i.test(rm.text),
  priceHints: [...rm.text.matchAll(/["'](?:price|priceValue|amount)["']\s*:\s*["']?([\d.,]+)/gi)].map(m => m[1]).slice(0, 10)
});
console.log('roastmarket product status', rm.status, 'bytes', rm.bytes);
console.log('roastmarket ld:', (ld[0] ?? '').slice(0, 800).replace(/\s+/g, ' '));

// 3. Roastmarket shipping policy candidates.
for (const url of [
  'https://www.roastmarket.com/en-us/shipping',
  'https://www.roastmarket.com/en-us/help/shipping',
  'https://www.roastmarket.com/en-us/pages/shipping'
]) {
  const res = await get(url);
  const text = res.text.replace(/<script[\s\S]*?<\/script>/gi, ' ').replace(/<style[\s\S]*?<\/style>/gi, ' ');
  const money = [...text.matchAll(/(?:€|EUR)\s?\d+(?:[.,]\d{1,2})?/g)].map(m => m[0]).slice(0, 15);
  out.push({
    label: `roastmarket shipping probe ${url}`, status: res.status, finalUrl: res.finalUrl, bytes: res.bytes,
    hasIsrael: /israel|ישראל/i.test(text), money,
    snippet: text.replace(/\s+/g, ' ').slice(0, 500)
  });
  console.log(url, res.status, 'israel=', /israel/i.test(text), 'money=', money.join(','));
}
await writeFile('/tmp/probe3.json', JSON.stringify(out, null, 2));
console.log('WROTE /tmp/probe3.json');

