#!/usr/bin/env node
// Offline fixture server for the browser QA harness.
//
// Serves public/ exactly as Cloudflare assets do, plus the read-only JSON API
// computed with the production quote engine from recorded vendor fixtures.
// This keeps `npm run qa:browser` deterministic and network-free: the browser
// exercises the real front-end code without a Worker, credentials or vendors
// being reachable. The API response mirrors the Worker's shape closely enough
// for the board UI (see src/index.js handleBoard).
//
// Can also be run directly for manual inspection:
//   node scripts/qa-server.mjs [port]

import { createServer } from 'node:http';
import { readFile, stat } from 'node:fs/promises';
import { extname, join, resolve, sep } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { coffeeman } from '../src/vendors/coffeeman.js';
import { pucks } from '../src/vendors/pucks.js';
import { coffee4u } from '../src/vendors/coffee4u.js';
import { products, resolveVariantId } from '../src/catalog.js';
import { quoteBoard, findDestination, DESTINATIONS } from '../src/lib/quote.js';
import { createObservation, registeredVendors } from '../src/vendors/index.js';
import { refreshFreshness } from '../src/refresh.js';
import { publicProducts, publicVendors } from '../src/index.js';
import { readFixtureForUrl } from '../tests/fixtures/vendor-fixtures.mjs';

const ROOT = fileURLToPath(new URL('..', import.meta.url));
const PUBLIC_DIR = resolve(ROOT, 'public');
const PUBLIC_CACHE = 'public, max-age=300, stale-while-revalidate=3600';

const MIME = {
  '.html': 'text/html; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.mjs': 'text/javascript; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.svg': 'image/svg+xml',
  '.json': 'application/json; charset=utf-8',
  '.png': 'image/png',
  '.ico': 'image/x-icon'
};

/** Parse the recorded vendor pages with the production adapters (no network). */
export async function fixtureObservations(now = Date.now()) {
  const fixtureFetch = async url => {
    const hit = await readFixtureForUrl(url);
    if (!hit) return { ok: false, status: 404, error: 'no fixture for this URL' };
    const buffer = new Uint8Array(hit.bytes);
    return {
      ok: true,
      status: 200,
      url,
      buffer,
      contentType: hit.contentType,
      text: new TextDecoder('utf-8', { fatal: false }).decode(buffer)
    };
  };
  const observations = [];
  for (const vendor of [coffeeman, pucks, coffee4u]) {
    const outcome = await vendor.observe({ fetchText: fixtureFetch, now, logger: null });
    if (outcome.failures?.length) {
      throw new Error(`${vendor.id}: fixture parse failed: ${JSON.stringify(outcome.failures)}`);
    }
    observations.push(...outcome.observations);
  }
  return observations;
}

/**
 * QA-only synthetic offer. It exists to exercise how the UI renders shipping
 * terms (minimum order, free-shipping threshold, locality restriction) that the
 * two recorded vendors do not currently publish. It is never part of the
 * production board and is clearly labelled as a fixture in the UI and API.
 */
export function termsDemoObservation(now = Date.now()) {
  return createObservation({
    vendor: { id: 'qa-terms-demo', name: 'QA fixture offer (terms demo, not a vendor)', homepage: null },
    itemUrl: 'https://example.invalid/qa-terms-demo',
    product: {
      productId: products[0].id,
      name: 'QA fixture: Lavazza Crema e Gusto Classico 250 g vacuum ground',
      sku: 'QA-DEMO',
      variantId: 'classico',
      variantLabel: 'Classico',
      form: 'ground',
      packGrams: 250,
      packCount: 1,
      totalGrams: 250,
      category: 'QA fixture'
    },
    price: { amount: 20, currency: 'ILS' },
    availability: 'in_stock',
    availabilityEvidence: {
      url: 'https://example.invalid/qa-terms-demo',
      value: 'fixture',
      note: 'Synthetic QA-only record: not an observation of any real vendor.'
    },
    shipping: {
      mode: 'delivery',
      certainty: 'verified',
      amount: { amount: 15, currency: 'ILS' },
      destination: { scope: 'localities', localities: ['tel-aviv', 'eilat'] },
      minOrder: { amount: 30, currency: 'ILS' },
      freeThreshold: { amount: 100, currency: 'ILS' },
      note: 'QA-only demo offer for shipping-term rendering. Not a real vendor listing.'
    },
    now
  });
}

/**
 * Start a local HTTP server that behaves like the deployed read-only board.
 * Returns { url, port, observations, close }.
 */
export async function startQaServer({ port = 0, now = Date.now(), withTermsDemo = false, staleRefresh = false } = {}) {
  const observations = await fixtureObservations(now);
  if (withTermsDemo) observations.push(termsDemoObservation(now));
  // `staleRefresh` simulates a board whose scheduled refresh has stopped running: the
  // offers are still as fresh as the fixture timestamps say, but the refresh is old.
  const lastRefreshAt = new Date(staleRefresh ? now - 30 * 60 * 60 * 1000 : now).toISOString();
  const server = createServer((request, response) => {
    handle(request, response, { observations, now, withTermsDemo, lastRefreshAt, staleRefresh }).catch(error => {
      response.writeHead(500, { 'content-type': 'text/plain; charset=utf-8' });
      response.end(`qa server error: ${error?.message ?? error}`);
    });
  });
  await new Promise((resolvePromise, reject) => {
    server.once('error', reject);
    server.listen(port, '127.0.0.1', resolvePromise);
  });
  const { port: boundPort } = server.address();
  return {
    url: `http://127.0.0.1:${boundPort}`,
    port: boundPort,
    observations,
    close: () => new Promise(resolvePromise => server.close(() => resolvePromise()))
  };
}

async function handle(request, response, { observations, now, withTermsDemo, lastRefreshAt, staleRefresh }) {
  const url = new URL(request.url, 'http://127.0.0.1');
  if (url.pathname === '/api/catalog') {
    return json(response, {
      products: publicProducts(),
      destinations: DESTINATIONS,
      vendors: publicVendors()
    });
  }
  if (url.pathname === '/api/board') {
    const product = products.find(item => item.id === url.searchParams.get('product')) ?? products[0];
    const variantId = resolveVariantId(product, url.searchParams.get('variant'));
    const grams = url.searchParams.get('grams') ?? '500';
    const destination = findDestination(url.searchParams.get('dest'));
    const board = quoteBoard({ observations, productId: product.id, variantId, targetGrams: grams, destination, fx: null, now });
    return json(response, {
      ...board,
      product: publicProducts().find(item => item.id === product.id) ?? null,
      freshness: {
        ...refreshFreshness(lastRefreshAt, now),
        fx: null,
        vendors: registeredVendors().map(vendor => ({
          vendorId: vendor.id,
          lastAttemptAt: new Date(now).toISOString(),
          lastSuccessAt: new Date(now).toISOString(),
          consecutiveFailures: 0,
          nextAttemptAt: null,
          lastErrors: []
        }))
      },
      status: board.ranked.length > 0
        ? 'Delivered totals ranked from verified observations.'
        : 'No offer currently has enough verified information to rank. Unknowns are listed below.',
      qa: {
        mode: 'fixtures',
        demoOffers: withTermsDemo ? 1 : 0,
        staleRefresh,
        note: withTermsDemo
          ? 'Offline browser QA server. Recorded fixtures plus one clearly labelled QA-only terms demo offer (not a real vendor).'
          : 'Offline browser QA server. Data comes from tests/fixtures, not a live refresh.'
      }
    });
  }
  if (url.pathname.startsWith('/api/')) {
    return json(response, { error: 'Not found' }, 404);
  }
  return serveStatic(response, url.pathname);
}

async function serveStatic(response, pathname) {
  const relative = pathname === '/' ? 'index.html' : decodeURIComponent(pathname).replace(/^\/+/, '');
  const target = resolve(PUBLIC_DIR, relative);
  if (target !== PUBLIC_DIR && !target.startsWith(`${PUBLIC_DIR}${sep}`)) {
    return json(response, { error: 'Not found' }, 404);
  }
  try {
    const info = await stat(target);
    if (!info.isFile()) throw new Error('not a file');
    const body = await readFile(target);
    response.writeHead(200, {
      'content-type': MIME[extname(target).toLowerCase()] ?? 'application/octet-stream',
      'cache-control': 'no-store'
    });
    return response.end(body);
  } catch {
    return json(response, { error: 'Not found' }, 404);
  }
}

function json(response, body, status = 200) {
  response.writeHead(status, { 'content-type': 'application/json; charset=utf-8', 'cache-control': PUBLIC_CACHE });
  response.end(JSON.stringify(body));
}

const invokedDirectly = process.argv[1] && import.meta.url === pathToFileURL(resolve(process.argv[1])).href;
if (invokedDirectly) {
  const port = Number(process.argv[2]) || 8789;
  const server = await startQaServer({ port });
  console.log(`QA fixture server on ${server.url} (${server.observations.length} fixture observations). Ctrl-C to stop.`);
}

// Recorded vendor pages and the URL → fixture routing used by the offline tools.
//
// One source of truth for `npm run check:sources -- --fixture`,
// `npm run cron:offline`, the browser QA fixture server and the unit tests, so a
// new tracked offer cannot silently lose its fixture. Every fixture is a
// minimized excerpt of a real public product page (see docs/SOURCES.md).

import { readFile } from 'node:fs/promises';
import { registeredVendors } from '../../src/vendors/index.js';

/** fixture file per "<vendorId>:<offerId>". */
export const FIXTURE_BY_OFFER = {
  'coffeeman:classico-250g': 'coffeeman-product.windows-1255.html',
  'coffeeman:classico-1000g-4pack': 'coffeeman-4pack-product.windows-1255.html',
  'coffeeman:classico-2000g-8pack': 'coffeeman-8pack-product.windows-1255.html',
  'coffeeman:qualita-oro-250g': 'coffeeman-qualita-oro-product.windows-1255.html',
  'coffeeman:qualita-oro-1000g-4pack': 'coffeeman-qualita-oro-4pack-product.windows-1255.html',
  'coffeeman:qualita-oro-2000g-8pack': 'coffeeman-qualita-oro-8pack-product.windows-1255.html',
  'coffeeman:qualita-rossa-250g': 'coffeeman-qualita-rossa-product.windows-1255.html',
  'coffeeman:suerte-250g': 'coffeeman-suerte-product.windows-1255.html',
  'pucks:classico-250g': 'pucks-product.html',
  'pucks:qualita-oro-250g': 'pucks-qualita-oro-product.html',
  'pucks:qualita-rossa-250g': 'pucks-qualita-rossa-product.html',
  'pucks:qualita-rossa-250g-oos': 'pucks-qualita-rossa-outofstock-product.html',
  'pucks:suerte-250g': 'pucks-suerte-product.html',
  'coffee4u:crema-e-gusto-250g-ground': 'coffee4u-product.windows-1255.html'
};

const WINDOWS_1255 = 'text/html; charset=windows-1255';
const CONTENT_TYPE_BY_FILE = {
  'coffeeman-product.windows-1255.html': WINDOWS_1255,
  'coffeeman-4pack-product.windows-1255.html': WINDOWS_1255,
  'coffeeman-8pack-product.windows-1255.html': WINDOWS_1255,
  'coffeeman-qualita-oro-product.windows-1255.html': WINDOWS_1255,
  'coffeeman-qualita-oro-4pack-product.windows-1255.html': WINDOWS_1255,
  'coffeeman-qualita-oro-8pack-product.windows-1255.html': WINDOWS_1255,
  'coffeeman-qualita-rossa-product.windows-1255.html': WINDOWS_1255,
  'coffeeman-suerte-product.windows-1255.html': WINDOWS_1255,
  'coffeeman-product.outofstock.windows-1255.html': WINDOWS_1255,
  'pucks-product.html': 'text/html; charset=utf-8',
  'pucks-product.outofstock.html': 'text/html; charset=utf-8',
  'pucks-product.preorder.html': 'text/html; charset=utf-8',
  'pucks-qualita-oro-product.html': 'text/html; charset=utf-8',
  'pucks-qualita-rossa-product.html': 'text/html; charset=utf-8',
  'pucks-qualita-rossa-outofstock-product.html': 'text/html; charset=utf-8',
  'pucks-suerte-product.html': 'text/html; charset=utf-8',
  'coffee4u-product.windows-1255.html': WINDOWS_1255,
  'coffee4u-product.outofstock.windows-1255.html': WINDOWS_1255
};

export const FIXTURES_DIR = new URL('./', import.meta.url);

/** Every tracked offer together with the fixture that reproduces its page. */
export function trackedOffers() {
  const offers = [];
  for (const vendor of registeredVendors()) {
    for (const offer of vendor.offers ?? []) {
      const file = FIXTURE_BY_OFFER[`${vendor.id}:${offer.id}`] ?? null;
      offers.push({ vendorId: vendor.id, offerId: offer.id, url: offer.url, productId: offer.productId ?? null, file });
    }
  }
  return offers;
}

const urlToOffer = new Map(trackedOffers().map(offer => [offer.url, offer]));

/** Read a recorded fixture by file name. */
export async function readFixture(file) {
  const bytes = await readFile(new URL(file, FIXTURES_DIR));
  const contentType = CONTENT_TYPE_BY_FILE[file] ?? 'text/html; charset=utf-8';
  return { file, bytes, contentType, text: new TextDecoder('utf-8', { fatal: false }).decode(bytes) };
}

/** Read the fixture that corresponds to a tracked vendor URL, or null. */
export async function readFixtureForUrl(url) {
  const offer = urlToOffer.get(String(url));
  if (!offer?.file) return null;
  return { ...(await readFixture(offer.file)), offer };
}

/** Fixture fetch for the production bounded fetcher shape (returns a Response). */
export function createFixtureFetch() {
  return async (url, init = {}) => {
    const hit = await readFixtureForUrl(url);
    if (!hit) return new Response('no fixture for this URL', { status: 404 });
    void init;
    return new Response(hit.bytes, { status: 200, headers: { 'content-type': hit.contentType } });
  };
}

// Coffee4U / קופי פור יו (coffee4u.co.il), Tel Aviv, Israel — Lavazza Crema e gusto
// 250 g ground coffee in a vacuum brick. The page is a legacy Windows-1255 document
// with schema.org Product/Offer microdata for price, currency, availability and SKU,
// plus a per-product delivery options list publishing a courier rate and a cheaper
// delivery-to-pickup-point service. Free self-pickup is kept separate from delivery.
//
// The robots.txt allows product pages and asks for a crawl delay of 7 seconds; the
// adapter declares that delay so the refresh pipeline spaces its requests to this host
// instead of assuming the six-hour interval is enough.

import { classifyListing } from '../catalog.js';
import { decodeHtml, parseDecimal, stripTags, collapse } from '../lib/text.js';
import { createObservation, parseError } from './index.js';

const PRODUCT_URL = 'https://www.coffee4u.co.il/product/lavazza-crema-e-gusto-250-gr-%D7%98%D7%97%D7%95%D7%9F';

const AVAILABILITY = {
  InStock: 'in_stock',
  LimitedAvailability: 'in_stock',
  OutOfStock: 'out_of_stock',
  SoldOut: 'out_of_stock',
  PreOrder: 'unknown'
};

export const coffee4u = {
  id: 'coffee4u',
  name: 'Coffee4U (קופי פור יו)',
  homepage: 'https://www.coffee4u.co.il',
  allowedHosts: ['www.coffee4u.co.il', 'coffee4u.co.il'],
  parserVersion: 'coffee4u/1',
  crawlDelayMs: 7000,
  offers: [{ id: 'crema-e-gusto-250g-ground', url: PRODUCT_URL, kind: 'delivery', productId: 'lavazza-crema-e-gusto-vacuum-ground' }],

  async observe({ fetchText, now }) {
    const observations = [];
    const failures = [];
    for (const offer of this.offers) {
      const response = await fetchText(offer.url, { accept: 'text/html' });
      if (!response.ok) {
        failures.push({ offerId: offer.id, url: offer.url, error: response.error ?? `HTTP ${response.status}` });
        continue;
      }
      try {
        const html = response.buffer ? decodeHtml(response.buffer, response.text) : response.text;
        observations.push(parseCoffee4uProduct(html, { now, url: offer.url, productId: offer.productId ?? null }));
      } catch (error) {
        failures.push({ offerId: offer.id, url: offer.url, error: error.message, details: error.details ?? null });
      }
    }
    return { observations, failures };
  }
};

export function parseCoffee4uProduct(html, { now, url = PRODUCT_URL, productId = null } = {}) {
  const name = extractName(html);
  if (!name) throw parseError('Product name not found', { url });
  const classification = classifyListing(name, { productId });
  if (!classification.matched) {
    throw parseError('Listing does not match the tracked product', { name, reasons: classification.reasons });
  }

  const priceMatch = /itemprop="price"[^>]*\bprice="([\d.,]+)"/.exec(html)
    ?? /itemprop="price"[^>]*\bcontent="([\d.,]+)"/.exec(html);
  const priceAmount = parseDecimal(priceMatch?.[1]);
  if (priceAmount == null) throw parseError('Price not found in product microdata', { name });
  const currency = /itemprop="priceCurrency"\s*>\s*([A-Z]{3})/.exec(html)?.[1] ?? null;
  if (!currency) throw parseError('Currency not found in product microdata', { name });

  const availabilityHref = /itemprop="availability"[^>]*href="([^"]+)"/.exec(html)?.[1] ?? '';
  const availability = AVAILABILITY[availabilityHref.split('/').pop()] ?? 'unknown';
  const sku = /itemprop="sku"[^>]*>([^<]+)</.exec(html)?.[1]?.trim() ?? null;

  const shipping = parseCoffee4uShipping(html);
  const observation = createObservation({
    vendor: coffee4u,
    itemUrl: url,
    product: {
      productId: classification.productId,
      name,
      sku,
      gtin: null,
      variantId: classification.variantId,
      variantLabel: classification.variantLabel,
      form: classification.form,
      packGrams: classification.packGrams,
      packCount: classification.packCount,
      totalGrams: classification.totalGrams,
      category: 'פולי קפה וקפה טחון'
    },
    price: { amount: priceAmount, currency },
    availability,
    availabilityEvidence: {
      url,
      value: availabilityHref || 'not stated',
      note: 'Availability comes from the product page offer microdata, not from a price-only scrape.'
    },
    shipping: {
      mode: 'delivery',
      certainty: shipping.courierAmount == null ? 'unknown' : 'verified',
      amount: shipping.courierAmount == null ? null : { amount: shipping.courierAmount, currency },
      destination: { scope: 'country', country: 'IL' },
      minOrder: null,
      freeThreshold: null,
      deliveryTime: shipping.deliveryTime,
      pickup: {
        available: shipping.selfPickup,
        amount: shipping.selfPickup ? { amount: 0, currency } : null,
        note: shipping.selfPickup ? 'Free self-pickup at the shop, listed on the product page.' : null
      },
      alternatives: shipping.pickupPointAmount == null ? [] : [{
        id: 'pickup-point',
        label: "Delivery to a צ'יטה שופס pickup point",
        amount: { amount: shipping.pickupPointAmount, currency },
        note: 'Published on the same product page for up to 5 kg; a different service from door-to-door courier delivery.'
      }],
      note: shipping.note,
      evidence: { url, retrievedAt: null, note: 'Delivery options are listed next to the product on the product page.' }
    },
    now
  });
  return observation;
}

export function parseCoffee4uShipping(html) {
  // The delivery list lives in one "delivery-price-product" block. Read to the end of
  // its <ul> so a longer list is still parsed, with a hard cap for untrusted markup.
  const start = html.indexOf('delivery-price-product');
  let block = '';
  if (start >= 0) {
    const listEnd = html.indexOf('</ul>', start);
    const end = listEnd >= 0 ? Math.min(listEnd + 5, start + 4000) : start + 4000;
    block = html.slice(start, end);
  }
  const items = [...block.matchAll(/<li[^>]*>([\s\S]*?)<\/li>/gi)].map(match => ({
    html: match[1],
    text: collapse(stripTags(match[1]))
  }));
  let courierAmount = null;
  let pickupPointAmount = null;
  let selfPickup = false;
  let deliveryTime = null;
  let pickupPointNote = null;
  for (const item of items) {
    const amount = parseDecimal(/<em[^>]*class=['"]?price['"]?[^>]*>\s*([\d.,]+)/.exec(item.html)?.[1])
      ?? parseDecimal(item.text.match(/([\d.,]+)\s*₪/)?.[1]);
    if (/איסוף עצמי/.test(item.text)) {
      selfPickup = true;
    } else if (/נקודת איסוף/.test(item.text)) {
      pickupPointAmount = amount;
      pickupPointNote = item.text;
    } else if (/שליחות|דלת לדלת/.test(item.text)) {
      courierAmount = amount;
      deliveryTime = collapse(item.text.match(/(עד\s*[\d-]+\s*ימי עסקים)/)?.[1] ?? '') || null;
    }
  }

  const notes = [];
  if (courierAmount != null) {
    notes.push(`Published door-to-door courier rate: ₪${courierAmount.toFixed(2)}${deliveryTime ? ` (${deliveryTime})` : ''}.`);
  } else {
    notes.push('No published courier rate found on the product page; delivery cost is unknown before checkout.');
  }
  if (pickupPointAmount != null) {
    notes.push(`The same page publishes delivery to a pickup point for ₪${pickupPointAmount.toFixed(2)} (up to 5 kg, up to 7 business days), a different service that is not used for the ranked delivered total.`);
  }
  if (selfPickup) {
    notes.push('Free self-pickup at the shop is available and is kept separate from delivery.');
  }
  notes.push('Door-to-door delivery is subject to the courier\u2019s published list of localities, which the product page does not enumerate.');

  return { courierAmount, pickupPointAmount, selfPickup, deliveryTime, pickupPointNote, note: notes.join(' ') };
}

function extractName(html) {
  const h1 = /<h1[^>]*itemprop="name"[^>]*>([\s\S]*?)<\/h1>/i.exec(html)?.[1];
  if (h1) return collapse(stripTags(h1));
  const og = /<meta\s+property="og:title"\s+content\s*=\s*"([^"]+)"/i.exec(html)?.[1];
  if (og) return collapse(og);
  return null;
}

#!/usr/bin/env node
// Repeatable local cron simulation.
//
//   npm run cron:local            # real vendor + Bank of Israel checks, persisted to .shurik-local/board.json
//   npm run cron:offline          # same pipeline with recorded fixtures, no network
//
// The Worker's scheduled handler calls the same runRefresh() function, so this
// script exercises the production refresh path without any Cloudflare account.
//
// Offline runs are deterministic: they use their own state file and start from a
// clean store, so the command can be repeated and the live script's six-hour
// backoff window is never consumed by a fixture run. Live runs keep their state
// (like the deployed cron); pass --fresh to a live run to reset it. Set
// BOARD_STATE_PATH to choose the state file explicitly.

import { rm } from 'node:fs/promises';
import { runRefresh } from '../src/refresh.js';
import { createFileStore } from '../src/store.js';
import { registeredVendors } from '../src/vendors/index.js';
import { createFixtureFetch } from '../tests/fixtures/vendor-fixtures.mjs';

const args = new Set(process.argv.slice(2));
const offline = args.has('--offline');
const explicitStatePath = process.env.BOARD_STATE_PATH || null;
const storePath = explicitStatePath ?? (offline ? '.shurik-local/board-offline.json' : '.shurik-local/board.json');
const resetState = args.has('--fresh') || (offline && !explicitStatePath);
const now = args.has('--simulate-failure-now') ? Date.now() + 24 * 60 * 60 * 1000 : Date.now();

if (resetState) await rm(storePath, { force: true });
const store = await createFileStore(storePath);

if (offline) {
  const fixtureFetch = createFixtureFetch();
  const boi = {
    exchangeRates: [
      { key: 'USD', currentExchangeRate: 3.0, unit: 1, lastUpdate: '2026-10-09T09:21:04.476265Z' },
      { key: 'EUR', currentExchangeRate: 3.5, unit: 1, lastUpdate: '2026-10-09T09:21:04.476265Z' }
    ]
  };
  globalThis.__offlineFetch = async (url, init) => {
    if (String(url).includes('boi.org.il')) return Response.json(boi);
    return fixtureFetch(url, init);
  };
}

const fetchImpl = offline ? globalThis.__offlineFetch : globalThis.fetch;
// Offline runs use recorded pages, so the crawl-delay wait would only slow the
// test down; the pacing itself is covered by tests/http fixtures in unit tests.
const sleep = offline ? async () => {} : undefined;
const logger = { info: message => process.stderr.write(`${message}\n`), warn: message => process.stderr.write(`${message}\n`) };

try {
  const summary = await runRefresh({
    store,
    vendors: registeredVendors(),
    fetchImpl,
    now,
    sleep,
    trigger: offline ? 'cron-simulation-offline' : 'cron-simulation',
    logger
  });
  await store.flush();
  const snapshot = await store.snapshot();
  console.log(JSON.stringify({
    mode: offline ? 'offline fixtures' : 'live sources',
    statePath: storePath,
    summary,
    offers: snapshot.observations.map(observation => ({
      key: observation.key,
      productId: observation.product?.productId ?? null,
      vendor: observation.vendor?.name,
      price: observation.price,
      availability: observation.availability,
      shipping: observation.shipping?.amount,
      shippingCertainty: observation.shipping?.certainty,
      observedAt: observation.observedAt,
      lastError: observation.lastError ?? null
    })),
    fx: snapshot.meta.fx ? { asOf: snapshot.meta.fx.asOf, fetchedAt: snapshot.meta.fx.fetchedAt, usd: snapshot.meta.fx.rates?.USD } : null
  }, null, 2));
  process.exitCode = summary.skipped ? 0 : 0;
} catch (error) {
  console.error('cron simulation failed:', error);
  process.exitCode = 1;
}

// Persistence for the self-updating board.
//
// Production uses a SQLite-backed Durable Object (class BoardStore) so the
// deployment can define its own storage without CF administration credentials
// in GitHub. The same method names are implemented by an in-memory store and a
// file-backed store for tests and the local cron simulation.

const SCHEMA = [
  `CREATE TABLE IF NOT EXISTS observations (
     key TEXT PRIMARY KEY,
     payload TEXT NOT NULL,
     observed_at TEXT,
     attempted_at TEXT,
     last_error TEXT
   )`,
  `CREATE TABLE IF NOT EXISTS vendor_state (
     vendor_id TEXT PRIMARY KEY,
     payload TEXT NOT NULL
   )`,
  `CREATE TABLE IF NOT EXISTS meta (
     key TEXT PRIMARY KEY,
     value TEXT NOT NULL
   )`,
  `CREATE TABLE IF NOT EXISTS runs (
     id INTEGER PRIMARY KEY AUTOINCREMENT,
     payload TEXT NOT NULL,
     started_at TEXT,
     finished_at TEXT
   )`
];

export const STORE_INTERFACE = [
  'listObservations', 'putObservation', 'markAttempt',
  'getVendorState', 'setVendorState', 'getMeta', 'setMeta',
  'recordRun', 'listRuns', 'acquireLease', 'releaseLease'
];

export class BoardStore {
  constructor(state) {
    this.state = state;
    this.storage = state.storage;
    this.sql = state.storage.sql;
    for (const statement of SCHEMA) this.sql.exec(statement);
    this.methods = {
      snapshot: () => this.snapshot(),
      listObservations: () => this.listObservations(),
      putObservation: args => this.putObservation(args[0]),
      markAttempt: args => this.markAttempt(args[0]),
      getVendorState: args => this.getVendorState(args[0]),
      setVendorState: args => this.setVendorState(args[0], args[1]),
      getMeta: args => this.getMeta(args[0]),
      setMeta: args => this.setMeta(args[0], args[1]),
      recordRun: args => this.recordRun(args[0]),
      listRuns: args => this.listRuns(args[0] ?? 10),
      acquireLease: args => this.acquireLease(args[0], args[1], args[2]),
      releaseLease: args => this.releaseLease(args[0])
    };
  }

  async fetch(request) {
    if (request.method !== 'POST') return new Response('Method not allowed', { status: 405 });
    let body;
    try {
      body = await request.json();
    } catch {
      return Response.json({ error: 'invalid JSON body' }, { status: 400 });
    }
    const method = this.methods[body?.op];
    if (!method) return Response.json({ error: `unknown op ${body?.op}` }, { status: 400 });
    try {
      return Response.json({ result: await method(body.args ?? []) });
    } catch (error) {
      return Response.json({ error: error?.message ?? String(error) }, { status: 500 });
    }
  }

  async listObservations() {
    return this.sql.exec('SELECT key, payload, observed_at, attempted_at, last_error FROM observations').toArray()
      .map(row => ({
        ...JSON.parse(row.payload),
        key: row.key,
        observedAt: row.observed_at,
        attemptedAt: row.attempted_at,
        lastError: row.last_error
      }));
  }

  async putObservation(observation) {
    this.sql.exec(
      `INSERT INTO observations (key, payload, observed_at, attempted_at, last_error)
       VALUES (?, ?, ?, ?, NULL)
       ON CONFLICT(key) DO UPDATE SET payload = excluded.payload, observed_at = excluded.observed_at, attempted_at = excluded.attempted_at, last_error = NULL`,
      observation.key,
      JSON.stringify(observation),
      observation.observedAt ?? null,
      observation.attemptedAt ?? observation.observedAt ?? null
    );
  }

  async markAttempt({ key, attemptedAt, error }) {
    this.sql.exec('UPDATE observations SET attempted_at = ?, last_error = ? WHERE key = ?', attemptedAt, error ?? null, key);
    this.sql.exec(
      `INSERT INTO observations (key, payload, observed_at, attempted_at, last_error)
       SELECT ?, ?, NULL, ?, ? WHERE NOT EXISTS (SELECT 1 FROM observations WHERE key = ?)`,
      key, '{}', attemptedAt, error ?? null, key
    );
  }

  async snapshot() {
    return {
      observations: await this.listObservations(),
      vendors: this.listVendorState(),
      runs: await this.listRuns(5),
      meta: this.allMeta()
    };
  }

  listVendorState() {
    const out = {};
    for (const row of this.sql.exec('SELECT vendor_id, payload FROM vendor_state').toArray()) {
      out[row.vendor_id] = JSON.parse(row.payload);
    }
    return out;
  }

  allMeta() {
    const out = {};
    for (const row of this.sql.exec('SELECT key, value FROM meta').toArray()) {
      out[row.key] = JSON.parse(row.value);
    }
    return out;
  }

  async getVendorState(vendorId) {
    const row = this.sql.exec('SELECT payload FROM vendor_state WHERE vendor_id = ?', vendorId).toArray()[0];
    return row ? JSON.parse(row.payload) : null;
  }

  async setVendorState(vendorId, value) {
    this.sql.exec(
      `INSERT INTO vendor_state (vendor_id, payload) VALUES (?, ?)
       ON CONFLICT(vendor_id) DO UPDATE SET payload = excluded.payload`,
      vendorId, JSON.stringify(value)
    );
  }

  async getMeta(key) {
    const row = this.sql.exec('SELECT value FROM meta WHERE key = ?', key).toArray()[0];
    return row ? JSON.parse(row.value) : null;
  }

  async setMeta(key, value) {
    this.sql.exec(
      `INSERT INTO meta (key, value) VALUES (?, ?)
       ON CONFLICT(key) DO UPDATE SET value = excluded.value`,
      key, JSON.stringify(value)
    );
  }

  async recordRun(run) {
    this.sql.exec('INSERT INTO runs (payload, started_at, finished_at) VALUES (?, ?, ?)', JSON.stringify(run), run.startedAt ?? null, run.finishedAt ?? null);
  }

  async listRuns(limit = 10) {
    return this.sql.exec('SELECT payload FROM runs ORDER BY id DESC LIMIT ?', limit).toArray().map(row => JSON.parse(row.payload));
  }

  async acquireLease(name, holderId, ttlMs) {
    // Keep the read-check-write synchronous: Durable Object SQL is synchronous, so no
    // other request can interleave between the check and the write and double-acquire.
    const key = `lease:${name}`;
    const row = this.sql.exec('SELECT value FROM meta WHERE key = ?', key).toArray()[0];
    const current = row ? JSON.parse(row.value) : null;
    const now = Date.now();
    if (current && current.expiresAt > now && current.holderId !== holderId) return false;
    this.sql.exec(
      `INSERT INTO meta (key, value) VALUES (?, ?)
       ON CONFLICT(key) DO UPDATE SET value = excluded.value`,
      key, JSON.stringify({ holderId, expiresAt: now + ttlMs, acquiredAt: new Date(now).toISOString() })
    );
    return true;
  }

  async releaseLease(name) {
    await this.setMeta(`lease:${name}`, null);
  }
}

/** Client for the DO; safe to call from a Worker request or scheduled handler. */
export function durableStore(env) {
  const id = env.BOARD.idFromName('board');
  return env.BOARD.get(id);
}

export async function callStore(stub, op, args = []) {
  const response = await stub.fetch('https://board.internal/', {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ op, args })
  });
  const payload = await response.json();
  if (!response.ok) throw new Error(payload?.error ?? `store error ${response.status}`);
  return payload.result;
}

export function storeClient(stub) {
  const call = (op, ...args) => callStore(stub, op, args);
  return {
    listObservations: () => call('listObservations'),
    putObservation: observation => call('putObservation', observation),
    markAttempt: attempt => call('markAttempt', attempt),
    getVendorState: vendorId => call('getVendorState', vendorId),
    setVendorState: (vendorId, value) => call('setVendorState', vendorId, value),
    getMeta: key => call('getMeta', key),
    setMeta: (key, value) => call('setMeta', key, value),
    recordRun: run => call('recordRun', run),
    listRuns: limit => call('listRuns', limit),
    acquireLease: (name, holderId, ttlMs) => call('acquireLease', name, holderId, ttlMs),
    releaseLease: name => call('releaseLease', name),
    snapshot: () => call('snapshot')
  };
}

/** In-memory implementation with the same interface, used by tests. */
export function createMemoryStore(initial = {}) {
  const observations = new Map();
  for (const observation of initial.observations ?? []) observations.set(observation.key, observation);
  const vendors = new Map(Object.entries(initial.vendors ?? {}));
  const meta = new Map(Object.entries(initial.meta ?? {}));
  const runs = [...(initial.runs ?? [])];
  return {
    async listObservations() {
      return [...observations.values()].map(item => ({ ...item }));
    },
    async putObservation(observation) {
      observations.set(observation.key, { ...observation });
    },
    async markAttempt({ key, attemptedAt, error }) {
      const existing = observations.get(key) ?? { key, product: {}, price: {}, shipping: {} };
      observations.set(key, { ...existing, attemptedAt, lastError: error ?? null });
    },
    async getVendorState(vendorId) {
      return vendors.has(vendorId) ? { ...vendors.get(vendorId) } : null;
    },
    async setVendorState(vendorId, value) {
      vendors.set(vendorId, { ...value });
    },
    async getMeta(key) {
      return meta.has(key) ? { ...meta.get(key) } : null;
    },
    async setMeta(key, value) {
      if (value == null) meta.delete(key);
      else meta.set(key, { ...value });
    },
    async recordRun(run) {
      runs.push({ ...run });
    },
    async listRuns(limit = 10) {
      return runs.slice(-limit).reverse();
    },
    async acquireLease(name, holderId, ttlMs) {
      // Read-check-write without awaits so two simultaneous runs cannot both acquire.
      const key = `lease:${name}`;
      const current = meta.get(key);
      const now = Date.now();
      if (current && current.expiresAt > now && current.holderId !== holderId) return false;
      meta.set(key, { holderId, expiresAt: now + ttlMs, acquiredAt: new Date(now).toISOString() });
      return true;
    },
    async releaseLease(name) {
      meta.delete(`lease:${name}`);
    },
    async snapshot() {
      return {
        observations: [...observations.values()].map(item => ({ ...item })),
        vendors: Object.fromEntries([...vendors.entries()].map(([id, value]) => [id, { ...value }])),
        runs: runs.slice(-5).reverse(),
        meta: Object.fromEntries(meta)
      };
    }
  };
}

/** File-backed store for the local cron simulation (gitignored path). */
export async function createFileStore(path) {
  const { readFile, writeFile, mkdir } = await import('node:fs/promises');
  const { dirname } = await import('node:path');
  let state = {};
  try {
    state = JSON.parse(await readFile(path, 'utf8'));
  } catch {
    state = { observations: [], vendors: {}, meta: {}, runs: [] };
  }
  const memory = createMemoryStore(state);
  return {
    ...memory,
    async flush() {
      await mkdir(dirname(path), { recursive: true });
      const snapshot = await memory.snapshot();
      await writeFile(path, `${JSON.stringify({ ...snapshot, runs: await memory.listRuns(20) }, null, 2)}\n`);
    }
  };
}

// Scheduled refresh pipeline.
//
// The pipeline is deterministic and bounded: allowlisted hosts, per-request
// timeouts and size limits, concurrency capped, one attempt per offer per run.
// A failing vendor keeps its previous good observation; a missing FX rate keeps
// the previous rate table. Nothing here needs a browser, an LLM or the coding
// loop to be running.

import { createBoundedFetcher } from './lib/http.js';
import { parseBoiRates, FX_SOURCE } from './lib/fx.js';
import { registeredVendors, vendorHosts } from './vendors/index.js';

export const REFRESH_INTERVAL_MS = 6 * 60 * 60 * 1000; // About every six hours.
// A scheduled refresh that has not completed for this long is surfaced to shoppers
// as stale: one missed six-hour run plus slack, so a broken cron does not stay silent.
export const REFRESH_STALE_MS = 8 * 60 * 60 * 1000;
export const BACKOFF_BASE_MS = 30 * 60 * 1000;
export const BACKOFF_MAX_MS = 12 * 60 * 60 * 1000;
export const LEASE_TTL_MS = 10 * 60 * 1000;
export const MAX_CONCURRENCY = 2;
export const INITIAL_REFRESH_THROTTLE_MS = 10 * 60 * 1000;

export const FX_URL = 'https://www.boi.org.il/currency.xml';
export const FX_HOSTS = ['www.boi.org.il', 'boi.org.il'];

/**
 * Test seam for crawl-delay pacing. Production and the real cron simulation use
 * real timers; unit tests and offline simulations replace these with a no-op so
 * they never wait. Pass `sleep`/`clock` to runRefresh for a per-call override.
 */
export const pacingDefaults = { sleep: undefined, clock: undefined };

export function backoffMs(consecutiveFailures) {
  if (!consecutiveFailures || consecutiveFailures <= 0) return 0;
  return Math.min(BACKOFF_BASE_MS * 2 ** (consecutiveFailures - 1), BACKOFF_MAX_MS);
}

/**
 * Freshness of the board as a whole, derived only from the last completed refresh.
 * Missing or old refresh timestamps are reported as stale instead of being hidden.
 */
export function refreshFreshness(lastRefreshAt, now = Date.now()) {
  const parsed = lastRefreshAt ? Date.parse(lastRefreshAt) : NaN;
  const ageMs = Number.isFinite(parsed) ? now - parsed : null;
  return {
    lastRefreshAt: lastRefreshAt ?? null,
    ageHours: ageMs == null ? null : Math.round((ageMs / 3_600_000) * 10) / 10,
    stale: ageMs == null || ageMs > REFRESH_STALE_MS
  };
}

export function isVendorDue(state, now) {
  if (!state?.nextAttemptAt) return true;
  return Date.parse(state.nextAttemptAt) <= now;
}

export async function runRefresh({
  store,
  vendors = registeredVendors(),
  fetchImpl = globalThis.fetch,
  now = Date.now(),
  includeFx = true,
  trigger = 'scheduled',
  holderId = `refresh-${now}-${Math.random().toString(36).slice(2, 8)}`,
  logger = null,
  sleep = undefined,
  clock = undefined
} = {}) {
  const acquired = await store.acquireLease('refresh', holderId, LEASE_TTL_MS);
  if (!acquired) {
    return { skipped: true, reason: 'another refresh holds the lease', trigger };
  }
  const startedAt = new Date(now).toISOString();
  let requests = 0;
  const counter = () => { requests += 1; };
  const fxHosts = FX_HOSTS;
  const results = [];
  try {
    const queued = [];
    for (const vendor of vendors) {
      const state = await store.getVendorState(vendor.id);
      if (!isVendorDue(state, now)) {
        results.push({ vendorId: vendor.id, skipped: true, reason: 'backoff', nextAttemptAt: state.nextAttemptAt });
        continue;
      }
      queued.push({ vendor, state });
    }

    for (let index = 0; index < queued.length; index += MAX_CONCURRENCY) {
      const batch = queued.slice(index, index + MAX_CONCURRENCY);
      const batchResults = await Promise.all(batch.map(({ vendor, state }) => refreshVendor({ store, vendor, state, fetchImpl, now, counter, logger, sleep, clock })));
      results.push(...batchResults);
    }

    let fx = null;
    if (includeFx) fx = await refreshFxCached({ store, fetchImpl, now, counter, logger });

    const finishedAt = new Date(Date.now()).toISOString();
    const summary = {
      trigger,
      startedAt,
      finishedAt,
      requests,
      vendors: results,
      fx: fx ? { ok: fx.ok, asOf: fx.fx?.asOf ?? null, error: fx.error ?? null } : { skipped: true }
    };
    await store.recordRun(summary);
    await store.setMeta('lastRefreshAt', { value: finishedAt, trigger });
    return summary;
  } finally {
    await store.releaseLease('refresh');
  }
}

async function refreshVendor({ store, vendor, state, fetchImpl, now, counter, logger, sleep, clock }) {
  const fetchText = createBoundedFetcher({
    fetchImpl,
    allowedHosts: vendor.allowedHosts ?? vendorHosts([vendor]),
    onRequest: counter,
    // Respect a vendor's published crawl delay (for example "Crawl-delay: 7")
    // instead of firing every tracked offer back to back.
    minIntervalMs: vendor.crawlDelayMs ?? 0,
    sleep: sleep ?? pacingDefaults.sleep,
    clock: clock ?? pacingDefaults.clock
  });
  const attemptedAt = new Date(now).toISOString();
  let saved = 0;
  const failures = [];
  try {
    const outcome = await vendor.observe({ fetchText, now, logger });
    for (const observation of outcome.observations ?? []) {
      observation.attemptedAt = attemptedAt;
      observation.lastError = null;
      await store.putObservation(observation);
      saved += 1;
    }
    for (const failure of outcome.failures ?? []) {
      failures.push(failure);
      await store.markAttempt({
        key: `${vendor.id}:offer:${failure.offerId}`,
        attemptedAt,
        error: failure.error
      });
    }
  } catch (error) {
    failures.push({ offerId: '*', error: error?.message ?? String(error) });
    for (const offer of vendor.offers ?? []) {
      await store.markAttempt({ key: `${vendor.id}:offer:${offer.id}`, attemptedAt, error: error?.message ?? String(error) });
    }
  }
  const ok = saved > 0;
  const previousFailures = ok ? 0 : (state?.consecutiveFailures ?? 0) + 1;
  const delay = ok ? REFRESH_INTERVAL_MS : Math.max(backoffMs(previousFailures), BACKOFF_BASE_MS);
  const nextAttemptAt = new Date(now + delay).toISOString();
  const nextState = {
    vendorId: vendor.id,
    lastAttemptAt: attemptedAt,
    lastSuccessAt: ok ? attemptedAt : (state?.lastSuccessAt ?? null),
    consecutiveFailures: previousFailures,
    nextAttemptAt,
    lastErrors: failures.map(failure => failure.error).slice(0, 5)
  };
  await store.setVendorState(vendor.id, nextState);
  logger?.info?.(`[refresh] ${vendor.id}: saved=${saved} failures=${failures.length} next=${nextAttemptAt}`);
  return { vendorId: vendor.id, ok, saved, failures, nextAttemptAt };
}

export const FX_MIN_INTERVAL_MS = 3 * 60 * 60 * 1000;

/** Skip the FX fetch when a recent official rate table is already stored. */
export async function refreshFxCached({ store, fetchImpl, now, counter, logger }) {
  const stored = await store.getMeta('fx');
  if (stored?.fetchedAt && now - Date.parse(stored.fetchedAt) < FX_MIN_INTERVAL_MS) {
    return { ok: true, fx: stored, cached: true };
  }
  return refreshFx({ store, fetchImpl, now, counter, logger });
}

export async function refreshFx({ store, fetchImpl, now, counter, logger }) {
  const fetchText = createBoundedFetcher({ fetchImpl, allowedHosts: FX_HOSTS, onRequest: counter });
  const response = await fetchText(FX_URL, { accept: 'application/json' });
  const attemptedAt = new Date(now).toISOString();
  if (!response.ok) {
    logger?.warn?.(`[refresh] fx fetch failed: ${response.error ?? response.status}`);
    return { ok: false, error: response.error ?? `HTTP ${response.status}`, attemptedAt };
  }
  const parsed = (() => {
    try {
      return parseBoiRates(JSON.parse(response.text));
    } catch {
      return null;
    }
  })();
  if (!parsed) return { ok: false, error: 'Bank of Israel feed could not be parsed', attemptedAt };
  const fx = { ...parsed, fetchedAt: attemptedAt, source: FX_SOURCE };
  await store.setMeta('fx', fx);
  return { ok: true, fx, attemptedAt };
}

/**
 * Runs a refresh in the background when the board has never refreshed, for the
 * initial refresh after deployment. Bounded by a lease and a throttle so public
 * traffic can never trigger unlimited scraping.
 */
export async function maybeInitialRefresh({ store, ctx, now = Date.now(), run = runRefresh, ...options } = {}) {
  const last = await store.getMeta('lastRefreshAt');
  if (last?.value) return { skipped: true, reason: 'already refreshed' };
  const attempt = await store.getMeta('initialRefreshAttemptAt');
  if (attempt?.value && now - Date.parse(attempt.value) < INITIAL_REFRESH_THROTTLE_MS) {
    return { skipped: true, reason: 'initial refresh throttled' };
  }
  await store.setMeta('initialRefreshAttemptAt', { value: new Date(now).toISOString() });
  const promise = run({ store, trigger: 'initial', now, ...options }).catch(error => {
    console.warn(`initial refresh failed: ${error?.message ?? error}`);
    return null;
  });
  if (ctx?.waitUntil) ctx.waitUntil(promise);
  return { started: true, promise };
}

