// Build committed evidence JSON from the raw probe captures (run once, not part of the app).
import { readFileSync, writeFileSync } from 'node:fs';

const read = path => JSON.parse(readFileSync(path, 'utf8'));
const prod = name => read(`.shurik-local/prod-probe/${name}.json`);
const dev = name => read(`.shurik-local/dev-3-61/${name}.json`);

const summarizeBoard = board => ({
  generatedAt: board.generatedAt,
  productId: board.productId,
  variantId: board.variantId,
  targetGrams: board.targetGrams,
  destination: board.destination,
  best: board.best && { vendorId: board.best.vendor.id, totalIls: board.best.totalIls, ilsPerKg: board.best.ilsPerKg, key: board.best.key, itemUrl: board.best.itemUrl },
  ranked: (board.ranked ?? []).map(q => ({ vendorId: q.vendor.id, key: q.key, totalIls: q.totalIls, ilsPerKg: q.ilsPerKg, shippingCertainty: q.shipping?.certaintyLabel ?? null })),
  unrankable: (board.unrankable ?? []).map(q => ({ vendorId: q.vendor.id, key: q.key, itemPrice: q.itemPrice, reasons: q.reasons })),
  pickup: (board.pickup ?? []).map(q => ({ vendorId: q.vendor.id, key: q.key, note: q.reasons?.[0] ?? null })),
  counts: board.counts,
  requestedRetiredProduct: board.requestedRetiredProduct,
  freshness: board.freshness
});

const production = {
  capturedAt: '2026-10-12T15:51:52Z to 2026-10-12T15:54:58Z',
  mode: 'read-only public GETs from the coding runner to the owner-reported production URL; no Cloudflare credentials, admin API, deploy or remote resource change',
  url: 'https://attention-shoppers.igormaka.workers.dev',
  interpretation: [
    'The owner-reported deployment is independently verified reachable and serving the tracked single-product scope (HTTP 200 on /health, /api/status, /api/catalog, /api/board).',
    'Before the probe, /health reported lastRefreshAt null while /api/status already held five observations and vendor successes from 13:34:41Z and 13:46:30Z: a production run had saved observations without writing the completion marker (interrupted run), which motivated the 3-61 freshness fallback.',
    'The first /health GET started the documented throttled initial refresh; the run completed 15:51:52.931Z -> 15:52:12.546Z with 4 bounded requests, CoffeeMan saved 3 observations and Pucks/Coffee4U skipped inside their six-hour backoff window. /health then reported a non-null lastRefreshAt, so the production refresh path and Durable Object persistence are independently verified from the runner.',
    'Board results at 15:54Z match the documented expectations: 500 g best NIS 91.00 (2 x 33 + 25 CoffeeMan), 1 kg best NIS 149.00 (4-pack), unstated variant NIS 106.00 (Coffee4U), retired Qualita Oro URL falls back with requestedRetiredProduct and no retired offer in the payload.',
    'This verifies the deployed build that main pointed at on 2026-10-12 before the 3-61 freshness fallback; the 3-61 code is not deployed by the loop and needs the owner-side Workers Builds run after the push.'
  ],
  requests: [
    { url: '/health', at: '2026-10-12T15:51:52Z', httpStatus: 200, note: 'lastRefreshAt null; triggered the documented initial refresh' },
    { url: '/api/status', at: '2026-10-12T15:52:05Z', httpStatus: 200, note: 'five observations, Pucks and Coffee4U vendor state, lastRefreshAt null' },
    { url: '/api/catalog', at: '2026-10-12T15:52:05Z', httpStatus: 200, note: 'exactly one product, three vendors' },
    { url: '/api/board (defaults)', at: '2026-10-12T15:52:09Z', httpStatus: 200, note: 'refresh still in progress; CoffeeMan observation already saved' },
    { url: '/health (after)', at: '2026-10-12T15:53:37Z', httpStatus: 200, note: 'lastRefreshAt 2026-10-12T15:52:12.546Z' },
    { url: '/api/status (after)', at: '2026-10-12T15:53:37Z', httpStatus: 200, note: 'completed initial run, five observations, fresh' },
    { url: '/api/board?grams=500&dest=tel-aviv', at: '2026-10-12T15:54:58Z', httpStatus: 200, note: 'best NIS 91.00' },
    { url: '/api/board?grams=1000&dest=tel-aviv', at: '2026-10-12T15:54:58Z', httpStatus: 200, note: 'best NIS 149.00' },
    { url: '/api/board?variant=unspecified&grams=500&dest=tel-aviv', at: '2026-10-12T15:54:58Z', httpStatus: 200, note: 'best NIS 106.00' },
    { url: '/api/board?product=lavazza-qualita-oro-vacuum-ground&grams=500&dest=tel-aviv', at: '2026-10-12T15:54:58Z', httpStatus: 200, note: 'retired URL falls back to Crema e Gusto with requestedRetiredProduct' }
  ],
  healthBeforeRefresh: prod('health'),
  healthAfterRefresh: prod('health-after'),
  statusAfterRefresh: prod('api_status-after'),
  catalogSummary: {
    products: prod('api_catalog').products.map(p => p.id),
    variantIds: prod('api_catalog').products[0]?.variants.map(v => v.id),
    vendorIds: prod('api_catalog').vendors.map(v => v.id)
  },
  board500: summarizeBoard(prod('api_board_final')),
  board1000: summarizeBoard(prod('api_board_1kg')),
  boardUnstated: summarizeBoard(prod('api_board_unstated')),
  retiredUrl: summarizeBoard(prod('api_board_retired'))
