// Builds the iteration 3-62 evidence for the cron phase-lock fix.
// Runs the real refresh pipeline against the recorded fixtures.
import { writeFileSync } from 'node:fs';
import { runRefresh, isVendorDue, EARLY_DUE_TOLERANCE_MS, REFRESH_INTERVAL_MS, REFRESH_STALE_MS } from '../src/refresh.js';
import { createMemoryStore } from '../src/store.js';
import { readFixtureForUrl } from '../tests/fixtures/vendor-fixtures.mjs';

const BOI = {
  exchangeRates: [{ key: 'USD', currentExchangeRate: 3.05, unit: 1, lastUpdate: '2026-10-09T09:21:04.476265Z' }]
};
async function fixtureFetch(url) {
  if (String(url).includes('boi.org.il')) return Response.json(BOI);
  const hit = await readFixtureForUrl(url);
  if (!hit) return new Response('unexpected', { status: 404 });
  return new Response(hit.bytes, { status: 200, headers: { 'content-type': hit.contentType } });
}
const run = options => runRefresh({ sleep: async () => {}, ...options });

const RUN_AT = Date.parse('2026-10-12T00:17:20.000Z'); // a run finishing 20 s after the 00:17 tick
const TICK = Date.parse('2026-10-12T06:17:00.000Z');    // the next fixed cron tick

const store = createMemoryStore();
const first = await run({ store, fetchImpl: fixtureFetch, now: RUN_AT, trigger: 'cron' });
const dueAt = new Date(RUN_AT + REFRESH_INTERVAL_MS).toISOString();
const lastRefreshAfterFirst = (await store.snapshot()).meta.lastRefreshAt.value;

const oldRuleDue = Date.parse(dueAt) <= TICK;
const newRuleDue = isVendorDue({ nextAttemptAt: dueAt, consecutiveFailures: 0 }, TICK);
const backoffStrict = isVendorDue({ nextAttemptAt: dueAt, consecutiveFailures: 1 }, TICK);
const hoursEarlyRejected = isVendorDue({ nextAttemptAt: dueAt, consecutiveFailures: 0 }, TICK - 3 * 60 * 60 * 1000);

const tick = await run({ store, fetchImpl: fixtureFetch, now: TICK, trigger: 'cron' });
const lastRefreshAfterTick = (await store.snapshot()).meta.lastRefreshAt.value;

const evidence = {
  capturedAt: new Date().toISOString(),
  iteration: '3-62',
  defect: 'Cron phase lock: a successful run stores nextAttemptAt = run start + 6 h, but the cron fires at fixed clock times (17 */6 * * *). A tick landing seconds before the due time skipped every vendor; the run saved no observations and did not advance lastRefreshAt, so the refresh cadence drifted from six to twelve hours and the board (stale after 8 h) reported stale for hours between runs.',
  scenario: {
