// Builds the iteration 3-62 evidence for the cron phase-lock fix.
// Runs the real refresh pipeline against the recorded fixtures with both the
// current code and a copy of the pre-fix refresh.js from commit 0f8ccae.
import { writeFileSync } from 'node:fs';
import { runRefresh, isVendorDue, EARLY_DUE_TOLERANCE_MS, REFRESH_INTERVAL_MS, REFRESH_STALE_MS } from '../src/refresh.js';
import { createMemoryStore } from '../src/store.js';
import { readFixtureForUrl } from '../tests/fixtures/vendor-fixtures.mjs';
import { runRefresh as runRefreshPrefix, REFRESH_INTERVAL_MS as PREFIX_INTERVAL } from './prefix/src/refresh.js';
import { createMemoryStore as createMemoryStorePrefix } from './prefix/src/store.js';

const BOI = {
  exchangeRates: [{ key: 'USD', currentExchangeRate: 3.05, unit: 1, lastUpdate: '2026-10-09T09:21:04.476265Z' }]
};
async function fixtureFetch(url) {
  if (String(url).includes('boi.org.il')) return Response.json(BOI);
  const hit = await readFixtureForUrl(url);
  if (!hit) return new Response('unexpected', { status: 404 });
  return new Response(hit.bytes, { status: 200, headers: { 'content-type': hit.contentType } });
}
const run = options => runRefresh({ sleep: async () => {}, ...options });
const runPrefix = options => runRefreshPrefix({ sleep: async () => {}, ...options });

const RUN_AT = Date.parse('2026-10-12T00:17:20.000Z'); // a run finishing 20 s after the 00:17 tick
const TICK = Date.parse('2026-10-12T06:17:00.000Z');    // the next fixed cron tick

async function scenario(runner, storeFactory) {
  const store = storeFactory();
  const first = await runner({ store, fetchImpl: fixtureFetch, now: RUN_AT, trigger: 'cron' });
  const dueAt = new Date(RUN_AT + REFRESH_INTERVAL_MS).toISOString();
  const tick = await runner({ store, fetchImpl: fixtureFetch, now: TICK, trigger: 'cron' });
  return {
    dueAt,
    firstRequests: first.requests,
    tickRequests: tick.requests,
    tickVendorsSkipped: tick.vendors.filter(vendor => vendor.skipped).length,
    tickVendorsSaved: tick.vendors.filter(vendor => (vendor.saved ?? 0) > 0).length,
    // In production lastRefreshAt advances only when a vendor saved an observation.
    tickAdvancesLastRefreshInProduction: tick.vendors.some(vendor => (vendor.saved ?? 0) > 0)
  };
}

const prefix = await scenario(runPrefix, createMemoryStorePrefix);
const current = await scenario(run, createMemoryStore);

const dueAt = prefix.dueAt;
const evidence = {
  capturedAt: new Date().toISOString(),
  iteration: '3-62',
  defect: 'Cron phase lock: a successful run stores nextAttemptAt = run start + 6 h, but the cron fires at fixed clock times (17 */6 * * *). A tick landing seconds before the due time skipped every vendor; the run saved no observations and did not advance lastRefreshAt, so the refresh cadence drifted from six to twelve hours and the board (stale after 8 h) reported stale for hours between runs.',
  scenario: {
    firstRunAt: new Date(RUN_AT).toISOString(),
    storedDueAt: dueAt,
    nextCronTick: new Date(TICK).toISOString(),
    secondsBetweenTickAndDue: (Date.parse(dueAt) - TICK) / 1000,
    fixtureSource: 'tests/fixtures via vendor-fixtures.mjs; Bank of Israel rate table stubbed for the offline run'
  },
  preFixRun: {
    code: 'refresh.js from commit 0f8ccae (before the tolerance)',
    expression: 'Date.parse(nextAttemptAt) <= now',
    tickDue: Date.parse(dueAt) <= TICK,
    ...prefix
  },
  currentRun: {
    code: 'working tree after the fix',
    expression: 'due <= now + EARLY_DUE_TOLERANCE_MS for vendors with consecutiveFailures = 0; strict for backoff',
    earlyDueToleranceMs: EARLY_DUE_TOLERANCE_MS,
    tickDue: isVendorDue({ nextAttemptAt: dueAt, consecutiveFailures: 0 }, TICK),
    vendorThreeHoursEarlyIsNotDue: isVendorDue({ nextAttemptAt: dueAt, consecutiveFailures: 0 }, TICK - 3 * 60 * 60 * 1000) === false,
    failingVendorKeepsStrictDueTime: isVendorDue({ nextAttemptAt: dueAt, consecutiveFailures: 1 }, TICK) === false,
    ...current
  },
  interpretation: 'Under the pre-fix rule the fixed tick saved 0 observations, so production would not advance lastRefreshAt and the board would report stale for hours between the (now twelve-hourly) refreshes. Under the fixed rule the same tick saves all three vendors and advances the completion marker. The scenario injects past timestamps; the pipeline records finishedAt with the real clock, so lastRefreshAt wall-clock values are not compared here. The deterministic signal is whether any vendor saved an observation, which is exactly the production rule for advancing lastRefreshAt.',
  regressionCoverage: [
    'tests/refresh.test.js: a successful vendor counts as due a little before its stored due time',
    'tests/refresh.test.js: a cron tick just before the six-hour mark refreshes instead of skipping every vendor',
    'tests/refresh.test.js: repeated failures back off and stop re-fetching the broken vendor (strict backoff unchanged)',
    'tests/refresh.test.js: a run that only refreshes the FX table does not claim a completed offer refresh'
  ],
  verification: {
    'npm run verify': '89/89 node:test cases pass; wrangler deploy --dry-run builds the Worker bundle (79.00 KiB, gzip 20.17 KiB; bindings BOARD + ASSETS)',
    'npm run cron:offline': '6 bounded requests, all three vendors saved (CoffeeMan 3, Pucks 1, Coffee4U 1), five offers persisted, pruned 0',
    'npm run qa:browser': '57/57 offline browser checks pass'
  }
};

const stamp = new Date().toISOString().replace(/[-:]/g, '').replace(/\.\d+Z$/, 'Z');
const path = `docs/evidence/cron-phase-lock-${stamp}.json`;
writeFileSync(path, `${JSON.stringify(evidence, null, 2)}\n`);
console.log('wrote', path);
console.log('pre-fix tick: requests', prefix.tickRequests, 'skipped', prefix.tickVendorsSkipped, 'saved', prefix.tickVendorsSaved);
console.log('fixed tick:   requests', current.tickRequests, 'skipped', current.tickVendorsSkipped, 'saved', current.tickVendorsSaved);

