```js
async function refreshVendor({ store, vendor, state, fetchImpl, now, counter, logger, sleep, clock, previousByKey = null }) {
  ...
  const attemptedAt = new Date(now).toISOString();
  let saved = 0;
  const failures = [];
  // A failed fetch has no parsed key, so stamp the failure on the offer's last
  // successful observation row when one exists (keeping its observedAt/price/stock)
  // instead of writing a detached marker: the board's "last attempt" must reflect
  // the most recent check attempt, including a failed one.
