}

/**
 * Start a local HTTP server that behaves like the deployed read-only board.
 * Returns { url, port, observations, close }.
 */
export async function startQaServer({ port = 0, now = Date.now(), withTermsDemo = false, staleRefresh = false, interruptedRefresh = false, failedAttempt = false } = {}) {
  const observations = await fixtureObservations(failedAttempt ? now - 30 * 60 * 1000 : now);
  if (withTermsDemo) observations.push(termsDemoObservation(now));
  // `failedAttempt` simulates the most recent vendor check failing while the last
  // successful observation is preserved: the fixture pages are parsed 30 minutes
  // before the server's reference time, then the ranked CoffeeMan offer and the
  // unrankable Pucks offer keep their price, stock and observedAt while carrying
  // attemptedAt/lastError for the failed check, so the UI must disclose it.
  if (failedAttempt) {
    const failedAt = new Date(now).toISOString();
    for (const observation of observations) {
      const isFailed = (observation.vendor.id === 'coffeeman' && observation.product.packCount === 1)
        || observation.vendor.id === 'pucks';
      if (!isFailed) continue;
      observation.attemptedAt = failedAt;
      observation.lastError = FAILED_ATTEMPT_REASON;
    }
  }
  // `staleRefresh` simulates a board whose scheduled refresh has stopped running: the
  // offers are still as fresh as the fixture timestamps say, but the refresh is old.
  // `interruptedRefresh` simulates a run that saved observations but was stopped before
  // writing the completion marker (for example a redeploy killed the background job).
  const lastRefreshAt = interruptedRefresh ? null : new Date(staleRefresh ? now - 30 * 60 * 60 * 1000 : now).toISOString();
  const server = createServer((request, response) => {
    handle(request, response, { observations, now, withTermsDemo, lastRefreshAt, staleRefresh, interruptedRefresh, failedAttempt }).catch(error => {
      response.writeHead(500, { 'content-type': 'text/plain; charset=utf-8' });
      response.end(`qa server error: ${error?.message ?? error}`);
    });
  });
  await new Promise((resolvePromise, reject) => {
    server.once('error', reject);
    server.listen(port, '127.0.0.1', resolvePromise);
  });
  const { port: boundPort } = server.address();
  return {
    url: `http://127.0.0.1:${boundPort}`,
    port: boundPort,
    observations,
    close: () => new Promise(resolvePromise => server.close(() => resolvePromise()))
  };
}

async function handle(request, response, { observations, now, withTermsDemo, lastRefreshAt, staleRefresh, interruptedRefresh, failedAttempt }) {
  const url = new URL(request.url, 'http://127.0.0.1');
  if (url.pathname === '/api/catalog') {
    return json(response, {
      products: publicProducts(),
      destinations: DESTINATIONS,
      vendors: publicVendors()
    });
  }
  if (url.pathname === '/api/board') {
    const { product, retired } = resolveProductRequest(url.searchParams.get('product'));
    const variantId = resolveVariantId(product, url.searchParams.get('variant'));
    const grams = url.searchParams.get('grams') ?? '500';
    const destination = findDestination(url.searchParams.get('dest'));
    const board = quoteBoard({ observations, productId: product.id, variantId, targetGrams: grams, destination, fx: null, now });
    return json(response, {
      ...board,
      product: publicProducts().find(item => item.id === product.id) ?? null,
      requestedRetiredProduct: retired ? { id: retired.id, line: retired.line } : null,
      freshness: {
        ...refreshFreshness(lastRefreshAt, now, newestObservationAt(observations, TRACKED_PRODUCT_IDS)),
        fx: null,
        vendors: registeredVendors().map(vendor => {
          const failed = failedAttempt && (vendor.id === 'coffeeman' || vendor.id === 'pucks');
          const lastSuccessAt = observations.find(row => row.vendor.id === vendor.id && row.observedAt)?.observedAt
            ?? new Date(now).toISOString();
          return {
            vendorId: vendor.id,
            lastAttemptAt: new Date(now).toISOString(),
            lastSuccessAt: failed ? lastSuccessAt : new Date(now).toISOString(),
            consecutiveFailures: failed ? 1 : 0,
            // Synthetic due time: six hours after a successful refresh (matching the
            // Worker's schedule) or the 30-minute failure backoff so the footer
            // next-check and failure lines are both testable offline.
            nextAttemptAt: new Date(now + (failed ? 30 * 60 * 1000 : 6 * 60 * 60 * 1000)).toISOString(),
            lastErrors: failed ? [FAILED_ATTEMPT_REASON] : []
          };
        })
      },
      status: board.ranked.length > 0
        ? 'Delivered totals ranked from verified observations.'
        : 'No offer currently has enough verified information to rank. Unknowns are listed below.',
      qa: {
        mode: 'fixtures',
        demoOffers: withTermsDemo ? 1 : 0,
        staleRefresh,
        interruptedRefresh,
        failedAttempt,
        previousCheckMetadata: 1,
        note: withTermsDemo
          ? 'Offline browser QA server. Recorded fixtures plus one clearly labelled QA-only terms demo offer (not a real vendor) and one synthetic previous-check price for change rendering.'
          : 'Offline browser QA server. Data comes from tests/fixtures, not a live refresh; one offer carries synthetic previous-check metadata for change rendering.'
      }
    });
  }
  if (url.pathname.startsWith('/api/')) {
    return json(response, { error: 'Not found' }, 404);
  }
  return serveStatic(response, url.pathname);
}

async function serveStatic(response, pathname) {
  const relative = pathname === '/' ? 'index.html' : decodeURIComponent(pathname).replace(/^\/+/, '');
  const target = resolve(PUBLIC_DIR, relative);
  if (target !== PUBLIC_DIR && !target.startsWith(`${PUBLIC_DIR}${sep}`)) {
    return json(response, { error: 'Not found' }, 404);
  }
  try {
    const info = await stat(target);
    if (!info.isFile()) throw new Error('not a file');
    const body = await readFile(target);
    response.writeHead(200, {
      'content-type': MIME[extname(target).toLowerCase()] ?? 'application/octet-stream',
      'cache-control': 'no-store'
    });
    return response.end(body);
  } catch {
    return json(response, { error: 'Not found' }, 404);
  }
}

function json(response, body, status = 200) {
  response.writeHead(status, { 'content-type': 'application/json; charset=utf-8', 'cache-control': PUBLIC_CACHE });

#!/usr/bin/env node
// Reusable interactive browser-research helper (research/development only).
//
// It keeps ONE real headless Google Chrome + ChromeDriver session alive between
// shell invocations, so a researcher can navigate a real vendor site, read the
// rendered page, click/fill/select, wait for JavaScript and take screenshots
// step by step instead of asserting a fixed list of labels.
//
//   npm run research:browser -- start
//   npm run research:browser -- goto https://example.com/product
//   npm run research:browser -- text --limit 200
//   npm run research:browser -- elements "button, a[href*='cart']"
//   npm run research:browser -- click --text "Add to cart"
//   npm run research:browser -- fill "#city" "Tel Aviv"
//   npm run research:browser -- select "#city" --label "תל אביב"
//   npm run research:browser -- wait --text "Shipping" --timeout 15000
//   npm run research:browser -- shot pucks-cart --viewport 1440x1200
//   npm run research:browser -- stop
//
// The session file lives in .shurik-local/browser-research/ (git-ignored) and
// must never be committed: it contains a WebDriver session id, which is a
// browser secret. Screenshots and text dumps are written under
// .shurik-local/browser-research/ too; only curated, secret-free excerpts are
// copied into docs/evidence/.
//
// This helper is deliberately NOT part of the Worker runtime and is never
// imported by src/.

import { spawn } from 'node:child_process';
import { mkdir, readFile, writeFile, rm } from 'node:fs/promises';
import { existsSync } from 'node:fs';
import { setTimeout as delay } from 'node:timers/promises';
import path from 'node:path';

const STATE_DIR = process.env.BROWSER_RESEARCH_DIR ?? '.shurik-local/browser-research';
const SESSION_FILE = path.join(STATE_DIR, 'session.json');
const PORT = Number(process.env.BROWSER_RESEARCH_PORT ?? 9515);
const BASE = `http://127.0.0.1:${PORT}`;
const CHROME_BINARY = process.env.CHROME_BINARY ?? '/usr/bin/google-chrome';

const argv = process.argv.slice(2);
const command = argv[0];
const rest = argv.slice(1);

function flag(name, fallback = null) {
  const index = rest.indexOf(`--${name}`);
  if (index === -1) return fallback;
  const value = rest[index + 1];
  return value && !value.startsWith('--') ? value : true;
}
function positional() {
  const out = [];
  for (let i = 0; i < rest.length; i += 1) {
    if (rest[i].startsWith('--')) { if (rest[i + 1] && !rest[i + 1].startsWith('--')) i += 1; continue; }
    out.push(rest[i]);
  }
  return out;
}

async function http(method, url, body) {
  const response = await fetch(url, {
    method,
    headers: body === undefined ? undefined : { 'content-type': 'application/json' },
    body: body === undefined ? undefined : JSON.stringify(body)
  });
  const text = await response.text();
  let json = null;
  try { json = text ? JSON.parse(text) : null; } catch { /* non-JSON error page */ }
  return { status: response.status, json, text };
}

async function loadSession() {
  if (!existsSync(SESSION_FILE)) return null;
  try { return JSON.parse(await readFile(SESSION_FILE, 'utf8')); } catch { return null; }
}

async function sessionAlive(session) {
  if (!session?.sessionId) return false;
  const status = await http('GET', `${BASE}/status`).catch(() => null);
  if (!status || status.status !== 200) return false;
  const sessions = status.json?.value?.ready !== undefined ? await http('GET', `${BASE}/sessions`).catch(() => null) : null;
  if (sessions?.json?.value) return sessions.json.value.some(s => s.id === session.sessionId);
  return true;
}

async function requireSession() {
  const session = await loadSession();
  if (!session || !(await sessionAlive(session))) {
    console.error('no live browser session; run: npm run research:browser -- start');
    process.exit(2);
  }
  return session;
}

const wd = (session, method, url, body) => http(method, `${BASE}/session/${session.sessionId}${url}`, body);
const wdValue = async (session, method, url, body) => {
  const result = await wd(session, method, url, body);
  if (result.status >= 400) throw new Error(`${method} ${url} -> ${result.status}: ${result.text.slice(0, 500)}`);
  return result.json?.value;
};

async function evaluate(session, script, args = []) {
  return wdValue(session, 'POST', '/execute/sync', { script, args });
}

async function waitForDriver(timeoutMs = 15000) {
  const deadline = Date.now() + timeoutMs;
  while (Date.now() < deadline) {
    const status = await http('GET', `${BASE}/status`).catch(() => null);
    if (status?.status === 200) return true;
    await delay(250);
  }
  return false;
}

async function start() {
  await mkdir(STATE_DIR, { recursive: true });
  const existing = await loadSession();
  if (existing && (await sessionAlive(existing))) {
    console.log(JSON.stringify({ reused: true, sessionIdPresent: true, startedAt: existing.startedAt, port: PORT }, null, 2));
    return;
  }
  const driverUp = await http('GET', `${BASE}/status`).then(r => r.status === 200).catch(() => false);
  if (!driverUp) {
    const child = spawn('chromedriver', [`--port=${PORT}`, '--allowed-ips='], { detached: true, stdio: 'ignore' });
    child.unref();
    const ready = await waitForDriver(15000);
    if (!ready) throw new Error('chromedriver did not start');
  }
  const created = await http('POST', `${BASE}/session`, {
    capabilities: {
      alwaysMatch: {
        browserName: 'chrome',
        'goog:chromeOptions': {
          binary: CHROME_BINARY,
          args: ['--headless=new', '--no-sandbox', '--disable-dev-shm-usage', '--disable-gpu', '--log-level=SEVERE']
        }
      }
    }
  });

