  const productId = product.id;
  const requestedVariant = url.searchParams.get('variant');
  // A variant id that is not tracked at all (a typo or an old shared link) falls
  // back to the product's default, like an unknown product or destination. A real
  // variant of another line stays strict: it matches nothing on this board.
  const variantId = resolveVariantId(product, requestedVariant);
  const grams = url.searchParams.get('grams') ?? '500';
  const destination = findDestination(url.searchParams.get('dest'));
  const snapshot = await store.snapshot();
  const lastObservationAt = newestObservationAt(snapshot.observations, TRACKED_PRODUCT_IDS);
  const board = quoteBoard({
    observations: snapshot.observations,
    productId,
    variantId,
    targetGrams: grams,
    destination,
    fx: snapshot.meta?.fx ?? null,
    now: Date.now()
  });
  const vendors = snapshot.vendors ?? {};
  return json({
    ...board,
    product: publicProduct(product),
    requestedRetiredProduct: retired ? { id: retired.id, line: retired.line } : null,
    freshness: {
      ...refreshFreshness(snapshot.meta?.lastRefreshAt?.value ?? null, Date.now(), lastObservationAt),
      fx: snapshot.meta?.fx ? { asOf: snapshot.meta.fx.asOf, fetchedAt: snapshot.meta.fx.fetchedAt, source: snapshot.meta.fx.source?.name ?? null } : null,
      vendors: Object.values(vendors).map(state => ({
        vendorId: state.vendorId,
        lastAttemptAt: state.lastAttemptAt,
        lastSuccessAt: state.lastSuccessAt,
        consecutiveFailures: state.consecutiveFailures,
        nextAttemptAt: state.nextAttemptAt,
        lastErrors: state.lastErrors ?? []
      }))
    },
    status: board.ranked.length > 0
      ? 'Delivered totals ranked from verified observations.'
      : 'No offer currently has enough verified information to rank. Unknowns are listed below.'
  }, 200, {
    'Vary': 'Accept-Encoding',
    'Access-Control-Allow-Origin': '*'
  });
}

async function handleStatus(env) {
  if (!env.BOARD) return json({ status: 'storage not configured', vendors: [], runs: [] });
  const store = storeClient(durableStore(env));
  const snapshot = await store.snapshot();
  const lastObservationAt = newestObservationAt(snapshot.observations, TRACKED_PRODUCT_IDS);
  return json({
    lastRefreshAt: snapshot.meta?.lastRefreshAt?.value ?? null,
    lastObservationAt,
    freshness: refreshFreshness(snapshot.meta?.lastRefreshAt?.value ?? null, Date.now(), lastObservationAt),
    fx: snapshot.meta?.fx ? { asOf: snapshot.meta.fx.asOf, fetchedAt: snapshot.meta.fx.fetchedAt } : null,
    vendors: Object.values(snapshot.vendors ?? {}).map(state => ({
      vendorId: state.vendorId,
      lastAttemptAt: state.lastAttemptAt,
      lastSuccessAt: state.lastSuccessAt,
      consecutiveFailures: state.consecutiveFailures,
      nextAttemptAt: state.nextAttemptAt,
      lastErrors: state.lastErrors ?? []
    })),
    runs: (snapshot.runs ?? []).map(run => ({
      trigger: run.trigger,
      startedAt: run.startedAt,
      finishedAt: run.finishedAt,
      requests: run.requests,
      vendors: run.vendors
    })),
    observations: snapshot.observations.length
  });
}

export function publicVendors() {
  return registeredVendors().map(vendor => ({
    id: vendor.id,
    name: vendor.name,
    homepage: vendor.homepage,
    offers: vendor.offers.map(offer => ({ id: offer.id, url: offer.url, kind: offer.kind, productId: offer.productId ?? null }))
  }));
}

/** Public product shape: identity, packaging and the selectable variants. */
export function publicProduct(product) {
  if (!product) return null;
  return {
    id: product.id,
    brand: product.brand,
    line: product.line,
    form: product.form,
    packaging: product.packaging,
    targetMarket: product.targetMarket,
    defaultVariant: product.defaultVariant,
    variants: variantCatalog(product),
    notes: product.notes
  };
}

export function publicProducts() {
  return products.map(publicProduct);
}

function scheduleInitialRefresh(env, ctx) {
  const work = triggerInitialRefreshIfNeeded(env, ctx)
    .catch(error => console.warn('initial refresh trigger failed:', error?.stack ?? error));
  if (ctx?.waitUntil) ctx.waitUntil(work);
  return work;
}

export async function triggerInitialRefreshIfNeeded(env, ctx) {
  if (!env.BOARD) return { skipped: true, reason: 'no storage binding' };
  const store = storeClient(durableStore(env));
  return maybeInitialRefresh({ store, ctx });
}

// Board client. Fetches the read-only snapshot API and renders the comparison.
// All vendor text is inserted with textContent: fetched pages are untrusted data.

const state = {
  grams: 500,
  destination: 'tel-aviv',
  product: null,
  variant: null,
  showUnknown: true,
  catalog: null,
  board: null,
  error: null
};

const GRAMS_OPTIONS = [250, 500, 750, 1000, 2000];

// Monotonic request token: board requests can overlap when a shopper changes the
// quantity, destination or variant while a previous request is still in flight.
// Only the newest request may write state, so a slow earlier response can never
// overwrite the latest selection with a stale board.
let loadToken = 0;

const VARIANT_LABELS = { classico: 'Classico (strength 7)', forte: 'Forte', ricco: 'Ricco', risveglio: 'Risveglio', decaf: 'Decaffeinated', unspecified: 'Variant not stated' };

const ILS = new Intl.NumberFormat('en-IL', { style: 'currency', currency: 'ILS', maximumFractionDigits: 2 });
const IL_TIME = new Intl.DateTimeFormat('en-GB', {
  timeZone: 'Asia/Jerusalem', dateStyle: 'medium', timeStyle: 'short'
});

function el(tag, props = {}, ...children) {
  const node = document.createElement(tag);
  for (const [key, value] of Object.entries(props)) {
    if (value == null) continue;
    if (key === 'class') node.className = value;
    else if (key === 'text') node.textContent = value;
    else if (key === 'dataset') Object.assign(node.dataset, value);
    else if (key.startsWith('on')) node.addEventListener(key.slice(2).toLowerCase(), value);
    else if (key === 'attrs') for (const [a, v] of Object.entries(value)) node.setAttribute(a, v);
    else node[key] = value;
  }
  for (const child of children.flat()) {
    if (child == null) continue;
    node.append(child instanceof Node ? child : document.createTextNode(String(child)));
  }
  return node;
}

function money(amount) {
  return amount == null ? null : ILS.format(amount).replace('₪', '₪');
}

/** Short single-line failure reason for the offer rows; never a raw payload. */
function truncate(text, max = 120) {
  const value = String(text ?? '').replace(/\s+/g, ' ').trim();
  return value.length > max ? `${value.slice(0, max - 1)}…` : value;
}

const HEBREW = /[\u0590-\u05FF]/;

/**
 * Plain-language price comparison against the previous successful check of the
 * same offer. Rendered as text only when the quote actually carries previous
 * evidence; an impossible comparison says why instead of claiming "no change".
 */
function priceChangeText(quote) {
  const change = quote?.priceChange;
  if (!change) return null;
  const when = timeLabel(change.previousObservedAt);
  if (!change.comparable) return `Previous price not compared: ${change.reason} (previous check ${when})`;
  if (change.direction === 'same') return `Unit price unchanged since the previous check (${when})`;
  return `Unit price ${change.direction === 'down' ? 'down' : 'up'} ${money(change.deltaIls)} since the previous check (${when})`;
}

function stockChangeText(quote) {
  const previous = quote?.previous;
  if (!previous || previous.availability === quote.availability) return null;
  return `Stock changed since the previous check: was ${previous.availabilityLabel ?? previous.availability}`;
}

/** Accurate pack description: a multipack must never read as a single 250 g pack. */
function packDescription(quote) {
  const product = quote.product ?? {};
  const per = product.packGrams != null ? `${product.packGrams} g` : 'weight not stated';
  if ((product.packCount ?? 1) > 1) {
    return `${product.packCount} × ${per} multipack${product.totalGrams != null ? ` (${product.totalGrams} g)` : ''}`;
  }
  return `${per} pack`;
}

/** What the shopper actually buys for the selected target quantity. */
function quantityDescription(quote) {
  const product = quote.product ?? {};
  const units = quote.units ?? 1;
  if ((product.packCount ?? 1) > 1) {
    return `${units} multipack${units === 1 ? '' : 's'} (${product.packCount} × ${product.packGrams} g) = ${quote.orderedGrams} g`;
  }
  return `${units} × ${product.packGrams ?? '?'} g pack${units === 1 ? '' : 's'} = ${quote.orderedGrams} g`;
}

function itemSubtotalText(quote) {
  if (quote.itemTotalIls != null) return money(quote.itemTotalIls);
  const amount = quote.itemPrice?.amount;
  if (amount == null) return 'Unknown';
  return `${money(amount)} ${quote.itemPrice.currency ?? ''}`.trim();
}

function shippingValueText(quote) {
  const shipping = quote.shipping ?? {};
  if (shipping.amountIls != null) {
    if (shipping.amountIls === 0) return shipping.freeThreshold != null ? 'Free (threshold met)' : 'Free';
    return money(shipping.amountIls);
  }
  if (shipping.amount != null) return `${money(shipping.amount)} ${shipping.currency ?? ''} (not converted)`.trim();
  return 'Shipping not published';
}

function shippingServiceText(quote) {
  if (quote.shipping?.mode === 'pickup') return 'Pickup only';
  return quote.shipping?.certaintyLabel ?? 'Not published before checkout';
}

/** Item subtotal, shipping service and delivered total stay visible together. */
function totalsBlock(quote, { perKg = true } = {}) {
  return el('div', { class: 'totals' },
    el('div', { class: 'totals__cell' },
      el('span', { class: 'totals__label', text: 'Item subtotal' }),
      el('span', { class: 'totals__value num', text: itemSubtotalText(quote) })),
    el('div', { class: 'totals__cell' },
      el('span', { class: 'totals__label', text: 'Shipping' }),
      el('span', { class: 'totals__value num', text: shippingValueText(quote) }),
      el('span', { class: 'totals__meta', text: shippingServiceText(quote) })),
    el('div', { class: 'totals__cell totals__cell--total' },
      el('span', { class: 'totals__label', text: 'Delivered total' }),
      el('span', { class: 'totals__value num', text: quote.totalIls != null ? money(quote.totalIls) : 'Not calculable' }),
      perKg && quote.ilsPerKg != null ? el('span', { class: 'totals__meta num', text: `${money(quote.ilsPerKg)} per kg` }) : null));
}

/** Human label for a destination id, used by locality-restricted delivery areas. */
function destinationLabel(id) {
  const found = (state.catalog?.destinations ?? []).find(item => item.id === id);
  return found?.label ?? id;
}

/** One written conditions list per offer; the same caveat is not repeated on a card. */
function conditionsList(quote) {
  const shipping = quote.shipping ?? {};
  const items = [];
  if (shipping.freeThreshold != null) {
    items.push(quote.itemTotalIls != null && quote.itemTotalIls >= shipping.freeThreshold
      ? `Free-shipping threshold met (from ${money(shipping.freeThreshold)})`
      : `Free shipping from ${money(shipping.freeThreshold)} item subtotal`);
  }
  if (shipping.minOrder != null) items.push(`Minimum order ${money(shipping.minOrder)}`);
  const coverage = shipping.destination;
  if (coverage?.scope === 'localities') {
    const names = (coverage.localities ?? []).map(destinationLabel);
    items.push(names.length ? `Delivery area: only ${names.join(', ')}` : 'Delivery area: restricted locality list not published');
  }
  for (const alternative of shipping.alternatives ?? []) {
    items.push(`${alternative.label}: ${alternative.amountIls != null ? money(alternative.amountIls) : 'rate not published'}`);
  }
  if (shipping.pickup?.available) items.push(shipping.pickup.note ? `Self-pickup: ${shipping.pickup.note}` : 'Free self-pickup available (kept separate from delivery)');
  if (shipping.deliveryTime) items.push(`Delivery time: ${shipping.deliveryTime}`);
  if (shipping.maxTotalGrams != null) items.push(`Rate quoted for carts up to ${shipping.maxTotalGrams} g`);
  if (!items.length) return null;
  const list = el('ul', { class: 'conditions' });
  for (const item of items) list.append(el('li', {}, bidi(item)));
  return list;
}

function caveatBlock(quote) {
  if (!quote.shipping?.coverageCaveat) return null;
  return el('p', { class: 'caveat' }, el('strong', { text: 'Coverage: ' }), bidi(quote.shipping.coverageCaveat));
}

/** Previous-check, failure and evidence provenance, collapsed behind a disclosure. */
function diagnosticsDisclosure(quote) {
  const rows = [];
  const change = priceChangeText(quote);
  if (change) rows.push(change);
  const stockChange = stockChangeText(quote);
  if (stockChange) rows.push(stockChange);
  rows.push(`Last successful check: ${timeLabel(quote.observedAt)}`);
  if (quote.lastAttemptFailed) rows.push(`Last attempt failed ${timeLabel(quote.attemptedAt)}${quote.lastError ? ` — ${truncate(quote.lastError)}` : ''}`);
  // The adapter's shipping note carries observed conditions (thresholds, cart
  // sizes, coverage caveats) that are not decision values; it stays in this
  // collapsed disclosure instead of repeating on the card face.
  if (quote.shipping?.note) rows.push(`Shipping terms: ${quote.shipping.note}`);
  const evidence = quote.shipping?.evidence;
  if (evidence?.url) {
    rows.push(`Shipping evidence: ${evidence.url}${evidence.retrievedAt ? ` (retrieved ${timeLabel(evidence.retrievedAt)})` : ''}${evidence.note ? ` — ${truncate(evidence.note, 160)}` : ''}`);
  }
  const body = el('div', { class: 'disclosure__body' });
  for (const row of rows) body.append(el('div', { text: row }));
  return el('details', { class: 'disclosure' }, el('summary', { text: 'Check history and evidence' }), body);
}

/** Wrap Hebrew-containing text in an isolated dir="auto" span so mixed IL/Latin names render correctly. */
function bidi(text) {
  const value = text == null ? '' : String(text);
  if (!HEBREW.test(value)) return value;
  return el('span', { class: 'bidi', attrs: { dir: 'auto', lang: 'he' }, text: value });
}

function timeLabel(iso) {
  if (!iso) return 'never';
  const date = new Date(iso);
  if (Number.isNaN(date.getTime())) return 'unknown time';
  const hours = (Date.now() - date.getTime()) / 3_600_000;
  const relative = hours < 0.1 ? 'just now' : hours < 1 ? `${Math.round(hours * 60)} min ago` : hours < 48 ? `${Math.round(hours)} h ago` : `${Math.round(hours / 24)} d ago`;
  return `${IL_TIME.format(date)} (${relative})`;
}

/** Format a future due time. Vendor nextAttemptAt is a due time, not a promise, so the copy says so. */
function dueLabel(iso) {
  if (!iso) return 'not scheduled';
  const date = new Date(iso);
  if (Number.isNaN(date.getTime())) return 'unknown time';
  const hours = (date.getTime() - Date.now()) / 3_600_000;
  const relative = hours <= 0 ? 'due now' : hours < 1 ? `in ${Math.round(hours * 60)} min` : `in ${Math.round(hours)} h`;
  return `${IL_TIME.format(date)} (${relative})`;
}

function statusBadge(status, label) {
  const kind = status === 'in_stock' ? 'in_stock' : status === 'out_of_stock' ? 'out_of_stock' : 'unknown';
  return el('span', { class: `status status--${kind}`, text: label });
}

function offerLink(quote, label = 'Open the vendor page') {
  return el('a', { href: quote.itemUrl, rel: 'noopener noreferrer nofollow', target: '_blank', text: label });
}

async function load() {
  const token = ++loadToken;
  try {
    const catalogResponse = await fetch('/api/catalog').then(response => response.json());
    if (token !== loadToken) return;
    state.catalog = catalogResponse;
    applyProductDefaults();
    // A product id from the URL is sent as requested, even when it names a
    // retired line, so the API can report the fallback instead of hiding it.
    const requestedProduct = state.requestedProduct ?? state.product;
    const params = new URLSearchParams({ product: requestedProduct, grams: String(state.grams), dest: state.destination, variant: state.variant });
    const board = await fetch(`/api/board?${params}`).then(response => response.json());
    if (token !== loadToken) return;
    state.board = board;
    state.error = null;
  } catch (error) {
    if (token !== loadToken) return;
    state.error = error?.message ?? String(error);
  }
  if (token !== loadToken) return;
  document.body.dataset.boardState = state.error ? 'error' : 'ready';
  render();
}

/** Keep the selected product and variant valid for the catalog's tracked products. */
function applyProductDefaults() {
  const catalogProducts = state.catalog?.products ?? [];
  if (!catalogProducts.length) return;
  if (!catalogProducts.some(item => item.id === state.product)) state.product = catalogProducts[0].id;
  const product = currentProduct();
  const variants = (product?.variants ?? []).map(item => item.id);
  if (!variants.includes(state.variant)) state.variant = product?.defaultVariant ?? variants[0] ?? 'unspecified';
}

function currentProduct() {
  return (state.catalog?.products ?? []).find(item => item.id === state.product) ?? null;
}

function render() {
  renderControls();
  updateFooterStatus();
  const board = document.getElementById('board');
  board.replaceChildren();
  if (state.error) {
    board.append(el('div', { class: 'empty' },
      el('strong', { text: 'The board could not be loaded.' }),
      el('p', { text: `Reason: ${state.error}. The stored observations are safe; try again in a moment.` })));
    return;
  }
  if (!state.board) return;

  const boardData = state.board;
  if (boardData.requestedRetiredProduct) board.append(renderRetiredNotice(boardData.requestedRetiredProduct));
  board.append(renderRankedSection(boardData));
  const pickupSection = renderPickupSection(boardData.pickup);
  if (pickupSection) board.append(pickupSection);
  if (state.showUnknown) board.append(renderUnknownSection(boardData));
  board.append(renderFooterStatus(boardData));
}

function updateFooterStatus() {
  const node = document.getElementById('footer-status');
  if (!node) return;
  if (state.error) {
    node.textContent = 'The board could not be loaded from the snapshot API. Stored observations are safe; try again in a moment.';
    return;
  }
  const f = state.board?.freshness;
  const last = f?.lastRefreshAt;
  const observed = f?.lastObservationAt;
  const stale = f?.stale;
  const age = f?.ageHours;
  if (last) {
    node.textContent = `Last completed refresh: ${timeLabel(last)}.${stale ? ` No completed scheduled refresh for ${age} h — prices may be out of date.` : ''}`;
  } else if (observed) {
    node.textContent = `Last offer observation: ${timeLabel(observed)}. No refresh has completed on this deployment yet${stale ? ` — offer data is ${age} h old` : ''}.`;
  } else {
    node.textContent = stale
      ? 'No scheduled refresh has completed yet — prices may be missing or out of date.'
      : 'No completed refresh yet; the first scheduled run will populate the board.';
  }
}

function renderControls() {
  const quantityGroup = document.getElementById('quantity-group');
  if (!quantityGroup.dataset.ready) {
    for (const grams of GRAMS_OPTIONS) {
      quantityGroup.append(el('button', {
        type: 'button',
        text: grams >= 1000 ? `${grams / 1000} kg` : `${grams} g`,
        dataset: { grams: String(grams) },
        attrs: { 'aria-pressed': String(state.grams === grams) },
        onClick: () => update({ grams })
      }));
    }
    quantityGroup.dataset.ready = 'true';
  }
  for (const button of quantityGroup.querySelectorAll('button')) {
    button.setAttribute('aria-pressed', String(Number(button.dataset.grams) === state.grams));
  }

  const destination = document.getElementById('destination');
  if (state.catalog?.destinations && !destination.dataset.ready) {
    for (const item of state.catalog.destinations) {
      destination.append(el('option', { value: item.id, text: item.postcode ? `${item.label} · ${item.postcode} area` : item.label }));
    }
    destination.dataset.ready = 'true';
    destination.addEventListener('change', () => update({ destination: destination.value }));
  }
  destination.value = state.destination;
  const variant = document.getElementById('variant');
  const product = currentProduct();
  const labels = new Map((product?.variants ?? []).map(item => [item.id, item.label]));
  const observed = state.board?.variants ?? [];
  // Show every variant the product can be compared under; mark which ones were
  // actually observed so an empty result is explained rather than silently empty.
  const variants = (product?.variants ?? []).map(item => item.id);
  for (const id of observed) if (!variants.includes(id)) variants.push(id);
  const signature = `${product?.id ?? ''}|${variants.join(',')}`;
  if (variant.dataset.signature !== signature) {
    variant.replaceChildren();
    for (const id of variants) {
      const suffix = observed.includes(id) ? '' : ' — not observed yet';
      variant.append(el('option', { value: id, text: `${labels.get(id) ?? VARIANT_LABELS[id] ?? id}${suffix}` }));
    }
    variant.dataset.signature = signature;
    variant.addEventListener('change', () => update({ variant: variant.value }));
  }
  variant.value = state.variant ?? '';

  const productSelect = document.getElementById('product');
  const productStatic = document.getElementById('product-static');
  const catalogProducts = state.catalog?.products ?? [];
  // Owner correction 2026-10-12: exactly one product line is tracked, so the
  // selector is replaced by a static label instead of a dead one-option control.
  if (productSelect) productSelect.hidden = catalogProducts.length <= 1;
  if (productStatic) {
    productStatic.hidden = catalogProducts.length > 1;
    productStatic.textContent = catalogProducts.length === 1
      ? `${catalogProducts[0].brand} ${catalogProducts[0].line} · ${catalogProducts[0].form} in a ${catalogProducts[0].packaging}`
      : '';
  }
  const productSignature = catalogProducts.map(item => item.id).join(',');
  if (productSelect && productSelect.dataset.signature !== productSignature) {
    productSelect.replaceChildren();
    for (const item of catalogProducts) {
      productSelect.append(el('option', { value: item.id, text: `${item.brand} ${item.line} · ${item.form} ${item.packaging}` }));
    }
    productSelect.dataset.signature = productSignature;
    productSelect.addEventListener('change', () => update({ product: productSelect.value }));
  }
  if (productSelect && state.product) productSelect.value = state.product;

  const showUnknown = document.getElementById('show-unknown');
  showUnknown.checked = state.showUnknown;
  showUnknown.onchange = () => update({ showUnknown: showUnknown.checked });
}

function update(patch) {
  Object.assign(state, patch);
  // Any user interaction replaces the URL's original product request with the
  // tracked product, so a retired-line link is not kept in the shareable URL.
  state.requestedProduct = null;
  // Changing the product resets the variant to that product's default so a
  // Classico selection is never silently applied to a different line.
  if (patch.product) {
    const product = (state.catalog?.products ?? []).find(item => item.id === patch.product);
    state.variant = product?.defaultVariant ?? null;
  }
  applyProductDefaults();
  const params = new URLSearchParams({
    product: state.product ?? '',
    grams: String(state.grams),
    dest: state.destination,
    variant: state.variant ?? '',
    unknown: state.showUnknown ? '1' : '0'
  });
  history.replaceState(null, '', `?${params}`);
  renderControls();
  load();
}

function renderRetiredNotice(retired) {
  return el('div', { class: 'notice', attrs: { id: 'retired-product-notice', role: 'note' } },
    el('strong', { text: 'Retired product line' }),
    el('p', {},
      'This link asked for Lavazza ',
      bidi(retired.line),
      '. Only Lavazza Crema e Gusto vacuum-packed ground coffee is tracked now, so the board below compares Crema e Gusto offers only. Re-tracking another product line needs an explicit new owner instruction.'));
}

function renderRankedSection(board) {
  const section = el('section', { class: 'section', attrs: { id: 'ranked', 'aria-labelledby': 'ranked-title' } });
  const product = currentProduct();
  section.append(el('div', { class: 'section__head' },
    el('div', { class: 'section__kicker', text: '01 / Delivered comparison' }),
    el('h2', { attrs: { id: 'ranked-title' }, text: 'Item subtotal + shipping = delivered total' }),
    el('p', { class: 'section__intro', text: `${board.product?.line ?? product?.line ?? 'Crema e Gusto'} ${board.product?.form ?? 'ground'} (${board.product?.packaging ?? 'vacuum brick'}), ${board.targetGrams} g to ${board.destination.label}.` })));

  if (!board.best) {
    section.append(el('div', { class: 'empty' },
      el('strong', { text: 'No offer can be ranked right now.' }),
      el('p', { text: 'Ranking needs a fresh confirmed stock observation and a published shipping price. The offers below explain exactly what is missing.' })));
    return section;
  }

  section.append(renderOfferCard(board.best, board, { best: true }));
  const others = board.ranked.slice(1);
  if (others.length) {
    section.append(el('h3', { class: 'section__kicker', text: 'Other ranked offers' }));
    const list = el('div', { class: 'offer-list' });
    for (const quote of others) list.append(renderOfferCard(quote, board, { best: false }));
    section.append(list);
  }
  if (board.counts?.excludedByVariant > 0) {
    const labels = (board.counts.excludedVariants ?? []).map(id => VARIANT_LABELS[id] ?? id).join(', ');
    section.append(el('p', { class: 'meta-line', text: `${board.counts.excludedByVariant} observed offer(s) for another blend variant (${labels || 'unspecified'}) stay out of this comparison so variants are never merged. Switch the variant control to compare them.` }));
  }
  const perKgWinner = board.bestPerKg && board.best && board.bestPerKg.key !== board.best.key ? board.bestPerKg : null;
  if (perKgWinner) {
    const pack = (perKgWinner.packCount ?? 1) > 1
      ? `${perKgWinner.packCount} × ${perKgWinner.packGrams} g multipack`
      : `${perKgWinner.packGrams} g pack`;
    section.append(el('p', { class: 'meta-line' },
      'Cheapest per kilogram: ',
      bidi(perKgWinner.vendor?.name ?? ''),
      ` — ${money(perKgWinner.ilsPerKg)} per kg (${perKgWinner.units} × ${pack}, delivered ${money(perKgWinner.totalIls)})`));
  }
  section.append(el('p', { class: 'meta-line', text: 'Comparison total = item subtotal + shipping + mandatory fees, converted to ILS where a stored Bank of Israel reference rate is needed. This is not a personalized checkout quote.' }));
  return section;
}

/** One offer card: identity, pack/quantity, the three money values together and the conditions. */
function renderOfferCard(quote, board, { best }) {
  const card = el('article', { class: best ? 'offer offer--best' : 'offer' });
  if (best) card.append(el('div', { class: 'offer__top' }, el('span', { class: 'tag tag--best', text: 'Best known delivered total' })));
  card.append(el('div', { class: 'offer__top' },
    el('div', { class: 'offer__vendor' }, bidi(quote.vendor.name), statusBadge(quote.availability, quote.availabilityLabel)),
    el('div', { class: 'offer__delta', text: offerDeltaText(quote, board, best) })));
  card.append(el('p', { class: 'offer__product' }, bidi(quote.product.name ?? 'Tracked product')));
  card.append(el('p', { class: 'offer__pack', text: `${packDescription(quote)} · ${quantityDescription(quote)} · ${quote.product.variantLabel}` }));
  card.append(totalsBlock(quote));
  if (quote.estimate) card.append(el('p', { class: 'unknown__meta' }, el('span', { class: 'status status--estimate', text: 'Estimate' }), ' includes a converted or estimated component'));
  const conditions = conditionsList(quote);
  if (conditions) card.append(conditions);
  const caveat = caveatBlock(quote);
  if (caveat) card.append(caveat);
  card.append(el('div', { class: 'offer__links' }, offerLink(quote, 'Open the vendor page')));
  card.append(diagnosticsDisclosure(quote));
  return card;
}

function offerDeltaText(quote, board, best) {
  if (best) return 'Cheapest delivered total for this selection';
  const delta = board.best && Number.isFinite(quote.totalIls) && Number.isFinite(board.best.totalIls)
    ? Math.round((quote.totalIls - board.best.totalIls) * 100) / 100
    : null;
  if (delta == null) return '';
  if (delta === 0) return 'Same delivered total as the best offer';
  return `+${money(delta)} vs best delivered total`;
}

function renderPickupSection(pickup = []) {
  if (!pickup.length) return null;
  const section = el('section', { class: 'section', attrs: { id: 'pickup', 'aria-labelledby': 'pickup-title' } });
  section.append(el('div', { class: 'section__head' },
    el('div', { class: 'section__kicker', text: '02 / Pickup only' }),
    el('h2', { attrs: { id: 'pickup-title' }, text: 'Pickup-only offers' }),
    el('p', { class: 'section__intro', text: 'Pickup is not a delivered price and never competes in the delivered ranking. Pickup that accompanies a delivered offer is shown on that offer card.' })));
  for (const quote of pickup) {
    // Pickup entries keep the delivery observation but carry their own pickup
    // terms. They are rendered as one compact row each: the repeated pickup
    // caveats live in a shared disclosure instead of three near-identical
    // three-cell cards.
    const pickupFee = quote.pickup?.amount?.amount;
    const feeText = pickupFee === 0 ? 'Free' : pickupFee != null ? money(pickupFee) : 'See vendor policy';
    const terms = [quote.pickup?.note, quote.labels.join('. ')].filter(Boolean).join(' ');
    section.append(el('div', { class: 'pickup-row' },
      el('div', { class: 'pickup-row__head' },
        el('strong', { text: bidi(quote.vendor.name) }),
        el('span', { class: 'pickup-row__pack', text: `${packDescription(quote)} · ${quantityDescription(quote)}` })),
      el('div', { class: 'pickup-row__facts' },
        el('span', { text: `Item subtotal: ${itemSubtotalText(quote)}` }),
        el('span', { text: `Pickup fee: ${feeText}` }),
        el('span', { text: 'Self-pickup, not delivery' }),
        el('span', { text: 'Delivered total: Not applicable' })),
      terms ? el('details', { class: 'disclosure' },
        el('summary', { text: 'Pickup terms' }),
        el('p', { class: 'disclosure__body', text: terms })) : null,
      el('p', { class: 'pickup-row__link' }, offerLink(quote, 'Open the vendor page'))));
  }
  return section;
}

function renderUnknownSection(board) {
  const section = el('section', { class: 'section', attrs: { id: 'unknown', 'aria-labelledby': 'unknown-title' } });
  section.append(el('div', { class: 'section__head' },
    el('div', { class: 'section__kicker', text: '03 / Not comparable yet' }),
    el('h2', { attrs: { id: 'unknown-title' }, text: 'Offers with missing information' }),
    el('p', { class: 'section__intro', text: 'These observations stay visible with their source, timestamp and the exact reason a delivered total cannot be calculated. Missing shipping is never treated as zero.' })));

  const entries = [...board.unrankable, ...board.staleOrUnavailable];
  if (!entries.length) {
    section.append(el('p', { class: 'meta-line', text: 'Nothing is missing right now: every stored offer has enough verified information to compare.' }));
    return section;
  }
  const list = el('div', { class: 'unknown-list' });
  for (const quote of entries) {
    const card = el('article', { class: 'unknown' });
    card.append(el('div', { class: 'unknown__vendor' }, bidi(quote.vendor.name), ' ', statusBadge(quote.availability, quote.availabilityLabel)));
    card.append(el('div', { class: 'unknown__meta' }, bidi(quote.product.name ?? '')));
    card.append(el('div', { class: 'unknown__meta', text: `${packDescription(quote)} · ${quantityDescription(quote)} · ${quote.product.variantLabel}` }));
    card.append(el('div', { class: 'unknown__grid' },
      el('span', { text: `Item subtotal: ${itemSubtotalText(quote)}` }),
      el('span', { text: `Shipping: ${shippingValueText(quote)}` }),
      el('span', { text: `Last successful check: ${timeLabel(quote.observedAt)}` }),
      quote.lastAttemptFailed ? el('span', { text: `Last attempt failed ${timeLabel(quote.attemptedAt)}${quote.lastError ? ` — ${truncate(quote.lastError)}` : ''}` }) : null));
    if (quote.shipping?.certainty === 'unknown' || quote.shipping?.amount == null) {
      card.append(el('p', { class: 'unknown__reason', text: 'Shipping not published. Needed for a delivered total: a published rate or a public checkout-estimator quote for this quantity and locality. A missing rate is never counted as free.' }));
    }
    card.append(el('p', { class: 'unknown__reason', text: quote.reasons.join('. ') || quote.labels.join('. ') || 'Not enough verified information yet.' }));
    const caveat = caveatBlock(quote);
    if (caveat) card.append(caveat);
    card.append(el('p', {}, offerLink(quote, 'Check this vendor page')));
    list.append(card);
  }
  section.append(list);
  return section;
}

function renderFooterStatus(board) {
  const vendors = board.freshness?.vendors ?? [];
  const failing = vendors.filter(vendor => (vendor.consecutiveFailures ?? 0) > 0);
  const freshness = board.freshness ?? {};
  const dataAsOf = freshness.dataAsOf ?? freshness.lastRefreshAt ?? freshness.lastObservationAt ?? null;
  const wrap = el('div', { class: 'meta-line' });
  wrap.append(el('div', { text: `Board data as of: ${timeLabel(dataAsOf)} · Offers observed for this variant: ${board.counts.observed} · Ranked: ${board.counts.ranked}` }));
  if (freshness.stale) {
    const age = freshness.ageHours;
    wrap.append(el('div', { class: 'status status--stale', text: freshness.lastRefreshAt
      ? `Scheduled refresh overdue by ${age} h — prices may be out of date.`
      : freshness.lastObservationAt
        ? `No completed scheduled refresh; the newest offer observation is ${age} h old — prices may be out of date.`
        : 'No scheduled refresh has completed yet — prices may be missing or out of date.' }));
  }
  if (failing.length) {
    wrap.append(el('div', { class: 'status status--stale', text: `${failing.length} source(s) failing` }));
  }
  // FX, per-vendor and next-due diagnostics are useful provenance but not
  // decision information, so they live behind a disclosure instead of filling
  // the first screen.
  const body = el('div', { class: 'disclosure__body' });
  if (freshness.fx) {
    body.append(el('div', { text: `Exchange rates: ${freshness.fx.source ?? 'Bank of Israel'} published ${freshness.fx.asOf ?? 'unknown'} · fetched ${timeLabel(freshness.fx.fetchedAt)}` }));
  } else {
    body.append(el('div', { text: 'Exchange rates: no official rate table stored yet, so foreign-currency offers cannot be ranked.' }));
  }
  for (const vendor of vendors) {
    body.append(el('div', { text: `${vendor.vendorId}: last success ${timeLabel(vendor.lastSuccessAt)} · last attempt ${timeLabel(vendor.lastAttemptAt)}` }));
  }
  const nextDue = vendors.map(vendor => vendor.nextAttemptAt).filter(Boolean).sort()[0] ?? null;
  if (nextDue) {
    body.append(el('div', { text: `Next source check due (approximate, set by each vendor's last run): ${dueLabel(nextDue)}` }));
  }
  for (const vendor of failing) {
    body.append(el('div', { text: `${vendor.vendorId}: ${vendor.consecutiveFailures} consecutive failure(s) · next attempt ${timeLabel(vendor.nextAttemptAt)}${vendor.lastErrors?.[0] ? ` · last error: ${vendor.lastErrors[0]}` : ''}` }));
  }
  wrap.append(el('details', { class: 'disclosure' }, el('summary', { text: 'Refresh diagnostics' }), body));
  return wrap;
}

const params = new URLSearchParams(location.search);
state.grams = Number(params.get('grams')) || 500;
state.destination = params.get('dest') || 'tel-aviv';
state.product = params.get('product') || null;
state.requestedProduct = params.get('product') || null;
state.variant = params.get('variant') || null;
state.showUnknown = params.get('unknown') !== '0';
load();

// Pure quote and ranking engine.
//
// Comparison total = item price + shipping + mandatory fees, normalized to ILS.
// Unknown shipping, unknown FX, stale observations, unknown availability and
// out-of-stock observations never become zero and never win.
// Pickup options are kept separate from delivered offers.

import { toIls } from './fx.js';

export const DEFAULT_STALE_AFTER_MS = 24 * 60 * 60 * 1000;
export const CLOCK_SKEW_MS = 5 * 60 * 1000;

export const DESTINATIONS = [
  { id: 'tel-aviv', label: 'Tel Aviv–Yafo', postcode: '6100000', country: 'IL' },
  { id: 'jerusalem', label: 'Jerusalem', postcode: '9100000', country: 'IL' },
  { id: 'haifa', label: 'Haifa', postcode: '3100000', country: 'IL' },
  { id: 'beer-sheva', label: "Be'er Sheva", postcode: '8400000', country: 'IL' },
  { id: 'eilat', label: 'Eilat', postcode: '8800000', country: 'IL' },
  { id: 'other', label: 'Elsewhere in Israel', postcode: null, country: 'IL' }
];

export function findDestination(id) {
  return DESTINATIONS.find(item => item.id === id) ?? DESTINATIONS[DESTINATIONS.length - 1];
}

const AVAILABILITY_LABELS = {
  in_stock: 'In stock (observed)',
  out_of_stock: 'Out of stock (observed)',
  unknown: 'Availability unknown'
};

/**
 * Plain-language shipping certainty. The board never presents an unknown rate as
 * free, so the label says where the amount came from (or that it is missing)
 * instead of relying on a color or a bare "verified" flag.
 */
const SHIPPING_CERTAINTY_LABELS = {
  verified: 'Published rate (verified)',
  // A rate read from an anonymous public cart/checkout estimator is observed
  // and usable for the recorded cart, but the vendor never published it on the
  // product page, so the label keeps the condition visible instead of calling
  // it a published or completed checkout price.
  checkout_quote: 'Checkout rate (observed, conditional)',
  estimated: 'Estimated rate',
  unknown: 'Not published before checkout'
};

export function shippingCertaintyLabel(certainty) {
  return SHIPPING_CERTAINTY_LABELS[certainty] ?? SHIPPING_CERTAINTY_LABELS.unknown;
}

export function quoteBoard({
  observations = [],
  productId,
  variantId = null,
  targetGrams = 500,
  destination = DESTINATIONS[0],
  fx = null,
  now = Date.now(),
  staleAfterMs = DEFAULT_STALE_AFTER_MS
} = {}) {
  const grams = clampGrams(targetGrams);
  const quotes = [];
  const variants = new Set();
  const excludedVariants = new Set();
  let excludedByVariant = 0;
  for (const observation of observations) {
    if (productId && observation?.product?.productId !== productId) continue;
    if (observation?.product?.form !== 'ground') continue;
    variants.add(observation?.product?.variantId ?? 'unspecified');
    if (variantId && (observation?.product?.variantId ?? 'unspecified') !== variantId) {
      // Kept out of this ranking on purpose: variants are never merged. The
      // count lets the UI tell the shopper that offers for another variant exist.
      excludedByVariant += 1;
      excludedVariants.add(observation?.product?.variantId ?? 'unspecified');
      continue;
    }
    quotes.push(quoteOffer(observation, { grams, destination, fx, now, staleAfterMs }));
  }
  const ranked = quotes.filter(quote => quote.rankable).sort(compareQuotes);
  // The cheapest delivered total is not always the cheapest bulk value. Keep the
  // per-kilogram winner as separate structured evidence so the board can call it
  // out without changing the ranking itself.
  const bestPerKgQuote = ranked.length
    ? ranked.reduce((min, quote) => (quote.ilsPerKg < min.ilsPerKg ? quote : min))
    : null;
  const pickup = [
    ...quotes.filter(quote => quote.group === 'pickup'),
    ...quotes
      .filter(quote => quote.group !== 'pickup' && quote.shipping?.pickup?.available)
      .map(toPickupEntry)
  ];
  const unrankable = quotes.filter(quote => quote.group === 'unrankable');
  const staleOrUnavailable = quotes.filter(quote => quote.group === 'stale_unavailable');
  const unknown = [...unrankable, ...staleOrUnavailable];
  return {
    productId,
    variantId,
    variants: [...variants].sort(),
    targetGrams: grams,
    destination,
    generatedAt: new Date(now).toISOString(),
    fx: fx ? { asOf: fx.asOf ?? null, source: fx.source?.name ?? null } : null,
    best: ranked[0] ?? null,
    bestPerKg: bestPerKgQuote
      ? {
          key: bestPerKgQuote.key,
          vendor: bestPerKgQuote.vendor,
          ilsPerKg: bestPerKgQuote.ilsPerKg,
          totalIls: bestPerKgQuote.totalIls,
          units: bestPerKgQuote.units,
          orderedGrams: bestPerKgQuote.orderedGrams,
          packGrams: bestPerKgQuote.product.packGrams,
          packCount: bestPerKgQuote.product.packCount
        }
      : null,
    ranked,
    pickup,
    unrankable,
    staleOrUnavailable,
    unknown,
    counts: {
      observed: quotes.length,
      ranked: ranked.length,
      pickup: pickup.length,
      unknown: unknown.length,
      excludedByVariant,
      excludedVariants: [...excludedVariants].sort()
    }
  };
}

export function quoteOffer(observation, { grams, destination, fx, now, staleAfterMs }) {
  const product = observation.product ?? {};
  const price = observation.price ?? {};
  const shipping = observation.shipping ?? {};
  const reasons = [];
  const labels = [];

  const ageMs = observation.observedAt ? now - Date.parse(observation.observedAt) : null;
  const stale = ageMs == null || ageMs > staleAfterMs || ageMs < -CLOCK_SKEW_MS;
  const freshness = ageMs == null ? 'unknown' : stale ? 'stale' : 'fresh';

  const base = {
    key: observation.key,
    vendor: observation.vendor,
    itemUrl: observation.itemUrl,
    product: {
      productId: product.productId,
      name: product.name ?? null,
      variantId: product.variantId ?? 'unspecified',
      variantLabel: product.variantLabel ?? 'Variant not stated',
      form: product.form,
      packGrams: product.packGrams ?? null,
      packCount: product.packCount ?? 1,
      totalGrams: product.totalGrams ?? null,
      sku: product.sku ?? null
    },
    availability: observation.availability ?? 'unknown',
    availabilityLabel: AVAILABILITY_LABELS[observation.availability] ?? AVAILABILITY_LABELS.unknown,
    freshness,
    ageHours: ageMs == null ? null : Math.round((ageMs / 3_600_000) * 10) / 10,
    observedAt: observation.observedAt ?? null,
    attemptedAt: observation.attemptedAt ?? null,
    // A failed last attempt keeps the previous good price and stock, but the
    // board must be able to say that the most recent check failed instead of
    // presenting the row as freshly re-checked.
    lastError: observation.lastError ?? null,
    lastAttemptFailed: Boolean(observation.lastError),
    evidence: observation.evidence ?? [],
    previous: summarizePrevious(observation.previous),
    priceChange: priceChangeOf({ current: price, previous: observation.previous, product, fx }),
    units: null,
    orderedGrams: null,
    itemPrice: { amount: price.amount ?? null, currency: price.currency ?? null },
    itemTotalIls: null,
    shipping: {
      mode: shipping.mode ?? 'delivery',
      certainty: shipping.certainty ?? 'unknown',
      certaintyLabel: shippingCertaintyLabel(shipping.certainty ?? 'unknown'),
      amount: shipping.amount?.amount ?? null,
      currency: shipping.amount?.currency ?? null,
      amountIls: null,
      freeThreshold: shipping.freeThreshold?.amount ?? null,
      freeThresholdCurrency: shipping.freeThreshold?.currency ?? null,
      minOrder: shipping.minOrder?.amount ?? null,
      minOrderCurrency: shipping.minOrder?.currency ?? null,
      destination: shipping.destination ?? { scope: 'country', country: 'IL' },
      deliveryTime: shipping.deliveryTime ?? null,
      maxTotalGrams: shipping.maxTotalGrams ?? null,
      pickup: shipping.pickup ?? null,
      alternatives: (shipping.alternatives ?? []).map(alternative => {
        const converted = toIls(alternative.amount?.amount ?? null, alternative.amount?.currency ?? price.currency, fx);
        return {
          id: alternative.id ?? null,
          label: alternative.label ?? 'Alternative shipping option',
          amount: alternative.amount?.amount ?? null,
          currency: alternative.amount?.currency ?? price.currency ?? null,
          amountIls: converted.known ? round2(converted.amount) : null,
          note: alternative.note ?? null
        };
      }),
      note: shipping.note ?? null,
      evidence: shipping.evidence ?? null
    },
    mandatoryFees: [],
    totalIls: null,
    ilsPerKg: null,
    estimate: false,
    rankable: false,
    reasons,
    labels,
    group: 'unrankable'
  };

  if (observation.shipping?.mode === 'pickup') {
    base.group = 'pickup';
    base.labels.push('Pickup only — not a delivered offer');
    if (product.totalGrams) {
      base.units = Math.max(1, Math.ceil(grams / product.totalGrams));
      base.orderedGrams = base.units * product.totalGrams;
    }
    const pickupTotal = toIls(price.amount == null ? null : price.amount * (base.units ?? 1), price.currency, fx);
    if (pickupTotal.known) {
      base.itemTotalIls = round2(pickupTotal.amount);
      base.labels.push('Shown for pickup comparison only');
    }
    if (stale) {
      base.labels.push('Stale observation — the last successful check is too old; treat the item total as out of date');
    }
    return base;
  }

  if (!product.totalGrams || !product.packGrams) {
    reasons.push('Pack weight is not stated, so the delivered price per kilogram cannot be calculated');
    return base;
  }

  const units = Math.max(1, Math.ceil(grams / product.totalGrams));
  base.units = units;
  base.orderedGrams = units * product.totalGrams;

  const itemTotal = toIls(price.amount == null ? null : price.amount * units, price.currency, fx);
  if (!itemTotal.known) {
    reasons.push(price.amount == null
      ? 'Item price was not observed'
      : `No ${price.currency} reference rate is stored, so the total cannot be converted to ILS`);
    if (price.amount != null && Number.isFinite(price.amount)) {
      base.itemPrice.amount = round2(price.amount * units);
    }
    return base;
  }
  base.itemTotalIls = round2(itemTotal.amount);
  if (itemTotal.converted) base.estimate = true;

  // A rate observed on a smaller anonymous cart is not silently stretched to a
  // bigger one: the offer stays visible and unrankable with the exact reason.
  if (shipping.maxTotalGrams != null && base.orderedGrams > shipping.maxTotalGrams) {
    reasons.push(`Shipping was quoted only for carts up to ${shipping.maxTotalGrams} g, but this quantity is ${base.orderedGrams} g`);
    return base;
  }

  if (shipping.minOrder != null) {
    const min = toIls(shipping.minOrder.amount, shipping.minOrder.currency ?? price.currency, fx);
    if (min.known && base.itemTotalIls < min.amount - 0.005) {
      reasons.push(`Order is below the vendor minimum order of ${formatAmount(min.amount, 'ILS')}`);
      return base;
    }
  }

  const coverage = coverageProblem(shipping.destination, destination);
  if (coverage) {
    reasons.push(coverage);
    return base;
  }
  // A published rate whose locality list is not published is a disclosed caveat,
  // not a blocker: the vendor states home delivery is subject to the list, so the
  // board keeps ranking but never claims unconditional coverage of the destination.
  const coverageCaveat = typeof shipping.destination?.caveat === 'string' && shipping.destination.caveat.trim()
    ? shipping.destination.caveat.trim()
    : null;
  if (coverageCaveat) {
    base.shipping.coverageCaveat = coverageCaveat;
    base.labels.push(`Delivery coverage caveat: ${coverageCaveat}`);
  }

  if (observation.availability === 'out_of_stock') {
    base.labels.push('Out of stock at last successful check');
    base.group = 'stale_unavailable';
    return base;
  }
  if (observation.availability !== 'in_stock') {
    reasons.push('Stock was not confirmed by the source, so this offer cannot be confirmed as available');
    base.group = 'stale_unavailable';
    return base;
  }

  const feeSum = { amount: 0, currency: 'ILS' };
  for (const fee of observation.mandatoryFees ?? []) {
    const converted = toIls(fee.amount, fee.currency, fx);
    if (!converted.known) {
      reasons.push(`A mandatory fee (${fee.label ?? 'unlabelled'}) could not be converted to ILS`);
      return base;
    }
    feeSum.amount += converted.amount;
    base.mandatoryFees.push({ label: fee.label ?? 'Mandatory fee', amountIls: round2(converted.amount) });
  }

  let shippingIls = null;
  if (shipping.certainty === 'unknown' || shipping.amount == null) {
    reasons.push(shipping.note
      ? `Shipping is not published before checkout, so it is treated as unknown, not free (${shipping.note})`
      : 'Shipping is not published before checkout, so it is treated as unknown, not free');
    return base;
  }
  const convertedShipping = toIls(shipping.amount.amount ?? shipping.amount, shipping.amount.currency ?? price.currency, fx);
  if (!convertedShipping.known) {
    reasons.push(`Shipping is quoted in ${shipping.amount.currency ?? 'an unknown currency'} with no stored reference rate`);
    return base;
  }
  shippingIls = convertedShipping.amount;
  if (convertedShipping.converted || shipping.certainty === 'estimated') base.estimate = true;

  if (shipping.freeThreshold != null) {
    const threshold = toIls(shipping.freeThreshold.amount, shipping.freeThreshold.currency, fx);
    if (threshold.known && base.itemTotalIls >= threshold.amount - 0.005) {
      shippingIls = 0;
      base.labels.push(`Free shipping threshold met (${formatAmount(threshold.amount, 'ILS')})`);
    }
  }

  base.shipping.amountIls = round2(shippingIls);
  if (stale) {
    labels.push('Stale observation — the last successful check is too old to rank');
    base.group = 'stale_unavailable';
    return base;
  }

  base.totalIls = round2(base.itemTotalIls + shippingIls + feeSum.amount);
  base.ilsPerKg = round2((base.totalIls / base.orderedGrams) * 1000);
  base.rankable = true;
  base.group = 'ranked';
  if (base.estimate) labels.push('Estimate — includes a converted or estimated component');
  return base;
}

/** Shape the stored previous-check snapshot for the API without leaking raw payloads. */
function summarizePrevious(previous) {
  if (!previous || typeof previous !== 'object') return null;
  const availability = previous.availability ?? 'unknown';
  return {
    observedAt: previous.observedAt ?? null,
    priceAmount: previous.price?.amount ?? null,
    priceCurrency: previous.price?.currency ?? null,
    availability,
    availabilityLabel: AVAILABILITY_LABELS[availability] ?? AVAILABILITY_LABELS.unknown
  };
}

/**
 * Compare the unit price with the previous successful check.
 * The comparison is in ILS using the stored Bank of Israel rate when needed, is
 * only made between equal pack weights, and is never reported as "no change"
 * when a conversion is impossible.
 */
function priceChangeOf({ current, previous, product, fx }) {
  const previousPrice = previous?.price;
  if (!previous?.observedAt || previousPrice?.amount == null || current?.amount == null) return null;
  const previousObservedAt = previous.observedAt;
  const previousAmount = previousPrice.amount;
  const previousCurrency = previousPrice.currency ?? current.currency ?? null;
  if (previous.totalGrams != null && product.totalGrams != null && previous.totalGrams !== product.totalGrams) {
    return {
      comparable: false,
      reason: 'the pack size changed since the previous check, so the unit prices are not comparable',
      previousObservedAt,
      previousAmount,
      previousCurrency
    };
  }
  const before = toIls(previousAmount, previousCurrency, fx);
  const after = toIls(current.amount, current.currency ?? previousCurrency, fx);
  if (!before.known || !after.known) {
    return {
      comparable: false,
      reason: 'a stored exchange rate is needed to compare the previous price',
      previousObservedAt,
      previousAmount,
      previousCurrency
    };
  }
  const delta = round2(after.amount - before.amount);
  return {
    comparable: true,
    direction: delta < 0 ? 'down' : delta > 0 ? 'up' : 'same',
    deltaIls: Math.abs(delta),
    previousAmount,
    previousCurrency,
    previousIls: round2(before.amount),
    previousObservedAt
  };
}

function coverageProblem(shippingDestination, destination) {
  if (!shippingDestination) return null;
  if (shippingDestination.scope === 'country') {
    if (destination?.country && shippingDestination.country !== destination.country) {
      return `Vendor does not deliver to ${destination.country}`;
    }
    return null;
  }
  if (shippingDestination.scope === 'localities') {
    const localities = shippingDestination.localities ?? [];
    if (!destination?.id || !localities.includes(destination.id)) {
      return `Vendor delivery list does not include ${destination?.label ?? 'this destination'}`;
    }
    return null;
  }
  return 'Vendor delivery coverage is not documented';
}

function toPickupEntry(quote) {
  const itemTotal = quote.itemTotalIls ?? (quote.itemPrice.amount != null && quote.units
    ? round2(quote.itemPrice.amount * quote.units)
    : null);
  return {
    ...quote,
    key: `${quote.key}:pickup`,
    group: 'pickup',
    rankable: false,
    totalIls: null,
    ilsPerKg: null,
    itemTotalIls: itemTotal,
    pickup: {
      available: true,
      amount: quote.shipping.pickup?.amount ?? null,
      note: quote.shipping.pickup?.note ?? null
    },
    labels: [...quote.labels.filter(label => !label.startsWith('Delivery coverage caveat:')), 'Pickup only — not a delivered offer']
  };
}

function compareQuotes(a, b) {
  if (a.totalIls !== b.totalIls) return a.totalIls - b.totalIls;
  if (a.ilsPerKg !== b.ilsPerKg) return a.ilsPerKg - b.ilsPerKg;
  return String(a.vendor?.name ?? '').localeCompare(String(b.vendor?.name ?? ''));
}

export function clampGrams(value) {
  const grams = Number(value);
  if (!Number.isFinite(grams) || grams <= 0) return 500;
  return Math.min(Math.max(Math.round(grams), 1), 100_000);
}

export function formatAmount(amount, currency = 'ILS') {
  const symbols = { ILS: '₪', USD: '$', EUR: '€', GBP: '£' };
  const symbol = symbols[String(currency).toUpperCase()] ?? `${currency} `;
  return `${symbol}${Number(amount).toFixed(2)}`;
}

function round2(value) {
  return Math.round(value * 100) / 100;
}

// Pucks (pucks.co.il), Ramla, Israel — the one tracked product line:
// Lavazza Crema e Gusto Classico 250 g ground coffee in a vacuum brick.
// The Qualità Oro, Qualità Rossa and Suerte pages were retired by the
// 2026-10-12 owner correction and are deliberately not fetched targets.
// Source of truth: schema.org Product JSON-LD on the public product page for
// price and listed availability. Shipping was resolved by browser research on
// 2026-10-12: the anonymous checkout estimator quoted a flat ₪30 home-delivery
// fee with free shipping above ₪100 for 1, 2 and 4 × 250 g carts to Tel Aviv /
// 6100000 (changing the locality to Eilat did not change the rule). The quote
// is stored with its condition and its own retrieval time, never as an
// unconditional country-wide promise.

import { classifyListing } from '../catalog.js';
import { findJsonLd, textOf } from '../lib/text.js';
import { createObservation, parseError } from './index.js';

const PRODUCT_URL = 'https://pucks.co.il/product/lavazza-crema-e-gusto-ground-coffee-250g';

const AVAILABILITY = {
  'https://schema.org/InStock': 'in_stock',
  'https://schema.org/LimitedAvailability': 'in_stock',
  'https://schema.org/OutOfStock': 'out_of_stock',
  'https://schema.org/SoldOut': 'out_of_stock'
};

/**
 * Browser-researched checkout quote (2026-10-12, 18:08-18:10 UTC).
 * Evidence: docs/evidence/browser-research/2026-10-12-vendor-shipping-quotes.json
 * and the pucks-checkout-*.png screenshots in the same directory. The public
 * estimator exposed home delivery only; no street address or personal detail
 * was entered and no order was submitted.
 */
export const PUCKS_CHECKOUT_SHIPPING = {
  amountIls: 30,
  freeThresholdIls: 100,
  currency: 'ILS',
  retrievedAt: '2026-10-12T18:10:10Z',
  sourceUrl: 'https://pucks.co.il/payment/request',
  note: 'Home delivery quoted by the anonymous checkout estimator on 2026-10-12: ₪30 flat, free above ₪100. Observed for 1, 2 and 4 × 250 g carts to Tel Aviv / 6100000; the estimator offers home delivery only.'
};

export const pucks = {
  id: 'pucks',
  name: 'Pucks (פאקס)',
  homepage: 'https://pucks.co.il',
  allowedHosts: ['pucks.co.il', 'www.pucks.co.il'],
  parserVersion: 'pucks/6',
  offers: [
    { id: 'classico-250g', url: PRODUCT_URL, kind: 'delivery', productId: 'lavazza-crema-e-gusto-vacuum-ground' }
  ],

  async observe({ fetchText, now }) {
    const observations = [];
    const failures = [];
    for (const offer of this.offers) {
      const response = await fetchText(offer.url, { accept: 'text/html' });
      if (!response.ok) {
        failures.push({ offerId: offer.id, url: offer.url, error: response.error ?? `HTTP ${response.status}` });
        continue;
      }
      try {
        observations.push(parsePucksProduct(response.text, { now, url: offer.url, productId: offer.productId ?? null }));
      } catch (error) {
        failures.push({ offerId: offer.id, url: offer.url, error: error.message, details: error.details ?? null });
      }
    }
    return { observations, failures };
  }
};

export function parsePucksProduct(html, { now, url = PRODUCT_URL, productId = null } = {}) {
  const product = findJsonLd(html, 'Product');
  if (!product) throw parseError('No schema.org Product JSON-LD found', { url });
  const offer = product.offers ?? {};
  const name = String(product.name ?? '');
  const classification = classifyListing(name, { productId });
  if (!classification.matched) {
    throw parseError('Listing does not match the tracked product', { name, reasons: classification.reasons });
  }
  const priceAmount = Number(offer.price);
  if (!Number.isFinite(priceAmount)) throw parseError('Price missing from JSON-LD offer', { name, price: offer.price });
  const currency = String(offer.priceCurrency ?? '').toUpperCase();
  if (!currency) throw parseError('Currency missing from JSON-LD offer', { name });
  const availability = AVAILABILITY[String(offer.availability ?? '')] ?? 'unknown';

  const shippingNote = /המשלוח מחושב/.test(html)
    ? 'Shipping is calculated at checkout'
    : 'Shipping terms are not published on the product page';

  return createObservation({
    vendor: pucks,
    itemUrl: url,
    product: {
      productId: classification.productId,
      name,
      sku: product.sku ?? product.mpn ?? null,
      gtin: product.gtin13 ?? product.gtin ?? null,
      variantId: classification.variantId,
      variantLabel: classification.variantLabel,
      form: classification.form,
      packGrams: classification.packGrams,
      packCount: classification.packCount,
      totalGrams: classification.totalGrams,
      category: product.category ?? null
    },
    price: { amount: priceAmount, currency },
    availability,
    availabilityEvidence: {
      url,
      value: String(offer.availability ?? 'not stated'),
      note: 'Availability comes from the product page structured data, not from a price-only scrape.'
    },
    shipping: {
      mode: 'delivery',
      // The browser-researched estimator quote is a verified observed rate for
      // the quantities and destination recorded in the evidence; it is not a
      // nationwide guarantee, it was never published on the product page, and
      // it is never used as a zero default.
      certainty: 'checkout_quote',
      amount: { amount: PUCKS_CHECKOUT_SHIPPING.amountIls, currency: PUCKS_CHECKOUT_SHIPPING.currency },
      freeThreshold: { amount: PUCKS_CHECKOUT_SHIPPING.freeThresholdIls, currency: PUCKS_CHECKOUT_SHIPPING.currency },
      destination: {
        scope: 'country',
        country: 'IL',
        caveat: 'The ₪30 rate was observed in the anonymous checkout estimator for Tel Aviv and Eilat carts; the fee did not change with locality and no restriction was displayed, but coverage for every locality was not individually verified.',
        caveatSource: PUCKS_CHECKOUT_SHIPPING.sourceUrl
      },
      note: shippingNote === 'Shipping is calculated at checkout'
        ? `${PUCKS_CHECKOUT_SHIPPING.note} The product page still says shipping is calculated at checkout.`
        : PUCKS_CHECKOUT_SHIPPING.note,
      evidence: {
        url: PUCKS_CHECKOUT_SHIPPING.sourceUrl,
        retrievedAt: PUCKS_CHECKOUT_SHIPPING.retrievedAt,
        note: 'Anonymous checkout estimator quote recorded by interactive browser research; see docs/evidence/browser-research/2026-10-12-vendor-shipping-quotes.json.'
      }
    },
    now
  });
}

export function pucksProductText(html) {
  return textOf(html).slice(0, 400);
}

// Scheduled refresh pipeline.
//
// The pipeline is deterministic and bounded: allowlisted hosts, per-request
// timeouts and size limits, concurrency capped, one attempt per offer per run.
// A failing vendor keeps its previous good observation; a missing FX rate keeps
// the previous rate table. Nothing here needs a browser, an LLM or the coding
// loop to be running.

import { createBoundedFetcher } from './lib/http.js';
import { parseBoiRates, FX_SOURCE } from './lib/fx.js';
import { PRODUCTS } from './catalog.js';
import { registeredVendors, vendorHosts } from './vendors/index.js';

export const REFRESH_INTERVAL_MS = 6 * 60 * 60 * 1000; // About every six hours.
// A scheduled refresh that has not completed for this long is surfaced to shoppers
// as stale: one missed six-hour run plus slack, so a broken cron does not stay silent.
export const REFRESH_STALE_MS = 8 * 60 * 60 * 1000;
export const BACKOFF_BASE_MS = 30 * 60 * 1000;
export const BACKOFF_MAX_MS = 12 * 60 * 60 * 1000;
export const LEASE_TTL_MS = 10 * 60 * 1000;
export const MAX_CONCURRENCY = 2;
export const INITIAL_REFRESH_THROTTLE_MS = 10 * 60 * 1000;

export const FX_URL = 'https://www.boi.org.il/currency.xml';
export const FX_HOSTS = ['www.boi.org.il', 'boi.org.il'];

/**
 * Test seam for crawl-delay pacing. Production and the real cron simulation use
 * real timers; unit tests and offline simulations replace these with a no-op so
 * they never wait. Pass `sleep`/`clock` to runRefresh for a per-call override.
 */
export const pacingDefaults = { sleep: undefined, clock: undefined };

export function backoffMs(consecutiveFailures) {
  if (!consecutiveFailures || consecutiveFailures <= 0) return 0;
  return Math.min(BACKOFF_BASE_MS * 2 ** (consecutiveFailures - 1), BACKOFF_MAX_MS);
}

/**
 * Newest successful observation time across stored rows. Attempt markers carry no
 * observedAt, so a failed refresh can never make the board look freshly checked.
 * Pass `productIds` to ignore rows for any product line that is no longer tracked:
 * a lingering historical row must not keep the Crema e Gusto board looking fresh.
 */
export function newestObservationAt(observations = [], productIds = null) {
  const allowed = productIds ? new Set(productIds) : null;
  let newestMs = null;
  let newest = null;
  for (const row of observations) {
    if (!row?.observedAt) continue;
    const productId = row?.product?.productId ?? null;
    if (allowed && productId != null && !allowed.has(productId)) continue;
    const parsed = Date.parse(row.observedAt);
    if (!Number.isFinite(parsed)) continue;
    if (newestMs == null || parsed > newestMs) {
      newestMs = parsed;
      newest = row.observedAt;
    }
  }
  return newest;
}

/**
 * Freshness of the board as a whole. `lastRefreshAt` is the last *completed*
 * refresh. A run that is interrupted after saving observations (for example a
 * redeploy stops the background job) never writes that marker, so the board also
 * reports the newest saved observation and falls back to it for the age when no
 * completed refresh exists. A recorded but old completion still reads as stale:
 * that is the scheduled pipeline having stopped, not missing data.
 */
export function refreshFreshness(lastRefreshAt, now = Date.now(), lastObservationAt = null) {
  const refreshMs = lastRefreshAt ? Date.parse(lastRefreshAt) : NaN;
  const observationMs = lastObservationAt ? Date.parse(lastObservationAt) : NaN;
  const dataMs = Number.isFinite(refreshMs) && Number.isFinite(observationMs)
    ? Math.max(refreshMs, observationMs)
    : (Number.isFinite(refreshMs) ? refreshMs : observationMs);
  const ageAnchorMs = Number.isFinite(refreshMs) ? refreshMs : observationMs;
  const ageMs = Number.isFinite(ageAnchorMs) ? now - ageAnchorMs : null;
  return {
    lastRefreshAt: lastRefreshAt ?? null,
    lastObservationAt: lastObservationAt ?? null,
    dataAsOf: Number.isFinite(dataMs) ? new Date(dataMs).toISOString() : null,
    ageHours: ageMs == null ? null : Math.round((ageMs / 3_600_000) * 10) / 10,
    stale: ageMs == null || ageMs > REFRESH_STALE_MS
  };
}

// The cron fires on fixed clock times while nextAttemptAt is stored as
// "run time + 6 h", so a tick can land seconds before a vendor's due time. Without
// a small tolerance that tick skips every vendor and the board silently drifts from
// a six-hour to a twelve-hour refresh cadence (and reports stale for hours between
// runs). Successful vendors therefore count as due up to this much early; vendors
// inside a failure backoff keep their strict due time.
export const EARLY_DUE_TOLERANCE_MS = 15 * 60 * 1000;

export function isVendorDue(state, now) {
  if (!state?.nextAttemptAt) return true;
  const due = Date.parse(state.nextAttemptAt);
  if (!Number.isFinite(due)) return true;
  const slack = (state.consecutiveFailures ?? 0) > 0 ? 0 : EARLY_DUE_TOLERANCE_MS;
  return due <= now + slack;
}

export async function runRefresh({
  store,
  vendors = registeredVendors(),
  fetchImpl = globalThis.fetch,
  now = Date.now(),
  includeFx = true,
  trigger = 'scheduled',
  holderId = `refresh-${now}-${Math.random().toString(36).slice(2, 8)}`,
  logger = null,
  sleep = undefined,
  clock = undefined,
  // Test seam for the completion timestamp. Production uses the real clock, so
  // `finishedAt` is the true finish time; a simulation can pass a time source on
  // the same timeline as `now`, which keeps stored freshness deterministic across
  // a multi-tick cron sequence instead of mixing in the real wall clock.
  timeSource = undefined
} = {}) {
  const currentTimeMs = () => (typeof timeSource === 'function' ? timeSource() : Date.now());
  const acquired = await store.acquireLease('refresh', holderId, LEASE_TTL_MS);
  if (!acquired) {
    return { skipped: true, reason: 'another refresh holds the lease', trigger };
  }
  const startedAt = new Date(now).toISOString();
  let requests = 0;
  const counter = () => { requests += 1; };
  const fxHosts = FX_HOSTS;
  const results = [];
  try {
    // Read the stored observations once, before any vendor writes, so each new
    // observation can carry the previous successful price and stock as
    // comparison evidence. The map is anchored to the pre-run state.
    const previousByKey = new Map();
    for (const row of await store.listObservations()) previousByKey.set(row.key, row);

    const queued = [];
    for (const vendor of vendors) {
      const state = await store.getVendorState(vendor.id);
      if (!isVendorDue(state, now)) {
        results.push({ vendorId: vendor.id, skipped: true, reason: 'backoff', nextAttemptAt: state.nextAttemptAt });
        continue;
      }
      queued.push({ vendor, state });
    }

    for (let index = 0; index < queued.length; index += MAX_CONCURRENCY) {
      const batch = queued.slice(index, index + MAX_CONCURRENCY);
      const batchResults = await Promise.all(batch.map(({ vendor, state }) => refreshVendor({ store, vendor, state, fetchImpl, now, counter, logger, sleep, clock, previousByKey })));
      results.push(...batchResults);
    }

    let fx = null;
    if (includeFx) fx = await refreshFxCached({ store, fetchImpl, now, counter, logger });

    // Owner correction 2026-10-12: only Crema e Gusto is tracked. Historical
    // observations and failure markers for retired product lines are removed
    // from the live store so old data cannot linger or be counted anywhere.
    let pruned = 0;
    try {
      pruned = await pruneRetiredObservations({ store, vendors });
    } catch (error) {
      logger?.warn?.(`[refresh] retired-observation prune failed: ${error?.message ?? error}`);
    }

    const finishedAt = new Date(currentTimeMs()).toISOString();
    const summary = {
      trigger,
      startedAt,
      finishedAt,
      requests,
      pruned,
      vendors: results,
      fx: fx ? { ok: fx.ok, asOf: fx.fx?.asOf ?? null, error: fx.error ?? null } : { skipped: true }
    };
    await store.recordRun(summary);
    // A completed refresh means at least one vendor actually produced a saved
    // observation. A run that fetched only the exchange-rate table (every vendor
    // still inside its backoff window) or fetched nothing at all must not make
    // the board look freshly checked when no offer was re-observed.
    const savedAny = results.some(result => (result.saved ?? 0) > 0);
    if (savedAny) {
      await store.setMeta('lastRefreshAt', { value: finishedAt, trigger });
    }
    return summary;
  } finally {
    await store.releaseLease('refresh');
  }
}

async function refreshVendor({ store, vendor, state, fetchImpl, now, counter, logger, sleep, clock, previousByKey = null }) {
  const fetchText = createBoundedFetcher({
    fetchImpl,
    allowedHosts: vendor.allowedHosts ?? vendorHosts([vendor]),
    onRequest: counter,
    // Respect a vendor's published crawl delay (for example "Crawl-delay: 7")
    // instead of firing every tracked offer back to back.
    minIntervalMs: vendor.crawlDelayMs ?? 0,
    sleep: sleep ?? pacingDefaults.sleep,
    clock: clock ?? pacingDefaults.clock
  });
  const attemptedAt = new Date(now).toISOString();
  let saved = 0;
  const failures = [];
  // A failed fetch has no freshly parsed key, so stamp the failure on the offer's
  // last successful observation row when one exists. The row keeps its observedAt,
  // price and stock, while `attemptedAt`/`lastError` describe the most recent check
  // attempt — including a failed one — instead of leaving a detached marker that no
  // board row can show. Offers that never succeeded keep the marker key.
  const attemptKeyFor = offer => {
    const existing = previousByKey
      ? [...previousByKey.values()].find(row => row?.observedAt && row?.itemUrl === offer?.url)
      : null;
    return existing?.key ?? `${vendor.id}:offer:${offer?.id ?? 'unknown'}`;
  };
  try {
    const outcome = await vendor.observe({ fetchText, now, logger });
    for (const observation of outcome.observations ?? []) {
      observation.attemptedAt = attemptedAt;
      observation.lastError = null;
      // Keep one step of comparison evidence: what the same offer showed at the
      // previous successful check. Attempt markers have no observedAt and are
      // skipped, so a failed refresh never fabricates a previous price.
      const previous = previousByKey?.get(observation.key);
      if (previous?.observedAt && previous?.price?.amount != null) {
        observation.previous = {
          observedAt: previous.observedAt,
          price: { amount: previous.price.amount, currency: previous.price.currency ?? null },
          availability: previous.availability ?? 'unknown',
          totalGrams: previous.product?.totalGrams ?? null
        };
      }
      await store.putObservation(observation);
      saved += 1;
    }
    for (const failure of outcome.failures ?? []) {
      failures.push(failure);
      const offer = (vendor.offers ?? []).find(candidate => candidate.id === failure.offerId);
      await store.markAttempt({
        key: attemptKeyFor(offer),
        attemptedAt,
        error: failure.error
      });
    }
  } catch (error) {
    failures.push({ offerId: '*', error: error?.message ?? String(error) });
    for (const offer of vendor.offers ?? []) {
      await store.markAttempt({ key: attemptKeyFor(offer), attemptedAt, error: error?.message ?? String(error) });
    }
  }
  const ok = saved > 0;
  const previousFailures = ok ? 0 : (state?.consecutiveFailures ?? 0) + 1;
  const delay = ok ? REFRESH_INTERVAL_MS : Math.max(backoffMs(previousFailures), BACKOFF_BASE_MS);
  const nextAttemptAt = new Date(now + delay).toISOString();
  const nextState = {
    vendorId: vendor.id,
    lastAttemptAt: attemptedAt,
    lastSuccessAt: ok ? attemptedAt : (state?.lastSuccessAt ?? null),
    consecutiveFailures: previousFailures,
    nextAttemptAt,
    lastErrors: failures.map(failure => failure.error).slice(0, 5)
  };
  await store.setVendorState(vendor.id, nextState);
  logger?.info?.(`[refresh] ${vendor.id}: saved=${saved} failures=${failures.length} next=${nextAttemptAt}`);
  return { vendorId: vendor.id, ok, saved, failures, nextAttemptAt };
}

export const FX_MIN_INTERVAL_MS = 3 * 60 * 60 * 1000;

/** Skip the FX fetch when a recent official rate table is already stored. */
export async function refreshFxCached({ store, fetchImpl, now, counter, logger }) {
  const stored = await store.getMeta('fx');
  if (stored?.fetchedAt && now - Date.parse(stored.fetchedAt) < FX_MIN_INTERVAL_MS) {
    return { ok: true, fx: stored, cached: true };
  }
  return refreshFx({ store, fetchImpl, now, counter, logger });
}

export async function refreshFx({ store, fetchImpl, now, counter, logger }) {
  const fetchText = createBoundedFetcher({ fetchImpl, allowedHosts: FX_HOSTS, onRequest: counter });
  const response = await fetchText(FX_URL, { accept: 'application/json' });
  const attemptedAt = new Date(now).toISOString();
  if (!response.ok) {
    logger?.warn?.(`[refresh] fx fetch failed: ${response.error ?? response.status}`);
    return { ok: false, error: response.error ?? `HTTP ${response.status}`, attemptedAt };
  }
  const parsed = (() => {
    try {
      return parseBoiRates(JSON.parse(response.text));
    } catch {
      return null;
    }
  })();
  if (!parsed) return { ok: false, error: 'Bank of Israel feed could not be parsed', attemptedAt };
  const fx = { ...parsed, fetchedAt: attemptedAt, source: FX_SOURCE };
  await store.setMeta('fx', fx);
  return { ok: true, fx, attemptedAt };
}

/**
 * Runs a refresh in the background when the board has never refreshed, for the
 * initial refresh after deployment. Bounded by a lease and a throttle so public
 * traffic can never trigger unlimited scraping.
 */
export async function maybeInitialRefresh({ store, ctx, now = Date.now(), run = runRefresh, ...options } = {}) {
  const last = await store.getMeta('lastRefreshAt');
  if (last?.value) return { skipped: true, reason: 'already refreshed' };
  const attempt = await store.getMeta('initialRefreshAttemptAt');
  if (attempt?.value && now - Date.parse(attempt.value) < INITIAL_REFRESH_THROTTLE_MS) {
    return { skipped: true, reason: 'initial refresh throttled' };
  }
  await store.setMeta('initialRefreshAttemptAt', { value: new Date(now).toISOString() });
  const promise = run({ store, trigger: 'initial', now, ...options }).catch(error => {
    console.warn(`initial refresh failed: ${error?.message ?? error}`);
    return null;
  });
  if (ctx?.waitUntil) ctx.waitUntil(promise);
  return { started: true, promise };
}

/**
 * Remove stored rows that belong to retired product lines or to offers that are
 * no longer tracked. The tracked product's last-known-good observations are
 * never touched, so a failing vendor still keeps its previous price and stock.
 * Returns the number of rows removed.
 */
export async function pruneRetiredObservations({ store, vendors = registeredVendors() } = {}) {
  if (typeof store?.deleteObservation !== 'function') return 0;
  const activeProductIds = new Set(PRODUCTS.map(product => product.id));
  const trackedAttemptKeys = new Set(vendors.flatMap(vendor =>
    (vendor.offers ?? []).map(offer => `${vendor.id}:offer:${offer.id}`)
  ));
  let pruned = 0;
  for (const row of await store.listObservations()) {
    const productId = row?.product?.productId ?? null;
    const retiredProduct = productId != null && !activeProductIds.has(productId);
    const retiredAttempt = typeof row?.key === 'string'
      && row.key.includes(':offer:')
      && !trackedAttemptKeys.has(row.key);
    if (!retiredProduct && !retiredAttempt) continue;
    await store.deleteObservation(row.key);
    pruned += 1;
  }
  return pruned;
}

