  InStock: 'in_stock',
  LimitedAvailability: 'in_stock',
  OutOfStock: 'out_of_stock',
  SoldOut: 'out_of_stock',
  PreOrder: 'unknown'
};

const CREMA_E_GUSTO = 'lavazza-crema-e-gusto-vacuum-ground';

/**
 * Browser-researched checkout quotes (2026-10-12, 18:16-18:17 UTC).
 * Evidence: docs/evidence/browser-research/2026-10-12-vendor-shipping-quotes.json
 * and the coffeeman-checkout-8pack.png screenshot. No street address, personal
 * detail, login or order submission was involved.
 */
export const COFFEEMAN_CHECKOUT_QUOTES = {
  [EIGHT_PACK_URL]: {
    amountIls: 20,
    currency: 'ILS',
    maxTotalGrams: 2000,
    distributionCenterIls: 20,
    observedCarts: 'the 2 kg cart',
    retrievedAt: '2026-10-12T20:07:00Z',
    sourceUrl: 'https://www.coffeeman.co.il/checkout.asp',
    note: 'Anonymous checkout quote for one 8 × 250 g multipack (2 kg) on 2026-10-12, re-checked in a fresh cart at 20:07 UTC: ₪20 home courier and ₪20 distribution-center delivery up to 5 kg; self-pickup free. The product page publishes no courier price, and carts above 2 kg are not verified.'
  }
};

/**
 * Browser-researched anonymous-cart observations for the single 250 g and
 * 4 × 250 g listings (2026-10-12, 19:56-20:09 UTC). The product page lists the
 * distribution-center delivery option without a price; the cart quoted ₪15 for
 * 0.5-1 kg carts, and larger carts were sometimes shown free. No free-shipping
 * rule is published, so the board keeps the published ₪25 courier rate as the
 * ranked amount and never assumes free shipping. Evidence:
 * docs/evidence/browser-research/2026-10-12-coffeeman-cart-single-4pack.json.
 * No street address, personal detail, login or order submission was involved.
 */
export const COFFEEMAN_CART_OBSERVATIONS = {
  [PRODUCT_URL]: {
    distributionCenterIls: 15,
    observedCarts: '0.5–1 kg carts',
    retrievedAt: '2026-10-12T19:57:00Z',
    sourceUrl: 'https://www.coffeeman.co.il/checkout.asp',
    note: 'Anonymous cart 2026-10-12 (https://www.coffeeman.co.il/checkout.asp): ₪25 home courier (matching the published rate) and ₪15 distribution-center delivery up to 5 kg for 0.5–1 kg carts; free courier was observed from a 1.75 kg / ₪231 cart, but no free-shipping rule is published, so the board keeps the published ₪25 and never assumes free shipping.'
  },
  [FOUR_PACK_URL]: {
    distributionCenterIls: 15,
    observedCarts: 'the 1 kg cart',
    retrievedAt: '2026-10-12T20:04:00Z',
    sourceUrl: 'https://www.coffeeman.co.il/checkout.asp',
    note: 'Anonymous cart 2026-10-12 (https://www.coffeeman.co.il/checkout.asp): ₪25 home courier (matching the published rate) and ₪15 distribution-center delivery up to 5 kg for the 1 kg cart; free courier was observed for a 2 kg / ₪248 two-4-pack cart, but no free-shipping rule is published, so the board keeps the published ₪25 and never assumes free shipping.'
  }
};

export const coffeeman = {
  id: 'coffeeman',
  name: 'CoffeeMan (אמיגו)',
  homepage: 'https://www.coffeeman.co.il',
  allowedHosts: ['www.coffeeman.co.il', 'coffeeman.co.il'],
  parserVersion: 'coffeeman/6',
  crawlDelayMs: 7000,
  offers: [
    { id: 'classico-250g', url: PRODUCT_URL, kind: 'delivery', productId: CREMA_E_GUSTO },
    { id: 'classico-1000g-4pack', url: FOUR_PACK_URL, kind: 'delivery', productId: CREMA_E_GUSTO },
    { id: 'classico-2000g-8pack', url: EIGHT_PACK_URL, kind: 'delivery', productId: CREMA_E_GUSTO }
  ],

  async observe({ fetchText, now }) {
    const observations = [];
    const failures = [];
    for (const offer of this.offers) {
      const response = await fetchText(offer.url, { accept: 'text/html' });
      if (!response.ok) {
        failures.push({ offerId: offer.id, url: offer.url, error: response.error ?? `HTTP ${response.status}` });
        continue;
      }
      try {
        const html = response.buffer ? decodeHtml(response.buffer, response.text) : response.text;
        observations.push(parseCoffeemanProduct(html, { now, url: offer.url, productId: offer.productId ?? null }));
      } catch (error) {
        failures.push({ offerId: offer.id, url: offer.url, error: error.message, details: error.details ?? null });
      }
    }
    return { observations, failures };
  }
};

export function parseCoffeemanProduct(html, { now, url = PRODUCT_URL, productId = null } = {}) {
  const name = extractName(html);
  if (!name) throw parseError('Product name not found', { url });
  const classification = classifyListing(name, { productId });
  if (!classification.matched) {
    throw parseError('Listing does not match the tracked product', { name, reasons: classification.reasons });
  }

  const priceMatch = /itemprop="price"[^>]*\bprice="([\d.,]+)"/.exec(html) ?? /itemprop="price"[^>]*\bcontent="([\d.,]+)"/.exec(html);
  const priceAmount = parseDecimal(priceMatch?.[1]);
  if (priceAmount == null) throw parseError('Price not found in product microdata', { name });
  const currency = /itemprop="priceCurrency"\s*>\s*([A-Z]{3})/.exec(html)?.[1] ?? null;
  if (!currency) throw parseError('Currency not found in product microdata', { name });

  const regularMatch = /\bprice="([\d.,]+)"\s+id="total_regularprice"/.exec(html) ?? /\bprice="([\d.,]+)"[^>]*class="toal_regularprice_view"/.exec(html);
  const regularPrice = parseDecimal(regularMatch?.[1]);

  const availabilityHref = /itemprop="availability"[^>]*href="([^"]+)"/.exec(html)?.[1] ?? '';
  const availability = AVAILABILITY[availabilityHref.split('/').pop()] ?? 'unknown';
  const sku = /itemprop="sku"[^>]*>([^<]+)</.exec(html)?.[1]?.trim()
    ?? /מקט:\s*(\d+)/.exec(html)?.[1]
    ?? null;
  const deliveryTime = collapse(/זמן\s*אספקה\s*:\s*([^<\n]+)/.exec(html)?.[1] ?? '');

  const shipping = parseShippingOptions(html);
  const checkoutQuote = checkoutQuoteFor({ url, classification });
  const cartObservation = cartObservationFor({ url, classification });
  const shippingNote = [...new Set([shipping.note, checkoutQuote?.note, cartObservation?.note].filter(Boolean))].join(' ');
  const observation = createObservation({
    vendor: coffeeman,
    itemUrl: url,
    product: {
      productId: classification.productId,
      name,
      sku,
      gtin: null,
      variantId: classification.variantId,
      variantLabel: classification.variantLabel,
      form: classification.form,
      packGrams: classification.packGrams,
      packCount: classification.packCount,
      totalGrams: classification.totalGrams,
      category: 'קפה טחון'
    },
    price: { amount: priceAmount, currency, regularAmount: regularPrice },
    availability,
    availabilityEvidence: {
      url,
      value: availabilityHref || 'not stated',
      note: 'Availability comes from the product page offer microdata, not from a price-only scrape.'
    },
    shipping: {
      mode: 'delivery',
      certainty: shipping.deliveryCents != null ? 'verified' : checkoutQuote ? 'checkout_quote' : 'unknown',
      amount: shipping.deliveryCents != null
        ? { amount: shipping.deliveryCents, currency }
        : checkoutQuote
          ? { amount: checkoutQuote.amountIls, currency: checkoutQuote.currency }
          : null,
      // A checkout-quoted rate is only used for the cart size it was observed
      // on; the quote engine refuses to rank a larger cart with it.
      maxTotalGrams: shipping.deliveryCents != null ? null : checkoutQuote?.maxTotalGrams ?? null,
      // The product page publishes the courier rate but not the locality list, and the
      // vendor terms state home delivery is subject to that list. The caveat is kept
      // structured so the board can disclose the geographic restriction instead of
      // claiming unconditional country-wide coverage.
      destination: {
        scope: 'country',
        country: 'IL',
        caveat: 'Home delivery is limited to the localities on Amigo’s home-delivery list, which the product page does not publish. Confirm the destination at checkout.',
        caveatSource: 'https://www.coffeeman.co.il/page/%D7%AA%D7%A0%D7%90%D7%99-%D7%A9%D7%99%D7%9E%D7%95%D7%A9'
      },
      minOrder: null,
      freeThreshold: null,
      // The distribution-center option is listed on the product page without a
      // price; the anonymous cart quoted it for the recorded cart sizes, so it
      // is shown as a conditional alternative and never replaces the ranked rate.
      alternatives: shipping.distributionCenter && cartObservation?.distributionCenterIls != null
        ? [{
            id: 'distribution-center',
            label: `Distribution-center delivery up to 5 kg (cart-observed for ${cartObservation.observedCarts})`,
            amount: { amount: cartObservation.distributionCenterIls, currency },
            note: cartObservation.note
          }]
        : [],
      note: shippingNote,
      deliveryTime: deliveryTime || null,
      pickup: {
        available: shipping.pickupFree,
        amount: shipping.pickupFree ? { amount: 0, currency } : null,
        note: shipping.pickupFree ? 'Free self-pickup, listed on the product page.' : null
      },
      evidence: checkoutQuote
        ? {
            url: checkoutQuote.sourceUrl,
            retrievedAt: checkoutQuote.retrievedAt,
            note: 'Anonymous checkout estimator quote recorded by interactive browser research; see docs/evidence/browser-research/2026-10-12-vendor-shipping-quotes.json.'
          }
        : { url, retrievedAt: null, note: 'Delivery options are listed on the product page.' }
    },
    now
  });
  return observation;
}

/**
 * Resolve the browser-researched checkout quote for a parsed listing. The URL
 * is the primary key; the tracked 8 × 250 g = 2 kg multipack shape is accepted
 * as a fallback so fixture tests that pass a placeholder URL still exercise the
 * same offer identity.
 */
function checkoutQuoteFor({ url, classification }) {
  if (COFFEEMAN_CHECKOUT_QUOTES[url]) return COFFEEMAN_CHECKOUT_QUOTES[url];
  if (classification.packCount === 8 && classification.totalGrams === 2000) return COFFEEMAN_CHECKOUT_QUOTES[EIGHT_PACK_URL];
  return null;
}

/**
 * Resolve the cart-researched distribution-center observation for a parsed
 * listing. The 8-pack quote doubles as its own cart observation; the 4-pack is
 * accepted by shape so fixture tests with a placeholder URL still exercise it.
 */
function cartObservationFor({ url, classification }) {
  if (COFFEEMAN_CART_OBSERVATIONS[url]) return COFFEEMAN_CART_OBSERVATIONS[url];
  if (classification.packCount === 4 && classification.totalGrams === 1000) return COFFEEMAN_CART_OBSERVATIONS[FOUR_PACK_URL];
  const quote = checkoutQuoteFor({ url, classification });
  return quote?.distributionCenterIls != null ? quote : null;
}

export function parseShippingOptions(html) {
  const start = html.indexOf('delivery-price-product');
  const block = start >= 0 ? html.slice(start, start + 2500) : '';
  const items = [...block.matchAll(/<li[^>]*>([\s\S]*?)<\/li>/gi)].map(match => collapse(stripTags(match[1])));
  let deliveryCents = null;
  let pickupFree = false;
  let distributionCenter = null;
  for (const item of items) {
    if (item.includes('איסוף עצמי')) {
      pickupFree = true;
    } else if (item.includes('שליח')) {
      const amount = parseDecimal(item.match(/([\d.,]+)/)?.[1]);
      if (amount != null) deliveryCents = amount;
    } else if (item.includes('מרכז חלוקה')) {
      distributionCenter = item;
    }
  }
  const notes = [];
  if (deliveryCents != null) {
    notes.push(`Published courier delivery rate: ₪${deliveryCents.toFixed(2)}.`);
  } else {
    notes.push('No published courier rate found; delivery cost is unknown before checkout.');
  }
  if (distributionCenter) {
    notes.push('A distribution-center delivery option exists, but its price is not published on the product page.');
  }
  if (pickupFree) {
    notes.push('Free self-pickup is available and is kept separate from delivery.');
  }
  return { deliveryCents, pickupFree, distributionCenter, note: notes.join(' ') };
}

function extractName(html) {
  const h1 = /<h1[^>]*itemprop="name"[^>]*>([\s\S]*?)<\/h1>/i.exec(html)?.[1];
  if (h1) return decodeEntities(collapse(stripTags(h1)));
  const og = /<meta\s+property="og:title"\s+content\s*=\s*"([^"]+)"/i.exec(html)?.[1];
  if (og) return decodeEntities(collapse(String(og).replace(/\s*-\s*₪[\d.,]+\s*$/, '')));
  const title = /<title>([\s\S]*?)<\/title>/i.exec(html)?.[1];
  return title ? decodeEntities(collapse(stripTags(title).split('|')[0])) : null;
}

#!/usr/bin/env node
// Reusable interactive browser-research helper (research/development only).
//
// It keeps ONE real headless Google Chrome + ChromeDriver session alive between
// shell invocations, so a researcher can navigate a real vendor site, read the
// rendered page, click/fill/select, wait for JavaScript and take screenshots
// step by step instead of asserting a fixed list of labels.
//
//   npm run research:browser -- start
//   npm run research:browser -- goto https://example.com/product
//   npm run research:browser -- text --limit 200
//   npm run research:browser -- elements "button, a[href*='cart']"
//   npm run research:browser -- click --text "Add to cart"
//   npm run research:browser -- fill "#city" "Tel Aviv"
//   npm run research:browser -- select "#city" --label "תל אביב"
//   npm run research:browser -- wait --text "Shipping" --timeout 15000
//   npm run research:browser -- shot pucks-cart --viewport 1440x1200
//   npm run research:browser -- stop
//
// The session file lives in .shurik-local/browser-research/ (git-ignored) and
// must never be committed: it contains a WebDriver session id, which is a
// browser secret. Screenshots and text dumps are written under
// .shurik-local/browser-research/ too; only curated, secret-free excerpts are
// copied into docs/evidence/.
//
// This helper is deliberately NOT part of the Worker runtime and is never
// imported by src/.

import { spawn } from 'node:child_process';
import { mkdir, readFile, writeFile, rm } from 'node:fs/promises';
import { existsSync } from 'node:fs';
import { setTimeout as delay } from 'node:timers/promises';
import path from 'node:path';

const STATE_DIR = process.env.BROWSER_RESEARCH_DIR ?? '.shurik-local/browser-research';
const SESSION_FILE = path.join(STATE_DIR, 'session.json');
const PORT = Number(process.env.BROWSER_RESEARCH_PORT ?? 9515);
const BASE = `http://127.0.0.1:${PORT}`;
const CHROME_BINARY = process.env.CHROME_BINARY ?? '/usr/bin/google-chrome';

const argv = process.argv.slice(2);
const command = argv[0];
const rest = argv.slice(1);

function flag(name, fallback = null) {
  const index = rest.indexOf(`--${name}`);
  if (index === -1) return fallback;
  const value = rest[index + 1];
  return value && !value.startsWith('--') ? value : true;
}
function positional() {
  const out = [];
  for (let i = 0; i < rest.length; i += 1) {
    if (rest[i].startsWith('--')) { if (rest[i + 1] && !rest[i + 1].startsWith('--')) i += 1; continue; }
    out.push(rest[i]);
  }
  return out;
}

async function http(method, url, body) {
  const response = await fetch(url, {
    method,
    headers: body === undefined ? undefined : { 'content-type': 'application/json' },
    body: body === undefined ? undefined : JSON.stringify(body)
  });
  const text = await response.text();
  let json = null;
  try { json = text ? JSON.parse(text) : null; } catch { /* non-JSON error page */ }
  return { status: response.status, json, text };
}

async function loadSession() {
  if (!existsSync(SESSION_FILE)) return null;
  try { return JSON.parse(await readFile(SESSION_FILE, 'utf8')); } catch { return null; }
}

async function sessionAlive(session) {
  if (!session?.sessionId) return false;
  const status = await http('GET', `${BASE}/status`).catch(() => null);
  if (!status || status.status !== 200) return false;
  const sessions = status.json?.value?.ready !== undefined ? await http('GET', `${BASE}/sessions`).catch(() => null) : null;
  if (sessions?.json?.value) return sessions.json.value.some(s => s.id === session.sessionId);
  return true;
}

async function requireSession() {
  const session = await loadSession();
  if (!session || !(await sessionAlive(session))) {
    console.error('no live browser session; run: npm run research:browser -- start');
    process.exit(2);
  }
  return session;
}

const wd = (session, method, url, body) => http(method, `${BASE}/session/${session.sessionId}${url}`, body);
const wdValue = async (session, method, url, body) => {
  const result = await wd(session, method, url, body);
  if (result.status >= 400) throw new Error(`${method} ${url} -> ${result.status}: ${result.text.slice(0, 500)}`);
  return result.json?.value;
};

async function evaluate(session, script, args = []) {
  return wdValue(session, 'POST', '/execute/sync', { script, args });
}

async function waitForDriver(timeoutMs = 15000) {
  const deadline = Date.now() + timeoutMs;
  while (Date.now() < deadline) {
    const status = await http('GET', `${BASE}/status`).catch(() => null);
    if (status?.status === 200) return true;
    await delay(250);
  }
  return false;
}

async function start() {
  await mkdir(STATE_DIR, { recursive: true });
  const existing = await loadSession();
  if (existing && (await sessionAlive(existing))) {
    console.log(JSON.stringify({ reused: true, sessionIdPresent: true, startedAt: existing.startedAt, port: PORT }, null, 2));
    return;
  }
  const driverUp = await http('GET', `${BASE}/status`).then(r => r.status === 200).catch(() => false);
  if (!driverUp) {
    const child = spawn('chromedriver', [`--port=${PORT}`, '--allowed-ips='], { detached: true, stdio: 'ignore' });
    child.unref();
    const ready = await waitForDriver(15000);
    if (!ready) throw new Error('chromedriver did not start');
  }
  const created = await http('POST', `${BASE}/session`, {
    capabilities: {
      alwaysMatch: {
        browserName: 'chrome',
        'goog:chromeOptions': {
          binary: CHROME_BINARY,
          args: ['--headless=new', '--no-sandbox', '--disable-dev-shm-usage', '--disable-gpu', '--log-level=SEVERE']
        }
      }
    }
  });
  if (created.status >= 400) throw new Error(`session create failed: ${created.text.slice(0, 500)}`);
  const sessionId = created.json.sessionId ?? created.json.value?.sessionId;
  const state = { port: PORT, sessionId, startedAt: new Date().toISOString() };
  await writeFile(SESSION_FILE, JSON.stringify(state, null, 2));
  await wd(state, 'POST', '/timeouts', { implicit: 0, pageLoad: 45_000, script: 30_000 });
  const ua = await evaluate(state, 'return navigator.userAgent;');
  console.log(JSON.stringify({ started: true, startedAt: state.startedAt, port: PORT, userAgent: ua }, null, 2));
}

async function stop() {
  const session = await loadSession();
  if (session) {
    await wd(session, 'DELETE', '').catch(() => null);
  }
  await rm(SESSION_FILE, { force: true });
  // Stop a driver we may have left running; harmless if it is already gone.
  const pids = await new Promise(resolve => {
    const child = spawn('pkill', ['-f', `chromedriver --port=${PORT}`], { stdio: 'ignore' });
    child.on('close', () => resolve(true));
    child.on('error', () => resolve(false));
  }).catch(() => false);
  console.log(JSON.stringify({ stopped: true, driverPkill: pids }));
}

function normalize(text, limit) {
  const value = String(text ?? '').replace(/\u00a0/g, ' ').replace(/[ \t]+\n/g, '\n').trim();
  return limit ? value.slice(0, Number(limit)) : value;
}

async function goto(session) {
  const [url] = positional();
  if (!url) throw new Error('goto needs a URL');
  await wd(session, 'POST', '/url', { url });
  await delay(Number(flag('settle', 1500)));
  const info = await evaluate(session, 'return {url: location.href, title: document.title, ready: document.readyState};');
  console.log(JSON.stringify(info, null, 2));
}

async function text(session) {
  const [selector] = positional();
  const limit = flag('limit', 12000);
  const grep = flag('grep');
  const out = await evaluate(session, `return (() => {
    const root = arguments[0] ? document.querySelector(arguments[0]) : document.body;
    if (!root) return null;
    return { url: location.href, title: document.title, text: root.innerText };
  })()`, [selector ?? null]);
  if (!out) { console.log('(selector not found)'); return; }
  let body = normalize(out.text, null);
  if (grep) {
    const re = new RegExp(grep, 'i');
    body = body.split('\n').filter(line => re.test(line)).join('\n');
  }
  console.log(`# ${out.title} — ${out.url}`);
  console.log(normalize(body, limit));
}

async function elements(session) {
  const [selector] = positional();
  if (!selector) throw new Error('elements needs a CSS selector');
  const limit = Number(flag('limit', 60));
  const out = await evaluate(session, `return (() => {
    const nodes = [...document.querySelectorAll(arguments[0])].slice(0, arguments[1]);
    return nodes.map(node => {
      const rect = node.getBoundingClientRect();
      const attrs = {};
      for (const name of ['href', 'name', 'id', 'type', 'value', 'placeholder', 'aria-label', 'data-testid', 'role']) {
        const value = node.getAttribute?.(name);
        if (value) attrs[name] = value.slice(0, 160);
      }
      return {
        tag: node.tagName.toLowerCase(),
        cls: typeof node.className === 'string' ? node.className.slice(0, 80) : '',
        text: (node.innerText ?? node.value ?? '').replace(/\\s+/g, ' ').trim().slice(0, 200),
        visible: rect.width > 0 && rect.height > 0 && rect.bottom >= 0 && rect.top <= innerHeight * 3,
        rect: [Math.round(rect.x), Math.round(rect.y), Math.round(rect.width), Math.round(rect.height)],
        attrs
      };
    });
  })()`, [selector, limit]);
  console.log(JSON.stringify(out, null, 2));
}

async function click(session) {
  const textMatch = flag('text');
  const linkMatch = flag('link');
  const [selector] = positional();
  let css = selector ?? null;
  let matched = null;
  if (textMatch || linkMatch) {
    const needle = String(textMatch || linkMatch);
    matched = await evaluate(session, `return (() => {
      const needle = arguments[0].toLowerCase();
      const linkOnly = arguments[1] === true;
      const candidates = [...document.querySelectorAll(linkOnly ? 'a' : 'a, button, input[type=submit], input[type=button], [role=button], label')];
      const score = node => {
        const value = (node.innerText ?? node.value ?? '').replace(/\\s+/g, ' ').trim().toLowerCase();
        if (!value) return -1;
        if (value === needle) return 100;
        if (value.includes(needle)) return 50 - Math.min(20, value.length - needle.length);
        return -1;
      };
      const best = candidates.map(node => ({ node, score: score(node) })).filter(c => c.score >= 0)
        .sort((a, b) => b.score - a.score)[0];
      if (!best) return null;
      best.node.setAttribute('data-research-click', '1');
      best.node.scrollIntoView({ block: 'center', inline: 'center' });
      return { tag: best.node.tagName.toLowerCase(), text: (best.node.innerText ?? best.node.value ?? '').replace(/\\s+/g, ' ').trim().slice(0, 200), score: best.score };
    })()`, [needle, Boolean(linkMatch)]);
    if (!matched) throw new Error(`no clickable element matched ${JSON.stringify(needle)}`);
    css = '[data-research-click="1"]';
  }
  if (!css) throw new Error('click needs a CSS selector or --text/--link');
  const element = await wdValue(session, 'POST', '/element', { using: 'css selector', value: css });
  const elementId = element['element-6066-11e4-a52e-4f735466cecf'];
  await wdValue(session, 'POST', `/element/${elementId}/click`, {});
  if (matched) await evaluate(session, `document.querySelector('[data-research-click="1"]')?.removeAttribute('data-research-click');`);
  await delay(Number(flag('settle', 1200)));
  const info = await evaluate(session, 'return {url: location.href, title: document.title};');
  console.log(JSON.stringify({ clicked: matched ?? css, ...info }, null, 2));
}

async function fill(session) {
  const [selector, value] = positional();
  if (!selector || value === undefined) throw new Error('fill needs <selector> <value>');
  const element = await wdValue(session, 'POST', '/element', { using: 'css selector', value: selector });
  const elementId = element['element-6066-11e4-a52e-4f735466cecf'];
  await wdValue(session, 'POST', `/element/${elementId}/clear`, {});
  await wdValue(session, 'POST', `/element/${elementId}/value`, { text: value });
  await delay(Number(flag('settle', 500)));
  const out = await evaluate(session, `(() => { const el = document.querySelector(arguments[0]); return el ? { value: el.value, tag: el.tagName.toLowerCase() } : null; })()`, [selector]);
  console.log(JSON.stringify({ filled: selector, ...out }, null, 2));
}

async function select(session) {
  const [selector] = positional();
  const value = flag('value');
  const label = flag('label');
  if (!selector || (value === null && label === null)) throw new Error('select needs <selector> and --value or --label');
  const out = await evaluate(session, `return (() => {
    const el = document.querySelector(arguments[0]);
    if (!el) return { ok: false, reason: 'selector not found' };
    const options = [...el.options].map(o => ({ value: o.value, label: o.textContent.trim() }));
    const wantedValue = arguments[1];
    const wantedLabel = arguments[2];
    const option = options.find(o => wantedValue !== null && o.value === wantedValue)
      ?? options.find(o => wantedLabel !== null && o.label.includes(wantedLabel));
    if (!option) return { ok: false, reason: 'option not found', options };
    el.value = option.value;
    el.dispatchEvent(new Event('input', { bubbles: true }));
    el.dispatchEvent(new Event('change', { bubbles: true }));
    return { ok: true, selected: option };
  })()`, [selector, value ?? null, label ?? null]);
  console.log(JSON.stringify(out, null, 2));
  await delay(Number(flag('settle', 1500)));
}

async function wait(session) {
  const timeout = Number(flag('timeout', 15000));
  const needle = flag('text');
  const [selector] = positional();
  if (!selector && !needle) throw new Error('wait needs a CSS selector or --text');
  const deadline = Date.now() + timeout;
  let last = null;
  while (Date.now() < deadline) {
    last = await evaluate(session, `return (() => {
      const sel = arguments[0];
      const text = arguments[1];
      if (sel) {
        const node = document.querySelector(sel);
        if (node) return { found: true, kind: 'selector', text: (node.innerText ?? '').slice(0, 200) };
      }
      if (text) {
        const body = document.body?.innerText ?? '';
        if (body.toLowerCase().includes(String(text).toLowerCase())) return { found: true, kind: 'text' };
      }
      return { found: false };
    })()`, [selector ?? null, needle ?? null]);
    if (last?.found) break;
    await delay(300);
  }
  console.log(JSON.stringify({ waitedFor: selector ?? needle, ...last }, null, 2));
}

async function shot(session) {
  const [name] = positional();
  if (!name) throw new Error('shot needs a name');
  const viewport = flag('viewport');
  const scroll = flag('scroll');
  const full = Boolean(flag('full', false));
  if (viewport) {
    const [width, height] = String(viewport).split('x').map(Number);
    await wdValue(session, 'POST', '/window/rect', { width, height, x: 0, y: 0 });
  }
  if (full) {
    const height = await evaluate(session, 'return Math.min(12000, Math.max(document.body.scrollHeight, document.documentElement.scrollHeight));');
    await wdValue(session, 'POST', '/window/rect', { width: Number(String(viewport ?? '1440').split('x')[0]), height });
  } else if (scroll) {
    await evaluate(session, `document.querySelector(arguments[0])?.scrollIntoView({ block: 'start' }); return true;`, [String(scroll)]);
    await delay(400);
  }
  const result = await wd(session, 'GET', '/screenshot');
  if (result.status >= 400) throw new Error(`screenshot failed: ${result.text.slice(0, 300)}`);
  const buffer = Buffer.from(result.json.value, 'base64');
  await mkdir(STATE_DIR, { recursive: true });
  const file = path.join(STATE_DIR, `${name.replace(/[^a-z0-9_.-]/gi, '_')}.png`);
  await writeFile(file, buffer);
  console.log(JSON.stringify({ file, bytes: buffer.length }, null, 2));
}

async function resize(session) {
  const [size] = positional();
  const [width, height] = String(size ?? '1440x1200').split('x').map(Number);
  const rect = await wdValue(session, 'POST', '/window/rect', { width, height, x: 0, y: 0 });
  const viewport = await evaluate(session, 'return {innerWidth, innerHeight, dpr: devicePixelRatio};');
  console.log(JSON.stringify({ rect, viewport }, null, 2));
}

async function frames(session) {
  const out = await evaluate(session, `return [...document.querySelectorAll('iframe')].map(f => ({ src: f.src, id: f.id, w: f.offsetWidth, h: f.offsetHeight }));`);
  console.log(JSON.stringify(out, null, 2));
}

async function evalCommand(session) {
  const script = positional().join(' ');
  if (!script) throw new Error('eval needs a JS expression');
  const out = await evaluate(session, `return (${script});`);
  console.log(typeof out === 'string' ? out : JSON.stringify(out, null, 2));
}

async function html(session) {
  const [selector] = positional();
  const out = await evaluate(session, `return (() => { const node = arguments[0] ? document.querySelector(arguments[0]) : document.documentElement; return node ? node.outerHTML : null; })()`, [selector ?? null]);
  console.log(normalize(out, flag('limit', 20000)));
}

async function main() {
  switch (command) {
    case 'start': return start();
    case 'stop': return stop();
    case 'goto': return goto(await requireSession());
    case 'text': return text(await requireSession());
    case 'elements': return elements(await requireSession());
    case 'click': return click(await requireSession());
    case 'fill': return fill(await requireSession());
    case 'select': return select(await requireSession());
    case 'wait': return wait(await requireSession());
    case 'shot': return shot(await requireSession());
    case 'resize': return resize(await requireSession());
    case 'frames': return frames(await requireSession());
    case 'eval': return evalCommand(await requireSession());
    case 'html': return html(await requireSession());
    default:
      console.log(`browser-research commands:
  start | stop
  goto <url> [--settle ms]
  text [selector] [--limit n] [--grep pattern]
  elements <selector> [--limit n]
  click <selector> | click --text "visible label" | click --link "anchor text"
  fill <selector> <value>
  select <selector> --value v | --label "text"
  wait <selector> | wait --text "text" [--timeout ms]
  shot <name> [--viewport 1440x1200] [--scroll selector] [--full]
  resize [WxH] | frames | eval '<js expression>' | html [selector]`);
      process.exit(command ? 1 : 0);
  }
}

main().catch(error => {
  console.error(`browser-research: ${error.message}`);
  process.exit(1);
});

#!/usr/bin/env node
// Browser QA for the redesigned Canton Zürich board using the installed headless
// Chrome via WebDriver.
//
//   npm run qa:browser                       # offline: fixture-backed local server, no network
//   node scripts/browser-qa.mjs <baseUrl>    # live: run against a server you started (wrangler dev)
//
// In the default mode the script starts scripts/qa-server.mjs, which serves
// public/ plus the read-only JSON API computed by the production quote engine
// from the recorded fixtures in tests/fixtures/. Expectations are derived from
// that API response, so the checks test the UI wiring and math rather than
// hard-coded prices. The report records which data source was used.
//
// The board is a set of offer cards: each ranked offer keeps item subtotal,
// shipping service/charge and delivered total in one `.totals` row, with
// conditions and provenance in short lists/disclosures. The old wide
// comparison table is gone; these checks assert the card behavior instead.
//
// The script is dependency-free: it speaks the W3C WebDriver protocol over HTTP
// and writes screenshots and a JSON report to .shurik-local/qa/.

import { spawn } from 'node:child_process';
import { mkdir, writeFile } from 'node:fs/promises';
import { setTimeout as delay } from 'node:timers/promises';
import { startQaServer } from './qa-server.mjs';

const LIVE_BASE = process.argv.slice(2).find(arg => /^https?:\/\//i.test(arg)) ?? null;
const FIXTURE_PORT = Number(process.env.QA_PORT) || 0; // 0 = ephemeral port, never clashes with a dev server
const OUT = '.shurik-local/qa';
const PORT = 9515;
const EMOJI = /[\u{1F300}-\u{1FAFF}\u{1F000}-\u{1F2FF}\u{2600}-\u{27BF}\u{FE0F}]/u;
const ILS = new Intl.NumberFormat('en-IL', { style: 'currency', currency: 'ILS', maximumFractionDigits: 2 });
const ils = amount => (amount == null ? null : ILS.format(amount));
const BEST_TOTAL_EXPR = `document.querySelector('#ranked .offer--best .totals__cell--total .totals__value')?.textContent ?? null`;
const BEST_VENDOR_EXPR = `document.querySelector('#ranked .offer--best .offer__vendor')?.innerText ?? null`;
const VARIANT_LABELS = { classico: 'Classico (strength 7)', forte: 'Forte', ricco: 'Ricco', risveglio: 'Risveglio', decaf: 'Decaffeinated', unspecified: 'Variant not stated' };

// The expectations below mirror the rendering helpers in public/app.js so the
// browser checks compare rendered text with the same rules the UI uses.

function packDescription(quote) {
  const product = quote.product ?? {};
  const per = product.packGrams != null ? `${product.packGrams} g` : 'weight not stated';
  if ((product.packCount ?? 1) > 1) {
    return `${product.packCount} × ${per} multipack${product.totalGrams != null ? ` (${product.totalGrams} g)` : ''}`;
  }
  return `${per} pack`;
}

function quantityDescription(quote) {
  const product = quote.product ?? {};
  const units = quote.units ?? 1;
  if ((product.packCount ?? 1) > 1) {
    return `${units} multipack${units === 1 ? '' : 's'} (${product.packCount} × ${product.packGrams} g) = ${quote.orderedGrams} g`;
  }
  return `${units} × ${product.packGrams ?? '?'} g pack${units === 1 ? '' : 's'} = ${quote.orderedGrams} g`;
}

const packLine = quote => `${packDescription(quote)} · ${quantityDescription(quote)} · ${quote.product.variantLabel}`;

function shippingValueText(quote) {
  const shipping = quote.shipping ?? {};
  if (shipping.amountIls != null) {
    if (shipping.amountIls === 0) return shipping.freeThreshold != null ? 'Free (threshold met)' : 'Free';
    return ils(shipping.amountIls);
  }
  if (shipping.amount != null) return `${ils(shipping.amount)} ${shipping.currency ?? ''} (not converted)`.trim();
  return 'Shipping not published';
}

function conditionsFor(quote, destinationLabels) {
  const shipping = quote.shipping ?? {};
  const items = [];
  if (shipping.freeThreshold != null) {
    items.push(quote.itemTotalIls != null && quote.itemTotalIls >= shipping.freeThreshold
      ? `Free-shipping threshold met (from ${ils(shipping.freeThreshold)})`
      : `Free shipping from ${ils(shipping.freeThreshold)} item subtotal`);
  }
  if (shipping.minOrder != null) items.push(`Minimum order ${ils(shipping.minOrder)}`);
  if (shipping.destination?.scope === 'localities') {
    const names = (shipping.destination.localities ?? []).map(id => destinationLabels.get(id) ?? id);
    items.push(names.length ? `Delivery area: only ${names.join(', ')}` : 'Delivery area: restricted locality list not published');
  }
  for (const alternative of shipping.alternatives ?? []) {
    items.push(`${alternative.label}: ${alternative.amountIls != null ? ils(alternative.amountIls) : 'rate not published'}`);
  }
  if (shipping.pickup?.available) items.push(shipping.pickup.note ? `Self-pickup: ${shipping.pickup.note}` : 'Free self-pickup available (kept separate from delivery)');
  if (shipping.deliveryTime) items.push(`Delivery time: ${shipping.deliveryTime}`);
  if (shipping.maxTotalGrams != null) items.push(`Rate quoted for carts up to ${shipping.maxTotalGrams} g`);
  return items;
}

function offerDeltaText(quote, board) {
  if (quote.key === board.best?.key) return 'Cheapest delivered total for this selection';
  const delta = board.best && Number.isFinite(quote.totalIls) && Number.isFinite(board.best.totalIls)
    ? Math.round((quote.totalIls - board.best.totalIls) * 100) / 100
    : null;
  if (delta == null) return '';
  if (delta === 0) return 'Same delivered total as the best offer';
  return `+${ils(delta)} vs best delivered total`;
}

