  const rule = resolved.policy.rule;
  const next = { ...shipping };
  let changed = false;
  if (next.certainty === 'unknown' || next.amount == null) {
    if (rule.amount?.amount != null) { next.amount = { ...rule.amount }; next.certainty = resolved.policy.certainty; changed = true; }
  }
  if (next.freeThreshold == null && rule.freeThreshold?.amount != null) { next.freeThreshold = { ...rule.freeThreshold }; changed = true; }
  if (next.minOrder == null && rule.minOrder?.amount != null) { next.minOrder = {...}; changed = true; }
  if (next.service == null && resolved.policy.service) { next.service = resolved.policy.service; changed = true; }
  if (next.maxTotalGrams == null && rule.maxTotalGrams != null) { next.maxTotalGrams = rule.maxTotalGrams; changed = true; }
  if (!next.destination && resolved.policy.destination) { next.destination = { ...resolved.policy.destination }; changed = true; }
