content.text:
// Tracked product and strict listing classification.
//
// Scope (owner correction, 2026-10-12): exactly one product is tracked —
// Lavazza Crema e Gusto ground coffee in a vacuum brick. Qualità Oro,
// Qualità Rossa, Suerte and every other Lavazza line are retired: their names
// survive only as tombstones below, so a listing, a parser page or an old
// ?product= URL can never silently re-enter the board. Re-adding a product
// line requires an explicit new owner instruction.
//
// Classification stays conservative: a listing that cannot be tied to the
// tracked product is rejected instead of being merged into the board. Blend
// variants (Classico, Forte, ...) and pack sizes stay separate so different
// products are never mixed into one comparison.

import { decodeEntities } from './lib/text.js';

const LINE_PATTERNS = {
  'lavazza-crema-e-gusto': [
    /crema\s*(?:e|&|and|-)?\s*gusto/i,
    /קרמה\s*(?:אה\s*)?גוסטו/
  ]
};

/**
 * Product lines that earlier iterations tracked and the 2026-10-12 owner
 * correction retired. They are not fetch targets, not catalog entries and not
 * selectable anywhere; the patterns exist only so `classifyListing()` can
 * reject those pages with an explicit reason and `resolveProductRequest()`
 * can fall back to the tracked product instead of resurrecting them.
 */
export const RETIRED_LINES = [
  {
    id: 'lavazza-qualita-oro-vacuum-ground',
    line: 'Qualità Oro',
    patterns: [
      /qualit[aàáy]\s*oro/i,
      /קוואליטה\s*אורו/,
      /קווליטה\s*אורו/
    ]
  },
  {
    id: 'lavazza-qualita-rossa-vacuum-ground',
    line: 'Qualità Rossa',
    patterns: [
      /qualit[aàáy]\s*rossa/i,
      /קוואליטה\s*רוסה/,
      /קווליטה\s*רוסה/,
      /לווצה\s*רוסה/
    ]
  },
  {
    id: 'lavazza-suerte-ground',
    line: 'Suerte',
    patterns: [
      /lavazza\s*suerte/i,
      /לווצה\s*סוארטה/
    ]
  }
];

export const RETIRED_PRODUCT_IDS = RETIRED_LINES.map(line => line.id);

export const PRODUCTS = [
  {
    id: 'lavazza-crema-e-gusto-vacuum-ground',
    brand: 'Lavazza',
    line: 'Crema e Gusto',
    form: 'ground',
    packaging: 'vacuum brick',
    targetMarket: 'IL',
    defaultVariant: 'classico',
    variants: ['classico', 'forte', 'ricco', 'risveglio', 'decaf', 'unspecified'],
    linePatterns: LINE_PATTERNS['lavazza-crema-e-gusto'],
    notes: 'The only tracked product line (owner correction, 2026-10-12). Ground coffee in a vacuum brick; Classico, Forte, Ricco, Risveglio and decaf remain separate variants, and pack sizes and multipacks stay separate. Beans, capsules, pods and every other Lavazza product line are rejected.'
  }
];

export const products = PRODUCTS;

export const VARIANTS = {
  classico: { id: 'classico', label: 'Classico', aliases: ['classico', 'classic', 'קלאסיקו', 'קלאסי'] },
  forte: { id: 'forte', label: 'Forte', aliases: ['forte', 'פורטה'] },
  ricco: { id: 'ricco', label: 'Ricco', aliases: ['ricco', 'ריקו'] },
  risveglio: { id: 'risveglio', label: 'Risveglio', aliases: ['risveglio', 'התעוררות'] },
  decaf: { id: 'decaf', label: 'Decaffeinated', aliases: ['decaf', 'decaffeinato', 'נטול קפאין', 'dek'] },
  unspecified: { id: 'unspecified', label: 'Variant not stated', aliases: [] }
};

const REJECT_FORMS = [
  // Hebrew is written without word characters, so the Hebrew bean words are matched
  // without \b (a bare \bפולי\b can never match).
  { id: 'beans', pattern: /\b(beans?|whole\s*bean|kaffeebohnen|bønner|boenner|grain)\b|פולי|פול\s*קפה/i, label: 'whole beans' },
  { id: 'capsules', pattern: /(capsul|קפסול|coffee\s*pods?|\bpods?\b|nespresso|dolce\s*gusto|senseo|a\s*modo\s*mio|\bese\b)/i, label: 'capsules or pods' },
  { id: 'machine', pattern: /(coffee\s*machin|מכונת\s*קפה|espresso\s*machine)/i, label: 'coffee machine' }
];

const GROUND_PATTERN = /(ground|טחון|macinato|molido|moulu|gemahlen|malet|filtro|filter\s*coffee)/i;
const BRAND_PATTERN = /(lavazza|לוואצה|לבאצה)/i;

/** Look up a tracked product by id. Retired ids return null by design. */
export function productById(id) {
  return PRODUCTS.find(product => product.id === id) ?? null;
}

/** Look up a retired line definition by id, or null when it was never tracked. */
export function retiredProductById(id) {
  return RETIRED_LINES.find(line => line.id === id) ?? null;
}

export function isRetiredProductId(id) {
  return retiredProductById(id) !== null;
}

/**
 * Resolve a requested product id to the tracked product.
 *
 * Unknown ids — including the retired Qualità Oro, Qualità Rossa and Suerte
 * ids that older shared links and bookmarks still carry — fall back to the
 * one tracked product. The retired definition is returned alongside so callers
 * (the Worker and the offline QA server) can say plainly what happened
 * instead of quietly showing a different product.
 */
export function resolveProductRequest(id) {
  const requested = id ?? null;
  if (!requested) return { product: PRODUCTS[0], retired: null, known: true };
  const product = productById(requested);
  if (product) return { product, retired: null, known: true };
  return { product: PRODUCTS[0], retired: retiredProductById(requested), known: false };
}

/** Look up a blend variant definition by id. */
export function variantById(id) {
  return VARIANTS[id] ?? VARIANTS.unspecified;
}

/**
 * Resolve a requested variant id for a product. An id that is not a tracked
 * variant at all (a typo or an old shared link) falls back to the product's
 * default, exactly like an unknown product or destination. A real variant of
 * another line is returned unchanged so it stays strict and matches no offer on
 * this product's board instead of being silently rewritten.
 */
export function resolveVariantId(product, requested) {
  return requested && Object.hasOwn(VARIANTS, requested) ? requested : product.defaultVariant;
}

/** Variants a product can be compared under, with their display labels. */
export function variantCatalog(product = PRODUCTS[0]) {
  return (product?.variants ?? ['unspecified']).map(id => ({ id, label: variantById(id).label }));
}

/**
 * Classify a listing name against the tracked product.
 *
 * Pass `productId` to require a specific tracked product (vendor adapters do
 * this for the offer they track); without it the first matching tracked product
 * is returned. Heavy HTML entities in vendor titles are decoded first, because
 * pages publish names such as "Lavazza Qualit&#224; Oro". Retired lines are
 * rejected with an explicit reason so historical pages can never re-enter the
 * comparison.
 */
export function classifyListing(text, { productId = null } = {}) {
  const value = decodeEntities(String(text ?? '')).toLowerCase();
  const reasons = [];
  const requestedProduct = productId ? productById(productId) : null;
  const requestedRetired = productId ? retiredProductById(productId) : null;
  const candidates = requestedProduct ? [requestedProduct] : (productId ? [] : PRODUCTS);

  if (productId && !requestedProduct && !requestedRetired) reasons.push(`unknown tracked product: ${productId}`);
  if (requestedRetired) reasons.push(`product line ${requestedRetired.line} was retired; only Lavazza Crema e Gusto is tracked`);
  if (!BRAND_PATTERN.test(value)) reasons.push('brand is not Lavazza');

  const retiredLine = RETIRED_LINES.find(line => line.patterns.some(pattern => pattern.test(value)));
  if (retiredLine) reasons.push(`listing belongs to the retired Lavazza ${retiredLine.line} line; only Lavazza Crema e Gusto is tracked`);

  const product = candidates.find(candidate => candidate.linePatterns.some(pattern => pattern.test(value)));
  if (!product && !retiredLine) {
    const wanted = productId ? `the tracked ${productById(productId)?.line ?? requestedRetired?.line ?? productId} line` : 'the tracked Lavazza Crema e Gusto line';
    reasons.push(`listing is not ${wanted}`);
  }

  const rejected = REJECT_FORMS.find(form => form.pattern.test(value));
  if (rejected) reasons.push(`listing is ${rejected.label}`);
  const ground = GROUND_PATTERN.test(value);
  if (!ground) reasons.push('listing does not state ground coffee');

  const variant = variantOf(value);
  const pack = parsePackSize(text);
  const matched = reasons.length === 0;

  return {
    matched,
    productId: matched ? product.id : null,
    productLine: matched ? product.line : null,
    variantId: variant.id,
    variantLabel: variant.label,
    form: matched ? 'ground' : (rejected ? rejected.id : 'unknown'),
    packGrams: pack.grams,
    packCount: pack.count,
    totalGrams: pack.grams != null ? pack.grams * pack.count : null,
    retiredLine: retiredLine ? { id: retiredLine.id, line: retiredLine.line } : null,
    reasons: matched
      ? (pack.grams == null ? ['pack weight not stated; offer can be shown but not normalized'] : [])
      : reasons
  };
}

export function variantOf(text) {
  const value = String(text || '').toLowerCase();
  for (const variant of Object.values(VARIANTS)) {
    if (variant.id === 'unspecified') continue;
    if (variant.aliases.some(alias => value.includes(alias))) return variant;
  }
  return VARIANTS.unspecified;
}

const OZ_TO_GRAMS = 28.349523125;

/** Parse grams per pack and pack count from a listing name. */
export function parsePackSize(text) {
  const value = decodeEntities(String(text ?? ''));
  let grams = null;

  const ounce = /(\d+(?:[.,]\d+)?)\s*(?:-|\s)?(?:ounce|oz)\b/i.exec(value);
  if (ounce) {
    grams = round(Math.round(parseDecimalValue(ounce[1]) * OZ_TO_GRAMS));
  }
  if (grams == null) {
    const gram = /(\d{2,4}(?:[.,]\d+)?)\s*(?:גרם|גר'|ג'|ג׳|gr\b|g\b|grams?\b|grs\b|gramos\b)/i.exec(value);
    if (gram) grams = round(parseDecimalValue(gram[1]));
  }
  if (grams == null) {
    const kg = /(\d+(?:[.,]\d+)?)\s*(?:kg|ק"ג|קג|קילו)/i.exec(value);
    if (kg) grams = round(parseDecimalValue(kg[1]) * 1000);
  }

  let count = 1;
  const packOf = /pack\s*of\s*(\d{1,3})/i.exec(value);
  const multiply = /(\d{1,3})\s*(?:x|×)\s*\d{2,4}\s*(?:גרם|gr\b|g\b|grams?\b|oz\b|ounce)/i.exec(value);
  const hebrewPacks = /(\d{1,3})\s*(?:אריזות|חבילות|יחידות)/.exec(value);
  if (packOf) count = Number(packOf[1]);
  else if (multiply) count = Number(multiply[1]);
  else if (hebrewPacks) count = Number(hebrewPacks[1]);
  else if (grams == null) {
    const bareCount = /^(\d{1,3})\s*(?:אריזות|חבילות)/.exec(value.trim());
    if (bareCount) count = Number(bareCount[1]);
  }
  if (!Number.isFinite(count) || count < 1 || count > 99) count = 1;
  return { grams, count };
}

function parseDecimalValue(raw) {
  return Number(String(raw).replace(',', '.'));
}

function round(value) {
  return Math.round(value * 10) / 10;
}

// Pure quote and ranking engine.
//
// Comparison total = item price + shipping + mandatory fees, normalized to ILS.
// Unknown shipping, unknown FX, stale observations, unknown availability and
// out-of-stock observations never become zero and never win.
// Pickup options are kept separate from delivered offers.

import { toIls } from './fx.js';
import { enrichObservationShipping, policySummary, SHIPPING_POLICIES } from './policies.js';

export const DEFAULT_STALE_AFTER_MS = 24 * 60 * 60 * 1000;
export const CLOCK_SKEW_MS = 5 * 60 * 1000;

export const DESTINATIONS = [
  { id: 'tel-aviv', label: 'Tel Aviv–Yafo', postcode: '6100000', country: 'IL' },
  { id: 'jerusalem', label: 'Jerusalem', postcode: '9100000', country: 'IL' },
  { id: 'haifa', label: 'Haifa', postcode: '3100000', country: 'IL' },
  { id: 'beer-sheva', label: "Be'er Sheva", postcode: '8400000', country: 'IL' },
  { id: 'eilat', label: 'Eilat', postcode: '8800000', country: 'IL' },
  { id: 'other', label: 'Elsewhere in Israel', postcode: null, country: 'IL' }
];

export function findDestination(id) {
  return DESTINATIONS.find(item => item.id === id) ?? DESTINATIONS[DESTINATIONS.length - 1];
}

const AVAILABILITY_LABELS = {
  in_stock: 'In stock (observed)',
  out_of_stock: 'Out of stock (observed)',
  unknown: 'Availability unknown'
};

/**
 * Plain-language shipping certainty. The board never presents an unknown rate as
 * free, so the label says where the amount came from (or that it is missing)
 * instead of relying on a color or a bare "verified" flag.
 */
const SHIPPING_CERTAINTY_LABELS = {
  verified: 'Published rate (verified)',
  // A rate read from an anonymous public cart/checkout estimator is observed
  // and usable for the recorded cart, but the vendor never published it on the
  // product page, so the label keeps the condition visible instead of calling
  // it a published or completed checkout price.
  checkout_quote: 'Checkout rate (observed, conditional)',
  estimated: 'Estimated rate',
  unknown: 'Not published before checkout'
};

export function shippingCertaintyLabel(certainty) {
  return SHIPPING_CERTAINTY_LABELS[certainty] ?? SHIPPING_CERTAINTY_LABELS.unknown;
}

/**
 * The delivery method a charge buys. This is deliberately separate from the
 * certainty label: a shopper must be able to tell whether ₪30 buys home
 * courier delivery, pickup-point delivery or a distribution-center service,
 * and how well that rate is evidenced.
 */
const SHIPPING_SERVICE_LABELS = {
  home_delivery: 'Home delivery',
  courier: 'Home courier delivery',
  pickup_point: 'Pickup-point delivery',
  distribution_center: 'Distribution-center delivery',
  self_pickup: 'Self-pickup',
  locker: 'Locker delivery'
};

export function shippingServiceLabel(service, mode = 'delivery') {
  if (service && SHIPPING_SERVICE_LABELS[service]) return SHIPPING_SERVICE_LABELS[service];
  return mode === 'pickup' ? SHIPPING_SERVICE_LABELS.self_pickup : 'Delivery method not stated';
}

export function quoteBoard({
  observations = [],
  productId,
  variantId = null,
  targetGrams = 500,
  destination = DESTINATIONS[0],
  fx = null,
  now = Date.now(),
  staleAfterMs = DEFAULT_STALE_AFTER_MS,
  // Validated shipping policies enrich observations whose own shipping is
  // unknown. Pass null to disable (tests of the raw stored evidence).
  policies = SHIPPING_POLICIES
} = {}) {
  const grams = clampGrams(targetGrams);
  const quotes = [];
  const variants = new Set();
  const excludedVariants = new Set();
  let excludedByVariant = 0;
  for (const observation of observations) {
    if (productId && observation?.product?.productId !== productId) continue;
    if (observation?.product?.form !== 'ground') continue;
    variants.add(observation?.product?.variantId ?? 'unspecified');
    if (variantId && (observation?.product?.variantId ?? 'unspecified') !== variantId) {
      // Kept out of this ranking on purpose: variants are never merged. The
      // count lets the UI tell the shopper that offers for another variant exist.
      excludedByVariant += 1;
      excludedVariants.add(observation?.product?.variantId ?? 'unspecified');
      continue;
    }
    // Read-time policy enrichment: an old stored row whose shipping was unknown
    // gains a validated rule without waiting for the next vendor refresh. The
    // observation's own price, stock and observedAt are never touched.
    const enriched = policies === null
      ? observation
      : enrichObservationShipping(observation, { policies, now }).observation;
    quotes.push(quoteOffer(enriched, { grams, destination, fx, now, staleAfterMs }));
  }
  const ranked = quotes.filter(quote => quote.rankable).sort(compareQuotes);
  // The cheapest delivered total is not always the cheapest bulk value. Keep the
  // per-kilogram winner as separate structured evidence so the board can call it
  // out without changing the ranking itself.
  const bestPerKgQuote = ranked.length
    ? ranked.reduce((min, quote) => (quote.ilsPerKg < min.ilsPerKg ? quote : min))
    : null;
  const pickup = [
    ...quotes.filter(quote => quote.group === 'pickup'),
    ...quotes
      .filter(quote => quote.group !== 'pickup' && quote.shipping?.pickup?.available)
      .map(toPickupEntry)
  ];
  const unrankable = quotes.filter(quote => quote.group === 'unrankable');
  const staleOrUnavailable = quotes.filter(quote => quote.group === 'stale_unavailable');
  const unknown = [...unrankable, ...staleOrUnavailable];
  return {
    productId,
    variantId,
    variants: [...variants].sort(),
    targetGrams: grams,
    destination,
    generatedAt: new Date(now).toISOString(),
    fx: fx ? { asOf: fx.asOf ?? null, source: fx.source?.name ?? null } : null,
    shippingPolicies: policies === null ? [] : policySummary(now, policies),
    best: ranked[0] ?? null,
    bestPerKg: bestPerKgQuote
      ? {
          key: bestPerKgQuote.key,
          vendor: bestPerKgQuote.vendor,
          ilsPerKg: bestPerKgQuote.ilsPerKg,
          totalIls: bestPerKgQuote.totalIls,
          units: bestPerKgQuote.units,
          orderedGrams: bestPerKgQuote.orderedGrams,
          packGrams: bestPerKgQuote.product.packGrams,
          packCount: bestPerKgQuote.product.packCount
        }
      : null,
    ranked,
    pickup,
    unrankable,
    staleOrUnavailable,
    unknown,
    counts: {
      observed: quotes.length,
      ranked: ranked.length,
      pickup: pickup.length,
      unknown: unknown.length,
      excludedByVariant,
      excludedVariants: [...excludedVariants].sort()
    }
  };
}

export function quoteOffer(observation, { grams, destination, fx, now, staleAfterMs }) {
  const product = observation.product ?? {};
  const price = observation.price ?? {};
  const shipping = observation.shipping ?? {};
  const reasons = [];
  const labels = [];

  const ageMs = observation.observedAt ? now - Date.parse(observation.observedAt) : null;
  const stale = ageMs == null || ageMs > staleAfterMs || ageMs < -CLOCK_SKEW_MS;
  const freshness = ageMs == null ? 'unknown' : stale ? 'stale' : 'fresh';

  const base = {
    key: observation.key,
    vendor: observation.vendor,
    itemUrl: observation.itemUrl,
    product: {
      productId: product.productId,
      name: product.name ?? null,
      variantId: product.variantId ?? 'unspecified',
      variantLabel: product.variantLabel ?? 'Variant not stated',
      form: product.form,
      packGrams: product.packGrams ?? null,
      packCount: product.packCount ?? 1,
      totalGrams: product.totalGrams ?? null,
      sku: product.sku ?? null
    },
    availability: observation.availability ?? 'unknown',
    availabilityLabel: AVAILABILITY_LABELS[observation.availability] ?? AVAILABILITY_LABELS.unknown,
    freshness,
    ageHours: ageMs == null ? null : Math.round((ageMs / 3_600_000) * 10) / 10,
    observedAt: observation.observedAt ?? null,
    attemptedAt: observation.attemptedAt ?? null,
    // A failed last attempt keeps the previous good price and stock, but the
    // board must be able to say that the most recent check failed instead of
    // presenting the row as freshly re-checked.
    lastError: observation.lastError ?? null,
    lastAttemptFailed: Boolean(observation.lastError),
    evidence: observation.evidence ?? [],
    previous: summarizePrevious(observation.previous),
    priceChange: priceChangeOf({ current: price, previous: observation.previous, product, fx }),
    units: null,
    orderedGrams: null,
    itemPrice: { amount: price.amount ?? null, currency: price.currency ?? null },
    itemTotalIls: null,
    shipping: {
      mode: shipping.mode ?? 'delivery',
      service: shipping.service ?? null,
      serviceLabel: shippingServiceLabel(shipping.service ?? null, shipping.mode ?? 'delivery'),
      certainty: shipping.certainty ?? 'unknown',
      certaintyLabel: shippingCertaintyLabel(shipping.certainty ?? 'unknown'),
      amount: shipping.amount?.amount ?? null,
      currency: shipping.amount?.currency ?? null,
      amountIls: null,
      freeThreshold: shipping.freeThreshold?.amount ?? null,
      freeThresholdCurrency: shipping.freeThreshold?.currency ?? null,
      // The vendor's own wording decides the boundary: "above ₪100" is strictly
      // greater than the threshold, "from/at least ₪100" is greater-or-equal.
      // The default only applies when no wording was recorded.
      freeThresholdSemantics: shipping.freeThresholdSemantics ?? shipping.policy?.thresholdSemantics ?? 'at_least',
      minOrder: shipping.minOrder?.amount ?? null,
      minOrderCurrency: shipping.minOrder?.currency ?? null,
      destination: shipping.destination ?? { scope: 'country', country: 'IL' },
      deliveryTime: shipping.deliveryTime ?? null,
      maxTotalGrams: shipping.maxTotalGrams ?? null,
      pickup: shipping.pickup ?? null,
      alternatives: (shipping.alternatives ?? []).map(alternative => {
        const converted = toIls(alternative.amount?.amount ?? null, alternative.amount?.currency ?? price.currency, fx);
        return {
          id: alternative.id ?? null,
          label: alternative.label ?? 'Alternative shipping option',
          amount: alternative.amount?.amount ?? null,
          currency: alternative.amount?.currency ?? price.currency ?? null,
          amountIls: converted.known ? round2(converted.amount) : null,
          note: alternative.note ?? null
        };
      }),
      note: shipping.note ?? null,
      policy: shipping.policy ?? null,
      evidence: shipping.evidence ?? null
    },
    mandatoryFees: [],
    totalIls: null,
    ilsPerKg: null,
    estimate: false,
    rankable: false,
    reasons,
    labels,
    group: 'unrankable'
  };

  if (observation.shipping?.mode === 'pickup') {
    base.group = 'pickup';
    base.labels.push('Pickup only — not a delivered offer');
    if (product.totalGrams) {
      base.units = Math.max(1, Math.ceil(grams / product.totalGrams));
      base.orderedGrams = base.units * product.totalGrams;
    }
    const pickupTotal = toIls(price.amount == null ? null : price.amount * (base.units ?? 1), price.currency, fx);
    if (pickupTotal.known) {
      base.itemTotalIls = round2(pickupTotal.amount);
      base.labels.push('Shown for pickup comparison only');
    }
    if (stale) {
      base.labels.push('Stale observation — the last successful check is too old; treat the item total as out of date');
    }
    return base;
  }

  if (!product.totalGrams || !product.packGrams) {
    reasons.push('Pack weight is not stated, so the delivered price per kilogram cannot be calculated');
    return base;
  }

  const units = Math.max(1, Math.ceil(grams / product.totalGrams));
  base.units = units;
  base.orderedGrams = units * product.totalGrams;

  const itemTotal = toIls(price.amount == null ? null : price.amount * units, price.currency, fx);
  if (!itemTotal.known) {
    reasons.push(price.amount == null
      ? 'Item price was not observed'
      : `No ${price.currency} reference rate is stored, so the total cannot be converted to ILS`);
    if (price.amount != null && Number.isFinite(price.amount)) {
      base.itemPrice.amount = round2(price.amount * units);
    }
    return base;
  }
  base.itemTotalIls = round2(itemTotal.amount);
  if (itemTotal.converted) base.estimate = true;

  // A rate observed on a smaller anonymous cart is not silently stretched to a
  // bigger one: the offer stays visible and unrankable with the exact reason.
  if (shipping.maxTotalGrams != null && base.orderedGrams > shipping.maxTotalGrams) {
    reasons.push(`Shipping was quoted only for carts up to ${shipping.maxTotalGrams} g, but this quantity is ${base.orderedGrams} g`);
    return base;
  }

  if (shipping.minOrder != null) {
    const min = toIls(shipping.minOrder.amount, shipping.minOrder.currency ?? price.currency, fx);
    if (min.known && base.itemTotalIls < min.amount - 0.005) {
      reasons.push(`Order is below the vendor minimum order of ${formatAmount(min.amount, 'ILS')}`);
      return base;
    }
  }

  const coverage = coverageProblem(shipping.destination, destination);
  if (coverage) {
    reasons.push(coverage);
    return base;
  }
  // A published rate whose locality list is not published is a disclosed caveat,
  // not a blocker: the vendor states home delivery is subject to the list, so the
  // board keeps ranking but never claims unconditional coverage of the destination.
  const coverageCaveat = typeof shipping.destination?.caveat === 'string' && shipping.destination.caveat.trim()
    ? shipping.destination.caveat.trim()
    : null;
  if (coverageCaveat) {
    base.shipping.coverageCaveat = coverageCaveat;
    base.labels.push(`Delivery coverage caveat: ${coverageCaveat}`);
  }

  if (observation.availability === 'out_of_stock') {
    base.labels.push('Out of stock at last successful check');
    base.group = 'stale_unavailable';
    return base;
  }
  if (observation.availability !== 'in_stock') {
    reasons.push('Stock was not confirmed by the source, so this offer cannot be confirmed as available');
    base.group = 'stale_unavailable';
    return base;
  }

  const feeSum = { amount: 0, currency: 'ILS' };
  for (const fee of observation.mandatoryFees ?? []) {
    const converted = toIls(fee.amount, fee.currency, fx);
    if (!converted.known) {
      reasons.push(`A mandatory fee (${fee.label ?? 'unlabelled'}) could not be converted to ILS`);
      return base;
    }
    feeSum.amount += converted.amount;
    base.mandatoryFees.push({ label: fee.label ?? 'Mandatory fee', amountIls: round2(converted.amount) });
  }

  let shippingIls = null;
  if (shipping.certainty === 'unknown' || shipping.amount == null) {
    reasons.push(shipping.note
      ? `Shipping is not published before checkout, so it is treated as unknown, not free (${shipping.note})`
      : 'Shipping is not published before checkout, so it is treated as unknown, not free');
    return base;
  }
  const convertedShipping = toIls(shipping.amount.amount ?? shipping.amount, shipping.amount.currency ?? price.currency, fx);
  if (!convertedShipping.known) {
    reasons.push(`Shipping is quoted in ${shipping.amount.currency ?? 'an unknown currency'} with no stored reference rate`);
    return base;
  }
  shippingIls = convertedShipping.amount;
  if (convertedShipping.converted || shipping.certainty === 'estimated') base.estimate = true;

  if (shipping.freeThreshold != null) {
    const threshold = toIls(shipping.freeThreshold.amount, shipping.freeThreshold.currency, fx);
    // "above ₪100" means the ₪100 boundary itself is not free; only a strictly
    // larger item subtotal is. Never silently relax the vendor's wording.
    const semantics = base.shipping.freeThresholdSemantics;
    const met = threshold.known && (semantics === 'above'
      ? base.itemTotalIls > threshold.amount + 0.005
      : base.itemTotalIls >= threshold.amount - 0.005);
    if (met) {
      shippingIls = 0;
      base.labels.push(`Free shipping threshold met (${semantics === 'above' ? 'above' : 'from'} ${formatAmount(threshold.amount, 'ILS')})`);
    }
  }

  base.shipping.amountIls = round2(shippingIls);
  if (stale) {
    labels.push('Stale observation — the last successful check is too old to rank');
    base.group = 'stale_unavailable';
    return base;
  }

  base.totalIls = round2(base.itemTotalIls + shippingIls + feeSum.amount);
  base.ilsPerKg = round2((base.totalIls / base.orderedGrams) * 1000);
  base.rankable = true;
  base.group = 'ranked';
  if (base.estimate) labels.push('Estimate — includes a converted or estimated component');
  return base;
}

/** Shape the stored previous-check snapshot for the API without leaking raw payloads. */
function summarizePrevious(previous) {
  if (!previous || typeof previous !== 'object') return null;
  const availability = previous.availability ?? 'unknown';
  return {
    observedAt: previous.observedAt ?? null,
    priceAmount: previous.price?.amount ?? null,
    priceCurrency: previous.price?.currency ?? null,
    availability,
    availabilityLabel: AVAILABILITY_LABELS[availability] ?? AVAILABILITY_LABELS.unknown
  };
}

/**
 * Compare the unit price with the previous successful check.
 * The comparison is in ILS using the stored Bank of Israel rate when needed, is
 * only made between equal pack weights, and is never reported as "no change"
 * when a conversion is impossible.
 */
function priceChangeOf({ current, previous, product, fx }) {
  const previousPrice = previous?.price;
  if (!previous?.observedAt || previousPrice?.amount == null || current?.amount == null) return null;
  const previousObservedAt = previous.observedAt;
  const previousAmount = previousPrice.amount;
  const previousCurrency = previousPrice.currency ?? current.currency ?? null;
  if (previous.totalGrams != null && product.totalGrams != null && previous.totalGrams !== product.totalGrams) {
    return {
      comparable: false,
      reason: 'the pack size changed since the previous check, so the unit prices are not comparable',
      previousObservedAt,
      previousAmount,
      previousCurrency
    };
  }
  const before = toIls(previousAmount, previousCurrency, fx);
  const after = toIls(current.amount, current.currency ?? previousCurrency, fx);
  if (!before.known || !after.known) {
    return {
      comparable: false,
      reason: 'a stored exchange rate is needed to compare the previous price',
      previousObservedAt,
      previousAmount,
      previousCurrency
    };
  }
  const delta = round2(after.amount - before.amount);
  return {
    comparable: true,
    direction: delta < 0 ? 'down' : delta > 0 ? 'up' : 'same',
    deltaIls: Math.abs(delta),
    previousAmount,
    previousCurrency,
    previousIls: round2(before.amount),
    previousObservedAt
  };
}

function coverageProblem(shippingDestination, destination) {
  if (!shippingDestination) return null;
  if (shippingDestination.scope === 'country') {
    if (destination?.country && shippingDestination.country !== destination.country) {
      return `Vendor does not deliver to ${destination.country}`;
    }
    return null;
  }
  if (shippingDestination.scope === 'localities') {
    const localities = shippingDestination.localities ?? [];
    if (!destination?.id || !localities.includes(destination.id)) {
      return `Vendor delivery list does not include ${destination?.label ?? 'this destination'}`;
    }
    return null;
  }
  return 'Vendor delivery coverage is not documented';
}

function toPickupEntry(quote) {
  const itemTotal = quote.itemTotalIls ?? (quote.itemPrice.amount != null && quote.units
    ? round2(quote.itemPrice.amount * quote.units)
    : null);
  return {
    ...quote,
    key: `${quote.key}:pickup`,
    group: 'pickup',
    rankable: false,
    totalIls: null,
    ilsPerKg: null,
    itemTotalIls: itemTotal,
    pickup: {
      available: true,
      amount: quote.shipping.pickup?.amount ?? null,
      note: quote.shipping.pickup?.note ?? null
    },
    labels: [...quote.labels.filter(label => !label.startsWith('Delivery coverage caveat:')), 'Pickup only — not a delivered offer']
  };
}

function compareQuotes(a, b) {
  if (a.totalIls !== b.totalIls) return a.totalIls - b.totalIls;
  if (a.ilsPerKg !== b.ilsPerKg) return a.ilsPerKg - b.ilsPerKg;
  return String(a.vendor?.name ?? '').localeCompare(String(b.vendor?.name ?? ''));
}

export function clampGrams(value) {
  const grams = Number(value);
  if (!Number.isFinite(grams) || grams <= 0) return 500;
  return Math.min(Math.max(Math.round(grams), 1), 100_000);
}

export function formatAmount(amount, currency = 'ILS') {
  const symbols = { ILS: '₪', USD: '$', EUR: '€', GBP: '£' };
  const symbol = symbols[String(currency).toUpperCase()] ?? `${currency} `;
  return `${symbol}${Number(amount).toFixed(2)}`;
}

function round2(value) {
  return Math.round(value * 100) / 100;
}

// Public Worker: read-only comparison board plus the scheduled refresh entry.
//
// Public routes only read the persisted snapshot. They never fetch vendor URLs
// supplied by a visitor and never trigger unbounded scraping. The first request
// after a deployment may start one throttled initial refresh.

import { products, resolveProductRequest, variantCatalog, resolveVariantId } from './catalog.js';
import { quoteBoard, findDestination, DESTINATIONS } from './lib/quote.js';
import { policySummary } from './lib/policies.js';
import { runRefresh, maybeInitialRefresh, refreshFreshness, newestObservationAt } from './refresh.js';
import { durableStore, storeClient } from './store.js';
import { registeredVendors } from './vendors/index.js';

export { BoardStore } from './store.js';

const PUBLIC_CACHE = 'public, max-age=300, stale-while-revalidate=3600';
// Freshness must only consider observations for product lines that are still tracked:
// a lingering historical row must not keep the single-product board looking fresh.
const TRACKED_PRODUCT_IDS = products.map(product => product.id);

export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);
    if (request.method !== 'GET' && request.method !== 'HEAD') {
      return Response.json({ error: 'Method not allowed' }, { status: 405, headers: { allow: 'GET, HEAD' } });
    }
    if (url.pathname === '/health') {
      scheduleInitialRefresh(env, ctx);
      return handleHealth(env);
    }
    if (url.pathname === '/api/catalog') {
      return json({ products: publicProducts(), destinations: DESTINATIONS, vendors: publicVendors() });
    }
    if (url.pathname === '/api/board') {
      scheduleInitialRefresh(env, ctx);
      return handleBoard(request, env, ctx, url);
    }
    if (url.pathname === '/api/status') {
      return handleStatus(env);
    }
    if (url.pathname.startsWith('/api/')) {
      return json({ error: 'Not found' }, 404);
    }
    // Product-detail pages are directly loadable: /product/<id> is served the
    // product page asset, which resolves the id (including a retired-line
    // fallback) against the tracked catalog through the read-only API.
    if (url.pathname === '/product' || /^\/product\/[^/]+\/?$/.test(url.pathname)) {
      if (!env.ASSETS) return new Response('Not found', { status: 404 });
      const assetUrl = new URL('/product.html', url.origin);
      return env.ASSETS.fetch(new Request(assetUrl, { method: request.method, headers: request.headers }));
    }
    if (env.ASSETS) return env.ASSETS.fetch(request);
    return new Response('Not found', { status: 404 });
  },

  async scheduled(event, env, ctx) {
    const store = storeClient(durableStore(env));
    const job = runRefresh({ store, trigger: event?.cron ? 'cron' : 'scheduled' });
    if (ctx?.waitUntil) ctx.waitUntil(job);
    return job;
  }
};

function json(body, status = 200, headers = {}) {
  return Response.json(body, { status, headers: { 'Cache-Control': PUBLIC_CACHE, ...headers } });
}

async function handleHealth(env) {
  let refresh = null;
  let lastObservationAt = null;
  let error = null;
  try {
    if (env.BOARD) {
      const store = storeClient(durableStore(env));
      const snapshot = await store.snapshot();
      refresh = snapshot.meta?.lastRefreshAt?.value ?? null;
      lastObservationAt = newestObservationAt(snapshot.observations, TRACKED_PRODUCT_IDS);
    }
  } catch (cause) {
    error = 'storage unavailable';
  }
  return json({ status: 'ok', stage: 'live', lastRefreshAt: refresh, lastObservationAt, storageError: error });
}

async function handleBoard(request, env, ctx, url) {
  if (!env.BOARD) {
    return json({
      status: 'storage not configured',
      offers: [],
      message: 'The board needs the BOARD Durable Object binding from docs/DEPLOYMENT.md.'
    });
  }
  const store = storeClient(durableStore(env));
  // Owner correction 2026-10-12: only Crema e Gusto is tracked. An old shared
  // URL that still names a retired line (Qualità Oro, Qualità Rossa, Suerte)
  // falls back to the tracked product and says so instead of reviving it.
  const { product, retired } = resolveProductRequest(url.searchParams.get('product'));
  const productId = product.id;
  const requestedVariant = url.searchParams.get('variant');
  // A variant id that is not tracked at all (a typo or an old shared link) falls
  // back to the product's default, like an unknown product or destination. A real
  // variant of another line stays strict: it matches nothing on this board.
  const variantId = resolveVariantId(product, requestedVariant);
  const grams = url.searchParams.get('grams') ?? '500';
  const destination = findDestination(url.searchParams.get('dest'));
  const snapshot = await store.snapshot();
  const lastObservationAt = newestObservationAt(snapshot.observations, TRACKED_PRODUCT_IDS);
  const board = quoteBoard({
    observations: snapshot.observations,
    productId,
    variantId,
    targetGrams: grams,
    destination,
    fx: snapshot.meta?.fx ?? null,
    now: Date.now()
  });
  const vendors = snapshot.vendors ?? {};
  return json({
    ...board,
    product: publicProduct(product),
    requestedRetiredProduct: retired ? { id: retired.id, line: retired.line } : null,
    freshness: {
      ...refreshFreshness(snapshot.meta?.lastRefreshAt?.value ?? null, Date.now(), lastObservationAt),
      fx: snapshot.meta?.fx ? { asOf: snapshot.meta.fx.asOf, fetchedAt: snapshot.meta.fx.fetchedAt, source: snapshot.meta.fx.source?.name ?? null } : null,
      vendors: Object.values(vendors).map(state => ({
        vendorId: state.vendorId,
        lastAttemptAt: state.lastAttemptAt,
        lastSuccessAt: state.lastSuccessAt,
        consecutiveFailures: state.consecutiveFailures,
        nextAttemptAt: state.nextAttemptAt,
        lastErrors: state.lastErrors ?? []
      }))
    },
    status: board.ranked.length > 0
      ? 'Delivered totals ranked from verified observations.'
      : 'No offer currently has enough verified information to rank. Unknowns are listed below.'
  }, 200, {
    'Vary': 'Accept-Encoding',
    'Access-Control-Allow-Origin': '*'
  });
}

async function handleStatus(env) {
  if (!env.BOARD) return json({ status: 'storage not configured', vendors: [], runs: [] });
  const store = storeClient(durableStore(env));
  const snapshot = await store.snapshot();
  const lastObservationAt = newestObservationAt(snapshot.observations, TRACKED_PRODUCT_IDS);
  return json({
    lastRefreshAt: snapshot.meta?.lastRefreshAt?.value ?? null,
    lastObservationAt,
    freshness: refreshFreshness(snapshot.meta?.lastRefreshAt?.value ?? null, Date.now(), lastObservationAt),
    fx: snapshot.meta?.fx ? { asOf: snapshot.meta.fx.asOf, fetchedAt: snapshot.meta.fx.fetchedAt } : null,
    // Versioned shipping policies applied at read time: which rule version is in
    // force, when it was observed and when it must be re-checked. An expired
    // policy stops enriching offers until browser research renews it.
    shippingPolicies: policySummary(Date.now()),
    vendors: Object.values(snapshot.vendors ?? {}).map(state => ({
      vendorId: state.vendorId,
      lastAttemptAt: state.lastAttemptAt,
      lastSuccessAt: state.lastSuccessAt,
      consecutiveFailures: state.consecutiveFailures,
      nextAttemptAt: state.nextAttemptAt,
      lastErrors: state.lastErrors ?? []
    })),
    runs: (snapshot.runs ?? []).map(run => ({
      trigger: run.trigger,
      startedAt: run.startedAt,
      finishedAt: run.finishedAt,
      requests: run.requests,
      vendors: run.vendors
    })),
    observations: snapshot.observations.length
  });
}

export function publicVendors() {
  return registeredVendors().map(vendor => ({
    id: vendor.id,
    name: vendor.name,
    homepage: vendor.homepage,
    offers: vendor.offers.map(offer => ({ id: offer.id, url: offer.url, kind: offer.kind, productId: offer.productId ?? null }))
  }));
}

/** Public product shape: identity, packaging and the selectable variants. */
export function publicProduct(product) {
  if (!product) return null;
  return {
    id: product.id,
    brand: product.brand,
    line: product.line,
    form: product.form,
    packaging: product.packaging,
    targetMarket: product.targetMarket,
    defaultVariant: product.defaultVariant,
    variants: variantCatalog(product),
    notes: product.notes
  };
}

export function publicProducts() {
  return products.map(publicProduct);
}

function scheduleInitialRefresh(env, ctx) {
  const work = triggerInitialRefreshIfNeeded(env, ctx)
    .catch(error => console.warn('initial refresh trigger failed:', error?.stack ?? error));
  if (ctx?.waitUntil) ctx.waitUntil(work);
  return work;
}

export async function triggerInitialRefreshIfNeeded(env, ctx) {
  if (!env.BOARD) return { skipped: true, reason: 'no storage binding' };
  const store = storeClient(durableStore(env));
  return maybeInitialRefresh({ store, ctx });
}

// Home product index.
//
// The canonical home route shows the tracked catalog as cards, not the vendor
// comparison board. Each card links to the product's own directly loadable page
// (`/product/<id>`). A legacy board link that still carries product/quantity/
// destination/variant query state is forwarded to the product page with that
// state intact, so old shared URLs keep working and a retired product id can
// still be reported as a fallback instead of being silently dropped.

import { el, timeLabel, bidi } from './ui.js';

const params = new URLSearchParams(location.search);
const LEGACY_KEYS = ['product', 'grams', 'dest', 'variant', 'unknown'];
const isLegacyBoardLink = LEGACY_KEYS.some(key => params.has(key));

const list = document.getElementById('catalog-list');
const footer = document.getElementById('footer-status');

async function main() {
  let catalog = null;
  try {
    catalog = await fetch('/api/catalog').then(response => response.json());
  } catch (error) {
    renderError(`The product index could not be loaded (${error?.message ?? error}). The stored observations are safe; try again in a moment.`);
    return;
  }
  const products = catalog?.products ?? [];
  if (!products.length) {
    renderError('No tracked product is configured on this deployment.');
    return;
  }
  if (isLegacyBoardLink) {
    // Keep the old selection state (including a retired product request) in the
    // forwarded URL. The product page resolves it against the tracked catalog.
    const target = `/product/${encodeURIComponent(products[0].id)}?${params.toString()}`;
    location.replace(target);
    return;
  }
  renderCatalog(products, catalog.vendors ?? []);
  renderFooterStatus();
}

function renderCatalog(products, vendors) {
  list.replaceChildren();
  for (const product of products) {
    list.append(productCard(product, vendors));
  }
}

function productCard(product, vendors) {
  const vendorCount = vendors.length;
  const listingCount = vendors.reduce((sum, vendor) => sum + (vendor.offers?.length ?? 0), 0);
  const vendorNames = vendors.map(vendor => vendor.name).filter(Boolean);
  const card = el('article', { class: 'product-card' },
    el('p', { class: 'product-card__brand', text: product.brand }),
    el('h2', { class: 'product-card__name' }, bidi(`${product.brand} ${product.line}`)),
    el('p', { class: 'product-card__meta', text: `${product.form} coffee in a ${product.packaging} · sold as 250 g packs and multipacks · blend variants compared separately` }),
    el('p', { class: 'product-card__summary', text: `Compare item subtotal, named delivery method and charge, and the delivered total for a chosen quantity and Israeli locality. ${vendorCount} tracked vendor${vendorCount === 1 ? '' : 's'}${listingCount ? ` · ${listingCount} listing${listingCount === 1 ? '' : 's'}` : ''}${vendorNames.length ? `: ${vendorNames.join(', ')}` : ''}.` }),
    el('p', { class: 'product-card__action' },
      el('a', { class: 'product-card__link', href: `/product/${encodeURIComponent(product.id)}`, text: 'Compare delivered offers' })));
  return card;
}

async function renderFooterStatus() {
  if (!footer) return;
  try {
    const status = await fetch('/api/status').then(response => response.json());
    const observed = status?.lastObservationAt ?? status?.freshness?.lastObservationAt ?? null;
    footer.textContent = observed
      ? `Tracked offers last checked ${timeLabel(observed)}.`
      : 'No offer observation is stored yet; the first scheduled refresh will populate the board.';
  } catch {
    footer.textContent = 'Observation time is unavailable right now.';
  }
}

function renderError(message) {
  list.replaceChildren(el('div', { class: 'empty' }, el('strong', { text: 'The product index could not be loaded.' }), el('p', { text: message })));
}

main();

// Product-detail client for one tracked product.
//
// The page keeps the shopping decision compact: product identity, quantity,
// locality and variant controls, then the best eligible offer with item
// subtotal, named shipping method/charge and delivered total visible together.
// Everything else — other offers, delivery alternatives and conditions, pickup,
// missing-information offers, check history and diagnostics — is progressively
// disclosed in native <details> sections. All vendor text is inserted as text.

import {
  el, money, bidi, timeLabel, dueLabel, truncate,
  packDescription, quantityDescription, itemSubtotalText,
  totalsBlock, statusBadge, offerLink, conditionsList, caveatBlock,
  coverageQualifier, diagnosticsDisclosure, VARIANT_LABELS
} from './ui.js';

const GRAMS_OPTIONS = [250, 500, 750, 1000, 2000];

const params = new URLSearchParams(location.search);
const pathProduct = decodeURIComponent(location.pathname.replace(/^\/product\/?/, '')) || null;

const state = {
  grams: Number(params.get('grams')) || 500,
  destination: params.get('dest') || 'tel-aviv',
  product: pathProduct,
  requestedProduct: params.get('product') || pathProduct,
  variant: params.get('variant') || null,
  catalog: null,
  board: null,
  error: null
};

// Monotonic request token: board requests can overlap when a shopper changes the
// quantity, destination or variant while a previous request is still in flight.
// Only the newest request may write state.
let loadToken = 0;

function packLine(quote) {
  return `${packDescription(quote)} · ${quantityDescription(quote)} · ${quote.product.variantLabel}`;
}

function destinationLabel(id) {
  const found = (state.catalog?.destinations ?? []).find(item => item.id === id);
  return found?.label ?? id;
}

async function load() {
  const token = ++loadToken;
  try {
    const catalogResponse = await fetch('/api/catalog').then(response => response.json());
    if (token !== loadToken) return;
    state.catalog = catalogResponse;
    applyProductDefaults();
    // The requested id (which may name a retired line) is sent as requested so
    // the API can report the fallback instead of hiding it.
    const requestedProduct = state.requestedProduct ?? state.product;
    const query = new URLSearchParams({ product: requestedProduct, grams: String(state.grams), dest: state.destination, variant: state.variant });
    const board = await fetch(`/api/board?${query}`).then(response => response.json());
    if (token !== loadToken) return;
    state.board = board;
    state.error = null;
  } catch (error) {
    if (token !== loadToken) return;
    state.error = error?.message ?? String(error);
  }
  if (token !== loadToken) return;
  document.body.dataset.boardState = state.error ? 'error' : 'ready';
  render();
}

/** Keep the selected product and variant valid for the tracked catalog. */
function applyProductDefaults() {
  const catalogProducts = state.catalog?.products ?? [];
  if (!catalogProducts.length) return;
  if (!catalogProducts.some(item => item.id === state.product)) state.product = catalogProducts[0].id;
  const product = currentProduct();
  const variants = (product?.variants ?? []).map(item => item.id);
  if (!variants.includes(state.variant)) state.variant = product?.defaultVariant ?? variants[0] ?? 'unspecified';
}

function currentProduct() {
  return (state.catalog?.products ?? []).find(item => item.id === state.product) ?? null;
}

function render() {
  renderIdentity();
  renderControls();
  updateFooterStatus();
  const board = document.getElementById('board');
  board.replaceChildren();
  if (state.error) {
    board.append(el('div', { class: 'empty' },
      el('strong', { text: 'The comparison could not be loaded.' }),
      el('p', { text: `Reason: ${state.error}. The stored observations are safe; try again in a moment.` })));
    return;
  }
  if (!state.board) return;
  const boardData = state.board;
  const fallbackNotice = renderFallbackNotice(boardData);
  if (fallbackNotice) board.append(fallbackNotice);
  board.append(renderDecision(boardData));
}

/** Product heading names the product; the masthead carries the compact branding. */
function renderIdentity() {
  const product = state.board?.product ?? currentProduct();
  const title = document.getElementById('product-title');
  const subtitle = document.getElementById('product-subtitle');
  if (title && product) title.textContent = `${product.brand} ${product.line}`;
  if (subtitle && product) {
    subtitle.textContent = `${product.form} coffee · ${product.packaging} · delivery in Israel`;
  }
}

function renderFallbackNotice(board) {
  if (board.requestedRetiredProduct) {
    return el('div', { class: 'notice', attrs: { id: 'retired-product-notice', role: 'note' } },
      el('strong', { text: 'Retired product line' }),
      el('p', {},
        'This link asked for Lavazza ',
        bidi(board.requestedRetiredProduct.line),
        '. Only Lavazza Crema e Gusto vacuum-packed ground coffee is tracked now, so the comparison below covers Crema e Gusto offers only. Re-tracking another product line needs an explicit new owner instruction.'));
  }
  const requested = state.requestedProduct;
  if (requested && board.product && requested !== board.product.id) {
    return el('div', { class: 'notice', attrs: { id: 'unknown-product-notice', role: 'note' } },
      el('strong', { text: 'Untracked product link' }),
      el('p', { text: `This link asked for product “${requested}”, which is not tracked. Showing the tracked product instead.` }));
  }
  return null;
}

/** Default view: best eligible offer plus progressively disclosed comparison. */
function renderDecision(board) {
  const section = el('section', { class: 'decision', attrs: { id: 'decision' } });
  if (!board.best) {
    section.append(el('div', { class: 'empty' },
      el('strong', { text: 'No offer can be ranked for this selection right now.' }),
      el('p', { text: 'Ranking needs a fresh confirmed stock observation and a published or observed shipping rate. The offers with missing information below explain exactly what is missing.' })));
  } else {
    section.append(renderBestOffer(board.best, board));
    const others = board.ranked.slice(1);
    if (others.length) section.append(renderCompareDisclosure(others, board));
  }
  const pickup = board.pickup ?? [];
  if (pickup.length) section.append(renderPickupDisclosure(pickup));
  const unknownEntries = [...(board.unrankable ?? []), ...(board.staleOrUnavailable ?? [])];
  if (unknownEntries.length) section.append(renderUnknownDisclosure(unknownEntries));
  const perKgWinner = board.bestPerKg && board.best && board.bestPerKg.key !== board.best.key ? board.bestPerKg : null;
  if (perKgWinner) {
    const quantity = (perKgWinner.packCount ?? 1) > 1
      ? `${perKgWinner.units} multipack${perKgWinner.units === 1 ? '' : 's'} (${perKgWinner.packCount} × ${perKgWinner.packGrams} g) = ${perKgWinner.orderedGrams} g`
      : `${perKgWinner.units} × ${perKgWinner.packGrams} g pack${perKgWinner.units === 1 ? '' : 's'} = ${perKgWinner.orderedGrams} g`;
    section.append(el('p', { class: 'meta-line' },
      'Cheapest per kilogram: ',
      bidi(perKgWinner.vendor?.name ?? ''),
      ` — ${money(perKgWinner.ilsPerKg)} per kg (${quantity}, delivered ${money(perKgWinner.totalIls)})`));
  }
  section.append(el('p', { class: 'meta-line', text: 'Comparison total = item subtotal + shipping + mandatory fees, converted to ILS where a stored Bank of Israel reference rate is needed. This is not a personalized checkout quote.' }));
  section.append(renderFooterStatus(board));
  return section;
}

/** Best eligible offer: vendor, pack/grams, the three money values and a short warning. */
function renderBestOffer(quote, board) {
  const card = el('article', { class: 'offer offer--best', attrs: { id: 'best-offer' } });
  // One compact identity row: the best-offer label, the vendor and its stock
  // label. The full comparison values follow immediately below so the money is
  // in the first mobile viewport instead of below a second heading row.
  card.append(el('div', { class: 'offer__top' },
    el('span', { class: 'tag tag--best', text: 'Best known delivered total' }),
    el('div', { class: 'offer__vendor' }, bidi(quote.vendor.name), ' ', statusBadge(quote.availability, quote.availabilityLabel))));
  card.append(el('p', { class: 'offer__pack', text: packLine(quote) }));
  card.append(totalsBlock(quote));
  const qualifier = coverageQualifier(quote);
  if (qualifier) card.append(el('p', { class: 'qualifier' }, el('strong', { text: 'Conditional total: ' }), bidi(qualifier)));
  const delivery = deliveryOptionsDisclosure(quote);
  if (delivery) card.append(delivery);
  card.append(el('p', { class: 'offer__links' }, offerLink(quote, 'Open the vendor page')));
  card.append(diagnosticsDisclosure(quote));
  return card;
}

/**
 * Delivery alternatives, pickup terms, free-shipping conditions, coverage prose
 * and rate limits for one offer, collapsed behind one disclosure. Returns null
 * when there is nothing to disclose, so empty sections are never rendered.
 */
function deliveryOptionsDisclosure(quote) {
  const body = el('div', { class: 'disclosure__body' });
  const conditions = conditionsList(quote, destinationLabel);
  if (conditions) body.append(conditions);
  const caveat = caveatBlock(quote);
  if (caveat) body.append(caveat);
  if (!body.childNodes.length) return null;
  return el('details', { class: 'disclosure', attrs: { id: `delivery-options-${slug(quote.key)}` } },
    el('summary', { text: 'Delivery options and conditions' }), body);
}

/** Other ranked offers, collapsed: one compact card each with its own details. */
function renderCompareDisclosure(others, board) {
  const details = el('details', { class: 'disclosure disclosure--compare', attrs: { id: 'compare-other-offers' } });
  details.append(el('summary', { text: `Compare other offers (${others.length})` }));
  const list = el('div', { class: 'offer-list offer-list--compact' });
  for (const quote of others) list.append(renderOtherOffer(quote, board));
  details.append(list);
  if ((board.counts?.excludedByVariant ?? 0) > 0) {
    const labels = (board.counts.excludedVariants ?? []).map(id => VARIANT_LABELS[id] ?? id).join(', ');
    details.append(el('p', { class: 'meta-line', text: `${board.counts.excludedByVariant} observed offer(s) for another blend variant (${labels || 'unspecified'}) stay out of this comparison so variants are never merged. Switch the variant control to compare them.` }));
  }
  return details;
}

function renderOtherOffer(quote, board) {
  const card = el('article', { class: 'offer offer--compact' });
  card.append(el('div', { class: 'offer__top' },
    el('div', { class: 'offer__vendor' }, bidi(quote.vendor.name), ' ', statusBadge(quote.availability, quote.availabilityLabel)),
    el('div', { class: 'offer__delta', text: offerDeltaText(quote, board) })));
  card.append(el('p', { class: 'offer__pack', text: packLine(quote) }));
  card.append(totalsBlock(quote));
  const qualifier = coverageQualifier(quote);
  if (qualifier) card.append(el('p', { class: 'qualifier', text: qualifier }));
  const delivery = deliveryOptionsDisclosure(quote);
  if (delivery) card.append(delivery);
  card.append(el('p', { class: 'offer__links' }, offerLink(quote, 'Open the vendor page')));
  card.append(diagnosticsDisclosure(quote));
  return card;
}

function offerDeltaText(quote, board) {
  const delta = board.best && Number.isFinite(quote.totalIls) && Number.isFinite(board.best.totalIls)
    ? Math.round((quote.totalIls - board.best.totalIls) * 100) / 100
    : null;
  if (delta == null) return '';
  if (delta === 0) return 'Same delivered total as the best offer';
  return `+${money(delta)} vs best delivered total`;
}

/** Self-pickup stays separate from the delivered ranking and collapsed by default. */
function renderPickupDisclosure(pickup) {
  const details = el('details', { class: 'disclosure disclosure--pickup', attrs: { id: 'pickup-options' } });
  details.append(el('summary', { text: `Self-pickup options (${pickup.length}) — not a delivered price` }));
  const body = el('div', { class: 'disclosure__body' });
  body.append(el('p', { text: 'Pickup never competes in the delivered ranking. Pickup that accompanies a delivered offer is also shown on that offer card.' }));
  for (const quote of pickup) {
    const pickupFee = quote.pickup?.amount?.amount;
    const feeText = pickupFee === 0 ? 'Free' : pickupFee != null ? money(pickupFee) : 'See vendor policy';
    const terms = [quote.pickup?.note, quote.labels.join('. ')].filter(Boolean).join(' ');
    body.append(el('div', { class: 'pickup-row' },
      el('div', { class: 'pickup-row__head' },
        el('strong', {}, bidi(quote.vendor.name)),
        el('span', { class: 'pickup-row__pack', text: packLine(quote) })),
      el('div', { class: 'pickup-row__facts' },
        el('span', { text: `Item subtotal: ${itemSubtotalText(quote)}` }),
        el('span', { text: `Pickup fee: ${feeText}` }),
        el('span', { text: 'Self-pickup, not delivery' })),
      terms ? el('details', { class: 'disclosure' }, el('summary', { text: 'Pickup terms' }), el('p', { class: 'disclosure__body' }, bidi(terms))) : null,
      el('p', { class: 'pickup-row__link' }, offerLink(quote, 'Open the vendor page'))));
  }
  details.append(body);
  return details;
}

/** Unknown, stale and unavailable offers stay visible with their exact reason. */
function renderUnknownDisclosure(entries) {
  const details = el('details', { class: 'disclosure disclosure--unknown', attrs: { id: 'unknown-offers' } });
  details.append(el('summary', { text: `Offers with missing information (${entries.length})` }));
  const body = el('div', { class: 'disclosure__body' });
  body.append(el('p', { text: 'These observations stay visible with their source and the exact reason a delivered total cannot be calculated. Missing shipping is never treated as zero.' }));
  const list = el('div', { class: 'unknown-list' });
  for (const quote of entries) {
    const card = el('article', { class: 'unknown' });
    card.append(el('div', { class: 'unknown__vendor' }, bidi(quote.vendor.name), ' ', statusBadge(quote.availability, quote.availabilityLabel)));
    card.append(el('div', { class: 'unknown__meta', text: packLine(quote) }));
    card.append(el('div', { class: 'unknown__grid' },
      el('span', { text: `Item subtotal: ${itemSubtotalText(quote)}` }),
      el('span', { text: `Shipping: ${quote.shipping?.amountIls != null ? money(quote.shipping.amountIls) : 'Shipping not published'}` }),
      el('span', { text: `Last successful check: ${timeLabel(quote.observedAt)}` }),
      quote.lastAttemptFailed ? el('span', { text: `Last attempt failed ${timeLabel(quote.attemptedAt)}${quote.lastError ? ` — ${truncate(quote.lastError)}` : ''}` }) : null));
    if (quote.shipping?.certainty === 'unknown' || quote.shipping?.amount == null) {
      card.append(el('p', { class: 'unknown__reason', text: 'Shipping not published. Needed for a delivered total: a published rate or a public checkout-estimator quote for this quantity and locality. A missing rate is never counted as free.' }));
    }
    card.append(el('p', { class: 'unknown__reason', text: quote.reasons.join('. ') || quote.labels.join('. ') || 'Not enough verified information yet.' }));
    const caveat = caveatBlock(quote);
    if (caveat) card.append(caveat);
    card.append(el('p', {}, offerLink(quote, 'Check this vendor page')));
    list.append(card);
  }
  body.append(list);
  details.append(body);
  return details;
}

function renderControls() {
  const quantityGroup = document.getElementById('quantity-group');
  if (!quantityGroup.dataset.ready) {
    for (const grams of GRAMS_OPTIONS) {
      quantityGroup.append(el('button', {
        type: 'button',
        text: grams >= 1000 ? `${grams / 1000} kg` : `${grams} g`,
        dataset: { grams: String(grams) },
        attrs: { 'aria-pressed': String(state.grams === grams) },
        onClick: () => update({ grams })
      }));
    }
    quantityGroup.dataset.ready = 'true';
  }
  for (const button of quantityGroup.querySelectorAll('button')) {
    button.setAttribute('aria-pressed', String(Number(button.dataset.grams) === state.grams));
  }

  const destination = document.getElementById('destination');
  if (state.catalog?.destinations && !destination.dataset.ready) {
    for (const item of state.catalog.destinations) {
      destination.append(el('option', { value: item.id, text: item.postcode ? `${item.label} · ${item.postcode} area` : item.label }));
    }
    destination.dataset.ready = 'true';
    destination.addEventListener('change', () => update({ destination: destination.value }));
  }
  destination.value = state.destination;

  const variant = document.getElementById('variant');
  const product = currentProduct();
  const labels = new Map((product?.variants ?? []).map(item => [item.id, item.label]));
  const observed = state.board?.variants ?? [];
  const variants = (product?.variants ?? []).map(item => item.id);
  for (const id of observed) if (!variants.includes(id)) variants.push(id);
  const signature = `${product?.id ?? ''}|${variants.join(',')}`;
  if (variant.dataset.signature !== signature) {
    variant.replaceChildren();
    for (const id of variants) {
      const suffix = observed.includes(id) ? '' : ' — not observed yet';
      variant.append(el('option', { value: id, text: `${labels.get(id) ?? VARIANT_LABELS[id] ?? id}${suffix}` }));
    }
    variant.dataset.signature = signature;
    variant.addEventListener('change', () => update({ variant: variant.value }));
  }
  variant.value = state.variant ?? '';

  // The unstated-variant Coffee4U listing stays discoverable: name it when the
  // selected variant leaves it out, instead of silently merging it into Classico.
  const hint = document.getElementById('variant-hint');
  if (hint) {
    const excluded = state.board?.counts?.excludedByVariant ?? 0;
    const labels = (state.board?.counts?.excludedVariants ?? []).map(id => VARIANT_LABELS[id] ?? id).join(', ');
    hint.textContent = excluded > 0
      ? `${excluded} offer(s) for another variant (${labels || 'unspecified'}) stay separate — choose that variant to compare it.`
      : '';
    hint.hidden = excluded === 0;
  }
}

function update(patch) {
  Object.assign(state, patch);
  // Any user interaction replaces the URL's original product request with the
  // tracked product, so a retired-line link is not kept in the shareable URL.
  state.requestedProduct = null;
  if (patch.product) {
    const product = (state.catalog?.products ?? []).find(item => item.id === patch.product);
    state.variant = product?.defaultVariant ?? null;
  }
  applyProductDefaults();
  const query = new URLSearchParams({
    grams: String(state.grams),
    dest: state.destination,
    variant: state.variant ?? ''
  });
  history.replaceState(null, '', `/product/${encodeURIComponent(state.product)}?${query}`);
  renderControls();
  load();
}

function updateFooterStatus() {
  const node = document.getElementById('footer-status');
  if (!node) return;
  if (state.error) {
    node.textContent = 'The comparison could not be loaded from the snapshot API. Stored observations are safe; try again in a moment.';
    return;
  }
  const f = state.board?.freshness;
  const last = f?.lastRefreshAt;
  const observed = f?.lastObservationAt;
  const stale = f?.stale;
  const age = f?.ageHours;
  if (last) {
    node.textContent = `Last completed refresh: ${timeLabel(last)}.${stale ? ` No completed scheduled refresh for ${age} h — prices may be out of date.` : ''}`;
  } else if (observed) {
    node.textContent = `Last offer observation: ${timeLabel(observed)}. No refresh has completed on this deployment yet${stale ? ` — offer data is ${age} h old` : ''}.`;
  } else {
    node.textContent = stale
      ? 'No scheduled refresh has completed yet — prices may be missing or out of date.'
      : 'No completed refresh yet; the first scheduled run will populate the comparison.';
  }
}

/** Board-level freshness and per-vendor diagnostics behind one disclosure. */
function renderFooterStatus(board) {
  const vendors = board.freshness?.vendors ?? [];
  const failing = vendors.filter(vendor => (vendor.consecutiveFailures ?? 0) > 0);
  const freshness = board.freshness ?? {};
  const dataAsOf = freshness.dataAsOf ?? freshness.lastRefreshAt ?? freshness.lastObservationAt ?? null;
  const wrap = el('div', { class: 'meta-line' });
  wrap.append(el('div', { text: `Board data as of: ${timeLabel(dataAsOf)} · Offers observed for this variant: ${board.counts.observed} · Ranked: ${board.counts.ranked}` }));
  if (freshness.stale) {
    const age = freshness.ageHours;
    wrap.append(el('div', { class: 'status status--stale', text: freshness.lastRefreshAt
      ? `Scheduled refresh overdue by ${age} h — prices may be out of date.`
      : freshness.lastObservationAt
        ? `No completed scheduled refresh; the newest offer observation is ${age} h old — prices may be out of date.`
        : 'No scheduled refresh has completed yet — prices may be missing or out of date.' }));
  }
  if (failing.length) wrap.append(el('div', { class: 'status status--stale', text: `${failing.length} source(s) failing` }));
  const body = el('div', { class: 'disclosure__body' });
  if (freshness.fx) {
    body.append(el('div', { text: `Exchange rates: ${freshness.fx.source ?? 'Bank of Israel'} published ${freshness.fx.asOf ?? 'unknown'} · fetched ${timeLabel(freshness.fx.fetchedAt)}` }));
  } else {
    body.append(el('div', { text: 'Exchange rates: no official rate table stored yet, so foreign-currency offers cannot be ranked.' }));
  }
  for (const vendor of vendors) {
    body.append(el('div', { text: `${vendor.vendorId}: last success ${timeLabel(vendor.lastSuccessAt)} · last attempt ${timeLabel(vendor.lastAttemptAt)}` }));
  }
  const nextDue = vendors.map(vendor => vendor.nextAttemptAt).filter(Boolean).sort()[0] ?? null;
  if (nextDue) body.append(el('div', { text: `Next source check due (approximate, set by each vendor's last run): ${dueLabel(nextDue)}` }));
  for (const vendor of failing) {
    body.append(el('div', { text: `${vendor.vendorId}: ${vendor.consecutiveFailures} consecutive failure(s) · next attempt ${timeLabel(vendor.nextAttemptAt)}${vendor.lastErrors?.[0] ? ` · last error: ${vendor.lastErrors[0]}` : ''}` }));
  }
  wrap.append(el('details', { class: 'disclosure' }, el('summary', { text: 'Refresh diagnostics' }), body));
  return wrap;
}

function slug(value) {
  return String(value ?? 'offer').replace(/[^a-z0-9]+/gi, '-').slice(0, 60);
}

load();

// Shared rendering helpers for the home product index and the product page.
//
// All vendor text is inserted as text: fetched pages are untrusted data. `el()`
// accepts a DOM node for `text` (used by `bidi()`, which wraps Hebrew runs in a
// dir="auto" span) and appends it instead of stringifying it — a Node assigned
// to textContent would render as "[object HTMLSpanElement]".

export const VARIANT_LABELS = {
  classico: 'Classico (strength 7)',
  forte: 'Forte',
  ricco: 'Ricco',
  risveglio: 'Risveglio',
  decaf: 'Decaffeinated',
  unspecified: 'Variant not stated'
};

export const ILS = new Intl.NumberFormat('en-IL', { style: 'currency', currency: 'ILS', maximumFractionDigits: 2 });
export const IL_TIME = new Intl.DateTimeFormat('en-GB', {
  timeZone: 'Asia/Jerusalem', dateStyle: 'medium', timeStyle: 'short'
});

export function el(tag, props = {}, ...children) {
  const node = document.createElement(tag);
  for (const [key, value] of Object.entries(props)) {
    if (value == null) continue;
    if (key === 'class') node.className = value;
    else if (key === 'text') {
      // A Node (for example the dir="auto" wrapper built by bidi()) must be
      // appended as a child; assigning it to textContent would print
      // "[object HTMLSpanElement]".
      if (value instanceof Node) node.append(value);
      else node.textContent = String(value);
    }
    else if (key === 'dataset') Object.assign(node.dataset, value);
    else if (key.startsWith('on')) node.addEventListener(key.slice(2).toLowerCase(), value);
    else if (key === 'attrs') for (const [a, v] of Object.entries(value)) node.setAttribute(a, v);
    else node[key] = value;
  }
  for (const child of children.flat()) {
    if (child == null) continue;
    node.append(child instanceof Node ? child : document.createTextNode(String(child)));
  }
  return node;
}

export function money(amount) {
  return amount == null ? null : ILS.format(amount);
}

/** Short single-line text for cards; never a raw payload. */
export function truncate(text, max = 120) {
  const value = String(text ?? '').replace(/\s+/g, ' ').trim();
  return value.length > max ? `${value.slice(0, max - 1)}…` : value;
}

const HEBREW = /[\u0590-\u05FF]/;

/** Wrap Hebrew-containing text in an isolated dir="auto" span for mixed IL/Latin names. */
export function bidi(text) {
  const value = text == null ? '' : String(text);
  if (!HEBREW.test(value)) return value;
  return el('span', { class: 'bidi', attrs: { dir: 'auto', lang: 'he' }, text: value });
}

export function timeLabel(iso) {
  if (!iso) return 'never';
  const date = new Date(iso);
  if (Number.isNaN(date.getTime())) return 'unknown time';
  const hours = (Date.now() - date.getTime()) / 3_600_000;
  const relative = hours < 0.1 ? 'just now' : hours < 1 ? `${Math.round(hours * 60)} min ago` : hours < 48 ? `${Math.round(hours)} h ago` : `${Math.round(hours / 24)} d ago`;
  return `${IL_TIME.format(date)} (${relative})`;
}

/** Format a future due time. Vendor nextAttemptAt is a due time, not a promise, so the copy says so. */
export function dueLabel(iso) {
  if (!iso) return 'not scheduled';
  const date = new Date(iso);
  if (Number.isNaN(date.getTime())) return 'unknown time';
  const hours = (date.getTime() - Date.now()) / 3_600_000;
  const relative = hours <= 0 ? 'due now' : hours < 1 ? `in ${Math.round(hours * 60)} min` : `in ${Math.round(hours)} h`;
  return `${IL_TIME.format(date)} (${relative})`;
}

/** Accurate pack description: a multipack must never read as a single 250 g pack. */
export function packDescription(quote) {
  const product = quote.product ?? {};
  const per = product.packGrams != null ? `${product.packGrams} g` : 'weight not stated';
  if ((product.packCount ?? 1) > 1) {
    return `${product.packCount} × ${per} multipack${product.totalGrams != null ? ` (${product.totalGrams} g)` : ''}`;
  }
  return `${per} pack`;
}

/** What the shopper actually buys for the selected target quantity. */
export function quantityDescription(quote) {
  const product = quote.product ?? {};
  const units = quote.units ?? 1;
  if ((product.packCount ?? 1) > 1) {
    return `${units} multipack${units === 1 ? '' : 's'} (${product.packCount} × ${product.packGrams} g) = ${quote.orderedGrams} g`;
  }
  return `${units} × ${product.packGrams ?? '?'} g pack${units === 1 ? '' : 's'} = ${quote.orderedGrams} g`;
}

export function itemSubtotalText(quote) {
  if (quote.itemTotalIls != null) return money(quote.itemTotalIls);
  const amount = quote.itemPrice?.amount;
  if (amount == null) return 'Unknown';
  return `${money(amount)} ${quote.itemPrice.currency ?? ''}`.trim();
}

export function shippingValueText(quote) {
  const shipping = quote.shipping ?? {};
  if (shipping.amountIls != null) {
    if (shipping.amountIls === 0) return shipping.freeThreshold != null ? 'Free (threshold met)' : 'Free';
    return money(shipping.amountIls);
  }
  if (shipping.amount != null) return `${money(shipping.amount)} ${shipping.currency ?? ''} (not converted)`.trim();
  return 'Shipping not published';
}

/**
 * The delivery method a charge buys, separate from how certain the evidence is.
 * Falls back to the shipping mode; an unknown method says so instead of showing
 * the certainty label in its place.
 */
export function shippingMethodLabel(quote) {
  const shipping = quote.shipping ?? {};
  if (shipping.serviceLabel) return shipping.serviceLabel;
  return shipping.mode === 'pickup' ? 'Self-pickup' : 'Delivery method not stated';
}

export function shippingCertaintyText(quote) {
  return quote.shipping?.certaintyLabel ?? 'Not published before checkout';
}

export function statusBadge(status, label) {
  const kind = status === 'in_stock' ? 'in_stock' : status === 'out_of_stock' ? 'out_of_stock' : 'unknown';
  return el('span', { class: `status status--${kind}`, text: label });
}

export function offerLink(quote, label = 'Open the vendor page') {
  return el('a', { href: quote.itemUrl, rel: 'noopener noreferrer nofollow', target: '_blank', text: label });
}

/** Item subtotal, named shipping method/charge and delivered total stay together. */
export function totalsBlock(quote, { perKg = true } = {}) {
  return el('div', { class: 'totals' },
    el('div', { class: 'totals__cell' },
      el('span', { class: 'totals__label', text: 'Item subtotal' }),
      el('span', { class: 'totals__value num', text: itemSubtotalText(quote) })),
    el('div', { class: 'totals__cell' },
      el('span', { class: 'totals__label', text: 'Shipping' }),
      el('span', { class: 'totals__value num', text: shippingValueText(quote) }),
      el('span', { class: 'totals__meta totals__meta--method', text: shippingMethodLabel(quote) }),
      el('span', { class: 'totals__meta totals__meta--certainty', text: shippingCertaintyText(quote) })),
    el('div', { class: 'totals__cell totals__cell--total' },
      el('span', { class: 'totals__label', text: 'Delivered total' }),
      el('span', { class: 'totals__value num', text: quote.totalIls != null ? money(quote.totalIls) : 'Not calculable' }),
      perKg && quote.ilsPerKg != null ? el('span', { class: 'totals__meta num', text: `${money(quote.ilsPerKg)} per kg` }) : null));
}

/**
 * Plain-language price comparison against the previous successful check of the
 * same offer. Rendered as text only when the quote actually carries previous
 * evidence; an impossible comparison says why instead of claiming "no change".
 */
export function priceChangeText(quote) {
  const change = quote?.priceChange;
  if (!change) return null;
  const when = timeLabel(change.previousObservedAt);
  if (!change.comparable) return `Previous price not compared: ${change.reason} (previous check ${when})`;
  if (change.direction === 'same') return `Unit price unchanged since the previous check (${when})`;
  return `Unit price ${change.direction === 'down' ? 'down' : 'up'} ${money(change.deltaIls)} since the previous check (${when})`;
}

export function stockChangeText(quote) {
  const previous = quote?.previous;
  if (!previous || previous.availability === quote.availability) return null;
  return `Stock changed since the previous check: was ${previous.availabilityLabel ?? previous.availability}`;
}

/** Short conditions shown on a card face; the full list goes in a details block. */
export function conditionsList(quote, destinationLabelFn = id => id) {
  const shipping = quote.shipping ?? {};
  const items = [];
  if (shipping.freeThreshold != null) {
    const wording = shipping.freeThresholdSemantics === 'above' ? 'above' : 'from';
    const met = quote.itemTotalIls != null && (shipping.freeThresholdSemantics === 'above'
      ? quote.itemTotalIls > shipping.freeThreshold + 0.005
      : quote.itemTotalIls >= shipping.freeThreshold - 0.005);
    items.push(met
      ? `Free-shipping threshold met (${wording} ${money(shipping.freeThreshold)})`
      : `Free shipping ${wording} ${money(shipping.freeThreshold)} item subtotal`);
  }
  if (shipping.minOrder != null) items.push(`Minimum order ${money(shipping.minOrder)}`);
  const coverage = shipping.destination;
  if (coverage?.scope === 'localities') {
    const names = (coverage.localities ?? []).map(destinationLabelFn);
    items.push(names.length ? `Delivery area: only ${names.join(', ')}` : 'Delivery area: restricted locality list not published');
  }
  for (const alternative of shipping.alternatives ?? []) {
    items.push(`${alternative.label}: ${alternative.amountIls != null ? money(alternative.amountIls) : 'rate not published'}`);
  }
  if (shipping.pickup?.available) items.push(shipping.pickup.note ? `Self-pickup: ${shipping.pickup.note}` : 'Free self-pickup available (kept separate from delivery)');
  if (shipping.deliveryTime) items.push(`Delivery time: ${shipping.deliveryTime}`);
  if (shipping.maxTotalGrams != null) items.push(`Rate quoted for carts up to ${shipping.maxTotalGrams} g`);
  if (!items.length) return null;
  const list = el('ul', { class: 'conditions' });
  for (const item of items) list.append(el('li', {}, bidi(item)));
  return list;
}

export function caveatBlock(quote) {
  if (!quote.shipping?.coverageCaveat) return null;
  return el('p', { class: 'caveat' }, el('strong', { text: 'Coverage: ' }), bidi(quote.shipping.coverageCaveat));
}

/** A one-line amber qualification shown next to a conditional total. */
export function coverageQualifier(quote) {
  const shipping = quote.shipping ?? {};
  if (shipping.coverageCaveat) return 'Coverage not confirmed for every locality — full terms under Delivery options.';
  if (shipping.certainty === 'checkout_quote') return 'Rate observed in an anonymous cart; confirm the destination at checkout.';
  if (shipping.certainty === 'estimated') return 'Includes a converted or estimated component.';
  if (shipping.certainty === 'unknown') return 'Shipping not published: a delivered total cannot be established yet.';
  return null;
}

/** Previous-check, failure and evidence provenance, collapsed behind a disclosure. */
export function diagnosticsDisclosure(quote) {
  const rows = [];
  const change = priceChangeText(quote);
  if (change) rows.push(change);
  const stockChange = stockChangeText(quote);
  if (stockChange) rows.push(stockChange);
  rows.push(`Last successful check: ${timeLabel(quote.observedAt)}`);
  if (quote.lastAttemptFailed) rows.push(`Last attempt failed ${timeLabel(quote.attemptedAt)}${quote.lastError ? ` — ${truncate(quote.lastError)}` : ''}`);
  const policy = quote.shipping?.policy;
  if (policy) {
    rows.push(`Shipping rule: ${policy.id} v${policy.version} (${policy.origin === 'observed_cart' ? 'observed anonymous cart quote' : 'published rule'}, observed ${timeLabel(policy.retrievedAt)}, re-check by ${timeLabel(policy.reviewBy)})`);
  }
  if (quote.shipping?.note) rows.push(`Shipping terms: ${quote.shipping.note}`);
  const evidence = quote.shipping?.evidence;
  if (evidence?.url) {
    rows.push(`Shipping evidence: ${evidence.url}${evidence.retrievedAt ? ` (retrieved ${timeLabel(evidence.retrievedAt)})` : ''}${evidence.note ? ` — ${truncate(evidence.note, 160)}` : ''}`);
  }
  const body = el('div', { class: 'disclosure__body' });
  for (const row of rows) body.append(el('div', {}, bidi(row)));
  return el('details', { class: 'disclosure disclosure--diagnostics' }, el('summary', { text: 'Offer details and check history' }), body);
}

// Vendor adapter registry.
//
// Adapters are deterministic: fetch a fixed, allowlisted product URL, parse it
// with a versioned parser and return one observation per tracked offer. They
// never follow vendor content as instructions and never bypass access controls.
//
// Adding a vendor: create src/vendors/<id>.js exporting an adapter with
// { id, name, homepage, allowedHosts, parserVersion, offers, observe() } and
// register it here. Fixtures for its parser belong in tests/fixtures/.

import { pucks } from './pucks.js';
import { coffeeman } from './coffeeman.js';
import { coffee4u } from './coffee4u.js';

export function registeredVendors() {
  return [coffeeman, pucks, coffee4u];
}

/** Every host any adapter may contact. Used for the refresh-time allowlist. */
export function vendorHosts(vendors = registeredVendors()) {
  return [...new Set(vendors.flatMap(vendor => vendor.allowedHosts))];
}

export function createObservation({ vendor, itemUrl, product, price, availability, availabilityEvidence, shipping, mandatoryFees = [], now }) {
  const observedAt = new Date(now ?? Date.now()).toISOString();
  const key = [
    vendor.id,
    product.sku ?? product.productId,
    product.variantId ?? 'unspecified',
    product.form,
    `${product.totalGrams ?? 'x'}g`,
    `x${product.packCount ?? 1}`
  ].join(':');
  // Availability and shipping terms are read from the same product-page fetch as
  // the price. Stamp their evidence with that retrieval time unless the adapter
  // already knows a more precise one, so every claim on the board carries when
  // it was observed instead of an unexplained null.
  const stamp = entry => (entry ? { ...entry, retrievedAt: entry.retrievedAt ?? observedAt } : null);
  return {
    key,
    vendor: { id: vendor.id, name: vendor.name, homepage: vendor.homepage },
    itemUrl,
    product,
    price,
    availability,
    availabilityEvidence: stamp(availabilityEvidence),
    shipping: shipping
      ? { ...shipping, evidence: stamp(shipping.evidence) }
      : shipping,
    mandatoryFees,
    observedAt,
    evidence: [
      { url: itemUrl, retrievedAt: observedAt, note: 'Item price and listed availability parsed from the vendor product page.' }
    ],
    parserVersion: vendor.parserVersion
  };
}

