  board500: endpoints.board500.body,

  board500: endpoints.board500.body,
  board1000: endpoints.board1000.body,
  boardUnstated: endpoints.boardUnstated.body,
  retiredUrl: endpoints.retiredUrl.body
};
for (const [name, board] of Object.entries(boards)) {
