{
  "name": "attention-shoppers-happy-hunting",
  "version": "0.1.0",
  "private": true,
  "type": "module",
  "engines": {
    "node": ">=24"
  },
  "scripts": {
    "dev": "wrangler dev --port 8789",
    "test": "node --test tests/*.test.js",
    "build": "wrangler deploy --dry-run --outdir dist",
    "verify": "npm test && npm run build",
    "cron:local": "node scripts/simulate-cron.mjs",
    "cron:offline": "node scripts/simulate-cron.mjs --offline",
    "check:sources": "node scripts/check-sources.mjs",
    "probe:production": "node scripts/probe-production.mjs",
    "qa:browser": "node scripts/browser-qa.mjs",
    "research:browser": "node scripts/browser-research.mjs"
  },
  "devDependencies": {
    "wrangler": "4.149.0"
  }
}

// Validated shipping policies and the shared policy evaluator.
//
// A policy is a versioned, scoped statement of a shipping rule that browser
// research established: what the rule is, which vendor/product/service and
// destination scope it covers, when it was observed, and when it must be
// re-checked. Policies are deliberately separate from an observation's own
// parsed shipping block:
//
//   - Published rules and observed conditional cart quotes stay distinguishable
//     through `origin` and `certainty`; a cart quote is never relabelled as a
//     published rate.
//   - The evaluator is deterministic and shared by every vendor: it matches an
//     observation by vendor, product, service and item-URL scope, refuses to
//     guess when matching policies disagree (status `inconsistent`) and refuses
//     to keep applying evidence past its `reviewBy` date (status `expired`).
//   - Enrichment only fills missing shipping fields. An observation that already
//     carries its own amount, threshold or destination is never overwritten, so
//     a newer policy cannot rewrite a fresher parse.
//   - Enrichment happens at read time. It never changes the observation's price,
//     stock, `observedAt` or the refresh completion marker, so applying a newer
//     shipping rule cannot claim a fresh vendor price/stock check.
//
// Recheck/staleness: each policy carries `reviewBy`. Browser research re-runs
// update the evidence and version (and move `reviewBy` forward); until then the
// policy applies. Once `reviewBy` passes, the evaluator stops applying it and
// the offer falls back to its parsed shipping — explicit unknown rather than a
// stale unconditional rate.

const PRODUCT_ID = 'lavazza-crema-e-gusto-vacuum-ground';

/**
 * Pucks home-delivery rule, observed in the anonymous checkout estimator on
 * 2026-10-12: ₪30 flat home delivery, free above a ₪100 item subtotal.
 * Observed carts: 1, 2 and 4 × 250 g to Tel Aviv / 6100000 and Eilat / 8800000
 * (the fee did not change with locality; no restriction was displayed).
 * The vendor's own wording is "above ₪100"; the boundary was observed only at
 * ₪60 (paid) and ₪120 (free), so `thresholdSemantics` records "above" and the
 * quote engine keeps the observed `>=` arithmetic only as the conservative
 * reading of "free above the stated threshold" — see docs/SOURCES.md.
 */
export const pucksHomeDeliveryPolicy = {
  id: 'pucks-il-home-delivery',
  version: 1,
  vendorId: 'pucks',
  productIds: [PRODUCT_ID],
  itemUrlPrefixes: ['https://pucks.co.il/product/'],
  service: 'home_delivery',
  origin: 'observed_cart',
  certainty: 'checkout_quote',
  rule: {
    amount: { amount: 30, currency: 'ILS' },
    freeThreshold: { amount: 100, currency: 'ILS' },
    thresholdSemantics: 'above',
    minOrder: null,
    maxTotalGrams: null
  },
  destination: {
    scope: 'country',
    country: 'IL',
    caveat: 'The ₪30 rate was observed in the anonymous checkout estimator for Tel Aviv and Eilat carts; the fee did not change with locality and no restriction was displayed, but coverage for every locality was not individually verified.',
    caveatSource: 'https://pucks.co.il/payment/request'
  },
  evidence: {
    url: 'https://pucks.co.il/payment/request',
    retrievedAt: '2026-10-12T18:10:10Z',
    note: 'Anonymous checkout estimator quote recorded by interactive browser research: ₪30 flat home delivery, free above ₪100 item subtotal, for 1, 2 and 4 × 250 g carts; see docs/evidence/browser-research/2026-10-12-vendor-shipping-quotes.json.'
  },
  observedFor: {
    carts: ['1 × 250 g', '2 × 250 g', '4 × 250 g'],
    destinations: ['Tel Aviv / 6100000', 'Eilat / 8800000'],
    note: 'The estimator offered home delivery only; no street address or personal detail was entered and no order was submitted.'
  },
  reviewBy: '2026-11-11T00:00:00.000Z'
};

/** Every validated policy the shared evaluator may apply. */
export const SHIPPING_POLICIES = [pucksHomeDeliveryPolicy];

const CURRENCY_PATTERN = /^[A-Z]{3}$/;

/** Validate one policy's shape. Returns { ok, errors } without throwing. */
export function validatePolicy(policy) {
  const errors = [];
  if (!policy || typeof policy !== 'object') return { ok: false, errors: ['policy is not an object'] };
  if (!policy.id || typeof policy.id !== 'string') errors.push('id is required');
  if (!Number.isInteger(policy.version) || policy.version < 1) errors.push('version must be a positive integer');
  if (!policy.vendorId) errors.push('vendorId is required');
  if (!Array.isArray(policy.productIds) || policy.productIds.length === 0) errors.push('productIds must be a non-empty array');
  if (policy.service != null && typeof policy.service !== 'string') errors.push('service must be a string when present');
  if (!['observed_cart', 'published'].includes(policy.origin)) errors.push('origin must be "observed_cart" or "published"');
  if (!['verified', 'checkout_quote', 'estimated'].includes(policy.certainty)) errors.push('certainty must be verified, checkout_quote or estimated');
  const amount = policy.rule?.amount;
  if (!amount || !Number.isFinite(amount.amount) || !CURRENCY_PATTERN.test(String(amount.currency ?? ''))) {
    errors.push('rule.amount must carry a numeric amount and a 3-letter currency');
  }
  const threshold = policy.rule?.freeThreshold;
  if (threshold != null && (!Number.isFinite(threshold.amount) || !CURRENCY_PATTERN.test(String(threshold.currency ?? '')))) {
    errors.push('rule.freeThreshold must carry a numeric amount and a 3-letter currency when present');
  }
  if (threshold != null && !['above', 'at_least'].includes(policy.rule?.thresholdSemantics)) {
    errors.push('rule.thresholdSemantics must be "above" or "at_least" when a free threshold is present');
  }
  if (!policy.evidence?.url || !policy.evidence?.retrievedAt) errors.push('evidence.url and evidence.retrievedAt are required');
  if (!policy.reviewBy || Number.isNaN(Date.parse(policy.reviewBy))) errors.push('reviewBy must be an ISO date');
  if (!policy.destination || !['country', 'localities'].includes(policy.destination.scope)) errors.push('destination.scope must be country or localities');
  if (policy.destination?.scope === 'localities' && !Array.isArray(policy.destination.localities)) {
    errors.push('a localities destination needs a localities array');
  }
  return { ok: errors.length === 0, errors };
}

export function validatePolicies(policies = SHIPPING_POLICIES) {
  const results = policies.map(policy => ({ id: policy?.id ?? null, ...validatePolicy(policy) }));
  return { ok: results.every(result => result.ok), results };
}

/** Does this policy's scope cover the observation? */
function policyMatches(policy, observation) {
  if (!observation || !policy) return false;
  if (policy.vendorId && observation.vendor?.id !== policy.vendorId) return false;
  const productId = observation.product?.productId ?? null;
  if (policy.productIds?.length && !policy.productIds.includes(productId)) return false;
  if (policy.itemUrlPrefixes?.length) {
    const url = String(observation.itemUrl ?? '');
    if (!policy.itemUrlPrefixes.some(prefix => url.startsWith(prefix))) return false;
  }
  if (policy.service != null && observation.shipping?.service != null && observation.shipping.service !== policy.service) return false;
  return true;
}

function ruleKey(rule) {
  const amount = rule?.amount ? `${rule.amount.amount}${rule.amount.currency}` : '-';
  const threshold = rule?.freeThreshold ? `${rule.freeThreshold.amount}${rule.freeThreshold.currency}` : '-';
  return `${amount}/${threshold}/${rule?.minOrder?.amount ?? '-'}`;
}

/**
 * Resolve which policy (if any) may enrich this observation.
 * Statuses: applied | already-known | unmatched | expired | invalid | inconsistent.
 */
export function resolveShippingPolicy({ observation, policies = SHIPPING_POLICIES, now = Date.now() } = {}) {
  const matching = policies.filter(policy => policyMatches(policy, observation));
  if (!matching.length) return { status: 'unmatched', policy: null };
  const valid = [];
  const expired = [];
  const invalid = [];
  for (const policy of matching) {
    const check = validatePolicy(policy);
    if (!check.ok) { invalid.push({ policy, errors: check.errors }); continue; }
    if (Date.parse(policy.reviewBy) < now) expired.push(policy);
    else valid.push(policy);
  }
  if (!valid.length) {
    if (expired.length) return { status: 'expired', policy: expired.sort((a, b) => b.version - a.version)[0] };
    return { status: 'invalid', policy: invalid[0]?.policy ?? null, errors: invalid[0]?.errors ?? [] };
  }
  // One effective rule per policy id: the highest version.
  const latestById = new Map();
  for (const policy of valid) {
    const current = latestById.get(policy.id);
    if (!current || policy.version > current.version) latestById.set(policy.id, policy);
  }
  const effective = [...latestById.values()];
  const keys = new Set(effective.map(policy => ruleKey(policy.rule)));
  if (keys.size > 1) return { status: 'inconsistent', policy: null, policies: effective };
  return { status: 'applied', policy: effective.sort((a, b) => b.version - a.version)[0] };
}

/**
 * Fill only the shipping fields the observation is missing from a matching
 * validated policy. Returns { observation, status, policy }; the original
 * observation is never mutated and its observedAt/price/stock stay untouched.
 */
export function enrichObservationShipping(observation, options = {}) {
  const resolved = resolveShippingPolicy({ observation, ...options });
  if (resolved.status !== 'applied') return { observation, status: resolved.status, policy: resolved.policy ?? null };
  const policy = resolved.policy;
  const shipping = { ...(observation.shipping ?? {}) };
  let changed = false;

  if ((shipping.certainty === 'unknown' || shipping.amount == null) && policy.rule?.amount?.amount != null) {
    shipping.amount = { ...policy.rule.amount };
    shipping.certainty = policy.certainty;
    changed = true;
  }
  if (shipping.freeThreshold == null && policy.rule?.freeThreshold?.amount != null) {
    shipping.freeThreshold = { ...policy.rule.freeThreshold };
    changed = true;
  }
  // Keep the vendor's boundary wording attached to the threshold it belongs to,
  // so "above ₪100" is never silently evaluated as "at least ₪100".
  if (shipping.freeThresholdSemantics == null && shipping.freeThreshold != null && policy.rule?.thresholdSemantics) {
    shipping.freeThresholdSemantics = policy.rule.thresholdSemantics;
    changed = true;
  }
  if (shipping.minOrder == null && policy.rule?.minOrder?.amount != null) {
    shipping.minOrder = { ...policy.rule.minOrder };
    changed = true;
  }
  if (shipping.maxTotalGrams == null && policy.rule?.maxTotalGrams != null) {
    shipping.maxTotalGrams = policy.rule.maxTotalGrams;
    changed = true;
  }
  if (shipping.service == null && policy.service) {
    shipping.service = policy.service;
    changed = true;
  }
  if (shipping.destination == null && policy.destination) {
    shipping.destination = { ...policy.destination };
    changed = true;
  } else if (shipping.destination != null && policy.destination?.caveat && shipping.destination.caveat == null) {
    // An older stored row often already carries a generic destination scope but
    // not the coverage caveat the researched evidence established. Keep the
    // row's own scope and add the caveat, so an enriched rate is never
    // presented as unconditional country-wide delivery.
    shipping.destination = {
      ...shipping.destination,
      caveat: policy.destination.caveat,
      caveatSource: policy.destination.caveatSource ?? null
    };
    changed = true;
  }

  if (!changed) return { observation, status: 'already-known', policy };
  shipping.policy = {
    id: policy.id,
    version: policy.version,
    origin: policy.origin,
    retrievedAt: policy.evidence.retrievedAt,
    reviewBy: policy.reviewBy,
    thresholdSemantics: policy.rule?.thresholdSemantics ?? null
  };
  if (shipping.evidence == null) shipping.evidence = { ...policy.evidence };
  const originText = policy.origin === 'observed_cart' ? 'observed anonymous cart quote' : 'published rule';
  shipping.note = [shipping.note, `Shipping rule applied from validated policy ${policy.id} v${policy.version} (${originText}, observed ${policy.evidence.retrievedAt}); confirm at checkout.`]
    .filter(Boolean)
    .join(' ');
  return { observation: { ...observation, shipping }, status: 'applied', policy };
}

/** Compact policy status for the public status API; no secrets, no payloads. */
export function policySummary(now = Date.now(), policies = SHIPPING_POLICIES) {
  return policies.map(policy => ({
    id: policy.id,
    version: policy.version,
    vendorId: policy.vendorId,
    origin: policy.origin,
    certainty: policy.certainty,
    observedAt: policy.evidence?.retrievedAt ?? null,
    reviewBy: policy.reviewBy,
    expired: Date.parse(policy.reviewBy) < now
  }));
}

// Tracked product and strict listing classification.
//
// Scope (owner correction, 2026-10-12): exactly one product is tracked —
// Lavazza Crema e Gusto ground coffee in a vacuum brick. Qualità Oro,
// Qualità Rossa, Suerte and every other Lavazza line are retired: their names
// survive only as tombstones below, so a listing, a parser page or an old
// ?product= URL can never silently re-enter the board. Re-adding a product
// line requires an explicit new owner instruction.
//
// Classification stays conservative: a listing that cannot be tied to the
// tracked product is rejected instead of being merged into the board. Pack
// sizes and multipacks stay separate so different offers are never merged.
//
// Owner correction, 2026-10-12: there is no shopper-facing blend/variant
// feature. Every tracked Crema e Gusto vacuum-packed ground listing —
// including a listing that states no blend wording at all — takes part in one
// comparison for the selected quantity, locality and delivery method. The
// blend wording a vendor happens to print is kept only as raw listing identity
// metadata for evidence/offer details, never as a filter, menu entry or badge.

import { decodeEntities } from './lib/text.js';

const LINE_PATTERNS = {
  'lavazza-crema-e-gusto': [
    /crema\s*(?:e|&|and|-)?\s*gusto/i,
    /קרמה\s*(?:אה\s*)?גוסטו/
  ]
};

/**
 * Product lines that earlier iterations tracked and the 2026-10-12 owner
 * correction retired. They are not fetch targets, not catalog entries and not
 * selectable anywhere; the patterns exist only so `classifyListing()` can
 * reject those pages with an explicit reason and `resolveProductRequest()`
 * can fall back to the tracked product instead of resurrecting them.
 */
export const RETIRED_LINES = [
  {
    id: 'lavazza-qualita-oro-vacuum-ground',
    line: 'Qualità Oro',
    patterns: [
      /qualit[aàáy]\s*oro/i,
      /קוואליטה\s*אורו/,
      /קווליטה\s*אורו/
    ]
  },
  {
    id: 'lavazza-qualita-rossa-vacuum-ground',
    line: 'Qualità Rossa',
    patterns: [
      /qualit[aàáy]\s*rossa/i,
      /קוואליטה\s*רוסה/,
      /קווליטה\s*רוסה/,
      /לווצה\s*רוסה/
    ]
  },
  {
    id: 'lavazza-suerte-ground',
    line: 'Suerte',
    patterns: [
      /lavazza\s*suerte/i,
      /לווצה\s*סוארטה/
    ]
  }
];

export const RETIRED_PRODUCT_IDS = RETIRED_LINES.map(line => line.id);

export const PRODUCTS = [
  {
    id: 'lavazza-crema-e-gusto-vacuum-ground',
    brand: 'Lavazza',
    line: 'Crema e Gusto',
    form: 'ground',
    packaging: 'vacuum brick',
    targetMarket: 'IL',
    linePatterns: LINE_PATTERNS['lavazza-crema-e-gusto'],
    notes: 'The only tracked product line (owner correction, 2026-10-12). Ground coffee in a vacuum brick. All eligible Crema e Gusto vacuum-packed ground listings share one comparison; pack sizes and multipacks stay distinct offers. Any blend wording a listing prints is raw listing identity metadata only — never a shopper-selectable variant. Beans, capsules, pods and every other Lavazza product line are rejected.'
  }
];

export const products = PRODUCTS;

/**
 * Raw blend wording a vendor may print, kept only so an offer can show its own
 * listing identity in evidence/details. These ids are never a filter, a menu
 * entry, a ranking input or a shopper-facing selection.
 */
export const STATED_VARIANTS = {
  classico: { id: 'classico', label: 'Classico', aliases: ['classico', 'classic', 'קלאסיקו', 'קלאסי'] },
  forte: { id: 'forte', label: 'Forte', aliases: ['forte', 'פורטה'] },
  ricco: { id: 'ricco', label: 'Ricco', aliases: ['ricco', 'ריקו'] },
  risveglio: { id: 'risveglio', label: 'Risveglio', aliases: ['risveglio', 'התעוררות'] },
  decaf: { id: 'decaf', label: 'Decaffeinated', aliases: ['decaf', 'decaffeinato', 'נטול קפאין', 'dek'] },
  unspecified: { id: 'unspecified', label: 'Variant not stated', aliases: [] }
};

const REJECT_FORMS = [
  // Hebrew is written without word characters, so the Hebrew bean words are matched
  // without \b (a bare \bפולי\b can never match).
  { id: 'beans', pattern: /\b(beans?|whole\s*bean|kaffeebohnen|bønner|boenner|grain)\b|פולי|פול\s*קפה/i, label: 'whole beans' },
  { id: 'capsules', pattern: /(capsul|קפסול|coffee\s*pods?|\bpods?\b|nespresso|dolce\s*gusto|senseo|a\s*modo\s*mio|\bese\b)/i, label: 'capsules or pods' },
  { id: 'machine', pattern: /(coffee\s*machin|מכונת\s*קפה|espresso\s*machine)/i, label: 'coffee machine' }
];

const GROUND_PATTERN = /(ground|טחון|macinato|molido|moulu|gemahlen|malet|filtro|filter\s*coffee)/i;
const BRAND_PATTERN = /(lavazza|לוואצה|לבאצה)/i;

/** Look up a tracked product by id. Retired ids return null by design. */
export function productById(id) {
  return PRODUCTS.find(product => product.id === id) ?? null;
}

/** Look up a retired line definition by id, or null when it was never tracked. */
export function retiredProductById(id) {
  return RETIRED_LINES.find(line => line.id === id) ?? null;
}

export function isRetiredProductId(id) {
  return retiredProductById(id) !== null;
}

/**
 * Resolve a requested product id to the tracked product.
 *
 * Unknown ids — including the retired Qualità Oro, Qualità Rossa and Suerte
 * ids that older shared links and bookmarks still carry — fall back to the
 * one tracked product. The retired definition is returned alongside so callers
 * (the Worker and the offline QA server) can say plainly what happened
 * instead of quietly showing a different product.
 */
export function resolveProductRequest(id) {
  const requested = id ?? null;
  if (!requested) return { product: PRODUCTS[0], retired: null, known: true };
  const product = productById(requested);
  if (product) return { product, retired: null, known: true };
  return { product: PRODUCTS[0], retired: retiredProductById(requested), known: false };
}

/**
 * Extract the blend wording a listing prints, for provenance only. An unstated
 * listing returns the `unspecified` definition; it is never relabelled as
 * Classico and never withheld from the comparison.
 */
export function variantOf(text) {
  const value = String(text || '').toLowerCase();
  for (const variant of Object.values(STATED_VARIANTS)) {
    if (variant.id === 'unspecified') continue;
    if (variant.aliases.some(alias => value.includes(alias))) return variant;
  }
  return STATED_VARIANTS.unspecified;
}

/**
 * Classify a listing name against the tracked product.
 *
 * Pass `productId` to require a specific tracked product (vendor adapters do
 * this for the offer they track); without it the first matching tracked product
 * is returned. Heavy HTML entities in vendor titles are decoded first, because
 * pages publish names such as "Lavazza Qualit&#224; Oro". Retired lines are
 * rejected with an explicit reason so historical pages can never re-enter the
 * comparison.
 */
export function classifyListing(text, { productId = null } = {}) {
  const value = decodeEntities(String(text ?? '')).toLowerCase();
  const reasons = [];
  const requestedProduct = productId ? productById(productId) : null;
  const requestedRetired = productId ? retiredProductById(productId) : null;
  const candidates = requestedProduct ? [requestedProduct] : (productId ? [] : PRODUCTS);

  if (productId && !requestedProduct && !requestedRetired) reasons.push(`unknown tracked product: ${productId}`);
  if (requestedRetired) reasons.push(`product line ${requestedRetired.line} was retired; only Lavazza Crema e Gusto is tracked`);
  if (!BRAND_PATTERN.test(value)) reasons.push('brand is not Lavazza');

  const retiredLine = RETIRED_LINES.find(line => line.patterns.some(pattern => pattern.test(value)));
  if (retiredLine) reasons.push(`listing belongs to the retired Lavazza ${retiredLine.line} line; only Lavazza Crema e Gusto is tracked`);

  const product = candidates.find(candidate => candidate.linePatterns.some(pattern => pattern.test(value)));
  if (!product && !retiredLine) {
    const wanted = productId ? `the tracked ${productById(productId)?.line ?? requestedRetired?.line ?? productId} line` : 'the tracked Lavazza Crema e Gusto line';
    reasons.push(`listing is not ${wanted}`);
  }

  const rejected = REJECT_FORMS.find(form => form.pattern.test(value));
  if (rejected) reasons.push(`listing is ${rejected.label}`);
  const ground = GROUND_PATTERN.test(value);
  if (!ground) reasons.push('listing does not state ground coffee');

  const variant = variantOf(value);
  const pack = parsePackSize(text);
  const matched = reasons.length === 0;

  return {
    matched,
    productId: matched ? product.id : null,
    productLine: matched ? product.line : null,
    variantId: variant.id,
    variantLabel: variant.label,
    form: matched ? 'ground' : (rejected ? rejected.id : 'unknown'),
    packGrams: pack.grams,
    packCount: pack.count,
    totalGrams: pack.grams != null ? pack.grams * pack.count : null,
    retiredLine: retiredLine ? { id: retiredLine.id, line: retiredLine.line } : null,
    reasons: matched
      ? (pack.grams == null ? ['pack weight not stated; offer can be shown but not normalized'] : [])
      : reasons
  };
}

const OZ_TO_GRAMS = 28.349523125;

/** Parse grams per pack and pack count from a listing name. */
export function parsePackSize(text) {
  const value = decodeEntities(String(text ?? ''));
  let grams = null;

  const ounce = /(\d+(?:[.,]\d+)?)\s*(?:-|\s)?(?:ounce|oz)\b/i.exec(value);
  if (ounce) {
    grams = round(Math.round(parseDecimalValue(ounce[1]) * OZ_TO_GRAMS));
  }
  if (grams == null) {
    const gram = /(\d{2,4}(?:[.,]\d+)?)\s*(?:גרם|גר'|ג'|ג׳|gr\b|g\b|grams?\b|grs\b|gramos\b)/i.exec(value);
    if (gram) grams = round(parseDecimalValue(gram[1]));
  }
  if (grams == null) {
    const kg = /(\d+(?:[.,]\d+)?)\s*(?:kg|ק"ג|קג|קילו)/i.exec(value);
    if (kg) grams = round(parseDecimalValue(kg[1]) * 1000);
  }

  let count = 1;
  const packOf = /pack\s*of\s*(\d{1,3})/i.exec(value);
  const multiply = /(\d{1,3})\s*(?:x|×)\s*\d{2,4}\s*(?:גרם|gr\b|g\b|grams?\b|oz\b|ounce)/i.exec(value);
  const hebrewPacks = /(\d{1,3})\s*(?:אריזות|חבילות|יחידות)/.exec(value);
  if (packOf) count = Number(packOf[1]);
  else if (multiply) count = Number(multiply[1]);
  else if (hebrewPacks) count = Number(hebrewPacks[1]);
  else if (grams == null) {
    const bareCount = /^(\d{1,3})\s*(?:אריזות|חבילות)/.exec(value.trim());
    if (bareCount) count = Number(bareCount[1]);
  }
  if (!Number.isFinite(count) || count < 1 || count > 99) count = 1;
  return { grams, count };
}

function parseDecimalValue(raw) {
  return Number(String(raw).replace(',', '.'));
}

function round(value) {
  return Math.round(value * 10) / 10;
}

// Scheduled refresh pipeline.
//
// The pipeline is deterministic and bounded: allowlisted hosts, per-request
// timeouts and size limits, concurrency capped, one attempt per offer per run.
// A failing vendor keeps its previous good observation; a missing FX rate keeps
// the previous rate table. Nothing here needs a browser, an LLM or the coding
// loop to be running.

import { createBoundedFetcher } from './lib/http.js';
import { parseBoiRates, FX_SOURCE } from './lib/fx.js';
import { PRODUCTS } from './catalog.js';
import { registeredVendors, vendorHosts } from './vendors/index.js';

export const REFRESH_INTERVAL_MS = 6 * 60 * 60 * 1000; // About every six hours.
// A scheduled refresh that has not completed for this long is surfaced to shoppers
// as stale: one missed six-hour run plus slack, so a broken cron does not stay silent.
export const REFRESH_STALE_MS = 8 * 60 * 60 * 1000;
export const BACKOFF_BASE_MS = 30 * 60 * 1000;
export const BACKOFF_MAX_MS = 12 * 60 * 60 * 1000;
export const LEASE_TTL_MS = 10 * 60 * 1000;
export const MAX_CONCURRENCY = 2;
export const INITIAL_REFRESH_THROTTLE_MS = 10 * 60 * 1000;

export const FX_URL = 'https://www.boi.org.il/currency.xml';
export const FX_HOSTS = ['www.boi.org.il', 'boi.org.il'];

/**
 * Test seam for crawl-delay pacing. Production and the real cron simulation use
 * real timers; unit tests and offline simulations replace these with a no-op so
 * they never wait. Pass `sleep`/`clock` to runRefresh for a per-call override.
 */
export const pacingDefaults = { sleep: undefined, clock: undefined };

export function backoffMs(consecutiveFailures) {
  if (!consecutiveFailures || consecutiveFailures <= 0) return 0;
  return Math.min(BACKOFF_BASE_MS * 2 ** (consecutiveFailures - 1), BACKOFF_MAX_MS);
}

/**
 * Newest successful observation time across stored rows. Attempt markers carry no
 * observedAt, so a failed refresh can never make the board look freshly checked.
 * Pass `productIds` to ignore rows for any product line that is no longer tracked:
 * a lingering historical row must not keep the Crema e Gusto board looking fresh.
 */
export function newestObservationAt(observations = [], productIds = null) {
  const allowed = productIds ? new Set(productIds) : null;
  let newestMs = null;
  let newest = null;
  for (const row of observations) {
    if (!row?.observedAt) continue;
    const productId = row?.product?.productId ?? null;
    if (allowed && productId != null && !allowed.has(productId)) continue;
    const parsed = Date.parse(row.observedAt);
    if (!Number.isFinite(parsed)) continue;
    if (newestMs == null || parsed > newestMs) {
      newestMs = parsed;
      newest = row.observedAt;
    }
  }
  return newest;
}

/**
 * Freshness of the board as a whole. `lastRefreshAt` is the last *completed*
 * refresh. A run that is interrupted after saving observations (for example a
 * redeploy stops the background job) never writes that marker, so the board also
 * reports the newest saved observation and falls back to it for the age when no
 * completed refresh exists. A recorded but old completion still reads as stale:
 * that is the scheduled pipeline having stopped, not missing data.
 */
export function refreshFreshness(lastRefreshAt, now = Date.now(), lastObservationAt = null) {
  const refreshMs = lastRefreshAt ? Date.parse(lastRefreshAt) : NaN;
  const observationMs = lastObservationAt ? Date.parse(lastObservationAt) : NaN;
  const dataMs = Number.isFinite(refreshMs) && Number.isFinite(observationMs)
    ? Math.max(refreshMs, observationMs)
    : (Number.isFinite(refreshMs) ? refreshMs : observationMs);
  const ageAnchorMs = Number.isFinite(refreshMs) ? refreshMs : observationMs;
  const ageMs = Number.isFinite(ageAnchorMs) ? now - ageAnchorMs : null;
  return {
    lastRefreshAt: lastRefreshAt ?? null,
    lastObservationAt: lastObservationAt ?? null,
    dataAsOf: Number.isFinite(dataMs) ? new Date(dataMs).toISOString() : null,
    ageHours: ageMs == null ? null : Math.round((ageMs / 3_600_000) * 10) / 10,
    stale: ageMs == null || ageMs > REFRESH_STALE_MS
  };
}

// The cron fires on fixed clock times while nextAttemptAt is stored as
// "run time + 6 h", so a tick can land seconds before a vendor's due time. Without
// a small tolerance that tick skips every vendor and the board silently drifts from
// a six-hour to a twelve-hour refresh cadence (and reports stale for hours between
// runs). Successful vendors therefore count as due up to this much early; vendors
// inside a failure backoff keep their strict due time.
export const EARLY_DUE_TOLERANCE_MS = 15 * 60 * 1000;

export function isVendorDue(state, now) {
  if (!state?.nextAttemptAt) return true;
  const due = Date.parse(state.nextAttemptAt);
  if (!Number.isFinite(due)) return true;
  const slack = (state.consecutiveFailures ?? 0) > 0 ? 0 : EARLY_DUE_TOLERANCE_MS;
  return due <= now + slack;
}

export async function runRefresh({
  store,
  vendors = registeredVendors(),
  fetchImpl = globalThis.fetch,
  now = Date.now(),
  includeFx = true,
  trigger = 'scheduled',
  holderId = `refresh-${now}-${Math.random().toString(36).slice(2, 8)}`,
  logger = null,
  sleep = undefined,
  clock = undefined,
  // Test seam for the completion timestamp. Production uses the real clock, so
  // `finishedAt` is the true finish time; a simulation can pass a time source on
  // the same timeline as `now`, which keeps stored freshness deterministic across
  // a multi-tick cron sequence instead of mixing in the real wall clock.
  timeSource = undefined
} = {}) {
  const currentTimeMs = () => (typeof timeSource === 'function' ? timeSource() : Date.now());
  const acquired = await store.acquireLease('refresh', holderId, LEASE_TTL_MS);
  if (!acquired) {
    return { skipped: true, reason: 'another refresh holds the lease', trigger };
  }
  const startedAt = new Date(now).toISOString();
  let requests = 0;
  const counter = () => { requests += 1; };
  const fxHosts = FX_HOSTS;
  const results = [];
  try {
    // Read the stored observations once, before any vendor writes, so each new
    // observation can carry the previous successful price and stock as
    // comparison evidence. The map is anchored to the pre-run state.
    const previousByKey = new Map();
    for (const row of await store.listObservations()) previousByKey.set(row.key, row);

    const queued = [];
    for (const vendor of vendors) {
      const state = await store.getVendorState(vendor.id);
      if (!isVendorDue(state, now)) {
        results.push({ vendorId: vendor.id, skipped: true, reason: 'backoff', nextAttemptAt: state.nextAttemptAt });
        continue;
      }
      queued.push({ vendor, state });
    }

    for (let index = 0; index < queued.length; index += MAX_CONCURRENCY) {
      const batch = queued.slice(index, index + MAX_CONCURRENCY);
      const batchResults = await Promise.all(batch.map(({ vendor, state }) => refreshVendor({ store, vendor, state, fetchImpl, now, counter, logger, sleep, clock, previousByKey })));
      results.push(...batchResults);
    }

    let fx = null;
    if (includeFx) fx = await refreshFxCached({ store, fetchImpl, now, counter, logger });

    // Owner correction 2026-10-12: only Crema e Gusto is tracked. Historical
    // observations and failure markers for retired product lines are removed
    // from the live store so old data cannot linger or be counted anywhere.
    let pruned = 0;
    try {
      pruned = await pruneRetiredObservations({ store, vendors });
    } catch (error) {
      logger?.warn?.(`[refresh] retired-observation prune failed: ${error?.message ?? error}`);
    }

    const finishedAt = new Date(currentTimeMs()).toISOString();
    const summary = {
      trigger,
      startedAt,
      finishedAt,
      requests,
      pruned,
      vendors: results,
      fx: fx ? { ok: fx.ok, asOf: fx.fx?.asOf ?? null, error: fx.error ?? null } : { skipped: true }
    };
    await store.recordRun(summary);
    // A completed refresh means at least one vendor actually produced a saved
    // observation. A run that fetched only the exchange-rate table (every vendor
    // still inside its backoff window) or fetched nothing at all must not make
    // the board look freshly checked when no offer was re-observed.
    const savedAny = results.some(result => (result.saved ?? 0) > 0);
    if (savedAny) {
      await store.setMeta('lastRefreshAt', { value: finishedAt, trigger });
    }
    return summary;
  } finally {
    await store.releaseLease('refresh');
  }
}

async function refreshVendor({ store, vendor, state, fetchImpl, now, counter, logger, sleep, clock, previousByKey = null }) {
  const fetchText = createBoundedFetcher({
    fetchImpl,
    allowedHosts: vendor.allowedHosts ?? vendorHosts([vendor]),
    onRequest: counter,
    // Respect a vendor's published crawl delay (for example "Crawl-delay: 7")
    // instead of firing every tracked offer back to back.
    minIntervalMs: vendor.crawlDelayMs ?? 0,
    sleep: sleep ?? pacingDefaults.sleep,
    clock: clock ?? pacingDefaults.clock
  });
  const attemptedAt = new Date(now).toISOString();
  let saved = 0;
  const failures = [];
  // A failed fetch has no freshly parsed key, so stamp the failure on the offer's
  // last successful observation row when one exists. The row keeps its observedAt,
  // price and stock, while `attemptedAt`/`lastError` describe the most recent check
  // attempt — including a failed one — instead of leaving a detached marker that no
  // board row can show. Offers that never succeeded keep the marker key.
  const attemptKeyFor = offer => {
    const existing = previousByKey
      ? [...previousByKey.values()].find(row => row?.observedAt && row?.itemUrl === offer?.url)
      : null;
    return existing?.key ?? `${vendor.id}:offer:${offer?.id ?? 'unknown'}`;
  };
  try {
    const outcome = await vendor.observe({ fetchText, now, logger });
    for (const observation of outcome.observations ?? []) {
      observation.attemptedAt = attemptedAt;
      observation.lastError = null;
      // Keep one step of comparison evidence: what the same offer showed at the
      // previous successful check. Attempt markers have no observedAt and are
      // skipped, so a failed refresh never fabricates a previous price.
      const previous = previousByKey?.get(observation.key);
      if (previous?.observedAt && previous?.price?.amount != null) {
        observation.previous = {
          observedAt: previous.observedAt,
          price: { amount: previous.price.amount, currency: previous.price.currency ?? null },
          availability: previous.availability ?? 'unknown',
          totalGrams: previous.product?.totalGrams ?? null
        };
      }
      await store.putObservation(observation);
      saved += 1;
    }
    for (const failure of outcome.failures ?? []) {
      failures.push(failure);
      const offer = (vendor.offers ?? []).find(candidate => candidate.id === failure.offerId);
      await store.markAttempt({
        key: attemptKeyFor(offer),
        attemptedAt,
        error: failure.error
      });
    }
  } catch (error) {
    failures.push({ offerId: '*', error: error?.message ?? String(error) });
    for (const offer of vendor.offers ?? []) {
      await store.markAttempt({ key: attemptKeyFor(offer), attemptedAt, error: error?.message ?? String(error) });
    }
  }
  const ok = saved > 0;
  const previousFailures = ok ? 0 : (state?.consecutiveFailures ?? 0) + 1;
  const delay = ok ? REFRESH_INTERVAL_MS : Math.max(backoffMs(previousFailures), BACKOFF_BASE_MS);
  const nextAttemptAt = new Date(now + delay).toISOString();
  const nextState = {
    vendorId: vendor.id,
    lastAttemptAt: attemptedAt,
    lastSuccessAt: ok ? attemptedAt : (state?.lastSuccessAt ?? null),
    consecutiveFailures: previousFailures,
    nextAttemptAt,
    lastErrors: failures.map(failure => failure.error).slice(0, 5)
  };
  await store.setVendorState(vendor.id, nextState);
  logger?.info?.(`[refresh] ${vendor.id}: saved=${saved} failures=${failures.length} next=${nextAttemptAt}`);
  return { vendorId: vendor.id, ok, saved, failures, nextAttemptAt };
}

export const FX_MIN_INTERVAL_MS = 3 * 60 * 60 * 1000;

/** Skip the FX fetch when a recent official rate table is already stored. */
export async function refreshFxCached({ store, fetchImpl, now, counter, logger }) {
  const stored = await store.getMeta('fx');
  if (stored?.fetchedAt && now - Date.parse(stored.fetchedAt) < FX_MIN_INTERVAL_MS) {
    return { ok: true, fx: stored, cached: true };
  }
  return refreshFx({ store, fetchImpl, now, counter, logger });
}

export async function refreshFx({ store, fetchImpl, now, counter, logger }) {
  const fetchText = createBoundedFetcher({ fetchImpl, allowedHosts: FX_HOSTS, onRequest: counter });
  const response = await fetchText(FX_URL, { accept: 'application/json' });
  const attemptedAt = new Date(now).toISOString();
  if (!response.ok) {
    logger?.warn?.(`[refresh] fx fetch failed: ${response.error ?? response.status}`);
    return { ok: false, error: response.error ?? `HTTP ${response.status}`, attemptedAt };
  }
  const parsed = (() => {
    try {
      return parseBoiRates(JSON.parse(response.text));
    } catch {
      return null;
    }
  })();
  if (!parsed) return { ok: false, error: 'Bank of Israel feed could not be parsed', attemptedAt };
  const fx = { ...parsed, fetchedAt: attemptedAt, source: FX_SOURCE };
  await store.setMeta('fx', fx);
  return { ok: true, fx, attemptedAt };
}

/**
 * Runs a refresh in the background when the board has never refreshed, for the
 * initial refresh after deployment. Bounded by a lease and a throttle so public
 * traffic can never trigger unlimited scraping.
 */
export async function maybeInitialRefresh({ store, ctx, now = Date.now(), run = runRefresh, ...options } = {}) {
  const last = await store.getMeta('lastRefreshAt');
  if (last?.value) return { skipped: true, reason: 'already refreshed' };
  const attempt = await store.getMeta('initialRefreshAttemptAt');
  if (attempt?.value && now - Date.parse(attempt.value) < INITIAL_REFRESH_THROTTLE_MS) {
    return { skipped: true, reason: 'initial refresh throttled' };
  }
  await store.setMeta('initialRefreshAttemptAt', { value: new Date(now).toISOString() });
  const promise = run({ store, trigger: 'initial', now, ...options }).catch(error => {
    console.warn(`initial refresh failed: ${error?.message ?? error}`);
    return null;
  });
  if (ctx?.waitUntil) ctx.waitUntil(promise);
  return { started: true, promise };
}

/**
 * Remove stored rows that belong to retired product lines or to offers that are
 * no longer tracked. The tracked product's last-known-good observations are
 * never touched, so a failing vendor still keeps its previous price and stock.
 * Returns the number of rows removed.
 */
export async function pruneRetiredObservations({ store, vendors = registeredVendors() } = {}) {
  if (typeof store?.deleteObservation !== 'function') return 0;
  const activeProductIds = new Set(PRODUCTS.map(product => product.id));
  const trackedAttemptKeys = new Set(vendors.flatMap(vendor =>
    (vendor.offers ?? []).map(offer => `${vendor.id}:offer:${offer.id}`)
  ));
  let pruned = 0;
  for (const row of await store.listObservations()) {
    const productId = row?.product?.productId ?? null;
    const retiredProduct = productId != null && !activeProductIds.has(productId);
    const retiredAttempt = typeof row?.key === 'string'
      && row.key.includes(':offer:')
      && !trackedAttemptKeys.has(row.key);
    if (!retiredProduct && !retiredAttempt) continue;
    await store.deleteObservation(row.key);
    pruned += 1;
  }
  return pruned;
}

