export function parseCoffeemanProduct(html, { now, url = PRODUCT_URL, productId = null } = {}) {
  const name = extractName(html);
  if (!name) throw parseError('Product name not found', { url });
  const classification = classifyListing(name, { productId });
  if (!classification.matched) {
    throw parseError('Listing does not match the tracked product', { name, reasons: classification.reasons });
  }

  const priceMatch = /itemprop="price"[^>]*\bprice="([\d.,]+)"/.exec(html) ?? /itemprop="price"[^>]*\bcontent="([\d.,]+)"/.exec(html);
  const priceAmount = parseDecimal(priceMatch?.[1]);
  if (priceAmount == null) throw parseError('Price not found in product microdata', { name });
  const currency = /itemprop="priceCurrency"\s*>\s*([A-Z]{3})/.exec(html)?.[1] ?? null;
  if (!currency) throw parseError('Currency not found in product microdata', { name });

  const regularMatch = /\bprice="([\d.,]+)"\s+id="total_regularprice"/.exec(html) ?? /\bprice="([\d.,]+)"[^>]*class="toal_regularprice_view"/.exec(html);
  const regularPrice = parseDecimal(regularMatch?.[1]);

  const availabilityHref = /itemprop="availability"[^>]*href="([^"]+)"/.exec(html)?.[1] ?? '';
  const availability = AVAILABILITY[availabilityHref.split('/').pop()] ?? 'unknown';
  const sku = /itemprop="sku"[^>]*>([^<]+)</.exec(html)?.[1]?.trim()
    ?? /מקט:\s*(\d+)/.exec(html)?.[1]
    ?? null;
  const deliveryTime = collapse(/זמן\s*אספקה\s*:\s*([^<\n]+)/.exec(html)?.[1] ?? '');

  const shipping = parseShippingOptions(html);
  const checkoutQuote = checkoutQuoteFor({ url, classification });
  const cartObservation = cartObservationFor({ url, classification });
  const shippingNote = [...new Set([shipping.note, checkoutQuote?.note, cartObservation?.note].filter(Boolean))].join(' ');
  const observation = createObservation({
    vendor: coffeeman,
    itemUrl: url,
    product: {
      productId: classification.productId,
      name,
      sku,
      gtin: null,
      variantId: classification.variantId,
      variantLabel: classification.variantLabel,
      form: classification.form,
      packGrams: classification.packGrams,
      packCount: classification.packCount,
      totalGrams: classification.totalGrams,
      category: 'קפה טחון'
    },
    price: { amount: priceAmount, currency, regularAmount: regularPrice },
    availability,
    availabilityEvidence: {
      url,
      value: availabilityHref || 'not stated',
      note: 'Availability comes from the product page offer microdata, not from a price-only scrape.'
    },
    shipping: {
      mode: 'delivery',
      service: 'home_delivery',
      certainty: shipping.deliveryCents != null ? 'verified' : checkoutQuote ? 'checkout_quote' : 'unknown',
      amount: shipping.deliveryCents != null
        ? { amount: shipping.deliveryCents, currency }
        : checkoutQuote
          ? { amount: checkoutQuote.amountIls, currency: checkoutQuote.currency }
          : null,
      // A checkout-quoted rate is only used for the cart size it was observed
      // on; the quote engine refuses to rank a larger cart with it.
      maxTotalGrams: shipping.deliveryCents != null ? null : checkoutQuote?.maxTotalGrams ?? null,
      // The product page publishes the courier rate but not the locality list, and the
      // vendor terms state home delivery is subject to that list. The caveat is kept
      // structured so the board can disclose the geographic restriction instead of
      // claiming unconditional country-wide coverage.
      destination: {
        scope: 'country',
        country: 'IL',
        caveat: 'Home delivery is limited to the localities on Amigo’s home-delivery list, which the product page does not publish. Confirm the destination at checkout.',
        caveatSource: 'https://www.coffeeman.co.il/page/%D7%AA%D7%A0%D7%90%D7%99-%D7%A9%D7%99%D7%9E%D7%95%D7%A9'
      },
      minOrder: null,
      freeThreshold: null,
      // The distribution-center option is listed on the product page without a
      // price; the anonymous cart quoted it for the recorded cart sizes, so it
      // is shown as a conditional alternative and never replaces the ranked rate.
      alternatives: shipping.distributionCenter && cartObservation?.distributionCenterIls != null
        ? [{
            id: 'distribution-center',
            label: `Distribution-center delivery up to 5 kg (cart-observed for ${cartObservation.observedCarts})`,
            amount: { amount: cartObservation.distributionCenterIls, currency },
            note: cartObservation.note
          }]
        : [],
      note: shippingNote,
      deliveryTime: deliveryTime || null,
      pickup: {
        available: shipping.pickupFree,
        amount: shipping.pickupFree ? { amount: 0, currency } : null,
        note: shipping.pickupFree ? 'Free self-pickup, listed on the product page.' : null
      },
      evidence: checkoutQuote
        ? {
            url: checkoutQuote.sourceUrl,
            retrievedAt: checkoutQuote.retrievedAt,
            note: 'Anonymous checkout estimator quote recorded by interactive browser research; see docs/evidence/browser-research/2026-10-12-vendor-shipping-quotes.json.'
          }
        : { url, retrievedAt: null, note: 'Delivery options are listed on the product page.' }
    },
    now
  });
  return observation;
}

/**
 * Resolve the browser-researched checkout quote for a parsed listing. The URL
 * is the primary key; the tracked 8 × 250 g = 2 kg multipack shape is accepted
 * as a fallback so fixture tests that pass a placeholder URL still exercise the
 * same offer identity.
 */
function checkoutQuoteFor({ url, classification }) {
  if (COFFEEMAN_CHECKOUT_QUOTES[url]) return COFFEEMAN_CHECKOUT_QUOTES[url];
  if (classification.packCount === 8 && classification.totalGrams === 2000) return COFFEEMAN_CHECKOUT_QUOTES[EIGHT_PACK_URL];
  return null;
}

/**
 * Resolve the cart-researched distribution-center observation for a parsed
 * listing. The 8-pack quote doubles as its own cart observation; the 4-pack is
 * accepted by shape so fixture tests with a placeholder URL still exercise it.
 */
function cartObservationFor({ url, classification }) {
  if (COFFEEMAN_CART_OBSERVATIONS[url]) return COFFEEMAN_CART_OBSERVATIONS[url];
  if (classification.packCount === 4 && classification.totalGrams === 1000) return COFFEEMAN_CART_OBSERVATIONS[FOUR_PACK_URL];
  const quote = checkoutQuoteFor({ url, classification });
  return quote?.distributionCenterIls != null ? quote : null;
}

export function parseShippingOptions(html) {
  const start = html.indexOf('delivery-price-product');
  const block = start >= 0 ? html.slice(start, start + 2500) : '';
  const items = [...block.matchAll(/<li[^>]*>([\s\S]*?)<\/li>/gi)].map(match => collapse(stripTags(match[1])));
  let deliveryCents = null;
  let pickupFree = false;
  let distributionCenter = null;
  for (const item of items) {
    if (item.includes('איסוף עצמי')) {
      pickupFree = true;
    } else if (item.includes('שליח')) {
      const amount = parseDecimal(item.match(/([\d.,]+)/)?.[1]);
      if (amount != null) deliveryCents = amount;
    } else if (item.includes('מרכז חלוקה')) {
      distributionCenter = item;
    }
  }
  const notes = [];
  if (deliveryCents != null) {
    notes.push(`Published courier delivery rate: ₪${deliveryCents.toFixed(2)}.`);
  } else {
    notes.push('No published courier rate found; delivery cost is unknown before checkout.');
  }
  if (distributionCenter) {
    notes.push('A distribution-center delivery option exists, but its price is not published on the product page.');
  }
  if (pickupFree) {
    notes.push('Free self-pickup is available and is kept separate from delivery.');
  }
  return { deliveryCents, pickupFree, distributionCenter, note: notes.join(' ') };
}

function extractName(html) {
  const h1 = /<h1[^>]*itemprop="name"[^>]*>([\s\S]*?)<\/h1>/i.exec(html)?.[1];
  if (h1) return decodeEntities(collapse(stripTags(h1)));
  const og = /<meta\s+property="og:title"\s+content\s*=\s*"([^"]+)"/i.exec(html)?.[1];
  if (og) return decodeEntities(collapse(String(og).replace(/\s*-\s*₪[\d.,]+\s*$/, '')));
  const title = /<title>([\s\S]*?)<\/title>/i.exec(html)?.[1];
  return title ? decodeEntities(collapse(stripTags(title).split('|')[0])) : null;
}

// Coffee4U / קופי פור יו (coffee4u.co.il), Tel Aviv, Israel — Lavazza Crema e gusto
// 250 g ground coffee in a vacuum brick. The page is a legacy Windows-1255 document
// with schema.org Product/Offer microdata for price, currency, availability and SKU,
// plus a per-product delivery options list publishing a courier rate and a cheaper
// delivery-to-pickup-point service. Free self-pickup is kept separate from delivery.
//
// The robots.txt allows product pages and asks for a crawl delay of 7 seconds; the
// adapter declares that delay so the refresh pipeline spaces its requests to this host
// instead of assuming the six-hour interval is enough.

import { classifyListing } from '../catalog.js';
import { decodeHtml, parseDecimal, stripTags, collapse } from '../lib/text.js';
import { createObservation, parseError } from './index.js';

const PRODUCT_URL = 'https://www.coffee4u.co.il/product/lavazza-crema-e-gusto-250-gr-%D7%98%D7%97%D7%95%D7%9F';

// Browser-researched coverage of the rendered anonymous checkout (2026-10-12, no
// order or personal details). The checkout's own destination lists are closed:
// door-to-door requires an exact match from its locality list, and the cheaper
// pickup-point service lists only the localities that have an actual pickup spot.
const CHECKOUT_COVERAGE = {
  courierLocalities: 1269,
  pickupPointLocalities: 420,
  verifiedLocalities: ['תל אביב - יפו', 'אילת'],
  observedAt: '2026-10-12T20:25:00Z',
  entryUrl: 'https://www.coffee4u.co.il/cart.asp',
  evidence: 'docs/evidence/browser-research/2026-10-12-coffee4u-coverage.json',
  note: 'Rendered anonymous checkout (2026-10-12): the door-to-door method quotes ₪30.00 with the destination chosen from a closed list of 1,269 Israeli localities (Tel Aviv - Yafo and Eilat selected, fee unchanged); the ₪15 pickup-point method lists 420 localities with pickup spots.'
};

const AVAILABILITY = {
  InStock: 'in_stock',
  LimitedAvailability: 'in_stock',
  OutOfStock: 'out_of_stock',
  SoldOut: 'out_of_stock',
  PreOrder: 'unknown'
};

export const coffee4u = {
  id: 'coffee4u',
  name: 'Coffee4U (קופי פור יו)',
  homepage: 'https://www.coffee4u.co.il',
  allowedHosts: ['www.coffee4u.co.il', 'coffee4u.co.il'],
  parserVersion: 'coffee4u/2',
  crawlDelayMs: 7000,
  offers: [{ id: 'crema-e-gusto-250g-ground', url: PRODUCT_URL, kind: 'delivery', productId: 'lavazza-crema-e-gusto-vacuum-ground' }],

  async observe({ fetchText, now }) {
    const observations = [];
    const failures = [];
    for (const offer of this.offers) {
      const response = await fetchText(offer.url, { accept: 'text/html' });
      if (!response.ok) {
        failures.push({ offerId: offer.id, url: offer.url, error: response.error ?? `HTTP ${response.status}` });
        continue;
      }
      try {
        const html = response.buffer ? decodeHtml(response.buffer, response.text) : response.text;
        observations.push(parseCoffee4uProduct(html, { now, url: offer.url, productId: offer.productId ?? null }));
      } catch (error) {
        failures.push({ offerId: offer.id, url: offer.url, error: error.message, details: error.details ?? null });
      }
    }
    return { observations, failures };
  }
};

export function parseCoffee4uProduct(html, { now, url = PRODUCT_URL, productId = null } = {}) {
  const name = extractName(html);
  if (!name) throw parseError('Product name not found', { url });
  const classification = classifyListing(name, { productId });
  if (!classification.matched) {
    throw parseError('Listing does not match the tracked product', { name, reasons: classification.reasons });
  }

  const priceMatch = /itemprop="price"[^>]*\bprice="([\d.,]+)"/.exec(html)
    ?? /itemprop="price"[^>]*\bcontent="([\d.,]+)"/.exec(html);
  const priceAmount = parseDecimal(priceMatch?.[1]);
  if (priceAmount == null) throw parseError('Price not found in product microdata', { name });
  const currency = /itemprop="priceCurrency"\s*>\s*([A-Z]{3})/.exec(html)?.[1] ?? null;
  if (!currency) throw parseError('Currency not found in product microdata', { name });

  const availabilityHref = /itemprop="availability"[^>]*href="([^"]+)"/.exec(html)?.[1] ?? '';
  const availability = AVAILABILITY[availabilityHref.split('/').pop()] ?? 'unknown';
  const sku = /itemprop="sku"[^>]*>([^<]+)</.exec(html)?.[1]?.trim() ?? null;

  const shipping = parseCoffee4uShipping(html);
  const observation = createObservation({
    vendor: coffee4u,
    itemUrl: url,
    product: {
      productId: classification.productId,
      name,
      sku,
      gtin: null,
      variantId: classification.variantId,
      variantLabel: classification.variantLabel,
      form: classification.form,
      packGrams: classification.packGrams,
      packCount: classification.packCount,
      totalGrams: classification.totalGrams,
      category: 'פולי קפה וקפה טחון'
    },
    price: { amount: priceAmount, currency },
    availability,
    availabilityEvidence: {
      url,
      value: availabilityHref || 'not stated',
      note: 'Availability comes from the product page offer microdata, not from a price-only scrape.'
    },
    shipping: {
      mode: 'delivery',
      service: 'home_delivery',
      certainty: shipping.courierAmount == null ? 'unknown' : 'verified',
      amount: shipping.courierAmount == null ? null : { amount: shipping.courierAmount, currency },
      // The product page publishes the door-to-door rate but not the locality list;
      // the vendor terms make home delivery subject to that list, so the board
      // discloses the restriction instead of assuming every Israeli destination.
      // The rendered anonymous checkout showed that list is closed and exact-match,
      // so the caveat names the observed shape and keeps the checkout confirmation.
      destination: {
        scope: 'country',
        country: 'IL',
        caveat: 'Door-to-door delivery is limited to the localities on Coffee4U’s home-delivery list, which the product page does not publish. The rendered anonymous checkout requires the destination from a closed list of 1,269 Israeli localities (Tel Aviv - Yafo and Eilat verified 2026-10-12); the ₪15 pickup-point service lists 420 localities with pickup spots. Confirm the destination at checkout.',
        caveatSource: 'https://www.coffee4u.co.il/page/%D7%AA%D7%A7%D7%A0%D7%95%D7%9F-0',
        observed: {
          courierLocalities: CHECKOUT_COVERAGE.courierLocalities,
          pickupPointLocalities: CHECKOUT_COVERAGE.pickupPointLocalities,
          verifiedLocalities: CHECKOUT_COVERAGE.verifiedLocalities,
          observedAt: CHECKOUT_COVERAGE.observedAt,
          entryUrl: CHECKOUT_COVERAGE.entryUrl,
          evidence: CHECKOUT_COVERAGE.evidence
        }
      },
      minOrder: null,
      freeThreshold: null,
      deliveryTime: shipping.deliveryTime,
      pickup: {
        available: shipping.selfPickup,
        amount: shipping.selfPickup ? { amount: 0, currency } : null,
        note: shipping.selfPickup ? 'Free self-pickup at the shop, listed on the product page.' : null
      },
      alternatives: shipping.pickupPointAmount == null ? [] : [{
        id: 'pickup-point',
        label: "Delivery to a צ'יטה שופס pickup point",
        amount: { amount: shipping.pickupPointAmount, currency },
        note: 'Published on the same product page for up to 5 kg; a different service from door-to-door courier delivery. The rendered checkout lists 420 localities with pickup spots (observed 2026-10-12).'
      }],
      note: `${shipping.note} ${CHECKOUT_COVERAGE.note}`,
      evidence: { url, retrievedAt: null, note: `Delivery options are listed next to the product on the product page. Checkout coverage observed in the rendered anonymous checkout; see ${CHECKOUT_COVERAGE.evidence}.` }
    },
    now
  });
  return observation;
}

export function parseCoffee4uShipping(html) {
  // The delivery list lives in one "delivery-price-product" block. Read to the end of
  // its <ul> so a longer list is still parsed, with a hard cap for untrusted markup.
  const start = html.indexOf('delivery-price-product');
  let block = '';
  if (start >= 0) {
    const listEnd = html.indexOf('</ul>', start);
    const end = listEnd >= 0 ? Math.min(listEnd + 5, start + 4000) : start + 4000;
    block = html.slice(start, end);
  }
  const items = [...block.matchAll(/<li[^>]*>([\s\S]*?)<\/li>/gi)].map(match => ({
    html: match[1],
    text: collapse(stripTags(match[1]))
  }));
  let courierAmount = null;
  let pickupPointAmount = null;
  let selfPickup = false;
  let deliveryTime = null;
  let pickupPointNote = null;
  for (const item of items) {
    const amount = parseDecimal(/<em[^>]*class=['"]?price['"]?[^>]*>\s*([\d.,]+)/.exec(item.html)?.[1])
      ?? parseDecimal(item.text.match(/([\d.,]+)\s*₪/)?.[1]);
    if (/איסוף עצמי/.test(item.text)) {
      selfPickup = true;
    } else if (/נקודת איסוף/.test(item.text)) {
      pickupPointAmount = amount;
      pickupPointNote = item.text;
    } else if (/שליחות|דלת לדלת/.test(item.text)) {
      courierAmount = amount;
      deliveryTime = collapse(item.text.match(/(עד\s*[\d-]+\s*ימי עסקים)/)?.[1] ?? '') || null;
    }
  }

  const notes = [];
  if (courierAmount != null) {
    notes.push(`Published door-to-door courier rate: ₪${courierAmount.toFixed(2)}${deliveryTime ? ` (${deliveryTime})` : ''}.`);
  } else {
    notes.push('No published courier rate found on the product page; delivery cost is unknown before checkout.');
  }
  if (pickupPointAmount != null) {
    notes.push(`The same page publishes delivery to a pickup point for ₪${pickupPointAmount.toFixed(2)} (up to 5 kg, up to 7 business days), a different service that is not used for the ranked delivered total.`);
  }
  if (selfPickup) {
    notes.push('Free self-pickup at the shop is available and is kept separate from delivery.');
  }

  return { courierAmount, pickupPointAmount, selfPickup, deliveryTime, pickupPointNote, note: notes.join(' ') };
}

function extractName(html) {
  const h1 = /<h1[^>]*itemprop="name"[^>]*>([\s\S]*?)<\/h1>/i.exec(html)?.[1];
  if (h1) return collapse(stripTags(h1));
  const og = /<meta\s+property="og:title"\s+content\s*=\s*"([^"]+)"/i.exec(html)?.[1];
  if (og) return collapse(og);
  return null;
}

#!/usr/bin/env node
// Read-only production probe for the deployed comparison board.
//
//   npm run probe:production                       # owner-reported production URL
//   npm run probe:production -- --url http://127.0.0.1:8789
//   npm run probe:production -- --out docs/evidence/production-probe-<timestamp>.json
//
// The probe sends only public GETs to a fixed endpoint list: /health, /api/status,
// /api/catalog and a few /api/board queries (including an old retired-product URL).
// It never authenticates, never deploys and never sends a credential. A snapshot
// is always written under .shurik-local/production/ unless --no-save is passed, so
// a later iteration can diff production state without re-inventing the probe.
//
// Exit code 1 when the site is unreachable, when a response is not HTTP 200, or
// when the single-product scope is violated (a retired product line appearing in
// a board payload or more than one catalog product).

import { mkdir, writeFile } from 'node:fs/promises';
import { dirname, join } from 'node:path';

const args = process.argv.slice(2);
const valueOf = flag => {
  const index = args.indexOf(flag);
  return index >= 0 ? args[index + 1] : null;
};
const baseUrl = (valueOf('--url') ?? 'https://attention-shoppers.igormaka.workers.dev').replace(/\/$/, '');
const explicitOut = valueOf('--out');
const noSave = args.includes('--no-save');
const jsonOnly = args.includes('--json');
const timeoutMs = Number(valueOf('--timeout') ?? 15_000);

const TRACKED_PRODUCT = 'lavazza-crema-e-gusto-vacuum-ground';
const RETIRED_PRODUCT_IDS = [
  'lavazza-qualita-oro-vacuum-ground',
  'lavazza-qualita-rossa-vacuum-ground',
  'lavazza-suerte-ground'
];

const startedAt = new Date().toISOString();

async function get(path) {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort('timeout'), timeoutMs);
  try {
    const response = await fetch(`${baseUrl}${path}`, {
      method: 'GET',
      redirect: 'follow',
      signal: controller.signal,
      headers: { accept: 'application/json,text/html;q=0.9,*/*;q=0.5' }
    });
    const text = await response.text();
    let body = null;
    try {
      body = JSON.parse(text);
    } catch {
      body = text.slice(0, 500);
    }
    return {
      status: response.status,
      headers: {
        contentType: response.headers.get('content-type'),
        cacheControl: response.headers.get('cache-control'),
        cfCacheStatus: response.headers.get('cf-cache-status')
      },
      body
    };
  } catch (error) {
    return { status: 0, error: error?.name === 'AbortError' ? `timeout after ${timeoutMs}ms` : `fetch failed: ${error?.message ?? error}` };
  } finally {
    clearTimeout(timer);
  }
}

const boardRows = board => [
  ...(board?.ranked ?? []),
  ...(board?.pickup ?? []),
  ...(board?.unrankable ?? []),
  ...(board?.staleOrUnavailable ?? []),
  ...(board?.unknown ?? []),
  ...(board?.best ? [board.best] : []),
  ...(board?.bestPerKg ? [board.bestPerKg] : [])
];

const summarizeBoard = board => ({
  generatedAt: board?.generatedAt ?? null,
  productId: board?.productId ?? null,
  variantId: board?.variantId ?? null,
  targetGrams: board?.targetGrams ?? null,
  destination: board?.destination?.id ?? null,
  best: board?.best ? { key: board.best.key, totalIls: board.best.totalIls, vendor: board.best.vendor?.id ?? null } : null,
  ranked: (board?.ranked ?? []).map(quote => ({
    key: quote.key,
    vendor: quote.vendor?.id ?? null,
    productId: quote.product?.productId ?? null,
    variantId: quote.product?.variantId ?? null,
    packGrams: quote.product?.packGrams ?? null,
    packCount: quote.product?.packCount ?? null,
    units: quote.units,
    itemTotalIls: quote.itemTotalIls,
    shippingIls: quote.shipping?.amountIls ?? null,
    shippingCertainty: quote.shipping?.certainty ?? null,
    totalIls: quote.totalIls,
    ilsPerKg: quote.ilsPerKg
  })),
  unrankable: (board?.unrankable ?? []).map(quote => ({
    key: quote.key,
    vendor: quote.vendor?.id ?? null,
    productId: quote.product?.productId ?? null,
    itemPrice: quote.itemPrice,
    reasons: quote.reasons
  })),
  staleOrUnavailable: (board?.staleOrUnavailable ?? []).map(quote => ({
    key: quote.key,
    vendor: quote.vendor?.id ?? null,
    availability: quote.availability,
    labels: quote.labels
  })),
  pickup: (board?.pickup ?? []).map(quote => ({
    key: quote.key,
    vendor: quote.vendor?.id ?? null,
    itemTotalIls: quote.itemTotalIls,
    note: quote.shipping?.pickup?.note ?? null
  })),
  freshness: board?.freshness ?? null,
  requestedRetiredProduct: board?.requestedRetiredProduct ?? null
});

const checks = [];
const check = (name, ok, detail) => {
  checks.push({ name, ok: Boolean(ok), detail: detail ?? null });
  return Boolean(ok);
};

const endpoints = {
  health: await get('/health'),
  status: await get('/api/status'),
  catalog: await get('/api/catalog'),
  board500: await get('/api/board?grams=500&dest=tel-aviv'),
  board1000: await get('/api/board?grams=1000&dest=tel-aviv'),
  boardUnstated: await get('/api/board?variant=unspecified&grams=500&dest=tel-aviv'),
  retiredUrl: await get('/api/board?product=lavazza-qualita-oro-vacuum-ground&grams=500&dest=tel-aviv')
};
const finishedAt = new Date().toISOString();

for (const [name, response] of Object.entries(endpoints)) {
  check(`${name} responds HTTP 200`, response.status === 200, response.error ?? `HTTP ${response.status}`);
}

const catalogProducts = (endpoints.catalog.body?.products ?? []).map(product => product.id);
check('catalog exposes exactly the tracked product', catalogProducts.length === 1 && catalogProducts[0] === TRACKED_PRODUCT, catalogProducts.join(', '));
check(
  'health reports ok with storage available',
  endpoints.health.body?.status === 'ok' && !endpoints.health.body?.storageError,
  `${endpoints.health.body?.status ?? 'missing'} / ${endpoints.health.body?.storageError ?? 'no storage error'}`
);

// Run-history integrity: a completed refresh must be recorded and time-ordered, so
// a missing or mis-stamped cron run is visible instead of silently reading as "never
// refreshed". The newest run is printed below, which is how a cron tick is observed.
const statusBody = endpoints.status.body ?? {};
const runs = Array.isArray(statusBody.runs) ? statusBody.runs : [];
const runsWellFormed = runs.length > 0 && runs.every(run => {
  const started = Date.parse(run?.startedAt);
  const finished = Date.parse(run?.finishedAt);
  return Number.isFinite(started) && Number.isFinite(finished) && finished >= started;
});
check('status run history is present and time-ordered', runsWellFormed, `${runs.length} run(s)`);
check(
  'health and status agree on the last completed refresh',
  (endpoints.health.body?.lastRefreshAt ?? null) === (statusBody.lastRefreshAt ?? null),
  `health=${endpoints.health.body?.lastRefreshAt ?? null} status=${statusBody.lastRefreshAt ?? null}`
);

const boards = {
  board500: endpoints.board500.body,
  board1000: endpoints.board1000.body,
  boardUnstated: endpoints.boardUnstated.body,
  retiredUrl: endpoints.retiredUrl.body
};
for (const [name, board] of Object.entries(boards)) {
  const ids = new Set(boardRows(board).map(quote => quote.product?.productId).filter(Boolean));
  const retiredSeen = [...ids].filter(id => RETIRED_PRODUCT_IDS.includes(id));
  check(`${name} has no retired product row`, retiredSeen.length === 0, [...ids].join(', '));
  check(`${name} names the tracked product`, board?.productId === TRACKED_PRODUCT, board?.productId ?? 'missing');
}
check(
  'the retired URL falls back with a written retired-line notice',
  boards.retiredUrl?.requestedRetiredProduct?.id === 'lavazza-qualita-oro-vacuum-ground',
  JSON.stringify(boards.retiredUrl?.requestedRetiredProduct ?? null)
);
// Owner correction 2026-10-12: no blend/variant feature. The obsolete parameter must
// not create a second, filtered view, and the catalog must expose no variant menu.
const rankedKeys = board => boardRows(board).map(quote => quote.key).sort().join('|');
check(
  'the obsolete variant parameter returns the same unified board',
  rankedKeys(boards.boardUnstated) === rankedKeys(boards.board500)
    && boards.board500?.variantId == null
    && boards.boardUnstated?.variantId == null
    && boards.board500?.counts?.excludedByVariant === undefined,
  `variantId500=${boards.board500?.variantId ?? null} variantIdUnstated=${boards.boardUnstated?.variantId ?? null} excluded=${boards.board500?.counts?.excludedByVariant ?? 'absent'}`
);
const catalogProduct = endpoints.catalog.body?.products?.[0] ?? null;
check(
  'the catalog exposes no variant selection',
  catalogProduct?.variants === undefined && catalogProduct?.defaultVariant === undefined,
  `variants=${catalogProduct?.variants === undefined ? 'absent' : JSON.stringify(catalogProduct?.variants)} defaultVariant=${catalogProduct?.defaultVariant ?? 'absent'}`
);

const snapshot = {
  capturedAt: `${startedAt} to ${finishedAt}`,
  mode: 'read-only public GETs from the coding runner; no Cloudflare credentials, admin API, deploy or remote resource change',
  url: baseUrl,
  endpoints: Object.fromEntries(Object.entries(endpoints).map(([name, response]) => [name, {
    status: response.status,
    error: response.error ?? null,
    headers: response.headers ?? null,
    body: name.startsWith('board') || name === 'retiredUrl' ? undefined : response.body,
    summary: name.startsWith('board') || name === 'retiredUrl' ? summarizeBoard(response.body) : undefined
  }])),
  checks
};

if (!noSave) {
  const outPath = explicitOut ?? join('.shurik-local', 'production', `probe-${startedAt.replace(/[:.]/g, '-')}.json`);
  await mkdir(dirname(outPath), { recursive: true });
  await writeFile(outPath, `${JSON.stringify(snapshot, null, 2)}\n`);
  snapshot.savedTo = outPath;
}

if (jsonOnly) {
  console.log(JSON.stringify(snapshot, null, 2));
} else {
  const status = endpoints.status.body ?? {};
  const catalog = endpoints.catalog.body ?? {};
  console.log(`Production probe (read-only) at ${startedAt}`);
  console.log(`URL: ${baseUrl}`);
  console.log(`Health: ${endpoints.health.status} lastRefreshAt=${endpoints.health.body?.lastRefreshAt ?? null} lastObservationAt=${endpoints.health.body?.lastObservationAt ?? null}`);
  console.log(`Status: observations=${status.observations ?? null} lastRefreshAt=${status.lastRefreshAt ?? null} stale=${status.freshness?.stale ?? null} ageHours=${status.freshness?.ageHours ?? null}`);
