import test from 'node:test';
import assert from 'node:assert/strict';
import { timeLabel, dueLabel } from '../public/ui.js';

test('timeLabel never calls a future timestamp "just now"', () => {
  const future = new Date(Date.now() + 29 * 24 * 3600_000).toISOString();
  const label = timeLabel(future);
  assert.match(label, /\(in 29 d\)/);
  assert.doesNotMatch(label, /just now/);
});

test('dueLabel formats hours and days ahead', () => {
  const hours = new Date(Date.now() + 5 * 3600_000).toISOString();
  assert.match(dueLabel(hours), /\(in 5 h\)/);
  const days = new Date(Date.now() + 29 * 24 * 3600_000).toISOString();
  assert.match(dueLabel(days), /\(in 29 d\)/);
  const past = new Date(Date.now() - 3600_000).toISOString();
  assert.match(dueLabel(past), /\(due now\)/);
});
```

