Now the UI: `public/ui.js`:
1. In `totalsBlock`, add the item-subtotal meta line when a discount applied.
2. Add a `promotionText(quote)` helper and use it in `diagnosticsDisclosure`.

Let me write the helper:

```js
/**
 * Published quantity promotion applied to this offer's item subtotal, in plain
 * shopping language. Returns null when no promotion applied. The raw vendor
 * wording stays in the details; the card face gets the short version.
 */
export function itemDiscountText(quote) {
  const discount = quote?.itemDiscount;
  if (!discount) return null;
  const before = quote.itemSubtotalBeforeDiscountIls != null ? money(quote.itemSubtotalBeforeDiscountIls) : null;
  return `${discount.percent}% promotion applied${before ? ` — was ${before}` : ''}`;
}

export function promotionDetailText(quote) {
  const discount = quote?.itemDiscount;
  if (!discount) return null;
  const from = discount.minItemSubtotal != null ? ` from ${money(discount.minItemSubtotal)} item subtotal` : '';
  const scope = discount.excludesMultipacks ? 'multipacks excluded' : 'all packs';
  return `Published promotion: ${discount.percent}% off${from} (${scope})${discount.source === 'policy' ? ', applied from the validated published-rule fallback' : ''}. Vendor wording: “${discount.wording}”`;
}
```

