export function recipeById(id) {
  return RECIPES[id] ?? null;
}

export function listRecipes() {
  return Object.values(RECIPES).map(recipe => ({
    id: recipe.id,
    vendorId: recipe.vendorId,
    vendorName: recipe.vendorName,
    productUrl: recipe.productUrl,
    cartUrl: recipe.cartUrl,
    packGrams: recipe.packGrams,
    steps: recipe.steps.length
  }));
}

/** Substitute {placeholders} from the run parameters. */
export function expandValue(value, params) {
  return String(value).replace(/\{(\w+)\}/g, (match, key) => (params[key] != null ? String(params[key]) : match));
}

export function expandSteps(recipe, params) {
  return recipe.steps.map(step => {
    const expanded = {};
    for (const [key, value] of Object.entries(step)) {
      expanded[key] = typeof value === 'string' ? expandValue(value, params) : value;
    }
    return expanded;
  });
}

/** Strip query strings and fragments: cart/session identifiers live there. */
export function sanitizeUrl(url) {
  if (!url) return null;
  try {
    const parsed = new URL(String(url));
    return `${parsed.origin}${parsed.pathname}`;
  } catch {
    return String(url).split(/[?#]/)[0];
  }
}

const TOKEN_LIKE = /\b[A-Za-z0-9_-]{24,}\b/g;
const SESSION_LIKE = /\b(?:sess(?:ion)?|sid|token|cart_?id|PHPSESSID|JSESSIONID|cf_clearance)\b\s*[=:]\s*\S+/gi;

/** Collapse whitespace, drop session/token-like runs and cap the excerpt length. */
export function sanitizeExcerpt(text, max = 600) {
  const value = String(text ?? '')
    .replace(/\u00a0/g, ' ')
    .replace(SESSION_LIKE, '[redacted]')
    .replace(TOKEN_LIKE, '[redacted]')
    .replace(/[ \t]+/g, ' ')
    .replace(/\n{2,}/g, '\n')
    .trim();
  return value.length > max ? `${value.slice(0, max - 1)}…` : value;
}

function toAmount(value) {
  if (value == null) return null;
  const parsed = Number(String(value).replace(/[^\d.,-]/g, '').replace(',', '.'));
  return Number.isFinite(parsed) ? parsed : null;
}

function freeLine(value) {
  return /חינם|free/i.test(String(value ?? ''));
}

/** Pucks summary: סכום ביניים / משלוח / סך הכל and the free-shipping sentence. */
export function parsePucksTotals(text) {
  const value = String(text ?? '');
  // The free-shipping sentence is not a charged shipping line: strip it before
  // looking for the summary fee, otherwise its "חינם" would be read as free
  // delivery on a cart that is actually below the threshold.
  const withoutThreshold = value
    .replace(/משלוח חינם בהזמנה מעל[^\n]*/g, '')
    .replace(/free shipping (?:above|over)[^\n]*/gi, '');
  const subtotal = /סכום ביניים[^\d]{0,12}([\d.,]+)/.exec(withoutThreshold)?.[1] ?? null;
  // The rendered summary prints the label and the amount on separate lines
  // ("משלוח" then "30 ₪"). Only a bare "משלוח" summary label counts: the
  // delivery-methods card ("משלוח עד הבית") and the "calculated at payment"
  // disclaimer must not be read as the applied charge.
  const shippingMatch = /(?:^|\n)[ \t]*משלוח[ \t]*\n[ \t]*([\d.,]+|חינם|free)/i.exec(withoutThreshold)
    ?? /משלוח[^\S\n]+([\d.,]+|חינם|free)/i.exec(withoutThreshold);
  const total = /סך הכל[^\d]{0,12}([\d.,]+)/.exec(withoutThreshold)?.[1] ?? null;
  const threshold = /משלוח חינם בהזמנה מעל\s*([\d.,]+)/.exec(value)?.[1] ?? null;
  const shipping = shippingMatch?.[1] ?? null;
  return {
    itemSubtotalIls: toAmount(subtotal),
    shippingIls: freeLine(shipping) ? 0 : toAmount(shipping),
    shippingLabel: freeLine(shipping) ? 'free' : shipping,
    deliveredTotalIls: toAmount(total),
    freeThresholdIls: toAmount(threshold),
    freeThresholdText: threshold ? `Free shipping above ₪${toAmount(threshold)}` : null,
    currency: 'ILS'
  };
}

/** CoffeeMan summary: סכום ביניים / משלוח / סה"כ. */
export function parseCoffeemanTotals(text) {
  const value = String(text ?? '');
  const subtotal = /סכום ביניים[^\d]{0,12}([\d.,]+)/.exec(value)?.[1] ?? null;
  const shippingMatch = /(?:משלוח|דמי משלוח)[^\S\n]*([\d.,]+|חינם|free)/i.exec(value);
  const total = /(?:סה"כ|סך הכל)[^\d]{0,12}([\d.,]+)/.exec(value)?.[1] ?? null;
  const shipping = shippingMatch?.[1] ?? null;
  return {
    itemSubtotalIls: toAmount(subtotal),
    shippingIls: freeLine(shipping) ? 0 : toAmount(shipping),
    shippingLabel: freeLine(shipping) ? 'free' : shipping,
    deliveredTotalIls: toAmount(total),
    freeThresholdIls: null,
    freeThresholdText: null,
    currency: 'ILS'
  };
}

/** Coffee4U summary: product-line total, delivery line and final total. */
export function parseCoffee4uTotals(text) {
  const value = String(text ?? '');
  // The item subtotal is the amount printed on the tracked product line
  // ("Lavazza Crema e gusto 250 gr טחון" then "₪ 76"); the checkout has no
  // separate "סכום ביניים" label. The rendered label and amount can sit on two
  // lines, so the product-line match may cross one line break (bounded).
  const subtotal = /(?:Lavazza\s+)?Crema\s*e\s*gusto[\s\S]{0,80}?₪\s*([\d.,]+)/i.exec(value)?.[1] ?? null;
  // After a method is selected the summary shows a bare "משלוח" label and then
  // the amount ("₪30"), often on the next line; before that the method card
  // shows option prices ("... - 15 ₪"), which must not be read as the applied
  // charge. The shekel sign sits before the amount on this page. A bare
  // "משלוח" summary line is required so the method-card sentences cannot match.
  const shippingMatch = /(?:^|\n)[ \t]*(?:משלוח|דמי משלוח|הובלה)[ \t]*\n[ \t]*₪\s*([\d.,]+)/i.exec(value)
    ?? /(?:^|\n)[ \t]*(?:משלוח|דמי משלוח|הובלה)[ \t]*₪\s*([\d.,]+)/i.exec(value)
    ?? /(?:^|\n)[ \t]*(?:משלוח|דמי משלוח|הובלה)[ \t]*\n[ \t]*([\d.,]+|חינם|free)/i.exec(value);
  const total = /(?:סה"כ לתשלום|סך הכל|סכום כולל מע["״]?מ)[^\d]{0,12}([\d.,]+)/.exec(value)?.[1] ?? null;
  const shipping = shippingMatch?.[1] ?? null;
  return {
    itemSubtotalIls: toAmount(subtotal),
    shippingIls: freeLine(shipping) ? 0 : toAmount(shipping),
    shippingLabel: freeLine(shipping) ? 'free' : shipping,
    deliveredTotalIls: toAmount(total),
    freeThresholdIls: null,
    freeThresholdText: null,
    currency: 'ILS'
  };
}

/**
 * Build one common evidence record from a recipe run. `status` is one of
 * `quoted` (displayed item subtotal, shipping and final total agree),
 * `partial` (a rate was read but not all three values agree),
 * `blocked` (the public flow could not produce a quote; `blocker` says where)
 * or `failed` (tooling/step error).
 */
export function buildEvidenceRecord({
  recipe,
  params = {},
  status,
  totals = {},
  pageUrl = null,
  blocker = null,
  steps = [],
  actualPacks = null,
  destinationVerified = null,
  now = Date.now()
} = {}) {
  const grams = Number(params.grams) > 0 ? Number(params.grams) : recipe.packGrams;
  const requestedPacks = Math.max(1, Math.ceil(grams / recipe.packGrams));
  const packs = Number.isFinite(actualPacks) && actualPacks > 0 ? actualPacks : requestedPacks;
  const arithmeticOk = totals.itemSubtotalIls != null && totals.shippingIls != null && totals.deliveredTotalIls != null
    && Math.abs(totals.itemSubtotalIls + totals.shippingIls - totals.deliveredTotalIls) <= 0.05;
  const resolvedStatus = status === 'quoted' && !arithmeticOk ? 'partial' : status;
  // A requested locality/postcode that the recipe could not set on the page must
  // not read as a destination quote: keep the requested values but say plainly
  // that the destination was not verified.
  const destinationNote = destinationVerified === false && (params.locality || params.postcode)
    ? 'The destination (locality/postcode) was requested but could not be verified on the rendered page, so the displayed quote is not confirmed for that destination.'
    : null;
  return {
    kind: 'browser-research-quote',
    schemaVersion: EVIDENCE_SCHEMA_VERSION,
    vendorId: recipe.vendorId,
    vendorName: recipe.vendorName,
    productUrl: sanitizeUrl(recipe.productUrl),
    cartUrl: sanitizeUrl(pageUrl ?? recipe.cartUrl),
    pack: `${packs} × ${recipe.packGrams} g = ${packs * recipe.packGrams} g`,
    requestedGrams: grams,
    observedPacks: Number.isFinite(actualPacks) ? actualPacks : null,
    locality: params.locality ?? null,
    postcode: params.postcode ?? null,
    destinationVerified: destinationVerified === true ? true : destinationVerified === false ? false : null,
    service: params.service ?? null,
    status: resolvedStatus,
    itemSubtotalIls: totals.itemSubtotalIls ?? null,
    shippingIls: totals.shippingIls ?? null,
    shippingLabel: totals.shippingLabel ?? null,
    deliveredTotalIls: totals.deliveredTotalIls ?? null,
    freeThresholdIls: totals.freeThresholdIls ?? null,
    freeThresholdText: totals.freeThresholdText ?? null,
    currency: totals.currency ?? 'ILS',
    arithmeticOk,
    qualification: [totals.qualification, destinationNote].filter(Boolean).join(' ') || null,
    blocker: blocker ? sanitizeExcerpt(blocker, 300) : null,
    excerpt: totals.excerpt ? sanitizeExcerpt(totals.excerpt) : null,
    steps: steps.map(step => ({ step: step.step, ok: step.ok, optional: Boolean(step.optional), error: step.error ? sanitizeExcerpt(step.error, 200) : null, detail: step.detail ? sanitizeExcerpt(step.detail, 120) : null })),
    observedAt: new Date(now).toISOString(),
    note: 'Anonymous cart quote recorded by interactive browser research. No order, payment, login, account or street address was involved. Cart/session identifiers are stripped from this record.'
  };
}

/** Structural validation of one evidence record before it can inform a policy. */
export function validateEvidence(record) {
  const errors = [];
  if (!record || typeof record !== 'object') return { ok: false, errors: ['record is not an object'] };
  if (record.kind !== 'browser-research-quote') errors.push('kind must be browser-research-quote');
  if (record.schemaVersion !== EVIDENCE_SCHEMA_VERSION) errors.push(`schemaVersion must be ${EVIDENCE_SCHEMA_VERSION}`);
  if (!record.vendorId) errors.push('vendorId is required');
  if (!['quoted', 'partial', 'blocked', 'failed'].includes(record.status)) errors.push('status is unknown');
  if (!record.observedAt || Number.isNaN(Date.parse(record.observedAt))) errors.push('observedAt must be an ISO date');
  for (const key of ['itemSubtotalIls', 'shippingIls', 'deliveredTotalIls']) {
    const value = record[key];
    if (value != null && !Number.isFinite(value)) errors.push(`${key} must be a number or null`);
  }
  if (record.status === 'quoted') {
    if (record.itemSubtotalIls == null || record.shippingIls == null || record.deliveredTotalIls == null) {
      errors.push('a quoted record needs item subtotal, shipping and delivered total');
    }
    if (record.arithmeticOk !== true) errors.push('a quoted record must have consistent arithmetic');
    if (!record.locality) errors.push('a quoted record must name the destination it was observed for');
    if (record.destinationVerified === false && !/destination .*could not be verified/i.test(record.qualification ?? '')) {
      errors.push('a quoted record with an unverified destination must say so in qualification');
    }
  }
  if (record.status === 'blocked' && !record.blocker) errors.push('a blocked record must explain the blocker');
  if (record.blocker && /[?&](?:sess|session|token|sid|cart_id|PHPSESSID)=/i.test(record.blocker)) {
    errors.push('blocker contains a session-like parameter');
  }
  return { ok: errors.length === 0, errors };
}

/**
 * The exact steps a runner must provide. Kept as a documented interface so the
 * WebDriver adapter in scripts/browser-research.mjs stays the only browser code.
 */
export const DRIVER_INTERFACE = [
  'goto(url)',
  'gotoUnlessText(url, text)',
  'clickText(text)',
  'clickAnyText(texts)',
  'clickSelector(selectors)',
  'selectLabel(selector, label)',
  'fill(selector, value)',
  'setQuantity(grams)',
  'waitText(text, timeoutMs)',
  'sleep(ms)',
  'getText()',
  'currentUrl()'
];

/**
 * Execute one recipe against a driver and return a sanitized evidence record.
 * A failed required step stops the run with `blocked`; optional steps are
 * reported but skipped. Extraction happens after the steps so a blocker still
 * captures what the page displayed.
 */
export async function runRecipe({ recipe, driver, params = {}, now = Date.now(), logger = null } = {}) {
  // Recipe URLs are part of the run parameters: a placeholder left unexpanded
  // would navigate to the literal "{productUrl}" instead of the vendor page.
  const runParams = { packGrams: recipe.packGrams, productUrl: recipe.productUrl, cartUrl: recipe.cartUrl, ...params };
  const steps = [];
  let status = 'quoted';
  let blocker = null;
  let actualPacks = null;
  // Destination verification: a step marked `verifies: 'destination'` must set
  // the requested locality/postcode and the page must hold it afterwards. The
  // flag stays null when a recipe has no destination steps, and turns false as
  // soon as one fails or sets something else, so the evidence record can say the
  // quote is not confirmed for the requested destination.
  let destinationVerified = null;
  const isDestinationStep = step => step.verifies === 'destination';
  const destinationMatches = (step, result) => {
    const expected = step.action === 'fill' ? step.value : step.label;
    const actual = step.action === 'fill' ? result?.value : result;
    if (expected == null) return true;
    return actual != null && String(actual).includes(String(expected));
  };
  const recordStep = (step, ok, error, detail = null) => {
    steps.push({
      step: step.action,
      ok,
      optional: Boolean(step.optional),
      error: error ? String(error.message ?? error) : null,
      detail: detail ? sanitizeExcerpt(String(detail), 120) : null
    });
  };
  for (const step of expandSteps(recipe, runParams)) {
    try {
      const result = await executeStep(step, driver, runParams);
      if (step.action === 'setQuantity' && Number.isFinite(result)) actualPacks = result;
      if (isDestinationStep(step)) {
        if (!destinationMatches(step, result)) {
          const actual = step.action === 'fill' ? result?.value ?? null : result ?? null;
          const expected = step.action === 'fill' ? step.value : step.label;
          throw new Error(`destination verification failed: the page holds ${JSON.stringify(actual)} instead of ${JSON.stringify(expected)}`);
        }
        destinationVerified = destinationVerified === false ? false : true;
      }
      recordStep(step, true, null, stepDetail(step, result));
    } catch (error) {
      recordStep(step, false, error);
      if (isDestinationStep(step)) destinationVerified = false;
      if (step.optional) continue;
      status = 'blocked';
      blocker = `Required step "${step.action}" failed: ${error?.message ?? error}`;
      break;
    }
  }
  let text = '';
  try {
    text = await driver.getText();
  } catch (error) {
    logger?.warn?.(`research: could not read page text: ${error?.message ?? error}`);
    if (status === 'quoted') {
      status = 'failed';
      blocker = `Could not read the rendered page: ${error?.message ?? error}`;
    }
  }
  let pageUrl = null;
  try {
    pageUrl = await driver.currentUrl();
  } catch {
    pageUrl = null;
  }
  let totals = {};
  if (typeof recipe.parseTotals === 'function') {
    totals = recipe.parseTotals(text) ?? {};
  }
  if (status === 'quoted' && totals.shippingIls == null) {
    status = 'blocked';
    blocker = blocker ?? 'The rendered flow did not display a shipping line for this quantity and destination.';
  }
  if (status === 'quoted' && totals.itemSubtotalIls == null) {
    status = 'blocked';
    blocker = blocker ?? 'The rendered flow did not display an item subtotal.';
  }
  if (status === 'quoted' && totals.itemSubtotalIls === 0) {
    status = 'blocked';
    blocker = blocker ?? 'The cart appears empty: no item subtotal was displayed for the tracked product.';
  }
  // A quote read without a verified whole-pack quantity is not a quoted cart:
  // keep it visible as partial evidence instead of attributing it to a cart
  // size that was never confirmed.
  const hasQuantityStep = recipe.steps.some(step => step.action === 'setQuantity');
  let qualification = totals.qualification ?? null;
  if (status === 'quoted' && hasQuantityStep && !Number.isFinite(actualPacks)) {
    status = 'partial';
    qualification = [qualification, 'Cart quantity was not verified by the recipe, so the pack size is the requested target, not a confirmed cart.'].filter(Boolean).join(' ');
  }
  // A cart that does not hold the requested number of packs must not be
  // recorded as a quote for the requested quantity.
  const requestedPacks = Math.max(1, Math.ceil((Number(runParams.grams) || recipe.packGrams) / recipe.packGrams));
  if (status === 'quoted' && Number.isFinite(actualPacks) && actualPacks !== requestedPacks) {
    status = 'partial';
    qualification = [qualification, `The page held ${actualPacks} pack(s), not the requested ${requestedPacks}, so the displayed amounts are recorded for ${actualPacks} pack(s).`].filter(Boolean).join(' ');
  }
  return buildEvidenceRecord({
    recipe,
    params: runParams,
    status,
    totals: { ...totals, qualification, excerpt: text.slice(0, 1200) },
    pageUrl,
    blocker,
    steps,
    actualPacks,
    destinationVerified,
    now
  });
}

async function executeStep(step, driver, params) {
  switch (step.action) {
    case 'goto':
      return driver.goto(step.url);
    case 'gotoUnlessText':
      return driver.gotoUnlessText(step.url, step.text);
    case 'clickText':
      return driver.clickText(step.text);
    case 'clickAnyText':
      return driver.clickAnyText(step.texts ?? [step.text]);
    case 'clickSelector':
      return driver.clickSelector(step.selectors ?? [step.selector]);
    case 'selectLabel':
      return driver.selectLabel(step.selector, step.label);
    case 'fill':
      return driver.fill(step.selector, step.value);
    case 'setQuantity':
      return driver.setQuantity(Number(step.target) || params.grams, params.packGrams);
    case 'waitText':
      return driver.waitText(step.text, step.timeout ?? 15000);
    case 'sleep':
      return driver.sleep(step.ms ?? 1000);
    case 'readTotals':
      return undefined;
    default:
      throw new Error(`unknown recipe action "${step.action}"`);
  }
}

/** Short, sanitized note about what a step actually did, for the evidence record. */
function stepDetail(step, result) {
  if (step.action === 'clickAnyText') return result ? `clicked: ${result}` : null;
  if (step.action === 'clickSelector') return result ? `clicked: ${result}` : null;
  if (step.action === 'gotoUnlessText') return result === 'skipped' ? 'already on the estimator page' : 'navigated';
  if (step.action === 'setQuantity' && Number.isFinite(result)) return `${result} pack(s) in cart`;
  // A fill step records the value the page actually holds after typing, so a
  // locality/postcode in the evidence is a verified field value, not just the
  // requested parameter.
  if (step.action === 'fill' && result && typeof result === 'object') return `${result.selector}=${result.value ?? ''}`;
  if (step.action === 'selectLabel' && result) return `selected: ${result}`;
  return null;
}

// Coffee4U / קופי פור יו (coffee4u.co.il), Tel Aviv, Israel — Lavazza Crema e gusto
// 250 g ground coffee in a vacuum brick. The page is a legacy Windows-1255 document
// with schema.org Product/Offer microdata for price, currency, availability and SKU,
// plus a per-product delivery options list publishing a courier rate and a cheaper
// delivery-to-pickup-point service. Free self-pickup is kept separate from delivery.
//
// The robots.txt allows product pages and asks for a crawl delay of 7 seconds; the
// adapter declares that delay so the refresh pipeline spaces its requests to this host
// instead of assuming the six-hour interval is enough.

import { classifyListing } from '../catalog.js';
import { coffee4uHomeDeliveryPolicy } from '../lib/policies.js';
import { decodeHtml, parseDecimal, stripTags, collapse } from '../lib/text.js';
import { createObservation, parseError } from './index.js';

const PRODUCT_URL = 'https://www.coffee4u.co.il/product/lavazza-crema-e-gusto-250-gr-%D7%98%D7%97%D7%95%D7%9F';

// Browser-researched coverage of the rendered anonymous checkout (2026-10-12, no
// order or personal details). The checkout's own destination lists are closed:
// door-to-door requires an exact match from its locality list, and the cheaper
// pickup-point service lists only the localities that have an actual pickup spot.
// The researched coverage and the pickup-point alternative live in the shared,
// validated policy (src/lib/policies.js); these helpers are the adapter-facing
// view of that one representation.
const COFFEE4U_POLICY = coffee4uHomeDeliveryPolicy;
const CHECKOUT_COVERAGE = {
  ...COFFEE4U_POLICY.destination.observed,
  entryUrl: COFFEE4U_POLICY.destination.observed.entryUrl,
  evidence: COFFEE4U_POLICY.destination.observed.evidence
};
// The verified localities are policy provenance, not a hard-coded sentence:
// extending the checkout research must reach the parsed row's note too.
const VERIFIED_LOCALITIES = [...(CHECKOUT_COVERAGE.verifiedLocalities ?? [])];
const PICKUP_POINT_ALTERNATIVE = COFFEE4U_POLICY.alternatives.find(alternative => alternative.id === 'pickup-point');

const AVAILABILITY = {
  InStock: 'in_stock',
  LimitedAvailability: 'in_stock',
  OutOfStock: 'out_of_stock',
  SoldOut: 'out_of_stock',
  PreOrder: 'unknown'
};

export const coffee4u = {
  id: 'coffee4u',
  name: 'Coffee4U (קופי פור יו)',
  homepage: 'https://www.coffee4u.co.il',
  allowedHosts: ['www.coffee4u.co.il', 'coffee4u.co.il'],
  parserVersion: 'coffee4u/3',
  crawlDelayMs: 7000,
  offers: [{ id: 'crema-e-gusto-250g-ground', url: PRODUCT_URL, kind: 'delivery', productId: 'lavazza-crema-e-gusto-vacuum-ground' }],

  async observe({ fetchText, now }) {
    const observations = [];
    const failures = [];
    for (const offer of this.offers) {
      const response = await fetchText(offer.url, { accept: 'text/html' });
      if (!response.ok) {
        failures.push({ offerId: offer.id, url: offer.url, error: response.error ?? `HTTP ${response.status}` });
        continue;
      }
      try {
        const html = response.buffer ? decodeHtml(response.buffer, response.text) : response.text;
        observations.push(parseCoffee4uProduct(html, { now, url: offer.url, productId: offer.productId ?? null }));
      } catch (error) {
        failures.push({ offerId: offer.id, url: offer.url, error: error.message, details: error.details ?? null });
      }
    }
    return { observations, failures };
  }
};

export function parseCoffee4uProduct(html, { now, url = PRODUCT_URL, productId = null } = {}) {
  const name = extractName(html);
  if (!name) throw parseError('Product name not found', { url });
  const classification = classifyListing(name, { productId });
  if (!classification.matched) {
    throw parseError('Listing does not match the tracked product', { name, reasons: classification.reasons });
  }

  const priceMatch = /itemprop="price"[^>]*\bprice="([\d.,]+)"/.exec(html)
    ?? /itemprop="price"[^>]*\bcontent="([\d.,]+)"/.exec(html);
  const priceAmount = parseDecimal(priceMatch?.[1]);
  if (priceAmount == null) throw parseError('Price not found in product microdata', { name });
  const currency = /itemprop="priceCurrency"\s*>\s*([A-Z]{3})/.exec(html)?.[1] ?? null;
  if (!currency) throw parseError('Currency not found in product microdata', { name });

  const availabilityHref = /itemprop="availability"[^>]*href="([^"]+)"/.exec(html)?.[1] ?? '';
  const availability = AVAILABILITY[availabilityHref.split('/').pop()] ?? 'unknown';
  const sku = /itemprop="sku"[^>]*>([^<]+)</.exec(html)?.[1]?.trim() ?? null;

  const shipping = parseCoffee4uShipping(html);
  const observation = createObservation({
    vendor: coffee4u,
    itemUrl: url,
    product: {
      productId: classification.productId,
      name,
      sku,
      gtin: null,
      variantId: classification.variantId,
      variantLabel: classification.variantLabel,
      form: classification.form,
      packGrams: classification.packGrams,
      packCount: classification.packCount,
      totalGrams: classification.totalGrams,
      category: 'פולי קפה וקפה טחון'
    },
    price: { amount: priceAmount, currency },
    availability,
    availabilityEvidence: {
      url,
      value: availabilityHref || 'not stated',
      note: 'Availability comes from the product page offer microdata, not from a price-only scrape.'
    },
    shipping: {
      mode: 'delivery',
      service: 'home_delivery',
      certainty: shipping.courierAmount == null ? 'unknown' : 'verified',
      amount: shipping.courierAmount == null ? null : { amount: shipping.courierAmount, currency },
      // The product page publishes the door-to-door rate but not the locality list;
      // the vendor terms make home delivery subject to that list, so the board
      // discloses the restriction instead of assuming every Israeli destination.
      // The rendered anonymous checkout showed that list is closed and exact-match,
      // so the caveat names the observed shape and keeps the checkout confirmation.
      destination: {
        ...COFFEE4U_POLICY.destination,
        observed: {
          ...CHECKOUT_COVERAGE,
          verifiedLocalities: [...CHECKOUT_COVERAGE.verifiedLocalities]
        }
      },
      minOrder: null,
      freeThreshold: null,
      deliveryTime: shipping.deliveryTime,
      pickup: {
        available: shipping.selfPickup,
        amount: shipping.selfPickup ? { amount: 0, currency } : null,
        note: shipping.selfPickup ? 'Free self-pickup at the shop, listed on the product page.' : null
      },
      alternatives: shipping.pickupPointAmount == null ? [] : [{
        id: PICKUP_POINT_ALTERNATIVE.id,
        label: PICKUP_POINT_ALTERNATIVE.label,
        amount: { amount: shipping.pickupPointAmount, currency },
        maxTotalGrams: PICKUP_POINT_ALTERNATIVE.maxTotalGrams ?? null,
        note: PICKUP_POINT_ALTERNATIVE.note
      }],
      note: `${shipping.note} Rendered anonymous checkout (${CHECKOUT_COVERAGE.observedAt}): the door-to-door method requires an exact match from a closed list of ${new Intl.NumberFormat('en-US').format(CHECKOUT_COVERAGE.courierLocalities)} Israeli localities (${VERIFIED_LOCALITIES.join(', ')} selected, fee unchanged); the ₪15 pickup-point method lists ${CHECKOUT_COVERAGE.pickupPointLocalities} localities with pickup spots.`,
      evidence: { url, retrievedAt: null, note: `Delivery options are listed next to the product on the product page. Checkout coverage observed in the rendered anonymous checkout; see ${CHECKOUT_COVERAGE.evidence}.` },
      policy: {
        id: COFFEE4U_POLICY.id,
        version: COFFEE4U_POLICY.version,
        origin: COFFEE4U_POLICY.origin,
        retrievedAt: COFFEE4U_POLICY.evidence.retrievedAt,
        reviewBy: COFFEE4U_POLICY.reviewBy,
        thresholdSemantics: COFFEE4U_POLICY.rule?.thresholdSemantics ?? null
      }
    },
    now
  });
  return observation;
}

export function parseCoffee4uShipping(html) {
  // The delivery list lives in one "delivery-price-product" block. Read to the end of
  // its <ul> so a longer list is still parsed, with a hard cap for untrusted markup.
  const start = html.indexOf('delivery-price-product');
  let block = '';
  if (start >= 0) {
    const listEnd = html.indexOf('</ul>', start);
    const end = listEnd >= 0 ? Math.min(listEnd + 5, start + 4000) : start + 4000;
    block = html.slice(start, end);
  }
  const items = [...block.matchAll(/<li[^>]*>([\s\S]*?)<\/li>/gi)].map(match => ({
    html: match[1],
    text: collapse(stripTags(match[1]))
  }));
  let courierAmount = null;
  let pickupPointAmount = null;
  let selfPickup = false;
  let deliveryTime = null;
  let pickupPointNote = null;
  for (const item of items) {
    const amount = parseDecimal(/<em[^>]*class=['"]?price['"]?[^>]*>\s*([\d.,]+)/.exec(item.html)?.[1])
      ?? parseDecimal(item.text.match(/([\d.,]+)\s*₪/)?.[1]);
    if (/איסוף עצמי/.test(item.text)) {
      selfPickup = true;
    } else if (/נקודת איסוף/.test(item.text)) {
      pickupPointAmount = amount;
      pickupPointNote = item.text;
    } else if (/שליחות|דלת לדלת/.test(item.text)) {
      courierAmount = amount;
      deliveryTime = collapse(item.text.match(/(עד\s*[\d-]+\s*ימי עסקים)/)?.[1] ?? '') || null;
    }
  }

  const notes = [];
  if (courierAmount != null) {
    notes.push(`Published door-to-door courier rate: ₪${courierAmount.toFixed(2)}${deliveryTime ? ` (${deliveryTime})` : ''}.`);
  } else {
    notes.push('No published courier rate found on the product page; delivery cost is unknown before checkout.');
  }
  if (pickupPointAmount != null) {
    notes.push(`The same page publishes delivery to a pickup point for ₪${pickupPointAmount.toFixed(2)} (up to 5 kg, up to 7 business days), a different service that is not used for the ranked delivered total.`);
  }
  if (selfPickup) {
    notes.push('Free self-pickup at the shop is available and is kept separate from delivery.');
  }

  return { courierAmount, pickupPointAmount, selfPickup, deliveryTime, pickupPointNote, note: notes.join(' ') };
}

function extractName(html) {
  const h1 = /<h1[^>]*itemprop="name"[^>]*>([\s\S]*?)<\/h1>/i.exec(html)?.[1];
  if (h1) return collapse(stripTags(h1));
  const og = /<meta\s+property="og:title"\s+content\s*=\s*"([^"]+)"/i.exec(html)?.[1];
  if (og) return collapse(og);
  return null;
}

// Home product index.
//
// The canonical home route shows the tracked catalog as cards, not the vendor
// comparison board. Each card links to the product's own directly loadable page
// (`/product/<id>`). A legacy board link that still carries product/quantity/
// destination query state — including an obsolete variant parameter — is
// forwarded to the product page with that state intact, so old shared URLs keep
// working and a retired product id can still be reported as a fallback instead
// of being silently dropped. The product page ignores the obsolete variant
// parameter and always shows the one unified comparison.

import { el, timeLabel, bidi } from './ui.js';

const params = new URLSearchParams(location.search);
const LEGACY_KEYS = ['product', 'grams', 'dest', 'variant', 'unknown'];
const isLegacyBoardLink = LEGACY_KEYS.some(key => params.has(key));

const list = document.getElementById('catalog-list');
const footer = document.getElementById('footer-status');

async function main() {
  let catalog = null;
  try {
    catalog = await fetch('/api/catalog').then(response => response.json());
  } catch (error) {
    renderError(`The product index could not be loaded (${error?.message ?? error}). The stored observations are safe; try again in a moment.`);
    return;
  }
  const products = catalog?.products ?? [];
  if (!products.length) {
    renderError('No tracked product is configured on this deployment.');
    return;
  }
  if (isLegacyBoardLink) {
    // Keep the old selection state (including a retired product request) in the
    // forwarded URL, but drop the obsolete variant parameter: the product page
    // resolves the request against the tracked catalog and shows one unified
    // comparison. Quantity and locality are preserved.
    const forwarded = new URLSearchParams(params);
    forwarded.delete('variant');
    const query = forwarded.toString();
    const target = `/product/${encodeURIComponent(products[0].id)}${query ? `?${query}` : ''}`;
    location.replace(target);
    return;
  }
  renderCatalog(products, catalog.vendors ?? []);
  renderFooterStatus();
}

function renderCatalog(products, vendors) {
  list.replaceChildren();
  for (const product of products) {
    list.append(productCard(product, vendors));
  }
}

function productCard(product, vendors) {
  const vendorCount = vendors.length;
  const listingCount = vendors.reduce((sum, vendor) => sum + (vendor.offers?.length ?? 0), 0);
  const vendorNames = vendors.map(vendor => vendor.name).filter(Boolean);
  const card = el('article', { class: 'product-card' },
    el('p', { class: 'product-card__brand', text: product.brand }),
    el('h2', { class: 'product-card__name' }, bidi(`${product.brand} ${product.line}`)),
    el('p', { class: 'product-card__meta', text: `${product.form} coffee in a ${product.packaging} · sold as 250 g packs and multipacks · one comparison for all tracked listings` }),
    el('p', { class: 'product-card__summary', text: `Compare item subtotal, named delivery method and charge, and the delivered total for a chosen quantity and Israeli locality. ${vendorCount} tracked vendor${vendorCount === 1 ? '' : 's'}${listingCount ? ` · ${listingCount} listing${listingCount === 1 ? '' : 's'}` : ''}${vendorNames.length ? `: ${vendorNames.join(', ')}` : ''}.` }),
    el('p', { class: 'product-card__action' },
      el('a', { class: 'product-card__link', href: `/product/${encodeURIComponent(product.id)}`, text: 'Compare delivered offers' })));
  return card;
}

async function renderFooterStatus() {
  if (!footer) return;
  try {
    const status = await fetch('/api/status').then(response => response.json());
    const observed = status?.lastObservationAt ?? status?.freshness?.lastObservationAt ?? null;
    footer.textContent = observed
      ? `Tracked offers last checked ${timeLabel(observed)}.`
      : 'No offer observation is stored yet; the first scheduled refresh will populate the board.';
  } catch {
    footer.textContent = 'Observation time is unavailable right now.';
  }
}

function renderError(message) {
  list.replaceChildren(el('div', { class: 'empty' }, el('strong', { text: 'The product index could not be loaded.' }), el('p', { text: message })));
}

main();

/* Canton Zürich design system (web-application patterns), adapted for a compact
   shopping tool. Flat surfaces, strict alignment, a neutral grey/black structure
   and the official blue used sparingly for the selected context and the best
   known delivered offer. Colour always carries a written label.
   Tokens: Blau #0070B4, Softblau #EDF5FA, black #000000, secondary text #666666,
   surfaces #F7F7F7, dividers #CCCCCC, stock green #1A7F1F on #EBF6EB, error red
   #D93C1A, uncertainty amber #8A4B00 on #FFF4E5 (our shopping-specific extension),
   Cyan #009EE0 only as a non-text active indicator, focus #0070B4. */

@font-face {
  font-family: 'Inter';
  src: url('/fonts/InterVariable.woff2') format('woff2-variations');
  font-weight: 100 900;
  font-style: normal;
  font-display: swap;
}

:root {
  color-scheme: light;
  --blue: #0070b4;
  --blue-soft: #edf5fa;
  --ink: #000000;
  --muted: #666666;
  --surface: #f7f7f7;
  --divider: #cccccc;
  --green: #1a7f1f;
  --green-soft: #ebf6eb;
  --red: #d93c1a;
  --amber: #8a4b00;
  --amber-soft: #fff4e5;
  --cyan: #009ee0;
  --focus: #0070b4;
  --page-max: 1240px;
}

* { box-sizing: border-box; }

html { scroll-behavior: smooth; }

body {
  margin: 0;
  background: #ffffff;
  color: var(--ink);
  font-family: 'Inter', system-ui, -apple-system, 'Segoe UI', Roboto, Arial, sans-serif;
  font-feature-settings: 'ss07', 'ss08', 'cv03', 'cv04', 'cv10';
  font-size: 16px;
  line-height: 1.45;
}

.num { font-variant-numeric: tabular-nums; }
.bidi { unicode-bidi: isolate; }
a { color: var(--ink); text-decoration: underline; text-underline-offset: 2px; }
a:hover { color: var(--blue); }

a:focus-visible,
button:focus-visible,
select:focus-visible,
input:focus-visible,
summary:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.skip {
  position: absolute;
  left: -9999px;
  top: 0;
  background: var(--ink);
  color: #fff;
  padding: 10px 14px;
  z-index: 10;
}
.skip:focus { left: 0; }

/* ---------- masthead ---------- */

.masthead {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 16px 32px;
  flex-wrap: wrap;
  max-width: var(--page-max);
  margin: 0 auto;
  padding: 14px 24px;
  border-bottom: 2px solid var(--ink);
  font-size: 12px;
  font-weight: 600;
  letter-spacing: .06em;
  text-transform: uppercase;
}
.masthead__scope { color: var(--muted); font-weight: 500; }
.masthead__brand { color: inherit; text-decoration: none; }
.masthead__brand:hover { text-decoration: underline; }
.masthead__back { color: var(--muted); font-weight: 600; text-decoration: none; }
.masthead__back:hover { color: var(--blue); text-decoration: underline; }

/* ---------- home product index ---------- */

.catalog {
  max-width: var(--page-max);
  margin: 0 auto;
  padding: 22px 24px 40px;
}
.catalog h1 {
  margin: 0;
  font-size: clamp(26px, 3.2vw, 40px);
  line-height: 1.05;
  letter-spacing: -.02em;
  font-weight: 700;
}
.catalog__intro { margin: 10px 0 0; max-width: 72ch; font-size: 14.5px; color: var(--muted); }
.catalog__list { display: grid; grid-template-columns: repeat(auto-fill, minmax(min(100%, 340px), 1fr)); gap: 16px; margin-top: 22px; }
.product-card {
  background: #fff;
  border: 1px solid var(--divider);
  border-top: 4px solid var(--blue);
  padding: 18px 20px 20px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.product-card__brand {
  margin: 0;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: .06em;
  text-transform: uppercase;
  color: var(--muted);
}
.product-card__name { margin: 0; font-size: clamp(21px, 2.2vw, 26px); line-height: 1.15; letter-spacing: -.01em; }
.product-card__meta { margin: 0; font-size: 13.5px; color: var(--muted); }
.product-card__summary { margin: 4px 0 0; font-size: 14px; }
.product-card__action { margin: 12px 0 0; }
.product-card__link { font-weight: 700; }

/* ---------- product detail head ---------- */

.product-head {
  max-width: var(--page-max);
  margin: 0 auto;
  padding: 18px 24px 10px;
}
.product-head h1 {
  margin: 0;
  font-size: clamp(24px, 3vw, 34px);
  line-height: 1.08;
  letter-spacing: -.02em;
  font-weight: 700;
}
.product-head__meta { margin: 4px 0 0; font-size: 13.5px; color: var(--muted); }

/* ---------- controls ---------- */

.controls {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 16px 24px;
  max-width: var(--page-max);
  margin: 0 auto;
  padding: 4px 24px 16px;
  border-bottom: 1px solid var(--divider);
}
.controls__group { display: flex; flex-direction: column; gap: 8px; min-width: 0; }
.controls__label {
  font-size: 12px;
  font-weight: 700;
  letter-spacing: .06em;
  text-transform: uppercase;
  padding-bottom: 4px;
  border-bottom: 2px solid var(--ink);
}
.field__static {
  font-size: 15px;
  font-weight: 600;
  padding: 9px 0;
  border-bottom: 2px solid var(--ink);
}
.field__static[hidden] { display: none; }
.controls__group select {
  font: inherit;
  font-weight: 400;
  font-size: 15px;
  padding: 9px 10px;
  border: 1px solid var(--divider);
  border-left: 3px solid var(--ink);
  border-radius: 0;
  background: #fff;
  color: var(--ink);
  min-height: 44px;
  width: 100%;
  max-width: 100%;
}
.segmented { display: flex; flex-wrap: wrap; gap: 6px; }
.segmented button {
  font: inherit;
  font-weight: 600;
  padding: 9px 13px;
  min-height: 44px;
  border: 1px solid var(--divider);
  border-bottom: 3px solid var(--divider);
  border-radius: 0;
  background: #fff;
  color: var(--ink);
  cursor: pointer;
  font-variant-numeric: tabular-nums;
}
.segmented button:hover { border-color: var(--ink); }
.segmented button[aria-pressed="true"] {
  background: var(--blue);
  border-color: var(--blue);
  border-bottom-color: var(--cyan);
  color: #fff;
}
.check { display: flex; gap: 8px; align-items: center; font-size: 13.5px; min-height: 44px; }
.check input { width: 20px; height: 20px; accent-color: var(--blue); }

/* ---------- board ---------- */

.board {
  max-width: var(--page-max);
  margin: 0 auto;
  padding: 0 24px 48px;
}
.loading { padding: 32px 0; font-size: 16px; color: var(--muted); }

/* product-detail decision area: best offer first, everything else disclosed */
.decision { padding: 8px 0 28px; }
.decision > .meta-line { max-width: 96ch; }

/* section-level disclosures (compare, pickup, missing information) */
details.disclosure--compare,
details.disclosure--pickup,
details.disclosure--unknown {
  margin-top: 18px;
  border: 1px solid var(--divider);
  border-top: 3px solid var(--ink);
  background: #fff;
}
details.disclosure--compare > summary,
details.disclosure--pickup > summary,
details.disclosure--unknown > summary {
  cursor: pointer;
  padding: 12px 16px;
  font-size: 15px;
  font-weight: 700;
  letter-spacing: 0;
  text-transform: none;
  color: var(--ink);
}
details.disclosure--compare > summary:hover,
details.disclosure--pickup > summary:hover,
details.disclosure--unknown > summary:hover { color: var(--blue); }
details.disclosure--compare > .disclosure__body,
details.disclosure--pickup > .disclosure__body,
details.disclosure--unknown > .disclosure__body {
  padding: 0 16px 16px;
  font-size: 14px;
  color: var(--ink);
  gap: 10px;
}
details.disclosure--compare > .disclosure__body > p,
details.disclosure--pickup > .disclosure__body > p { color: var(--muted); }

/* a one-line amber qualification next to a conditional total */
.qualifier {
  margin: 10px 0 0;
  padding: 7px 10px;
  background: var(--amber-soft);
  color: var(--amber);
  font-size: 13px;
  max-width: 92ch;
}
.qualifier strong { font-weight: 700; }
/* a failed last check is a short, visible uncertainty note on the card face */
.qualifier--failure { margin-top: 8px; }

.section { padding: 26px 0 30px; border-bottom: 1px solid var(--divider); }
.section:last-of-type { border-bottom: 0; }
.section__head { margin-bottom: 16px; }
.section__kicker {
  font-size: 12px;
  font-weight: 700;
  letter-spacing: .06em;
  text-transform: uppercase;
  color: var(--muted);
}
.section h2 { margin: 4px 0 0; font-size: clamp(20px, 2.4vw, 28px); line-height: 1.15; letter-spacing: -.01em; }
.section__intro { margin: 8px 0 0; max-width: 80ch; font-size: 14.5px; color: var(--muted); }

/* ---------- offer cards ---------- */

.offer-list { display: grid; gap: 14px; }
.offer {
  background: #fff;
  border: 1px solid var(--divider);
  padding: 16px 18px 18px;
}
.offer--best {
  background: var(--blue-soft);
  border-color: var(--blue);
  border-left-width: 5px;
}
.offer--compact { padding: 13px 16px 15px; }
.offer--compact .totals__value { font-size: clamp(17px, 1.9vw, 21px); }
.offer__top { display: flex; justify-content: space-between; align-items: baseline; gap: 12px; flex-wrap: wrap; }
.offer__vendor { font-size: 16px; font-weight: 700; }
.offer__vendor .status { margin-left: 8px; }
.offer__delta { font-size: 13px; color: var(--muted); font-variant-numeric: tabular-nums; }
.offer__product { margin: 8px 0 0; font-size: 15px; font-weight: 600; overflow-wrap: anywhere; }
.offer__pack { margin: 4px 0 0; font-size: 13.5px; color: var(--muted); }
.offer__links { margin-top: 12px; font-size: 14px; font-weight: 600; }

.tag {
  display: inline-block;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: .06em;
  text-transform: uppercase;
  padding: 3px 8px;
  border: 1px solid currentColor;
}
.tag--best { color: #fff; background: var(--blue); border-color: var(--blue); }
.tag--plain { color: var(--muted); border-color: var(--divider); }

/* totals: item subtotal, shipping and delivered total stay together */

.totals {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0;
  margin-top: 12px;
  border-top: 1px solid var(--divider);
  border-bottom: 1px solid var(--divider);
}
.totals__cell {
  padding: 10px 14px 10px 0;
  min-width: 0;
}
.totals__cell + .totals__cell { padding-left: 14px; border-left: 1px solid var(--divider); }
.totals__label {
  display: block;
  font-size: 11.5px;
  font-weight: 700;
  letter-spacing: .06em;
  text-transform: uppercase;
  color: var(--muted);
}
.totals__value {
  display: block;
  margin-top: 2px;
  font-size: clamp(19px, 2.2vw, 24px);
  font-weight: 700;
  line-height: 1.15;
  font-variant-numeric: tabular-nums;
  overflow-wrap: anywhere;
}
.totals__meta { display: block; margin-top: 2px; font-size: 12.5px; color: var(--muted); }
.totals__meta--method { color: var(--ink); font-weight: 600; }
.totals__cell--total .totals__value { color: var(--blue); }

/* conditions, caveats and evidence */

.conditions { margin: 12px 0 0; padding: 0; list-style: none; display: grid; gap: 4px; font-size: 13.5px; }
.conditions li { display: flex; gap: 8px; align-items: baseline; }
.conditions li::before { content: ''; width: 6px; height: 6px; margin-top: 6px; background: var(--divider); flex: none; }
.caveat {
  margin: 10px 0 0;
  padding: 8px 10px;
  background: var(--amber-soft);
  color: var(--amber);
  font-size: 13px;
  max-width: 92ch;
}
.caveat strong { font-weight: 700; }

/* status labels */

.status {
  display: inline-block;
  border: 1px solid currentColor;
  padding: 2px 7px;
  font-size: 11.5px;
  font-weight: 700;
  letter-spacing: .04em;
  text-transform: uppercase;
  white-space: nowrap;
}
.status--in_stock { color: var(--green); background: var(--green-soft); }
.status--out_of_stock { color: var(--red); background: #fff; }
.status--unknown,
.status--stale { color: var(--amber); background: var(--amber-soft); }
.status--estimate { color: var(--amber); border-style: dashed; background: #fff; }
/* Sentence-level status notes (for example the stale-refresh warning) must wrap
   inside the viewport; the badge styling above stays nowrap for short labels. */
.status--note {
  display: block;
  white-space: normal;
  text-transform: none;
  letter-spacing: normal;
}

/* unknown and pickup sections */

.unknown-list { display: grid; gap: 14px; }
.unknown {
  border: 1px solid var(--divider);
  border-left: 5px solid var(--amber);
  background: var(--amber-soft);
  padding: 16px 18px;
}
.unknown__vendor { font-weight: 700; font-size: 16px; }
.unknown__meta { font-size: 13px; color: var(--muted); font-variant-numeric: tabular-nums; overflow-wrap: anywhere; }
.unknown__reason { margin: 8px 0 0; max-width: 88ch; font-size: 14px; }
.unknown__grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(180px, 1fr)); gap: 6px 18px; margin-top: 10px; font-size: 13.5px; font-variant-numeric: tabular-nums; }
.unknown .totals { background: #fff; }
.unknown a { font-weight: 600; }
.pickup-row { border: 1px solid var(--divider); border-left: 5px solid var(--ink); background: var(--surface); padding: 12px 16px; margin-top: 10px; }
.pickup-row__head { display: flex; flex-wrap: wrap; gap: 2px 10px; align-items: baseline; }
.pickup-row__pack { font-size: 13px; color: var(--muted); }
.pickup-row__facts { display: flex; flex-wrap: wrap; gap: 4px 14px; margin-top: 6px; font-size: 13px; color: var(--muted); font-variant-numeric: tabular-nums; }
.pickup-row__link { margin: 6px 0 0; font-size: 13px; }
.pickup-row details.disclosure { margin-top: 4px; }

.empty {
  border: 1px solid var(--amber);
  background: var(--amber-soft);
  color: var(--amber);
  padding: 18px 20px;
  max-width: 82ch;
}
.empty strong { font-size: 17px; }
.empty p { margin: 8px 0 0; }

/* disclosure blocks for diagnostics and provenance */

details.disclosure { margin-top: 12px; border-top: 1px solid var(--divider); }
details.disclosure > summary {
  cursor: pointer;
  padding: 8px 0 4px;
  font-size: 12.5px;
  font-weight: 700;
  letter-spacing: .04em;
  text-transform: uppercase;
  color: var(--muted);
}
details.disclosure > summary:hover { color: var(--ink); }
details.disclosure .disclosure__body { padding: 2px 0 6px; font-size: 13px; color: var(--muted); display: grid; gap: 4px; }
details.disclosure .disclosure__body .num { font-variant-numeric: tabular-nums; }

.meta-line { margin: 14px 0 0; font-size: 12.5px; color: var(--muted); font-variant-numeric: tabular-nums; }
.notice {
  border: 1px solid var(--amber);
  border-left: 5px solid var(--amber);
  background: var(--amber-soft);
  color: var(--amber);
  padding: 12px 16px;
  margin: 0 0 18px;
  max-width: 92ch;
  font-size: 14px;
}
.notice strong { display: block; font-size: 12px; letter-spacing: .06em; text-transform: uppercase; margin-bottom: 4px; }
.notice p { margin: 0; max-width: 84ch; }

/* ---------- footer ---------- */

.site-footer {
  display: grid;
  grid-template-columns: 1.3fr 1fr;
  gap: 20px 32px;
  max-width: var(--page-max);
  margin: 0 auto;
  padding: 20px 24px 36px;
  border-top: 2px solid var(--ink);
  font-size: 13px;
}
.site-footer p { margin: 6px 0 0; max-width: 72ch; color: var(--muted); }
.site-footer__status { font-variant-numeric: tabular-nums; color: var(--muted); }
.site-footer__status details.disclosure { margin-top: 10px; }
.noscript { padding: 16px 24px; background: var(--amber-soft); color: var(--amber); }

/* ---------- responsive ---------- */

@media (max-width: 1020px) {
  .controls { grid-template-columns: repeat(3, minmax(0, 1fr)); }
}

@media (max-width: 720px) {
  .controls { grid-template-columns: 1fr 1fr; gap: 12px 14px; }
  .controls__group:first-child { grid-column: 1 / -1; }
  .totals { grid-template-columns: 1fr 1fr; }
  .totals__cell { padding: 10px 12px 10px 0; }
  .totals__cell + .totals__cell { padding-left: 12px; }
  .totals__cell--total { grid-column: 1 / -1; border-left: 0 !important; border-top: 1px solid var(--divider); padding-left: 0 !important; }
  .site-footer { grid-template-columns: 1fr; }
  .offer__top { flex-direction: column; align-items: flex-start; gap: 6px; }
}

@media (max-width: 420px) {
  body { font-size: 15px; }
  .masthead, .catalog, .product-head, .controls, .board, .site-footer { padding-left: 16px; padding-right: 16px; }
  .masthead { padding-top: 10px; padding-bottom: 10px; }
  .masthead__scope { display: none; }
  .product-head { padding-top: 12px; padding-bottom: 6px; }
  .controls { gap: 8px 12px; padding-bottom: 10px; }
  .controls__group { gap: 6px; }
  .decision { padding-top: 8px; }
  .offer { padding: 13px 14px 14px; }
  .offer--best { border-left-width: 4px; }
  .totals__cell { padding-top: 8px; padding-bottom: 8px; }
  /* Keep all five quantity buttons on one row so the best offer stays near the
     first screen: 44 px tap height is preserved, only the side padding shrinks. */
  .segmented { gap: 4px; }
  .segmented button { flex: 1 1 auto; padding-left: 10px; padding-right: 10px; }
}

@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
}

// CoffeeMan / Amigo (coffeeman.co.il), Israel — the one tracked product line:
// Lavazza Crema e Gusto Classico ground coffee in a vacuum brick
// (single 250 g pack, 4 × 250 g SKU 930334, 8 × 250 g SKU 930335).
// The Qualità Oro, Qualità Rossa and Suerte pages were retired by the
// 2026-10-12 owner correction and are deliberately not fetched targets.
// The pages are legacy Windows-1255 HTML documents with schema.org microdata.
// Price, listed availability, SKU and the published delivery options are parsed from each
// product page. Free self-pickup is kept separate from home delivery. The 8-pack page does not
// publish a courier price; the anonymous checkout estimator quoted ₪20 for one 2 kg multipack
// during browser research on 2026-10-12, so that offer now carries the observed cart rate with
// its 2 kg condition instead of staying unconditionally unknown.
// robots.txt asks for a crawl delay of 7 seconds; the adapter declares that delay so the
// refresh pipeline spaces its requests to this host.

import { classifyListing } from '../catalog.js';
import { decodeHtml, decodeEntities, parseDecimal, stripTags, collapse } from '../lib/text.js';
import { coffeemanEightPackPolicy, coffeemanSingleFourPackPolicy, policyIsCurrent } from '../lib/policies.js';
import { coffeemanGroundCoffeePercentPromotion } from '../lib/promotions.js';
import { createObservation, parseError } from './index.js';

const PRODUCT_URL = 'https://www.coffeeman.co.il/product/250-%D7%92%D7%A8%D7%9D-%D7%A7%D7%A4%D7%94-%D7%98%D7%97%D7%95%D7%9F-lavazza-crema-e-gusto-classico';
const FOUR_PACK_URL = 'https://www.coffeeman.co.il/product/4-%D7%90%D7%A8%D7%99%D7%96%D7%95%D7%AA-250-%D7%92%D7%A8%D7%9D-%D7%A7%D7%A4%D7%94-%D7%98%D7%97%D7%95%D7%9F-lavazza-crema-e-gusto-classico';
const EIGHT_PACK_URL = 'https://www.coffeeman.co.il/product/8-%D7%90%D7%A8%D7%99%D7%96%D7%95%D7%AA-250-%D7%92%D7%A8%D7%9D-%D7%A7%D7%A4%D7%94-%D7%98%D7%97%D7%95%D7%9F-lavazza-crema-e-gusto-classico';

const AVAILABILITY = {
  InStock: 'in_stock',
  LimitedAvailability: 'in_stock',
  OutOfStock: 'out_of_stock',
  SoldOut: 'out_of_stock',
  PreOrder: 'unknown'
};

const CREMA_E_GUSTO = 'lavazza-crema-e-gusto-vacuum-ground';

/**
 * Browser-researched checkout quote for the 8 × 250 g multipack (2026-10-12,
 * 18:16 UTC, re-checked in a fresh cart at 20:07 UTC). The researched rule
 * lives in src/lib/policies.js as a versioned policy so the adapter, the
 * read-time evaluator and the tests share one representation; this constant is
 * the adapter-facing view of that policy. The distribution-center alternative
 * is a second cart-observed method that happened to cost the same ₪20.
 * Evidence: docs/evidence/browser-research/2026-10-12-vendor-shipping-quotes.json
 * and the coffeeman-checkout-8pack.png screenshot. No street address, personal
 * detail, login or order submission was involved.
 */
export const COFFEEMAN_CHECKOUT_QUOTES = {
  [EIGHT_PACK_URL]: {
    amountIls: coffeemanEightPackPolicy.rule.amount.amount,
    currency: coffeemanEightPackPolicy.rule.amount.currency,
    maxTotalGrams: coffeemanEightPackPolicy.rule.maxTotalGrams,
    distributionCenterIls: coffeemanEightPackPolicy.alternatives.find(alternative => alternative.id === 'distribution-center').amount.amount,
    observedCarts: 'the 2 kg cart',
    retrievedAt: coffeemanEightPackPolicy.evidence.retrievedAt,
    sourceUrl: coffeemanEightPackPolicy.evidence.url,
    note: coffeemanEightPackPolicy.evidence.note
  }
};

/**
 * Browser-researched anonymous-cart observations for the single 250 g and
 * 4 × 250 g listings (2026-10-12, 19:56-20:09 UTC). The product page lists the
 * distribution-center delivery option without a price; the cart quoted ₪15 for
 * 0.5-1 kg carts and free home courier from a ₪231 item subtotal (charged at
 * ₪198), so the free condition is applied from ₪231 for these two listings and
 * keeps its observed-cart origin. The ₪240 8-pack SKU cart kept its own ₪20
 * quote and is covered by a separate policy. Evidence:
 * docs/evidence/browser-research/2026-10-12-coffeeman-cart-single-4pack.json.
 * No street address, personal detail, login or order submission was involved.
 */
export const COFFEEMAN_CART_OBSERVATIONS = {
  [PRODUCT_URL]: singleFourPackCartObservation(),
  [FOUR_PACK_URL]: singleFourPackCartObservation()
};

/**
 * The cart-researched distribution-center observation is stored once in the
 * validated policy (`coffeeman-single-4pack-il-home-delivery`); this helper is
 * the adapter-facing view of that policy, so the parsed row and the read-time
 * evaluator share one representation instead of a second hard-coded string.
 */
function singleFourPackCartObservation() {
  const alternative = coffeemanSingleFourPackPolicy.alternatives.find(entry => entry.id === 'distribution-center');
  return {
    distributionCenterIls: alternative.amount.amount,
    observedCarts: '0.5–1 kg carts',
    freeThresholdIls: coffeemanSingleFourPackPolicy.rule.freeThreshold?.amount ?? null,
    freeThresholdOrigin: coffeemanSingleFourPackPolicy.rule.freeThresholdOrigin ?? null,
    retrievedAt: coffeemanSingleFourPackPolicy.evidence.retrievedAt,
    sourceUrl: 'https://www.coffeeman.co.il/checkout.asp',
    note: alternative.note
  };
}

export const coffeeman = {
  id: 'coffeeman',
  name: 'CoffeeMan (אמיגו)',
  homepage: 'https://www.coffeeman.co.il',
  allowedHosts: ['www.coffeeman.co.il', 'coffeeman.co.il'],
  parserVersion: 'coffeeman/7',
  crawlDelayMs: 7000,
  offers: [
    { id: 'classico-250g', url: PRODUCT_URL, kind: 'delivery', productId: CREMA_E_GUSTO },
    { id: 'classico-1000g-4pack', url: FOUR_PACK_URL, kind: 'delivery', productId: CREMA_E_GUSTO },
    { id: 'classico-2000g-8pack', url: EIGHT_PACK_URL, kind: 'delivery', productId: CREMA_E_GUSTO }
  ],

  async observe({ fetchText, now }) {
    const observations = [];
    const failures = [];
    for (const offer of this.offers) {
      const response = await fetchText(offer.url, { accept: 'text/html' });
      if (!response.ok) {
        failures.push({ offerId: offer.id, url: offer.url, error: response.error ?? `HTTP ${response.status}` });
        continue;
      }
      try {
        const html = response.buffer ? decodeHtml(response.buffer, response.text) : response.text;
        observations.push(parseCoffeemanProduct(html, { now, url: offer.url, productId: offer.productId ?? null }));
      } catch (error) {
        failures.push({ offerId: offer.id, url: offer.url, error: error.message, details: error.details ?? null });
      }
    }
    return { observations, failures };
  }
};

export function parseCoffeemanProduct(html, { now, url = PRODUCT_URL, productId = null } = {}) {
  const name = extractName(html);
  if (!name) throw parseError('Product name not found', { url });
  const classification = classifyListing(name, { productId });
  if (!classification.matched) {
    throw parseError('Listing does not match the tracked product', { name, reasons: classification.reasons });
  }

  const priceMatch = /itemprop="price"[^>]*\bprice="([\d.,]+)"/.exec(html) ?? /itemprop="price"[^>]*\bcontent="([\d.,]+)"/.exec(html);
  const priceAmount = parseDecimal(priceMatch?.[1]);
  if (priceAmount == null) throw parseError('Price not found in product microdata', { name });
  const currency = /itemprop="priceCurrency"\s*>\s*([A-Z]{3})/.exec(html)?.[1] ?? null;
  if (!currency) throw parseError('Currency not found in product microdata', { name });

  const regularMatch = /\bprice="([\d.,]+)"\s+id="total_regularprice"/.exec(html) ?? /\bprice="([\d.,]+)"[^>]*class="toal_regularprice_view"/.exec(html);
  const regularPrice = parseDecimal(regularMatch?.[1]);

  const availabilityHref = /itemprop="availability"[^>]*href="([^"]+)"/.exec(html)?.[1] ?? '';
  const availability = AVAILABILITY[availabilityHref.split('/').pop()] ?? 'unknown';
  const sku = /itemprop="sku"[^>]*>([^<]+)</.exec(html)?.[1]?.trim()
    ?? /מקט:\s*(\d+)/.exec(html)?.[1]
    ?? null;
  const deliveryTime = collapse(/זמן\s*אספקה\s*:\s*([^<\n]+)/.exec(html)?.[1] ?? '');

  const shipping = parseShippingOptions(html);
  // The vendor publishes the ground-coffee quantity promotion in its own
  // promotion banner on the single-pack page. Parse it on every fetch so an
  // ended promotion stops applying with the next observation.
  const parsedPromotion = parseCoffeemanPromotion(html, { url, retrievedAt: new Date(now ?? Date.now()).toISOString() });
  const promotions = parsedPromotion ? [parsedPromotion] : [];
  const checkoutQuote = checkoutQuoteFor({ url, classification });
  const cartObservation = cartObservationFor({ url, classification });
  const coveragePolicy = checkoutQuote ? coffeemanEightPackPolicy : coffeemanSingleFourPackPolicy;
  const distributionCenterAlternative = coveragePolicy.alternatives?.find(alternative => alternative.id === 'distribution-center') ?? null;
  // Policy-derived rates are only applied while the policy is inside its review
  // window. The page-published ₪25 courier rate stands on its own; the
  // checkout-quoted 8-pack rate and the cart-observed distribution-center
  // alternative are withheld once `reviewBy` passes, so an overdue policy means
  // explicit unknown shipping instead of a stale unconditional rate.
  const policyCurrent = policyIsCurrent(coveragePolicy, now);
  const checkoutQuoteCurrent = checkoutQuote != null && policyCurrent;
  const cartObservationCurrent = cartObservation != null && policyCurrent;
  // The cart-observed free condition belongs to the single/4-pack policy only
  // (the 8-pack SKU kept its own ₪20 quote). It is applied only while the policy
  // is current and only when the page actually publishes the courier rate the
  // free condition modifies; once `reviewBy` passes the offer falls back to the
  // published rate with no free condition instead of a stale free promise.
  const freeThresholdRule = coveragePolicy === coffeemanSingleFourPackPolicy && policyCurrent && shipping.deliveryCents != null
    ? coffeemanSingleFourPackPolicy.rule
    : null;
  const overdueNote = (checkoutQuote || cartObservation) && !policyCurrent
    ? `The browser-researched checkout rule is past its review date (${coveragePolicy.reviewBy}) and is not applied until browser research re-checks it.`
    : null;
  const shippingNote = [...new Set([
    shipping.note,
    checkoutQuoteCurrent ? checkoutQuote?.note : null,
    cartObservationCurrent ? cartObservation?.note : null,
    overdueNote
  ].filter(Boolean))].join(' ');
  const observation = createObservation({
    vendor: coffeeman,
    itemUrl: url,
    product: {
      productId: classification.productId,
      name,
      sku,
      gtin: null,
      variantId: classification.variantId,
      variantLabel: classification.variantLabel,
      form: classification.form,
      packGrams: classification.packGrams,
      packCount: classification.packCount,
      totalGrams: classification.totalGrams,
      category: 'קפה טחון'
    },
    price: { amount: priceAmount, currency, regularAmount: regularPrice },
    availability,
    promotions,
    availabilityEvidence: {
      url,
      value: availabilityHref || 'not stated',
      note: 'Availability comes from the product page offer microdata, not from a price-only scrape.'
    },
    shipping: {
      mode: 'delivery',
      service: 'home_delivery',
      certainty: shipping.deliveryCents != null ? 'verified' : checkoutQuoteCurrent ? 'checkout_quote' : 'unknown',
      amount: shipping.deliveryCents != null
        ? { amount: shipping.deliveryCents, currency }
        : checkoutQuoteCurrent
          ? { amount: checkoutQuote.amountIls, currency: checkoutQuote.currency }
          : null,
      // A checkout-quoted rate is only used for the cart size it was observed
      // on; the quote engine refuses to rank a larger cart with it.
      maxTotalGrams: shipping.deliveryCents != null ? null : checkoutQuoteCurrent ? checkoutQuote.maxTotalGrams ?? null : null,
      // The product page publishes the courier rate but not the locality list, and the
      // vendor terms state home delivery is subject to that list. The caveat is kept
      // structured so the board can disclose the geographic restriction instead of
      // claiming unconditional country-wide coverage.
      destination: {
        scope: coveragePolicy.destination.scope,
        country: coveragePolicy.destination.country,
        caveat: coveragePolicy.destination.caveat,
        caveatSource: coveragePolicy.destination.caveatSource
      },
      minOrder: null,
      freeThreshold: freeThresholdRule?.freeThreshold ? { ...freeThresholdRule.freeThreshold } : null,
      freeThresholdSemantics: freeThresholdRule?.thresholdSemantics ?? null,
      freeThresholdOrigin: freeThresholdRule?.freeThresholdOrigin ?? null,
      freeThresholdEvidence: freeThresholdRule?.freeThresholdEvidence ? { ...freeThresholdRule.freeThresholdEvidence } : null,
      // The distribution-center option is listed on the product page without a
      // price; the anonymous cart quoted it for the recorded cart sizes, so it
      // is shown as a conditional alternative and never replaces the ranked rate.
      alternatives: shipping.distributionCenter && distributionCenterAlternative && policyCurrent
        ? [{
            id: distributionCenterAlternative.id,
            label: distributionCenterAlternative.label,
            amount: { ...distributionCenterAlternative.amount },
            maxTotalGrams: distributionCenterAlternative.maxTotalGrams ?? null,
            note: distributionCenterAlternative.note
          }]
        : [],
      note: shippingNote,
      deliveryTime: deliveryTime || null,
      pickup: {
        available: shipping.pickupFree,
        amount: shipping.pickupFree ? { amount: 0, currency } : null,
        note: shipping.pickupFree ? 'Free self-pickup, listed on the product page.' : null
      },
      evidence: checkoutQuoteCurrent
        ? {
            url: checkoutQuote.sourceUrl,
            retrievedAt: checkoutQuote.retrievedAt,
            note: 'Anonymous checkout estimator quote recorded by interactive browser research; see docs/evidence/browser-research/2026-10-12-vendor-shipping-quotes.json.'
          }
        : { url, retrievedAt: null, note: 'Delivery options are listed on the product page.' },
      // Stamp the validated policy the parsed row's coverage and alternatives
      // come from, so the offer detail can name the rule version and its review
      // date instead of an unexplained adapter constant. The adapter and the
      // read-time evaluator therefore share one researched representation.
      policy: {
        id: coveragePolicy.id,
        version: coveragePolicy.version,
        origin: coveragePolicy.origin,
        retrievedAt: coveragePolicy.evidence.retrievedAt,
        reviewBy: coveragePolicy.reviewBy,
        thresholdSemantics: coveragePolicy.rule?.thresholdSemantics ?? null,
        freeThresholdOrigin: coveragePolicy.rule?.freeThresholdOrigin ?? null
      }
    },
    now
  });
  return observation;
}

/**
 * Resolve the browser-researched checkout quote for a parsed listing. The URL
 * is the primary key; the tracked 8 × 250 g = 2 kg multipack shape is accepted
 * as a fallback so fixture tests that pass a placeholder URL still exercise the
 * same offer identity.
 */
function checkoutQuoteFor({ url, classification }) {
  if (COFFEEMAN_CHECKOUT_QUOTES[url]) return COFFEEMAN_CHECKOUT_QUOTES[url];
  if (classification.packCount === 8 && classification.totalGrams === 2000) return COFFEEMAN_CHECKOUT_QUOTES[EIGHT_PACK_URL];
  return null;
}

/**
 * Resolve the cart-researched distribution-center observation for a parsed
 * listing. The 8-pack quote doubles as its own cart observation; the 4-pack is
 * accepted by shape so fixture tests with a placeholder URL still exercise it.
 */
function cartObservationFor({ url, classification }) {
  if (COFFEEMAN_CART_OBSERVATIONS[url]) return COFFEEMAN_CART_OBSERVATIONS[url];
  if (classification.packCount === 4 && classification.totalGrams === 1000) return COFFEEMAN_CART_OBSERVATIONS[FOUR_PACK_URL];
  const quote = checkoutQuoteFor({ url, classification });
  return quote?.distributionCenterIls != null ? quote : null;
}

/**
 * Parse the vendor's published promotion banner(s) into the validated promotion
 * shape (src/lib/promotions.js). Only a ground-coffee percent-off rule with a
 * stated ILS subtotal becomes a promotion: the ₪990 vacuum-container gift
 * banner shown on the multipack pages states no discount and is ignored, so it
 * can never be turned into a price reduction.
 */
export function parseCoffeemanPromotion(html, { url = PRODUCT_URL, retrievedAt = new Date().toISOString() } = {}) {
  const blocks = [...html.matchAll(/<h3[^>]*class="promotionName"[^>]*>([\s\S]*?)<\/h3>\s*<p[^>]*class="promotionDesc"[^>]*>([\s\S]*?)<\/p>/gi)];
  for (const block of blocks) {
    const name = decodeEntities(collapse(stripTags(block[1])));
    const description = decodeEntities(collapse(stripTags(block[2])));
    const text = `${name} ${description}`.trim();
    if (!/הנחה/.test(text) || !/קפה טחון/.test(text)) continue;
    const percent = Number(/(\d{1,2})\s*%/.exec(text)?.[1]);
    const minItemSubtotal = parseDecimal(/ב-?\s*([\d.,]+)\s*ש["״]ח/.exec(text)?.[1]);
    if (!Number.isFinite(percent) || percent <= 0 || percent > 90 || minItemSubtotal == null) continue;
    return {
      id: coffeemanGroundCoffeePercentPromotion.id,
      vendorId: coffeeman.id,
      productIds: [...coffeemanGroundCoffeePercentPromotion.productIds],
      itemUrlPrefixes: [url],
      percent,
      minItemSubtotal: { amount: minItemSubtotal, currency: 'ILS' },
      // The vendor's own wording decides the boundary: "ב-250 ש\"ח" is "at ₪250".
      semantics: /(?:מעל\s*ל?|מעל\s|מעל-)/.test(description) ? 'above' : 'at_least',
      excludesMultipacks: /לא כולל מארזים/.test(text),
      origin: 'published',
      wording: text,
      evidence: { url, retrievedAt, note: 'Promotion banner parsed from the product page HTML (promotionName/promotionDesc).' }
    };
  }
  return null;
}

export function parseShippingOptions(html) {
  const start = html.indexOf('delivery-price-product');
  const block = start >= 0 ? html.slice(start, start + 2500) : '';
  const items = [...block.matchAll(/<li[^>]*>([\s\S]*?)<\/li>/gi)].map(match => collapse(stripTags(match[1])));
  let deliveryCents = null;
  let pickupFree = false;
  let distributionCenter = null;
  for (const item of items) {
    if (item.includes('איסוף עצמי')) {
      pickupFree = true;
    } else if (item.includes('שליח')) {
      const amount = parseDecimal(item.match(/([\d.,]+)/)?.[1]);
      if (amount != null) deliveryCents = amount;
    } else if (item.includes('מרכז חלוקה')) {
      distributionCenter = item;
    }
  }
  const notes = [];
  if (deliveryCents != null) {
    notes.push(`Published courier delivery rate: ₪${deliveryCents.toFixed(2)}.`);
  } else {
    notes.push('No published courier rate found; delivery cost is unknown before checkout.');
  }
  if (distributionCenter) {
    notes.push('A distribution-center delivery option exists, but its price is not published on the product page.');
  }
  if (pickupFree) {
    notes.push('Free self-pickup is available and is kept separate from delivery.');
  }
  return { deliveryCents, pickupFree, distributionCenter, note: notes.join(' ') };
}

function extractName(html) {
  const h1 = /<h1[^>]*itemprop="name"[^>]*>([\s\S]*?)<\/h1>/i.exec(html)?.[1];
  if (h1) return decodeEntities(collapse(stripTags(h1)));
  const og = /<meta\s+property="og:title"\s+content\s*=\s*"([^"]+)"/i.exec(html)?.[1];
  if (og) return decodeEntities(collapse(String(og).replace(/\s*-\s*₪[\d.,]+\s*$/, '')));
  const title = /<title>([\s\S]*?)<\/title>/i.exec(html)?.[1];
  return title ? decodeEntities(collapse(stripTags(title).split('|')[0])) : null;
}

