  `variantId500=${boards.board500?.variantId ?? null} variantIdUnstated=${boards.boardUnstated?.variantId ?? null} excluded=${boards.board500?.counts?.excludedByVariant ?? 'absent'}`
);
const catalogProduct = endpoints.catalog.body?.products?.[0] ?? null;
check(
  'the catalog exposes no variant selection',
  catalogProduct?.variants === undefined && catalogProduct?.defaultVariant === undefined,
  `variants=${catalogProduct?.variants === undefined ? 'absent' : JSON.stringify(catalogProduct?.variants)} defaultVariant=${catalogProduct?.defaultVariant ?? 'absent'}`
);

// Versioned shipping policies: the deployed status API must name the rules it
// applies at read time, with the date each one must be re-checked. A policy past
// its reviewBy date stops enriching offers, so an expired policy here is a real
// research gap, not a silent success.
const EXPECTED_POLICY_IDS = [
  'pucks-il-home-delivery',
  'coffeeman-single-4pack-il-home-delivery',
  'coffeeman-8pack-il-cart-quote',
  'coffee4u-il-home-delivery'
];
const shippingPolicies = Array.isArray(statusBody.shippingPolicies) ? statusBody.shippingPolicies : [];
const policyIds = shippingPolicies.map(policy => policy?.id);
const policiesWellFormed = EXPECTED_POLICY_IDS.every(id => {
  const policy = shippingPolicies.find(entry => entry?.id === id);
  return policy
    && Number.isInteger(policy.version) && policy.version >= 1
    && Number.isFinite(Date.parse(policy.reviewBy))
    && typeof policy.expired === 'boolean'
    && policy.origin && policy.certainty;
});
check(
  'status exposes every validated shipping policy with a review date',
  policiesWellFormed,
  `ids=[${policyIds.join(', ')}]`
);
const expiredPolicies = shippingPolicies.filter(policy => policy?.expired).map(policy => policy.id);
check(
  'no shipping policy is past its review date',
  shippingPolicies.length > 0 && expiredPolicies.length === 0,
  expiredPolicies.length ? `expired=[${expiredPolicies.join(', ')}]` : 'none expired'
);

// The board must serve the current validated policy version wherever the rule
// it applies still matches the policy's scope. A same-rule version update is
// applied at read time (provenance refresh), so an older stamp on an identical
// rule means the deployed build is not applying it; a rule that changed since
// the row was parsed legitimately waits for the next vendor refresh.
const policyVersionMismatches = [];
const policyVersionAwaiting = [];
for (const quote of boards.board500?.ranked ?? []) {
  const stamp = quote.shipping?.policy;
  if (!stamp?.id) continue;
  const current = shippingPolicies.find(policy => policy?.id === stamp.id);
  if (!current) {
    policyVersionMismatches.push(`${stamp.id}@v${stamp.version} missing from status`);
    continue;
  }
  const sameRule = (current.service ?? null) === (quote.shipping?.service ?? null)
    && (current.freeThreshold ?? null) === (quote.shipping?.freeThreshold ?? null)
    && (current.thresholdSemantics ?? null) === (quote.shipping?.freeThresholdSemantics ?? null);
  if (!sameRule) {
    policyVersionAwaiting.push(`${stamp.id}: board v${stamp.version}, current v${current.version}`);
    continue;
  }
  if (stamp.version !== current.version) {
    policyVersionMismatches.push(`${stamp.id}: board v${stamp.version} vs status v${current.version}`);
  }
}
check(
  'every ranked offer applies the current validated policy version for its rule',
  policyVersionMismatches.length === 0,
  policyVersionMismatches.length
    ? policyVersionMismatches.join(', ')
    : policyVersionAwaiting.length ? `awaiting vendor refresh: ${policyVersionAwaiting.join(', ')}` : 'all current'
);

// Published quantity promotions: only checked once the deployed build exposes
// them, so the probe stays green while the main-push deploy is still rolling
// out; once present, the rule, percent, threshold and review date must be
// well-formed (an expired promotion stops reducing an item subtotal).
const promotions = Array.isArray(statusBody.promotions) ? statusBody.promotions : null;
if (promotions) {
  const promotion = promotions.find(entry => entry?.id === 'coffeeman-ground-coffee-percent-off');
  check(
