// Ad-hoc rendered-text dump for manual readability review (not part of the repo).
import { spawn } from 'node:child_process';
import { startQaServer } from '../../scripts/qa-server.mjs';

const PORT = 9515;
const server = await startQaServer({ port: 0 });
const base = server.url;
const chrome = spawn('chromedriver', [`--port=${PORT}`, '--allowed-ips='], { stdio: ['ignore', 'pipe', 'pipe'] });
const wd = async (method, path, body) => {
  const res = await fetch(`http://127.0.0.1:${PORT}${path}`, {
    method,
    headers: { 'content-type': 'application/json' },
    body: body ? JSON.stringify(body) : undefined
  });
  const json = await res.json().catch(() => ({}));
  if (!res.ok) throw new Error(`${method} ${path} -> ${res.status} ${JSON.stringify(json).slice(0, 300)}`);
  return json.value;
};
const delay = ms => new Promise(r => setTimeout(r, ms));
try {
  const session = await wd('POST', '/session', { capabilities: { alwaysMatch: { 'goog:chromeOptions': { args: ['--headless=new', '--no-sandbox', '--disable-dev-shm-usage'] } } } });
  const id = session.sessionId;
  const evalJs = async script => wd('POST', `/session/${id}/execute/sync`, { script, args: [] });
  const goto = async url => { await wd('POST', `/session/${id}/url`, { url }); await delay(600); };
  for (const [label, width, height, url] of [
    ['home-390', 390, 844, `${base}/`],
    ['home-1440', 1440, 1000, `${base}/`],
    ['product-500-390', 390, 844, `${base}/product/lavazza-crema-e-gusto-vacuum-ground?grams=500&dest=tel-aviv`],
    ['product-2000-390', 390, 844, `${base}/product/lavazza-crema-e-gusto-vacuum-ground?grams=2000&dest=tel-aviv`],
    ['product-2000-1440', 1440, 1000, `${base}/product/lavazza-crema-e-gusto-vacuum-ground?grams=2000&dest=tel-aviv`]
  ]) {
    await wd('POST', `/session/${id}/window/rect`, { width, height, x: 0, y: 0 });
    await goto(url);
    const text = await evalJs('return document.body.innerText');
    const firstViewport = await evalJs(`return { h: window.innerHeight, text: (() => { const r = document.querySelector('#best-offer')?.getBoundingClientRect(); return null; })(), bodyText: document.body.innerText.split('\\n').slice(0, 40).join('\\n') }`);
    console.log(`\n===== ${label} =====\n${text}\n`);
  }
  await wd('DELETE', `/session/${id}`);
} finally {
  chrome.kill();
  await server.close();
}

