// Capture production (read-only) screenshots + DOM geometry of the real
// CoffeeMan last-check-failed state for overseer review. Not part of the repo.
import { spawn } from 'node:child_process';
import { mkdir, writeFile } from 'node:fs/promises';
import { setTimeout as delay } from 'node:timers/promises';

const BASE = 'https://attention-shoppers.igormaka.workers.dev';
const OUT = 'docs/evidence/visual-review';
const PORT = 9515;
await mkdir(OUT, { recursive: true });
const chrome = spawn('chromedriver', [`--port=${PORT}`, '--allowed-ips='], { stdio: ['ignore', 'pipe', 'pipe'] });
const wd = async (method, path, body) => {
  const res = await fetch(`http://127.0.0.1:${PORT}${path}`, {
    method,
    headers: { 'content-type': 'application/json' },
    body: body ? JSON.stringify(body) : undefined
  });
  const json = await res.json().catch(() => ({}));
  if (!res.ok) throw new Error(`${method} ${path} -> ${res.status} ${JSON.stringify(json).slice(0, 300)}`);
  return json.value;
};
const waitFor = async (fn, timeoutMs, label) => {
  const start = Date.now();
  while (Date.now() - start < timeoutMs) {
    if (await fn().catch(() => false)) return true;
    await delay(300);
  }
  throw new Error(`timed out waiting for ${label}`);
};
const review = { capturedAt: new Date().toISOString(), base: BASE, source: 'production read-only GETs + headless Chrome; no credentials, no cart, no order', screens: {} };
try {
  const session = await wd('POST', '/session', { capabilities: { alwaysMatch: { 'goog:chromeOptions': { args: ['--headless=new', '--no-sandbox', '--disable-dev-shm-usage'] } } } });
  const id = session.sessionId;
  const evaluate = script => wd('POST', `/session/${id}/execute/sync`, { script, args: [] });
  const goto = async url => { await wd('POST', `/session/${id}/url`, { url }); };
  const shot = async name => {
    const res = await wd('GET', `/session/${id}/screenshot`);
    await writeFile(`${OUT}/${name}`, Buffer.from(res.value, 'base64'));
    return name;
  };
  const waitProduct = () => waitFor(() => evaluate(`document.body.dataset.boardState === 'ready' && !!document.querySelector('#best-offer')`), 30_000, 'product render');
  const waitHome = () => waitFor(() => evaluate(`!!document.querySelector('#catalog-list .product-card')`), 30_000, 'home render');

  // 2 kg CoffeeMan winner, mobile 390x844, real last-check-failed state.
  await wd('POST', `/session/${id}/window/rect`, { width: 390, height: 844, x: 0, y: 0 });
  await goto(`${BASE}/product/lavazza-crema-e-gusto-vacuum-ground?grams=2000&dest=tel-aviv`);
  await waitProduct();
  review.screens['production-2kg-mobile-failed-390.png'] = await evaluate(`(() => {
    const rect = node => { const r = node.getBoundingClientRect(); return { top: Math.round(r.top), bottom: Math.round(r.bottom), left: Math.round(r.left), right: Math.round(r.right) }; };
    const card = document.querySelector('#best-offer');
    const cells = [...card.querySelectorAll('.totals__cell')];
    return {
      innerWidth: window.innerWidth, innerHeight: window.innerHeight,
      vendor: card.querySelector('.offer__vendor')?.textContent?.trim() ?? null,
      pack: card.querySelector('.offer__pack')?.textContent?.trim() ?? null,
      failure: card.querySelector('.qualifier--failure')?.textContent?.trim() ?? null,
      failureRect: rect(card.querySelector('.qualifier--failure')),
      item: cells[0]?.querySelector('.totals__value')?.textContent ?? null,
      itemMeta: cells[0]?.querySelector('.totals__meta--discount')?.textContent ?? null,
      shipping: cells[1]?.querySelector('.totals__value')?.textContent ?? null,
      method: cells[1]?.querySelector('.totals__meta--method')?.textContent ?? null,
      certainty: cells[1]?.querySelector('.totals__meta--certainty')?.textContent ?? null,
      total: cells[2]?.querySelector('.totals__value')?.textContent ?? null,
      totalRect: rect(cells[2]?.querySelector('.totals__value')),
      qualifier: card.querySelector('.qualifier:not(.qualifier--failure)')?.textContent?.trim() ?? null,
      overflow: document.documentElement.scrollWidth > window.innerWidth + 1
    };
  })()`);
  await shot('production-2kg-mobile-failed-390.png');

  // 500 g view, mobile: open compare and scroll the CoffeeMan single card into view.
  await goto(`${BASE}/product/lavazza-crema-e-gusto-vacuum-ground?grams=500&dest=tel-aviv`);
  await waitProduct();
  await evaluate(`(() => { const d = document.querySelector('#compare-other-offers'); if (d) d.open = true; return true; })()`);
