/** Every validated policy the shared evaluator may apply. */
export const SHIPPING_POLICIES = [
  pucksHomeDeliveryPolicy,
  coffeemanSingleFourPackPolicy,
  coffeemanEightPackPolicy,
  coffee4uHomeDeliveryPolicy
];

const CURRENCY_PATTERN = /^[A-Z]{3}$/;

/** Validate one policy's shape. Returns { ok, errors } without throwing. */
export function validatePolicy(policy) {
  const errors = [];
  if (!policy || typeof policy !== 'object') return { ok: false, errors: ['policy is not an object'] };
  if (!policy.id || typeof policy.id !== 'string') errors.push('id is required');
  if (!Number.isInteger(policy.version) || policy.version < 1) errors.push('version must be a positive integer');
  if (!policy.vendorId) errors.push('vendorId is required');
  if (!Array.isArray(policy.productIds) || policy.productIds.length === 0) errors.push('productIds must be a non-empty array');
  if (policy.service != null && typeof policy.service !== 'string') errors.push('service must be a string when present');
  if (!['observed_cart', 'published'].includes(policy.origin)) errors.push('origin must be "observed_cart" or "published"');
  if (!['verified', 'checkout_quote', 'estimated'].includes(policy.certainty)) errors.push('certainty must be verified, checkout_quote or estimated');
  const amount = policy.rule?.amount;
  if (!amount || !Number.isFinite(amount.amount) || !CURRENCY_PATTERN.test(String(amount.currency ?? ''))) {
    errors.push('rule.amount must carry a numeric amount and a 3-letter currency');
  }
  const threshold = policy.rule?.freeThreshold;
  if (threshold != null && (!Number.isFinite(threshold.amount) || !CURRENCY_PATTERN.test(String(threshold.currency ?? '')))) {
    errors.push('rule.freeThreshold must carry a numeric amount and a 3-letter currency when present');
  }
  if (threshold != null && !['above', 'at_least'].includes(policy.rule?.thresholdSemantics)) {
    errors.push('rule.thresholdSemantics must be "above" or "at_least" when a free threshold is present');
  }
  const thresholdOrigin = policy.rule?.freeThresholdOrigin;
  if (thresholdOrigin != null && !['published', 'observed_cart'].includes(thresholdOrigin)) {
    errors.push('rule.freeThresholdOrigin must be "published" or "observed_cart" when present');
  }
  if (thresholdOrigin != null && threshold == null) {
    errors.push('rule.freeThresholdOrigin needs a freeThreshold');
  }
  if (thresholdOrigin === 'observed_cart' && (!policy.rule?.freeThresholdEvidence?.url || !policy.rule?.freeThresholdEvidence?.retrievedAt)) {
    errors.push('an observed_cart free threshold needs freeThresholdEvidence.url and .retrievedAt');
  }
  // Scoped cart-observed free conditions: the exact cart a vendor showed free,
  // with its listing scope, whole-pack count, ordered grams, subtotal and method.
  // A threshold and scoped conditions are mutually exclusive so a rule cannot
  // silently become a monotone threshold again.
  const freeCartConditions = policy.rule?.freeCartConditions;
  if (freeCartConditions != null) {
    if (!Array.isArray(freeCartConditions) || freeCartConditions.length === 0) {
      errors.push('rule.freeCartConditions must be a non-empty array when present');
    } else if (threshold != null) {
      errors.push('rule.freeThreshold and rule.freeCartConditions cannot both be present');
    } else {
      freeCartConditions.forEach((condition, index) => {
        const at = `rule.freeCartConditions[${index}]`;
        if (!condition || typeof condition !== 'object') { errors.push(`${at} is not an object`); return; }
        if (!condition.id || typeof condition.id !== 'string') errors.push(`${at}.id is required`);
        if (!condition.service || typeof condition.service !== 'string') errors.push(`${at}.service is required`);
        if (condition.sku != null && typeof condition.sku !== 'string') errors.push(`${at}.sku must be a string when present`);
        if (!condition.itemUrlPrefix || typeof condition.itemUrlPrefix !== 'string') errors.push(`${at}.itemUrlPrefix is required`);
        if (!Number.isInteger(condition.packCount) || condition.packCount < 1) errors.push(`${at}.packCount must be a positive integer`);
        if (!Number.isInteger(condition.units) || condition.units < 1) errors.push(`${at}.units must be a positive integer`);
        if (!Number.isFinite(condition.orderedGrams) || condition.orderedGrams <= 0) errors.push(`${at}.orderedGrams must be a positive number`);
        if (!Number.isFinite(condition.itemSubtotalIls)) errors.push(`${at}.itemSubtotalIls must be a number`);
        if (condition.discountPercent != null && (!Number.isFinite(condition.discountPercent) || condition.discountPercent <= 0 || condition.discountPercent > 90)) {
          errors.push(`${at}.discountPercent must be between 0 and 90 when present`);
        }
        if (!Number.isFinite(condition.paidItemTotalIls)) errors.push(`${at}.paidItemTotalIls must be a number`);
        if (!condition.methodLabel || typeof condition.methodLabel !== 'string') errors.push(`${at}.methodLabel is required`);
        if (!condition.observedAt || Number.isNaN(Date.parse(condition.observedAt))) errors.push(`${at}.observedAt must be an ISO date`);
        if (!condition.evidence?.url || !condition.evidence?.note) errors.push(`${at}.evidence.url and .note are required`);
      });
    }
  }
  // A superseded rule is an explicit migration instruction for rows stamped by
  // an older version of the same policy; it must name the exact old amount and
  // semantics so only the superseded threshold is migrated.
  const supersedes = policy.supersedes?.freeThreshold;
  if (supersedes != null) {
    if (!Number.isFinite(supersedes.amount) || !CURRENCY_PATTERN.test(String(supersedes.currency ?? ''))) {
      errors.push('supersedes.freeThreshold must carry a numeric amount and a 3-letter currency');
    }
    if (!['above', 'at_least'].includes(supersedes.semantics)) errors.push('supersedes.freeThreshold.semantics must be "above" or "at_least"');
    if (!['published', 'observed_cart'].includes(supersedes.origin)) errors.push('supersedes.freeThreshold.origin must be "published" or "observed_cart"');
    if (!Number.isInteger(supersedes.policyVersion) || supersedes.policyVersion < 1) errors.push('supersedes.freeThreshold.policyVersion must be a positive integer');
  }
  if (policy.alternatives != null) {
    if (!Array.isArray(policy.alternatives)) {
      errors.push('alternatives must be an array when present');
    } else {
      policy.alternatives.forEach((alternative, index) => {
        if (!alternative || typeof alternative !== 'object') { errors.push(`alternatives[${index}] is not an object`); return; }
        if (!alternative.id || typeof alternative.id !== 'string') errors.push(`alternatives[${index}].id is required`);
        if (!alternative.label || typeof alternative.label !== 'string') errors.push(`alternatives[${index}].label is required`);
        const altAmount = alternative.amount;
        if (!altAmount || !Number.isFinite(altAmount.amount) || !CURRENCY_PATTERN.test(String(altAmount.currency ?? ''))) {
          errors.push(`alternatives[${index}].amount must carry a numeric amount and a 3-letter currency`);
        }
        if (alternative.maxTotalGrams != null && (!Number.isFinite(alternative.maxTotalGrams) || alternative.maxTotalGrams <= 0)) {
          errors.push(`alternatives[${index}].maxTotalGrams must be a positive number when present`);
        }
      });
    }
  }
  if (!policy.evidence?.url || !policy.evidence?.retrievedAt) errors.push('evidence.url and evidence.retrievedAt are required');
  if (!policy.reviewBy || Number.isNaN(Date.parse(policy.reviewBy))) errors.push('reviewBy must be an ISO date');
  if (!policy.destination || !['country', 'localities'].includes(policy.destination.scope)) errors.push('destination.scope must be country or localities');
  if (policy.destination?.scope === 'localities' && !Array.isArray(policy.destination.localities)) {
    errors.push('a localities destination needs a localities array');
  }
  return { ok: errors.length === 0, errors };
}

export function validatePolicies(policies = SHIPPING_POLICIES) {
  const results = policies.map(policy => ({ id: policy?.id ?? null, ...validatePolicy(policy) }));
  return { ok: results.every(result => result.ok), results };
}

/**
 * Is this policy still inside its review window at `now`?
 *
 * The read-time evaluator and the vendor adapters both use this: a policy past
 * its `reviewBy` date must not enrich an old row and must not be stamped onto a
 * freshly parsed row either, so the offer falls back to explicit unknown
 * shipping instead of a stale unconditional rate until browser research renews
 * the evidence.
 */
export function policyIsCurrent(policy, now = Date.now()) {
  const reviewBy = Date.parse(policy?.reviewBy ?? '');
  return Number.isFinite(reviewBy) && reviewBy >= now;
}

/** Does this policy's scope cover the observation? */
function policyMatches(policy, observation) {
  if (!observation || !policy) return false;
  if (policy.vendorId && observation.vendor?.id !== policy.vendorId) return false;
  const productId = observation.product?.productId ?? null;
  if (policy.productIds?.length && !policy.productIds.includes(productId)) return false;
  if (policy.itemUrlPrefixes?.length) {
    const url = String(observation.itemUrl ?? '');
    if (!policy.itemUrlPrefixes.some(prefix => url.startsWith(prefix))) return false;
  }
  if (policy.service != null && observation.shipping?.service != null && observation.shipping.service !== policy.service) return false;
  return true;
}

function ruleKey(rule, alternatives = []) {
  const amount = rule?.amount ? `${rule.amount.amount}${rule.amount.currency}` : '-';
  const threshold = rule?.freeThreshold ? `${rule.freeThreshold.amount}${rule.freeThreshold.currency}` : '-';
  const thresholdScope = `${rule?.thresholdSemantics ?? '-'}/${rule?.freeThresholdOrigin ?? '-'}`;
  const conditionsKey = (rule?.freeCartConditions ?? [])
    .map(condition => `${condition.id}:${condition.units}x${condition.packCount}:${condition.itemSubtotalIls}`)
    .join(',');
  const alternativesKey = alternatives.map(alternative => `${alternative.id}:${alternative.amount?.amount ?? '-'}${alternative.amount?.currency ?? ''}`).join(',');
  return `${amount}/${threshold}/${thresholdScope}/${conditionsKey}/${rule?.minOrder?.amount ?? '-'}/${alternativesKey}`;
}

/**
 * Does this policy describe exactly the money/scope the row already carries?
 * Used before refreshing a stamped row's provenance: a newer policy version may
 * update evidence (coverage, retrieval time) without changing the rule, but a
 * version that changes any amount must not overwrite a parsed rate at read time.
 */
function policyRuleMatchesShipping(policy, shipping) {
  const rule = policy?.rule ?? {};
  const sameAmount = (a, b) => (a?.amount ?? null) === (b?.amount ?? null) && (a?.currency ?? null) === (b?.currency ?? null);
  if (!sameAmount(rule.amount, shipping?.amount)) return false;
  if (!sameAmount(rule.freeThreshold, shipping?.freeThreshold)) return false;
  if ((rule.thresholdSemantics ?? null) !== (shipping?.freeThresholdSemantics ?? null)) return false;
  if ((rule.freeThresholdOrigin ?? null) !== (shipping?.freeThresholdOrigin ?? null)) return false;
  if ((rule.minOrder?.amount ?? null) !== (shipping?.minOrder?.amount ?? null)) return false;
  if ((rule.maxTotalGrams ?? null) !== (shipping?.maxTotalGrams ?? null)) return false;
  const policyConditions = (rule.freeCartConditions ?? [])
    .map(condition => `${condition.id}:${condition.units}x${condition.packCount}:${condition.itemSubtotalIls}`).join(',');
  const rowConditions = (shipping?.freeCartConditions ?? [])
    .map(condition => `${condition.id}:${condition.units}x${condition.packCount}:${condition.itemSubtotalIls}`).join(',');
  if (policyConditions !== rowConditions) return false;
  const policyAlternatives = (policy?.alternatives ?? [])
    .map(alternative => `${alternative.id}:${alternative.amount?.amount ?? '-'}${alternative.amount?.currency ?? ''}`).join(',');
  const rowAlternatives = (shipping?.alternatives ?? [])
    .map(alternative => `${alternative.id}:${alternative.amount?.amount ?? '-'}${alternative.amount?.currency ?? ''}`).join(',');
  return policyAlternatives === rowAlternatives;
}

/**
 * Resolve which policy (if any) may enrich this observation.
 * Statuses: applied | already-known | unmatched | expired | invalid | inconsistent.
 */
export function resolveShippingPolicy({ observation, policies = SHIPPING_POLICIES, now = Date.now() } = {}) {
  const matching = policies.filter(policy => policyMatches(policy, observation));
  if (!matching.length) return { status: 'unmatched', policy: null };
  const valid = [];
  const expired = [];
  const invalid = [];
  for (const policy of matching) {
    const check = validatePolicy(policy);
    if (!check.ok) { invalid.push({ policy, errors: check.errors }); continue; }
    if (Date.parse(policy.reviewBy) < now) expired.push(policy);
    else valid.push(policy);
  }
  if (!valid.length) {
    if (expired.length) return { status: 'expired', policy: expired.sort((a, b) => b.version - a.version)[0] };
    return { status: 'invalid', policy: invalid[0]?.policy ?? null, errors: invalid[0]?.errors ?? [] };
  }
  // One effective rule per policy id: the highest version.
  const latestById = new Map();
  for (const policy of valid) {
    const current = latestById.get(policy.id);
    if (!current || policy.version > current.version) latestById.set(policy.id, policy);
  }
  const effective = [...latestById.values()];
  const keys = new Set(effective.map(policy => ruleKey(policy.rule, policy.alternatives ?? [])));
  if (keys.size > 1) return { status: 'inconsistent', policy: null, policies: effective };
  return { status: 'applied', policy: effective.sort((a, b) => b.version - a.version)[0] };
}

/**
 * Fill only the shipping fields the observation is missing from a matching
 * validated policy. Returns { observation, status, policy }; the original
 * observation is never mutated and its observedAt/price/stock stay untouched.
 */
export function enrichObservationShipping(observation, options = {}) {
  const resolved = resolveShippingPolicy({ observation, ...options });
  if (resolved.status !== 'applied') return { observation, status: resolved.status, policy: resolved.policy ?? null };
  const policy = resolved.policy;
  const shipping = { ...(observation.shipping ?? {}) };
  let changed = false;

  // A rule correction (not new knowledge): the v2 policy applied an
  // unconditional free threshold from ₪231, but the free carts were observed
  // exactly, not as a threshold. A row stamped by that older version of the
  // same policy must stop applying the superseded threshold at read time — the
  // threshold itself came from this policy id, so removing it is not
  // overwriting a fresher vendor parse. The published base amount, the price,
  // the stock and the observation time stay untouched.
  const stampBefore = shipping.policy;
  const superseded = policy.supersedes?.freeThreshold;
  const supersedesRow = Boolean(superseded
    && stampBefore?.id === policy.id
    && Number(stampBefore.version) < policy.version
    && shipping.freeThreshold != null
    && Number(shipping.freeThreshold.amount) === superseded.amount
    && (shipping.freeThreshold.currency ?? null) === superseded.currency
    && (shipping.freeThresholdSemantics ?? null) === superseded.semantics
    && (shipping.freeThresholdOrigin ?? null) === superseded.origin
    && policy.rule?.freeThreshold == null);
  let supersededNote = null;
  if (supersedesRow) {
    delete shipping.freeThreshold;
    delete shipping.freeThresholdSemantics;
    delete shipping.freeThresholdOrigin;
    delete shipping.freeThresholdEvidence;
    supersededNote = `The earlier cart-observed free threshold (from ${superseded.amount} ${superseded.currency}) was superseded by policy ${policy.id} v${policy.version}: free delivery now applies only to the exact carts observed free (${(policy.rule?.freeCartConditions ?? []).map(condition => condition.id).join(', ')}), and a cart that matches none of them keeps the published base rate.`;
    changed = true;
  }

  if ((shipping.certainty === 'unknown' || shipping.amount == null) && policy.rule?.amount?.amount != null) {
    shipping.amount = { ...policy.rule.amount };
    shipping.certainty = policy.certainty;
    changed = true;
  }
  if (shipping.freeThreshold == null && policy.rule?.freeThreshold?.amount != null) {
    shipping.freeThreshold = { ...policy.rule.freeThreshold };
    changed = true;
  }
  // Keep the vendor's boundary wording attached to the threshold it belongs to,
  // so "above ₪100" is never silently evaluated as "at least ₪100".
  if (shipping.freeThresholdSemantics == null && shipping.freeThreshold != null && policy.rule?.thresholdSemantics) {
    shipping.freeThresholdSemantics = policy.rule.thresholdSemantics;
    changed = true;
  }
  // A threshold can be a published rule or a conditional anonymous-cart
  // observation; the origin travels with the amount so the UI can label the
  // free condition instead of presenting it as an unconditional published rate.
  if (shipping.freeThresholdOrigin == null && shipping.freeThreshold != null && policy.rule?.freeThresholdOrigin) {
    shipping.freeThresholdOrigin = policy.rule.freeThresholdOrigin;
    changed = true;
  }
  if (shipping.freeThresholdEvidence == null && shipping.freeThresholdOrigin === 'observed_cart' && policy.rule?.freeThresholdEvidence) {
    shipping.freeThresholdEvidence = { ...policy.rule.freeThresholdEvidence };
    changed = true;
  }
  // Scoped cart-observed free conditions travel with the policy the same way a
  // published threshold does; they are only ever applied when the current cart
  // matches one exactly (see the quote engine), never as a monotone threshold.
  if (shipping.freeCartConditions == null && policy.rule?.freeCartConditions?.length) {
    shipping.freeCartConditions = policy.rule.freeCartConditions.map(condition => ({
      ...condition,
      evidence: { ...condition.evidence }
    }));
    changed = true;
  }
  if (shipping.minOrder == null && policy.rule?.minOrder?.amount != null) {
    shipping.minOrder = { ...policy.rule.minOrder };
    changed = true;
  }
  if (shipping.maxTotalGrams == null && policy.rule?.maxTotalGrams != null) {
    shipping.maxTotalGrams = policy.rule.maxTotalGrams;
    changed = true;
  }
  if (shipping.service == null && policy.service) {
    shipping.service = policy.service;
    changed = true;
  }
  if ((shipping.alternatives == null || shipping.alternatives.length === 0) && policy.alternatives?.length) {
    // Secondary delivery methods (for example a cheaper distribution-center or
    // pickup-point service) are display-only alternatives: they are added when
    // the stored row has none, and they never replace the ranked amount.
    shipping.alternatives = policy.alternatives.map(alternative => ({ ...alternative, amount: { ...alternative.amount } }));
    changed = true;
  }
  if (shipping.destination == null && policy.destination) {
    shipping.destination = { ...policy.destination };
    changed = true;
  } else if (shipping.destination != null && policy.destination) {
    // An older stored row often already carries a generic destination scope but
    // not the coverage caveat the researched evidence established. Keep the
    // row's own scope and add the missing caveat (plus the observed coverage
    // shape when the row has none), so an enriched rate is never presented as
    // unconditional country-wide delivery. A row that already states its own
    // coverage caveat is left as it is.
    if (Boolean(policy.destination.caveat) && shipping.destination.caveat == null) {
      shipping.destination = {
        ...shipping.destination,
        caveat: policy.destination.caveat,
        caveatSource: policy.destination.caveatSource ?? null,
        ...(shipping.destination.observed == null && policy.destination.observed != null
          ? { observed: { ...policy.destination.observed } }
          : {})
      };
      changed = true;
    }
  }

  // A row stamped by an older version of the same policy keeps its amounts (the
  // rule is identical) but must not keep older provenance: newly validated
  // shipping knowledge — a coverage caveat, a re-check time — should reach
  // persisted offers promptly instead of waiting for the next item refresh.
  const stamp = shipping.policy;
  const provenanceRefresh = !changed
    && stamp?.id === policy.id
    && Number.isFinite(Number(stamp.version))
    && Number(stamp.version) < policy.version
    && policyRuleMatchesShipping(policy, shipping);
  if (!changed && !provenanceRefresh) return { observation, status: 'already-known', policy };

  if (provenanceRefresh) {
    if (policy.destination?.caveat && shipping.destination != null) {
      shipping.destination = {
        ...shipping.destination,
        caveat: policy.destination.caveat,
        caveatSource: policy.destination.caveatSource ?? shipping.destination.caveatSource ?? null,
        // The observed coverage shape is policy-derived provenance too (the
        // Coffee4U adapter copies it from the policy). Refreshing it here lets a
        // coverage extension reach already-stamped rows; the caveat text above
        // is what the shopper reads, and the counts/verified localities back it.
        ...(policy.destination.observed != null
          ? { observed: { ...policy.destination.observed, ...(Array.isArray(policy.destination.observed.verifiedLocalities) ? { verifiedLocalities: [...policy.destination.observed.verifiedLocalities] } : {}) } }
          : {})
      };
    }
    // Only refresh evidence that already came from this policy (same URL); a
    // row with its own page-parsed evidence keeps it.
    if (shipping.evidence?.url && policy.evidence?.url && shipping.evidence.url === policy.evidence.url) {
      shipping.evidence = { ...shipping.evidence, retrievedAt: policy.evidence.retrievedAt, note: policy.evidence.note };
    }
  }

  shipping.policy = {
    id: policy.id,
    version: policy.version,
    origin: policy.origin,
    retrievedAt: policy.evidence.retrievedAt,
    reviewBy: policy.reviewBy,
    thresholdSemantics: policy.rule?.thresholdSemantics ?? null,
    freeThresholdOrigin: policy.rule?.freeThresholdOrigin ?? null,
    freeCartConditionIds: (policy.rule?.freeCartConditions ?? []).map(condition => condition.id)
  };
  if (shipping.evidence == null) shipping.evidence = { ...policy.evidence };
  const originText = policy.origin === 'observed_cart' ? 'observed anonymous cart quote' : 'published rule';
  const appliedText = provenanceRefresh
    ? `Shipping evidence refreshed from validated policy ${policy.id} v${policy.version} (observed ${policy.evidence.retrievedAt}); the rate and its quantity scope are unchanged.`
    : `Shipping rule applied from validated policy ${policy.id} v${policy.version} (${originText}, observed ${policy.evidence.retrievedAt}); confirm at checkout.`;
  shipping.note = [shipping.note, supersededNote, appliedText].filter(Boolean).join(' ');
  return { observation: { ...observation, shipping }, status: 'applied', policy };
}

/** Compact policy status for the public status API; no secrets, no payloads. */
export function policySummary(now = Date.now(), policies = SHIPPING_POLICIES) {
  return policies.map(policy => ({
    id: policy.id,
    version: policy.version,
    vendorId: policy.vendorId,
    origin: policy.origin,
    certainty: policy.certainty,
    service: policy.service ?? null,
    alternatives: (policy.alternatives ?? []).map(alternative => alternative.id),
    freeThreshold: policy.rule?.freeThreshold?.amount ?? null,
    thresholdSemantics: policy.rule?.thresholdSemantics ?? null,
    freeThresholdOrigin: policy.rule?.freeThresholdOrigin ?? null,
    freeCartConditions: (policy.rule?.freeCartConditions ?? []).map(condition => ({
      id: condition.id,
      sku: condition.sku ?? null,
      units: condition.units,
      packCount: condition.packCount,
      orderedGrams: condition.orderedGrams,
      itemSubtotalIls: condition.itemSubtotalIls,
      discountPercent: condition.discountPercent ?? null,
      paidItemTotalIls: condition.paidItemTotalIls,
      service: condition.service,
      observedAt: condition.observedAt
    })),
    observedAt: policy.evidence?.retrievedAt ?? null,
    reviewBy: policy.reviewBy,
    expired: Date.parse(policy.reviewBy) < now
  }));
}

// Pure quote and ranking engine.
//
// Comparison total = item price + shipping + mandatory fees, normalized to ILS.
// Unknown shipping, unknown FX, stale observations, unknown availability and
// out-of-stock observations never become zero and never win.
// Pickup options are kept separate from delivered offers.

import { toIls } from './fx.js';
import { enrichObservationShipping, policySummary, SHIPPING_POLICIES } from './policies.js';
import { resolvePromotion, promotionSummary, PROMOTIONS } from './promotions.js';

export const DEFAULT_STALE_AFTER_MS = 24 * 60 * 60 * 1000;
export const CLOCK_SKEW_MS = 5 * 60 * 1000;

export const DESTINATIONS = [
  { id: 'tel-aviv', label: 'Tel Aviv–Yafo', postcode: '6100000', country: 'IL' },
  { id: 'jerusalem', label: 'Jerusalem', postcode: '9100000', country: 'IL' },
  { id: 'haifa', label: 'Haifa', postcode: '3100000', country: 'IL' },
  { id: 'beer-sheva', label: "Be'er Sheva", postcode: '8400000', country: 'IL' },
  { id: 'eilat', label: 'Eilat', postcode: '8800000', country: 'IL' },
  { id: 'other', label: 'Elsewhere in Israel', postcode: null, country: 'IL' }
];

export function findDestination(id) {
  return DESTINATIONS.find(item => item.id === id) ?? DESTINATIONS[DESTINATIONS.length - 1];
}

const AVAILABILITY_LABELS = {
  in_stock: 'In stock (observed)',
  out_of_stock: 'Out of stock (observed)',
  unknown: 'Availability unknown'
};

/**
 * Plain-language shipping certainty. The board never presents an unknown rate as
 * free, so the label says where the amount came from (or that it is missing)
 * instead of relying on a color or a bare "verified" flag.
 */
const SHIPPING_CERTAINTY_LABELS = {
  verified: 'Published rate (verified)',
  // A rate read from an anonymous public cart/checkout estimator is observed
  // and usable for the recorded cart, but the vendor never published it on the
  // product page, so the label keeps the condition visible instead of calling
  // it a published or completed checkout price.
  checkout_quote: 'Checkout rate (observed, conditional)',
  estimated: 'Estimated rate',
  unknown: 'Not published before checkout'
};

export function shippingCertaintyLabel(certainty) {
  return SHIPPING_CERTAINTY_LABELS[certainty] ?? SHIPPING_CERTAINTY_LABELS.unknown;
}

/**
 * The delivery method a charge buys. This is deliberately separate from the
 * certainty label: a shopper must be able to tell whether ₪30 buys home
 * courier delivery, pickup-point delivery or a distribution-center service,
 * and how well that rate is evidenced.
 */
const SHIPPING_SERVICE_LABELS = {
  home_delivery: 'Home delivery',
  courier: 'Home courier delivery',
  pickup_point: 'Pickup-point delivery',
  distribution_center: 'Distribution-center delivery',
  self_pickup: 'Self-pickup',
  locker: 'Locker delivery'
};

export function shippingServiceLabel(service, mode = 'delivery') {
  if (service && SHIPPING_SERVICE_LABELS[service]) return SHIPPING_SERVICE_LABELS[service];
  return mode === 'pickup' ? SHIPPING_SERVICE_LABELS.self_pickup : 'Delivery method not stated';
}

/**
 * Stable identity of a persisted offer: the vendor plus the listing URL. The
 * observation key before the 2026-10-12 owner correction also contained the
 * blend wording a listing printed, so a wording change could leave two rows for
 * one SKU. Identity deliberately ignores that wording (and the observation
 * time), while distinct listings, pack sizes and multipacks keep distinct URLs
 * and therefore stay separate offers.
 */
export function offerIdentity(observation) {
  const vendorId = observation?.vendor?.id ?? '';
  return `${vendorId}:${observation?.itemUrl ?? observation?.key ?? ''}`;
}

/**
 * Collapse rows that describe the same offer, keeping the most recently
 * observed row (failure markers without an observation time are passed through
 * and dropped by the quoting loop, exactly as before). This is what keeps a
 * legacy blend-keyed row from appearing as a duplicate next to its
 * re-observed replacement in an old persisted store. A row with an unparseable
 * observation time never outranks a row with a real one.
 */
export function dedupeObservations(observations = []) {
  const timeMs = row => {
    const parsed = Date.parse(row?.observedAt ?? '');
    return Number.isFinite(parsed) ? parsed : -Infinity;
  };
  const newest = new Map();
  for (const observation of observations) {
    if (!observation?.observedAt) continue;
    const identity = offerIdentity(observation);
    const current = newest.get(identity);
    if (!current || timeMs(observation) > timeMs(current)) {
      newest.set(identity, observation);
    }
  }
  const seen = new Set();
  const out = [];
  for (const observation of observations) {
    if (!observation?.observedAt) {
      out.push(observation);
      continue;
    }
    const identity = offerIdentity(observation);
    if (seen.has(identity) || newest.get(identity) !== observation) continue;
    seen.add(identity);
    out.push(observation);
  }
  return out;
}

export function quoteBoard({
  observations = [],
  productId,
  targetGrams = 500,
  destination = DESTINATIONS[0],
  fx = null,
  now = Date.now(),
  staleAfterMs = DEFAULT_STALE_AFTER_MS,
  // Validated shipping policies enrich observations whose own shipping is
  // unknown. Pass null to disable (tests of the raw stored evidence).
  policies = SHIPPING_POLICIES,
  // Published quantity promotions (item-price discounts). A parsed row's own
  // `promotions` array wins; the checked-in fallback only covers rows stored
  // before banner parsing. Pass null to disable.
  promotions = PROMOTIONS
} = {}) {
  const grams = clampGrams(targetGrams);
  const quotes = [];
  // Owner correction, 2026-10-12: one listing is one offer. Candidate rows are
  // collapsed by vendor + listing URL, keeping the most recent observation, so a
  // row stored under the old blend-wording key can never appear as a second
  // offer next to its own re-observed row. Different listings, pack sizes and
  // multipacks have different URLs/SKUs and stay separate.
  const candidates = observations.filter(observation =>
    (!productId || observation?.product?.productId === productId)
    && observation?.product?.form === 'ground'
  );
  for (const observation of dedupeObservations(candidates)) {
    // Read-time policy enrichment: an old stored row whose shipping was unknown
    // gains a validated rule without waiting for the next vendor refresh. The
    // observation's own price, stock and observedAt are never touched.
    const enriched = policies === null
      ? observation
      : enrichObservationShipping(observation, { policies, now }).observation;
    quotes.push(quoteOffer(enriched, { grams, destination, fx, now, staleAfterMs, promotions }));
  }
  const ranked = quotes.filter(quote => quote.rankable).sort(compareQuotes);
  // The cheapest delivered total is not always the cheapest bulk value. Keep the
  // per-kilogram winner as separate structured evidence so the board can call it
  // out without changing the ranking itself.
  const bestPerKgQuote = ranked.length
    ? ranked.reduce((min, quote) => (quote.ilsPerKg < min.ilsPerKg ? quote : min))
    : null;
  const pickup = [
    ...quotes.filter(quote => quote.group === 'pickup'),
    ...quotes
      .filter(quote => quote.group !== 'pickup' && quote.shipping?.pickup?.available)
      .map(toPickupEntry)
  ];
  const unrankable = quotes.filter(quote => quote.group === 'unrankable');
  const staleOrUnavailable = quotes.filter(quote => quote.group === 'stale_unavailable');
  const unknown = [...unrankable, ...staleOrUnavailable];
  return {
    productId,
    targetGrams: grams,
    destination,
    generatedAt: new Date(now).toISOString(),
    fx: fx ? { asOf: fx.asOf ?? null, source: fx.source?.name ?? null } : null,
    shippingPolicies: policies === null ? [] : policySummary(now, policies),
    promotions: promotions === null ? [] : promotionSummary(now, promotions),
    best: ranked[0] ?? null,
    bestPerKg: bestPerKgQuote
      ? {
          key: bestPerKgQuote.key,
          vendor: bestPerKgQuote.vendor,
          ilsPerKg: bestPerKgQuote.ilsPerKg,
          totalIls: bestPerKgQuote.totalIls,
          units: bestPerKgQuote.units,
          orderedGrams: bestPerKgQuote.orderedGrams,
          packGrams: bestPerKgQuote.product.packGrams,
          packCount: bestPerKgQuote.product.packCount
        }
      : null,
    ranked,
    pickup,
    unrankable,
    staleOrUnavailable,
    unknown,
    counts: {
      observed: quotes.length,
      ranked: ranked.length,
      pickup: pickup.length,
      unknown: unknown.length
    }
  };
}

export function quoteOffer(observation, { grams, destination, fx, now, staleAfterMs, promotions = PROMOTIONS }) {
  const product = observation.product ?? {};
  const price = observation.price ?? {};
  const shipping = observation.shipping ?? {};
  const reasons = [];
  const labels = [];

  const ageMs = observation.observedAt ? now - Date.parse(observation.observedAt) : null;
  const stale = ageMs == null || ageMs > staleAfterMs || ageMs < -CLOCK_SKEW_MS;
  const freshness = ageMs == null ? 'unknown' : stale ? 'stale' : 'fresh';

  const base = {
    key: observation.key,
    vendor: observation.vendor,
    itemUrl: observation.itemUrl,
    product: {
      productId: product.productId,
      name: product.name ?? null,
      variantId: product.variantId ?? 'unspecified',
      variantLabel: product.variantLabel ?? 'Variant not stated',
      form: product.form,
      packGrams: product.packGrams ?? null,
      packCount: product.packCount ?? 1,
      totalGrams: product.totalGrams ?? null,
      sku: product.sku ?? null
    },
    availability: observation.availability ?? 'unknown',
    availabilityLabel: AVAILABILITY_LABELS[observation.availability] ?? AVAILABILITY_LABELS.unknown,
    freshness,
    ageHours: ageMs == null ? null : Math.round((ageMs / 3_600_000) * 10) / 10,
    observedAt: observation.observedAt ?? null,
    attemptedAt: observation.attemptedAt ?? null,
    // A failed last attempt keeps the previous good price and stock, but the
    // board must be able to say that the most recent check failed instead of
    // presenting the row as freshly re-checked.
    lastError: observation.lastError ?? null,
    lastAttemptFailed: Boolean(observation.lastError),
    evidence: observation.evidence ?? [],
    previous: summarizePrevious(observation.previous),
    priceChange: priceChangeOf({ current: price, previous: observation.previous, product, fx }),
    units: null,
    orderedGrams: null,
    itemPrice: { amount: price.amount ?? null, currency: price.currency ?? null },
    itemTotalIls: null,
    itemSubtotalBeforeDiscountIls: null,
    itemDiscount: null,
    shipping: {
      mode: shipping.mode ?? 'delivery',
      service: shipping.service ?? null,
      serviceLabel: shippingServiceLabel(shipping.service ?? null, shipping.mode ?? 'delivery'),
      certainty: shipping.certainty ?? 'unknown',
      certaintyLabel: shippingCertaintyLabel(shipping.certainty ?? 'unknown'),
      amount: shipping.amount?.amount ?? null,
      currency: shipping.amount?.currency ?? null,
      amountIls: null,
      freeThreshold: shipping.freeThreshold?.amount ?? null,
      freeThresholdCurrency: shipping.freeThreshold?.currency ?? null,
      // The vendor's own wording decides the boundary: "above ₪100" is strictly
      // greater than the threshold, "from/at least ₪100" is greater-or-equal.
      // The default only applies when no wording was recorded.
      freeThresholdSemantics: shipping.freeThresholdSemantics ?? shipping.policy?.thresholdSemantics ?? 'at_least',
      // A threshold is either a published rule or a conditional anonymous-cart
      // observation; the origin and its evidence travel with the amount so the
      // UI never presents an observed free condition as an unconditional rate.
      freeThresholdOrigin: shipping.freeThresholdOrigin ?? shipping.policy?.freeThresholdOrigin ?? null,
      freeThresholdEvidence: shipping.freeThresholdEvidence ?? null,
      // Scoped cart-observed free conditions (for example CoffeeMan's exact
      // anonymous carts). These are matched against the current cart, never
      // applied as a monotone threshold; `freeCondition` is the matched entry.
      freeCartConditions: (shipping.freeCartConditions ?? []).map(condition => ({
        ...condition,
        evidence: condition.evidence ? { ...condition.evidence } : null
      })),
      freeCondition: null,
      minOrder: shipping.minOrder?.amount ?? null,
      minOrderCurrency: shipping.minOrder?.currency ?? null,
      destination: shipping.destination ?? { scope: 'country', country: 'IL' },
      deliveryTime: shipping.deliveryTime ?? null,
      maxTotalGrams: shipping.maxTotalGrams ?? null,
      pickup: shipping.pickup ?? null,
      alternatives: (shipping.alternatives ?? []).map(alternative => {
        const converted = toIls(alternative.amount?.amount ?? null, alternative.amount?.currency ?? price.currency, fx);
        return {
          id: alternative.id ?? null,
          label: alternative.label ?? 'Alternative shipping option',
          amount: alternative.amount?.amount ?? null,
          currency: alternative.amount?.currency ?? price.currency ?? null,
          amountIls: converted.known ? round2(converted.amount) : null,
          note: alternative.note ?? null
        };
      }),
      note: shipping.note ?? null,
      policy: shipping.policy ?? null,
      evidence: shipping.evidence ?? null
    },
    mandatoryFees: [],
    totalIls: null,
    ilsPerKg: null,
    estimate: false,
    rankable: false,
    reasons,
    labels,
    group: 'unrankable'
  };

  if (observation.shipping?.mode === 'pickup') {
    base.group = 'pickup';
    base.labels.push('Pickup only — not a delivered offer');
    if (product.totalGrams) {
      base.units = Math.max(1, Math.ceil(grams / product.totalGrams));
      base.orderedGrams = base.units * product.totalGrams;
    }
    const pickupTotal = toIls(price.amount == null ? null : price.amount * (base.units ?? 1), price.currency, fx);
    if (pickupTotal.known) {
      base.itemTotalIls = round2(pickupTotal.amount);
      base.labels.push('Shown for pickup comparison only');
    }
    if (stale) {
      base.labels.push('Stale observation — the last successful check is too old; treat the item total as out of date');
    }
    return base;
  }

  if (!product.totalGrams || !product.packGrams) {
    reasons.push('Pack weight is not stated, so the delivered price per kilogram cannot be calculated');
    return base;
  }

  const units = Math.max(1, Math.ceil(grams / product.totalGrams));
  base.units = units;
  base.orderedGrams = units * product.totalGrams;

  const itemTotal = toIls(price.amount == null ? null : price.amount * units, price.currency, fx);
  if (!itemTotal.known) {
    reasons.push(price.amount == null
      ? 'Item price was not observed'
      : `No ${price.currency} reference rate is stored, so the total cannot be converted to ILS`);
    if (price.amount != null && Number.isFinite(price.amount)) {
      base.itemPrice.amount = round2(price.amount * units);
    }
    return base;
  }
  base.itemTotalIls = round2(itemTotal.amount);
  if (itemTotal.converted) base.estimate = true;

  // Published quantity promotions reduce the item subtotal of the offer they
  // apply to (for example CoffeeMan's automatic 10% off ground coffee from a
  // ₪250 subtotal). The discount is disclosed on the card and in the offer
  // details; it never changes the base unit price or the observation time. A
  // row parsed without any promotion banner carries `promotions: []` and is
  // never re-enriched from the checked-in fallback.
  const promotion = promotions === null
    ? { status: 'none' }
    : resolvePromotion({
        observation,
        itemSubtotalIls: base.itemTotalIls,
        packCount: product.packCount ?? 1,
        now,
        promotions
      });
  if (promotion.status === 'applied') {
    base.itemSubtotalBeforeDiscountIls = base.itemTotalIls;
    base.itemDiscount = {
      id: promotion.promotion.id,
      percent: promotion.promotion.percent,
      amountIls: promotion.discountIls,
      minItemSubtotal: promotion.promotion.minItemSubtotal?.amount ?? null,
      semantics: promotion.promotion.semantics ?? null,
      excludesMultipacks: Boolean(promotion.promotion.excludesMultipacks),
      wording: promotion.promotion.wording ?? null,
      source: promotion.source,
      evidence: promotion.promotion.evidence ?? null,
      reviewBy: promotion.promotion.reviewBy ?? null
    };
    base.itemTotalIls = round2(base.itemTotalIls - promotion.discountIls);
    base.labels.push(`Published promotion applied: ${promotion.promotion.percent}% off the item subtotal (was ${formatAmount(base.itemSubtotalBeforeDiscountIls, 'ILS')})`);
  }

  // A rate observed on a smaller anonymous cart is not silently stretched to a
  // bigger one: the offer stays visible and unrankable with the exact reason.
  if (shipping.maxTotalGrams != null && base.orderedGrams > shipping.maxTotalGrams) {
    reasons.push(`Shipping was quoted only for carts up to ${shipping.maxTotalGrams} g, but this quantity is ${base.orderedGrams} g`);
    return base;
  }

  if (shipping.minOrder != null) {
    const min = toIls(shipping.minOrder.amount, shipping.minOrder.currency ?? price.currency, fx);
    if (min.known && base.itemTotalIls < min.amount - 0.005) {
      reasons.push(`Order is below the vendor minimum order of ${formatAmount(min.amount, 'ILS')}`);
      return base;
    }
  }

  const coverage = coverageProblem(shipping.destination, destination);
  if (coverage) {
    reasons.push(coverage);
    return base;
  }
  // A published rate whose locality list is not published is a disclosed caveat,
  // not a blocker: the vendor states home delivery is subject to the list, so the
  // board keeps ranking but never claims unconditional coverage of the destination.
  const coverageCaveat = typeof shipping.destination?.caveat === 'string' && shipping.destination.caveat.trim()
    ? shipping.destination.caveat.trim()
    : null;
  if (coverageCaveat) {
    base.shipping.coverageCaveat = coverageCaveat;
    base.labels.push(`Delivery coverage caveat: ${coverageCaveat}`);
  }

  if (observation.availability === 'out_of_stock') {
    base.labels.push('Out of stock at last successful check');
    base.group = 'stale_unavailable';
    return base;
  }
  if (observation.availability !== 'in_stock') {
    reasons.push('Stock was not confirmed by the source, so this offer cannot be confirmed as available');
    base.group = 'stale_unavailable';
    return base;
  }

  const feeSum = { amount: 0, currency: 'ILS' };
  for (const fee of observation.mandatoryFees ?? []) {
    const converted = toIls(fee.amount, fee.currency, fx);
    if (!converted.known) {
      reasons.push(`A mandatory fee (${fee.label ?? 'unlabelled'}) could not be converted to ILS`);
      return base;
    }
    feeSum.amount += converted.amount;
    base.mandatoryFees.push({ label: fee.label ?? 'Mandatory fee', amountIls: round2(converted.amount) });
  }

  let shippingIls = null;
  if (shipping.certainty === 'unknown' || shipping.amount == null) {
    reasons.push(shipping.note
      ? `Shipping is not published before checkout, so it is treated as unknown, not free (${shipping.note})`
      : 'Shipping is not published before checkout, so it is treated as unknown, not free');
    return base;
  }
  const convertedShipping = toIls(shipping.amount.amount ?? shipping.amount, shipping.amount.currency ?? price.currency, fx);
  if (!convertedShipping.known) {
    reasons.push(`Shipping is quoted in ${shipping.amount.currency ?? 'an unknown currency'} with no stored reference rate`);
    return base;
  }
  shippingIls = convertedShipping.amount;
  if (convertedShipping.converted || shipping.certainty === 'estimated') base.estimate = true;

  if (shipping.freeThreshold != null) {
    const threshold = toIls(shipping.freeThreshold.amount, shipping.freeThreshold.currency, fx);
    // "above ₪100" means the ₪100 boundary itself is not free; only a strictly
    // larger item subtotal is. Never silently relax the vendor's wording.
    const semantics = base.shipping.freeThresholdSemantics;
    const met = threshold.known && (semantics === 'above'
      ? base.itemTotalIls > threshold.amount + 0.005
      : base.itemTotalIls >= threshold.amount - 0.005);
    if (met) {
      shippingIls = 0;
      const scope = base.shipping.freeThresholdOrigin === 'observed_cart' ? ', observed in the vendor\u2019s anonymous cart' : '';
      base.labels.push(`Free shipping threshold met (${semantics === 'above' ? 'above' : 'from'} ${formatAmount(threshold.amount, 'ILS')}${scope})`);
    }
  }

  // Scoped cart-observed free conditions: the vendor showed free delivery on
  // exact anonymous carts (listing, whole-pack count, grams and item subtotal),
  // but never published a threshold. Free delivery is applied only when the
  // current cart matches an observed free configuration exactly. A larger or
  // otherwise unobserved cart keeps the published base rate instead of
  // inheriting zero shipping from its subtotal alone.
  const freeConditions = base.shipping.freeCartConditions;
  if (freeConditions.length) {
    const matched = freeConditions.find(condition => freeCartConditionMatches(condition, observation, base));
    if (matched) {
      shippingIls = 0;
      base.shipping.freeCondition = {
        id: matched.id,
        units: matched.units ?? null,
        packCount: matched.packCount ?? null,
        orderedGrams: matched.orderedGrams ?? null,
        itemSubtotalIls: matched.itemSubtotalIls ?? null,
        discountPercent: matched.discountPercent ?? null,
        paidItemTotalIls: matched.paidItemTotalIls ?? null,
        methodLabel: matched.methodLabel ?? 'delivery',
        observedAt: matched.observedAt ?? null,
        evidence: matched.evidence ?? null
      };
      base.labels.push(`Free ${matched.methodLabel ?? 'delivery'} observed for this exact cart (${freeConditionCartLabel(matched)}) in the vendor's anonymous cart`);
    } else {
      const minObserved = freeConditions
        .map(condition => condition.itemSubtotalIls)
        .filter(amount => Number.isFinite(amount))
        .reduce((min, amount) => (min == null || amount < min ? amount : min), null);
      base.shipping.freeConditionUnmatched = true;
      base.shipping.freeConditionNote = `The vendor's anonymous cart showed free ${freeConditions[0].methodLabel ?? 'delivery'} only on ${freeConditions.map(freeConditionCartLabel).join(', ')}; this cart keeps the published ${formatAmount(shippingIls, 'ILS')} base rate.`;
      // Only surprise the shopper when the cart is at or above an observed free
      // subtotal yet still unverified: then the base fee is visibly conditional.
      if (minObserved != null && base.itemTotalIls >= minObserved - 0.005) {
        base.shipping.freeConditionUnmatchedAboveMin = true;
        base.labels.push('Free delivery was observed only on specific carts; this unobserved cart keeps the published base rate');
      }
    }
  }

  base.shipping.amountIls = round2(shippingIls);
  if (stale) {
    labels.push('Stale observation — the last successful check is too old to rank');
    base.group = 'stale_unavailable';
    return base;
  }

  base.totalIls = round2(base.itemTotalIls + shippingIls + feeSum.amount);
  base.ilsPerKg = round2((base.totalIls / base.orderedGrams) * 1000);
  base.rankable = true;
  base.group = 'ranked';
  if (base.estimate) labels.push('Estimate — includes a converted or estimated component');
  return base;
}

/** Shape the stored previous-check snapshot for the API without leaking raw payloads. */
function summarizePrevious(previous) {
  if (!previous || typeof previous !== 'object') return null;
  const availability = previous.availability ?? 'unknown';
  return {
    observedAt: previous.observedAt ?? null,
    priceAmount: previous.price?.amount ?? null,
    priceCurrency: previous.price?.currency ?? null,
    availability,
    availabilityLabel: AVAILABILITY_LABELS[availability] ?? AVAILABILITY_LABELS.unknown
  };
}

/**
 * Compare the unit price with the previous successful check.
 * The comparison is in ILS using the stored Bank of Israel rate when needed, is
 * only made between equal pack weights, and is never reported as "no change"
 * when a conversion is impossible.
 */
function priceChangeOf({ current, previous, product, fx }) {
  const previousPrice = previous?.price;
  if (!previous?.observedAt || previousPrice?.amount == null || current?.amount == null) return null;
  const previousObservedAt = previous.observedAt;
  const previousAmount = previousPrice.amount;
  const previousCurrency = previousPrice.currency ?? current.currency ?? null;
  if (previous.totalGrams != null && product.totalGrams != null && previous.totalGrams !== product.totalGrams) {
    return {
      comparable: false,
      reason: 'the pack size changed since the previous check, so the unit prices are not comparable',
      previousObservedAt,
      previousAmount,
      previousCurrency
    };
  }
  const before = toIls(previousAmount, previousCurrency, fx);
  const after = toIls(current.amount, current.currency ?? previousCurrency, fx);
  if (!before.known || !after.known) {
    return {
      comparable: false,
      reason: 'a stored exchange rate is needed to compare the previous price',
      previousObservedAt,
      previousAmount,
      previousCurrency
    };
  }
  const delta = round2(after.amount - before.amount);
  return {
    comparable: true,
    direction: delta < 0 ? 'down' : delta > 0 ? 'up' : 'same',
    deltaIls: Math.abs(delta),
    previousAmount,
    previousCurrency,
    previousIls: round2(before.amount),
    previousObservedAt
  };
}

function coverageProblem(shippingDestination, destination) {
  if (!shippingDestination) return null;
  if (shippingDestination.scope === 'country') {
    if (destination?.country && shippingDestination.country !== destination.country) {
      return `Vendor does not deliver to ${destination.country}`;
    }
    return null;
  }
  if (shippingDestination.scope === 'localities') {
    const localities = shippingDestination.localities ?? [];
    if (!destination?.id || !localities.includes(destination.id)) {
      return `Vendor delivery list does not include ${destination?.label ?? 'this destination'}`;
    }
    return null;
  }
  return 'Vendor delivery coverage is not documented';
}

function toPickupEntry(quote) {
  const itemTotal = quote.itemTotalIls ?? (quote.itemPrice.amount != null && quote.units
    ? round2(quote.itemPrice.amount * quote.units)
    : null);
  return {
    ...quote,
    key: `${quote.key}:pickup`,
    group: 'pickup',
    rankable: false,
    totalIls: null,
    ilsPerKg: null,
    itemTotalIls: itemTotal,
    pickup: {
      available: true,
      amount: quote.shipping.pickup?.amount ?? null,
      note: quote.shipping.pickup?.note ?? null
    },
    labels: [...quote.labels.filter(label => !label.startsWith('Delivery coverage caveat:')), 'Pickup only — not a delivered offer']
  };
}

/**
 * Does the current cart match one observed-free cart configuration exactly?
 * The listing scope, whole-pack count, ordered grams and item subtotal (before
 * any applied discount, falling back to the paid total when no discount
 * applies) must all agree, so an unobserved larger cart can never inherit free
 * delivery from its subtotal alone.
 */
export function freeCartConditionMatches(condition, observation, quote) {
  if (!condition) return false;
  if (condition.itemUrlPrefix && !String(observation?.itemUrl ?? '').startsWith(condition.itemUrlPrefix)) return false;
  if (condition.service && quote?.shipping?.service && condition.service !== quote.shipping.service) return false;
  if (condition.sku && quote?.product?.sku && condition.sku !== quote.product.sku) return false;
  if (condition.packCount != null && (quote?.product?.packCount ?? 1) !== condition.packCount) return false;
  if (condition.units != null && quote?.units !== condition.units) return false;
  if (condition.orderedGrams != null && quote?.orderedGrams !== condition.orderedGrams) return false;
  if (condition.itemSubtotalIls != null) {
    const observedSubtotal = quote?.itemSubtotalBeforeDiscountIls ?? quote?.itemTotalIls;
    if (!Number.isFinite(observedSubtotal) || Math.abs(observedSubtotal - condition.itemSubtotalIls) > 0.005) return false;
  }
  return true;
}

/** Plain-language label for one observed-free cart configuration. */
export function freeConditionCartLabel(condition) {
  const packs = Number.isFinite(condition?.packCount) && condition.packCount > 1
    ? `${condition.units} × ${condition.packCount} × 250 g multipack${condition.units === 1 ? '' : 's'}`
    : `${condition?.units ?? '?'} × 250 g`;
  const grams = Number.isFinite(condition?.orderedGrams) ? ` = ${condition.orderedGrams} g` : '';
  const subtotal = Number.isFinite(condition?.itemSubtotalIls) ? `, ${formatAmount(condition.itemSubtotalIls, 'ILS')} item subtotal` : '';
  return `${packs}${grams}${subtotal}`;
}

function compareQuotes(a, b) {
  if (a.totalIls !== b.totalIls) return a.totalIls - b.totalIls;
  if (a.ilsPerKg !== b.ilsPerKg) return a.ilsPerKg - b.ilsPerKg;
  return String(a.vendor?.name ?? '').localeCompare(String(b.vendor?.name ?? ''));
}

export function clampGrams(value) {
  const grams = Number(value);
  if (!Number.isFinite(grams) || grams <= 0) return 500;
  return Math.min(Math.max(Math.round(grams), 1), 100_000);
}

export function formatAmount(amount, currency = 'ILS') {
  const symbols = { ILS: '₪', USD: '$', EUR: '€', GBP: '£' };
  const symbol = symbols[String(currency).toUpperCase()] ?? `${currency} `;
  return `${symbol}${Number(amount).toFixed(2)}`;
}

function round2(value) {
  return Math.round(value * 100) / 100;
}

// Reusable browser-research workflow (research/development tooling only).
//
// The interactive helper in scripts/browser-research.mjs keeps one real Chrome
// session alive; this module turns that session into a repeatable per-vendor
// recipe run:
//
//   - a recipe is vendor-specific navigation data: where the tracked listing is,
//     how to add whole packs to an anonymous cart, how to reach the public
//     estimator and which locality/postcode fields are permitted;
//   - the runner executes the steps, waits for recalculation and extracts the
//     displayed item subtotal, shipping line and final total;
//   - every run produces one record in the same evidence schema, whether it
//     ended in a quote, a public-flow blocker or a failure. Blocker records keep
//     the exact step and the rendered excerpt that stopped the flow.
//
// Evidence records are sanitized: URLs lose query strings/fragments (cart and
// session ids live there) and excerpts are collapsed and capped. The output is
// development evidence for human review; it is never imported by the Worker at
// runtime and never applied to the board automatically. A validated record can
// be promoted into a versioned policy in src/lib/policies.js by hand.

export const EVIDENCE_SCHEMA_VERSION = 1;

