const CURRENCY_PATTERN = /^[A-Z]{3}$/;

/** Validate one policy's shape. Returns { ok, errors } without throwing. */
export function validatePolicy(policy) {
  const errors = [];
  if (!policy || typeof policy !== 'object') return { ok: false, errors: ['policy is not an object'] };
  if (!policy.id || typeof policy.id !== 'string') errors.push('id is required');
  if (!Number.isInteger(policy.version) || policy.version < 1) errors.push('version must be a positive integer');
  if (!policy.vendorId) errors.push('vendorId is required');
  if (!Array.isArray(policy.productIds) || policy.productIds.length === 0) errors.push('productIds must be a non-empty array');
  if (policy.service != null && typeof policy.service !== 'string') errors.push('service must be a string when present');
  if (!['observed_cart', 'published'].includes(policy.origin)) errors.push('origin must be "observed_cart" or "published"');
  if (!['verified', 'checkout_quote', 'estimated'].includes(policy.certainty)) errors.push('certainty must be verified, checkout_quote or estimated');
  const amount = policy.rule?.amount;
  if (!amount || !Number.isFinite(amount.amount) || !CURRENCY_PATTERN.test(String(amount.currency ?? ''))) {
    errors.push('rule.amount must carry a numeric amount and a 3-letter currency');
  }
  const threshold = policy.rule?.freeThreshold;
  if (threshold != null && (!Number.isFinite(threshold.amount) || !CURRENCY_PATTERN.test(String(threshold.currency ?? '')))) {
    errors.push('rule.freeThreshold must carry a numeric amount and a 3-letter currency when present');
  }
  if (threshold != null && !['above', 'at_least'].includes(policy.rule?.thresholdSemantics)) {
    errors.push('rule.thresholdSemantics must be "above" or "at_least" when a free threshold is present');
  }
  const thresholdOrigin = policy.rule?.freeThresholdOrigin;
  if (thresholdOrigin != null && !['published', 'observed_cart'].includes(thresholdOrigin)) {
    errors.push('rule.freeThresholdOrigin must be "published" or "observed_cart" when present');
  }
  if (thresholdOrigin != null && threshold == null) {
    errors.push('rule.freeThresholdOrigin needs a freeThreshold');
  }
  if (thresholdOrigin === 'observed_cart' && (!policy.rule?.freeThresholdEvidence?.url || !policy.rule?.freeThresholdEvidence?.retrievedAt)) {
    errors.push('an observed_cart free threshold needs freeThresholdEvidence.url and .retrievedAt');
  }
  // Scoped cart-observed free conditions: the exact cart a vendor showed free,
  // with its listing scope, whole-pack count, ordered grams, subtotal and method.
  // A threshold and scoped conditions are mutually exclusive so a rule cannot
  // silently become a monotone threshold again.
  const freeCartConditions = policy.rule?.freeCartConditions;
  if (freeCartConditions != null) {
    if (!Array.isArray(freeCartConditions) || freeCartConditions.length === 0) {
      errors.push('rule.freeCartConditions must be a non-empty array when present');
    } else if (threshold != null) {
      errors.push('rule.freeThreshold and rule.freeCartConditions cannot both be present');
    } else {
      freeCartConditions.forEach((condition, index) => {
        const at = `rule.freeCartConditions[${index}]`;
        if (!condition || typeof condition !== 'object') { errors.push(`${at} is not an object`); return; }
        if (!condition.id || typeof condition.id !== 'string') errors.push(`${at}.id is required`);
        if (!condition.service || typeof condition.service !== 'string') errors.push(`${at}.service is required`);
        if (condition.sku != null && typeof condition.sku !== 'string') errors.push(`${at}.sku must be a string when present`);
        if (!condition.itemUrlPrefix || typeof condition.itemUrlPrefix !== 'string') errors.push(`${at}.itemUrlPrefix is required`);
        if (!Number.isInteger(condition.packCount) || condition.packCount < 1) errors.push(`${at}.packCount must be a positive integer`);
        if (!Number.isInteger(condition.units) || condition.units < 1) errors.push(`${at}.units must be a positive integer`);
        if (!Number.isFinite(condition.orderedGrams) || condition.orderedGrams <= 0) errors.push(`${at}.orderedGrams must be a positive number`);
        if (!Number.isFinite(condition.itemSubtotalIls)) errors.push(`${at}.itemSubtotalIls must be a number`);

// Home product index.
//
// The canonical home route shows the tracked catalog as cards, not the vendor
// comparison board. Each card links to the product's own directly loadable page
// (`/product/<id>`). A legacy board link that still carries product/quantity/
// destination query state — including an obsolete variant parameter — is
// forwarded to the product page with that state intact, so old shared URLs keep
// working and a retired product id can still be reported as a fallback instead
// of being silently dropped. The product page ignores the obsolete variant
// parameter and always shows the one unified comparison.

import { el, timeLabel, bidi } from './ui.js';

const params = new URLSearchParams(location.search);
const LEGACY_KEYS = ['product', 'grams', 'dest', 'variant', 'unknown'];
const isLegacyBoardLink = LEGACY_KEYS.some(key => params.has(key));

const list = document.getElementById('catalog-list');
const footer = document.getElementById('footer-status');

async function main() {
  let catalog = null;
  try {
    catalog = await fetch('/api/catalog').then(response => response.json());
  } catch (error) {
    renderError(`The product index could not be loaded (${error?.message ?? error}). The stored observations are safe; try again in a moment.`);
    return;
  }
  const products = catalog?.products ?? [];
  if (!products.length) {
    renderError('No tracked product is configured on this deployment.');
    return;
  }
  if (isLegacyBoardLink) {
    // Keep the old selection state (including a retired product request) in the
    // forwarded URL, but drop the obsolete variant parameter: the product page
    // resolves the request against the tracked catalog and shows one unified
    // comparison. Quantity and locality are preserved.
    const forwarded = new URLSearchParams(params);
    forwarded.delete('variant');
    const query = forwarded.toString();
    const target = `/product/${encodeURIComponent(products[0].id)}${query ? `?${query}` : ''}`;
    location.replace(target);
    return;
  }
  renderCatalog(products, catalog.vendors ?? []);
  renderFooterStatus();
}

function renderCatalog(products, vendors) {
  list.replaceChildren();
  for (const product of products) {
    list.append(productCard(product, vendors));
  }
}

function productCard(product, vendors) {
  const vendorCount = vendors.length;
  const listingCount = vendors.reduce((sum, vendor) => sum + (vendor.offers?.length ?? 0), 0);
  const vendorNames = vendors.map(vendor => vendor.name).filter(Boolean);
  // Concise index card: identity, packaging and where the offers come from.
  // The comparison workflow and its caveats live on the product page, not here.
  const card = el('article', { class: 'product-card' },
    el('p', { class: 'product-card__brand', text: product.brand }),
    el('h2', { class: 'product-card__name' }, bidi(`${product.brand} ${product.line}`)),
    el('p', { class: 'product-card__meta', text: `${product.form} coffee · ${product.packaging} · 250 g packs and multipacks` }),
    el('p', { class: 'product-card__summary', text: `${vendorCount} vendor${vendorCount === 1 ? '' : 's'} · ${listingCount} listing${listingCount === 1 ? '' : 's'}${vendorNames.length ? `: ${vendorNames.join(', ')}` : ''}` }),
    el('p', { class: 'product-card__action' },
      el('a', { class: 'product-card__link', href: `/product/${encodeURIComponent(product.id)}`, text: 'Compare delivered offers' })));
  return card;
}

async function renderFooterStatus() {
  if (!footer) return;
  try {
    const status = await fetch('/api/status').then(response => response.json());
    const observed = status?.lastObservationAt ?? status?.freshness?.lastObservationAt ?? null;
    footer.textContent = observed
      ? `Tracked offers last checked ${timeLabel(observed)}.`
      : 'No offer observation is stored yet; the first scheduled refresh will populate the board.';
  } catch {
    footer.textContent = 'Observation time is unavailable right now.';
  }
}

function renderError(message) {
  list.replaceChildren(el('div', { class: 'empty' }, el('strong', { text: 'The product index could not be loaded.' }), el('p', { text: message })));
}

main();

// Shared rendering helpers for the home product index and the product page.
//
// All vendor text is inserted as text: fetched pages are untrusted data. `el()`
// accepts a DOM node for `text` (used by `bidi()`, which wraps Hebrew runs in a
// dir="auto" span) and appends it instead of stringifying it — a Node assigned
// to textContent would render as "[object HTMLSpanElement]".
//
// There is no blend/variant selector: raw vendor listing wording and any stated
// blend wording are provenance shown inside offer details, never a filter.

export const ILS = new Intl.NumberFormat('en-IL', { style: 'currency', currency: 'ILS', maximumFractionDigits: 2 });
export const IL_TIME = new Intl.DateTimeFormat('en-GB', {
  timeZone: 'Asia/Jerusalem', dateStyle: 'medium', timeStyle: 'short'
});

export function el(tag, props = {}, ...children) {
  const node = document.createElement(tag);
  for (const [key, value] of Object.entries(props)) {
    if (value == null) continue;
    if (key === 'class') node.className = value;
    else if (key === 'text') {
      // A Node (for example the dir="auto" wrapper built by bidi()) must be
      // appended as a child; assigning it to textContent would print
      // "[object HTMLSpanElement]".
      if (value instanceof Node) node.append(value);
      else node.textContent = String(value);
    }
    else if (key === 'dataset') Object.assign(node.dataset, value);
    else if (key.startsWith('on')) node.addEventListener(key.slice(2).toLowerCase(), value);
    else if (key === 'attrs') for (const [a, v] of Object.entries(value)) node.setAttribute(a, v);
    else node[key] = value;
  }
  for (const child of children.flat()) {
    if (child == null) continue;
    node.append(child instanceof Node ? child : document.createTextNode(String(child)));
  }
  return node;
}

export function money(amount) {
  return amount == null ? null : ILS.format(amount);
}

/** Short single-line text for cards; never a raw payload. */
export function truncate(text, max = 120) {
  const value = String(text ?? '').replace(/\s+/g, ' ').trim();
  return value.length > max ? `${value.slice(0, max - 1)}…` : value;
}

const HEBREW = /[\u0590-\u05FF]/;

/** Wrap Hebrew-containing text in an isolated dir="auto" span for mixed IL/Latin names. */
export function bidi(text) {
  const value = text == null ? '' : String(text);
  if (!HEBREW.test(value)) return value;
  return el('span', { class: 'bidi', attrs: { dir: 'auto', lang: 'he' }, text: value });
}

export function timeLabel(iso) {
  if (!iso) return 'never';
  const date = new Date(iso);
  if (Number.isNaN(date.getTime())) return 'unknown time';
  const hours = (Date.now() - date.getTime()) / 3_600_000;
  // A timestamp that is actually in the future must never read "just now":
  // policy review dates and vendor next-attempt times are due times, and a
  // shopper needs to see that they are still ahead.
  const relative = hours < 0
    ? (hours > -48 ? `in ${Math.max(1, Math.round(-hours))} h` : `in ${Math.round(-hours / 24)} d`)
    : hours < 0.1 ? 'just now' : hours < 1 ? `${Math.round(hours * 60)} min ago` : hours < 48 ? `${Math.round(hours)} h ago` : `${Math.round(hours / 24)} d ago`;
  return `${IL_TIME.format(date)} (${relative})`;
}

/** Format a future due time. Vendor nextAttemptAt is a due time, not a promise, so the copy says so. */
export function dueLabel(iso) {
  if (!iso) return 'not scheduled';
  const date = new Date(iso);
  if (Number.isNaN(date.getTime())) return 'unknown time';
  const hours = (date.getTime() - Date.now()) / 3_600_000;
  const relative = hours <= 0 ? 'due now' : hours < 1 ? `in ${Math.round(hours * 60)} min` : hours < 48 ? `in ${Math.round(hours)} h` : `in ${Math.round(hours / 24)} d`;
  return `${IL_TIME.format(date)} (${relative})`;
}

