/** Full promotion line for the offer details, including the vendor's own wording. */
export function promotionDetailText(quote) {
  const discount = quote?.itemDiscount;
  if (!discount) return null;
  const from = discount.minItemSubtotal != null ? ` from ${money(discount.minItemSubtotal)} item subtotal` : '';
  const scope = discount.excludesMultipacks ? 'multipacks excluded' : 'all packs';
  const source = discount.source === 'policy' ? ', applied from the validated published-rule fallback' : '';
  const wording = discount.wording ? ` Vendor wording: “${discount.wording}”` : '';
  return `Published promotion: ${discount.percent}% off${from} (${scope}${source}).${wording}`;
}

export function shippingValueText(quote) {
  const shipping = quote.shipping ?? {};
  if (shipping.amountIls != null) {
    if (shipping.amountIls === 0) {
      if (shipping.freeCondition) return 'Free (observed for this cart)';
      return shipping.freeThreshold != null ? 'Free (threshold met)' : 'Free';
    }
    return money(shipping.amountIls);
  }
  if (shipping.amount != null) return `${money(shipping.amount)} ${shipping.currency ?? ''} (not converted)`.trim();
  return 'Shipping not published';
}

/**
 * The delivery method a charge buys, separate from how certain the evidence is.
 * Falls back to the shipping mode; an unknown method says so instead of showing
 * the certainty label in its place.
 */
export function shippingMethodLabel(quote) {
  const shipping = quote.shipping ?? {};
  if (shipping.serviceLabel) return shipping.serviceLabel;
  return shipping.mode === 'pickup' ? 'Self-pickup' : 'Delivery method not stated';
}

export function shippingCertaintyText(quote) {
  const label = quote.shipping?.certaintyLabel ?? 'Not published before checkout';
  // A published base rate can carry a cart-observed free condition. The free
  // application is conditional, so it must not read as part of the verified
  // rate; the written qualifier on the card explains it in full.
  if (quote.shipping?.freeCondition) {
    return `${label} · free condition cart-observed`;
  }
  if (quote.shipping?.freeThresholdOrigin === 'observed_cart' && quote.shipping?.amountIls === 0) {
    return `${label} · free condition cart-observed`;
  }
  return label;
}

/**
 * Short visible card-face warning when the most recent vendor check failed. The
 * offer still ranks its last successful observation, but the price and stock may
 * be out of date, so the shopper must see that before trusting the total. The
 * attempt time and error stay in the offer details.
 */
export function failedCheckNote(quote) {
  if (!quote?.lastAttemptFailed) return null;
  return 'Last check failed — showing the last successful observation.';
}

export function statusBadge(status, label) {
  const kind = status === 'in_stock' ? 'in_stock' : status === 'out_of_stock' ? 'out_of_stock' : 'unknown';
  return el('span', { class: `status status--${kind}`, text: label });
}

export function offerLink(quote, label = 'Open the vendor page') {
  return el('a', { href: quote.itemUrl, rel: 'noopener noreferrer nofollow', target: '_blank', text: label });
}

/** Item subtotal, named shipping method/charge and delivered total stay together. */
export function totalsBlock(quote, { perKg = true } = {}) {
  return el('div', { class: 'totals' },
    el('div', { class: 'totals__cell' },
      el('span', { class: 'totals__label', text: 'Item subtotal' }),
      el('span', { class: 'totals__value num', text: itemSubtotalText(quote) }),
      el('span', { class: 'totals__meta totals__meta--discount', text: itemDiscountText(quote) })),
    el('div', { class: 'totals__cell' },
      el('span', { class: 'totals__label', text: 'Shipping' }),
      el('span', { class: 'totals__value num', text: shippingValueText(quote) }),
      el('span', { class: 'totals__meta totals__meta--method', text: shippingMethodLabel(quote) }),
      el('span', { class: 'totals__meta totals__meta--certainty', text: shippingCertaintyText(quote) })),
    el('div', { class: 'totals__cell totals__cell--total' },
      el('span', { class: 'totals__label', text: 'Delivered total' }),
      el('span', { class: 'totals__value num', text: quote.totalIls != null ? money(quote.totalIls) : 'Not calculable' }),
      perKg && quote.ilsPerKg != null ? el('span', { class: 'totals__meta num', text: `${money(quote.ilsPerKg)} per kg` }) : null));
}

/**
 * Plain-language price comparison against the previous successful check of the
 * same offer. Rendered as text only when the quote actually carries previous
 * evidence; an impossible comparison says why instead of claiming "no change".
 */
export function priceChangeText(quote) {
  const change = quote?.priceChange;
  if (!change) return null;
  const when = timeLabel(change.previousObservedAt);
  if (!change.comparable) return `Previous price not compared: ${change.reason} (previous check ${when})`;
  if (change.direction === 'same') return `Unit price unchanged since the previous check (${when})`;
  return `Unit price ${change.direction === 'down' ? 'down' : 'up'} ${money(change.deltaIls)} since the previous check (${when})`;
}

export function stockChangeText(quote) {
  const previous = quote?.previous;
  if (!previous || previous.availability === quote.availability) return null;
  return `Stock changed since the previous check: was ${previous.availabilityLabel ?? previous.availability}`;
}

/** Plain-language description of one observed-free cart configuration. */
export function freeConditionText(condition) {
  if (!condition) return 'unrecorded cart';
  const packs = (condition.packCount ?? 1) > 1
    ? `${condition.units ?? '?'} × ${condition.packCount} × 250 g multipack${condition.units === 1 ? '' : 's'}`
    : `${condition.units ?? '?'} × 250 g pack${condition.units === 1 ? '' : 's'}`;
  const grams = condition.orderedGrams != null ? ` = ${condition.orderedGrams} g` : '';
  const subtotal = condition.itemSubtotalIls != null ? `, ${money(condition.itemSubtotalIls)} item subtotal` : '';
  const discount = condition.discountPercent ? ` before the ${condition.discountPercent}% quantity discount` : '';
  return `${packs}${grams}${subtotal}${discount}`;
}

/** Short conditions shown on a card face; the full list goes in a details block. */
export function conditionsList(quote, destinationLabelFn = id => id) {
  const shipping = quote.shipping ?? {};
  const items = [];
  if (shipping.freeThreshold != null) {
    const wording = shipping.freeThresholdSemantics === 'above' ? 'above' : 'from';
    const observed = shipping.freeThresholdOrigin === 'observed_cart';
    const met = quote.itemTotalIls != null && (shipping.freeThresholdSemantics === 'above'
      ? quote.itemTotalIls > shipping.freeThreshold + 0.005
      : quote.itemTotalIls >= shipping.freeThreshold - 0.005);
    if (met) {
      items.push(observed
        ? `Free-shipping threshold met (observed ${wording} ${money(shipping.freeThreshold)} in the vendor's anonymous cart)`
        : `Free-shipping threshold met (${wording} ${money(shipping.freeThreshold)})`);
    } else {
      items.push(observed
        ? `Free shipping ${wording} ${money(shipping.freeThreshold)} item subtotal (observed in the vendor's anonymous cart, not published)`
        : `Free shipping ${wording} ${money(shipping.freeThreshold)} item subtotal`);
    }
  }
  // Scoped cart-observed free conditions: name the exact carts the vendor
  // showed free, so a shopper can see why this cart did (or did not) match one
  // instead of reading a threshold the vendor never published.
  const freeConditions = shipping.freeCartConditions ?? [];
  if (freeConditions.length) {
    const observedCarts = freeConditions.map(condition => freeConditionText(condition)).join('; ');
    if (shipping.freeCondition) {
      items.push(`Free ${shipping.freeCondition.methodLabel ?? 'delivery'} observed for this exact cart (${freeConditionText(shipping.freeCondition)}) in the vendor's anonymous cart`);
    } else {
      items.push(`Free ${freeConditions[0].methodLabel ?? 'delivery'} was observed only on these exact carts: ${observedCarts}. Other cart sizes keep the published base rate.`);
    }
  }
  if (shipping.minOrder != null) items.push(`Minimum order ${money(shipping.minOrder)}`);
  const coverage = shipping.destination;
  if (coverage?.scope === 'localities') {
    const names = (coverage.localities ?? []).map(destinationLabelFn);
    items.push(names.length ? `Delivery area: only ${names.join(', ')}` : 'Delivery area: restricted locality list not published');
  }
  for (const alternative of shipping.alternatives ?? []) {
    items.push(`${alternative.label}: ${alternative.amountIls != null ? money(alternative.amountIls) : 'rate not published'}`);
  }
  if (shipping.pickup?.available) items.push(shipping.pickup.note ? `Self-pickup: ${shipping.pickup.note}` : 'Free self-pickup available (kept separate from delivery)');
  if (shipping.deliveryTime) items.push(`Delivery time: ${shipping.deliveryTime}`);
  if (shipping.maxTotalGrams != null) items.push(`Rate quoted for carts up to ${shipping.maxTotalGrams} g`);
  if (!items.length) return null;
  const list = el('ul', { class: 'conditions' });
  for (const item of items) list.append(el('li', {}, bidi(item)));
  return list;
}

export function caveatBlock(quote) {
  if (!quote.shipping?.coverageCaveat) return null;
  return el('p', { class: 'caveat' }, el('strong', { text: 'Coverage: ' }), bidi(quote.shipping.coverageCaveat));
}

/** A one-line amber qualification shown next to a conditional total. */
export function coverageQualifier(quote) {
  const shipping = quote.shipping ?? {};
  const parts = [];
  // An observed free condition changes the money on the card, so it is stated
  // first even when the offer also carries a coverage caveat.
  if (shipping.freeCondition) {
    parts.push('Free delivery applied from an anonymous-cart observation of this exact cart; confirm it at checkout.');
  } else if (shipping.freeConditionUnmatchedAboveMin) {
    parts.push('Free delivery was observed only on specific carts; this unobserved cart keeps the published base rate.');
  } else if (shipping.freeThresholdOrigin === 'observed_cart' && shipping.amountIls === 0) {
    parts.push('Free delivery applied from an anonymous-cart observation; confirm it at checkout.');
  }
  if (shipping.coverageCaveat) parts.push('Coverage not confirmed for every locality — full terms under Delivery options.');
  else if (shipping.certainty === 'checkout_quote') parts.push('Rate observed in an anonymous cart; confirm the destination at checkout.');
  else if (shipping.certainty === 'estimated') parts.push('Includes a converted or estimated component.');
  else if (shipping.certainty === 'unknown') parts.push('Shipping not published: a delivered total cannot be established yet.');
  return parts.length ? parts.join(' ') : null;
}

/** Previous-check, failure and evidence provenance, collapsed behind a disclosure. */
export function diagnosticsDisclosure(quote) {
  const rows = [];
  const change = priceChangeText(quote);
  if (change) rows.push(change);
  const stockChange = stockChangeText(quote);
  if (stockChange) rows.push(stockChange);
  const promotion = promotionDetailText(quote);
  if (promotion) rows.push(promotion);
  if (quote.itemDiscount?.evidence?.url) {
    rows.push(`Promotion evidence: ${quote.itemDiscount.evidence.url}${quote.itemDiscount.evidence.retrievedAt ? ` (retrieved ${timeLabel(quote.itemDiscount.evidence.retrievedAt)})` : ''}`);
  }
  rows.push(`Last successful check: ${timeLabel(quote.observedAt)}`);
  if (quote.product?.name) rows.push(`Vendor listing name: ${quote.product.name}`);
  if (quote.product?.variantId && quote.product.variantId !== 'unspecified' && quote.product.variantLabel) {
    rows.push(`Stated blend wording: ${quote.product.variantLabel}`);
  }
  if (quote.lastAttemptFailed) rows.push(`Last attempt failed ${timeLabel(quote.attemptedAt)}${quote.lastError ? ` — ${truncate(quote.lastError)}` : ''}`);
  const policy = quote.shipping?.policy;
  if (policy) {
    rows.push(`Shipping rule: ${policy.id} v${policy.version} (${policy.origin === 'observed_cart' ? 'observed anonymous cart quote' : 'published rule'}, observed ${timeLabel(policy.retrievedAt)}, re-check by ${dueLabel(policy.reviewBy)})`);
  }
  const thresholdEvidence = quote.shipping?.freeThresholdEvidence;
  if (quote.shipping?.freeThreshold != null && quote.shipping.freeThresholdOrigin === 'observed_cart') {
    const wording = quote.shipping.freeThresholdSemantics === 'above' ? 'above' : 'from';
    rows.push(`Free-shipping condition: observed ${wording} ${money(quote.shipping.freeThreshold)} item subtotal in the vendor's anonymous cart${thresholdEvidence?.retrievedAt ? ` (retrieved ${timeLabel(thresholdEvidence.retrievedAt)})` : ''}; the product page does not publish this threshold.`);
  }
  const freeConditions = quote.shipping?.freeCartConditions ?? [];
  if (freeConditions.length) {
    if (quote.shipping.freeCondition) {
      rows.push(`Free-delivery condition: the vendor's anonymous cart showed free ${quote.shipping.freeCondition.methodLabel ?? 'delivery'} on exactly this cart (${freeConditionText(quote.shipping.freeCondition)}${quote.shipping.freeCondition.observedAt ? `, observed ${timeLabel(quote.shipping.freeCondition.observedAt)}` : ''}).`);
    } else {
      rows.push(`Free-delivery conditions: the vendor's anonymous cart showed free delivery only on ${freeConditions.map(condition => freeConditionText(condition)).join('; ')}. No threshold is published, so a cart that matches none of them keeps the base rate${quote.shipping.freeConditionUnmatchedAboveMin ? ' (this cart is at or above an observed free subtotal but was not itself observed free)' : ''}.`);
    }
  }
  if (quote.shipping?.note) rows.push(`Shipping terms: ${quote.shipping.note}`);
  const evidence = quote.shipping?.evidence;
  if (evidence?.url) {
    rows.push(`Shipping evidence: ${evidence.url}${evidence.retrievedAt ? ` (retrieved ${timeLabel(evidence.retrievedAt)})` : ''}${evidence.note ? ` — ${truncate(evidence.note, 160)}` : ''}`);
  }
  const body = el('div', { class: 'disclosure__body' });
  for (const row of rows) body.append(el('div', {}, bidi(row)));
  return el('details', { class: 'disclosure disclosure--diagnostics' }, el('summary', { text: 'Offer details and check history' }), body);
}

        if (!Number.isFinite(condition.itemSubtotalIls)) errors.push(`${at}.itemSubtotalIls must be a number`);
        if (condition.discountPercent != null && (!Number.isFinite(condition.discountPercent) || condition.discountPercent <= 0 || condition.discountPercent > 90)) {
          errors.push(`${at}.discountPercent must be between 0 and 90 when present`);
        }
        if (!Number.isFinite(condition.paidItemTotalIls)) errors.push(`${at}.paidItemTotalIls must be a number`);
        if (!condition.methodLabel || typeof condition.methodLabel !== 'string') errors.push(`${at}.methodLabel is required`);
        if (!condition.observedAt || Number.isNaN(Date.parse(condition.observedAt))) errors.push(`${at}.observedAt must be an ISO date`);
        if (!condition.evidence?.url || !condition.evidence?.note) errors.push(`${at}.evidence.url and .note are required`);
      });
    }
  }
  // A superseded rule is an explicit migration instruction for rows stamped by
  // an older version of the same policy; it must name the exact old amount and
  // semantics so only the superseded threshold is migrated.
  const supersedes = policy.supersedes?.freeThreshold;
  if (supersedes != null) {
    if (!Number.isFinite(supersedes.amount) || !CURRENCY_PATTERN.test(String(supersedes.currency ?? ''))) {
      errors.push('supersedes.freeThreshold must carry a numeric amount and a 3-letter currency');
    }
    if (!['above', 'at_least'].includes(supersedes.semantics)) errors.push('supersedes.freeThreshold.semantics must be "above" or "at_least"');
    if (!['published', 'observed_cart'].includes(supersedes.origin)) errors.push('supersedes.freeThreshold.origin must be "published" or "observed_cart"');
    if (!Number.isInteger(supersedes.policyVersion) || supersedes.policyVersion < 1) errors.push('supersedes.freeThreshold.policyVersion must be a positive integer');
  }
  if (policy.alternatives != null) {
    if (!Array.isArray(policy.alternatives)) {
      errors.push('alternatives must be an array when present');
    } else {
      policy.alternatives.forEach((alternative, index) => {
        if (!alternative || typeof alternative !== 'object') { errors.push(`alternatives[${index}] is not an object`); return; }
        if (!alternative.id || typeof alternative.id !== 'string') errors.push(`alternatives[${index}].id is required`);
        if (!alternative.label || typeof alternative.label !== 'string') errors.push(`alternatives[${index}].label is required`);
        const altAmount = alternative.amount;
        if (!altAmount || !Number.isFinite(altAmount.amount) || !CURRENCY_PATTERN.test(String(altAmount.currency ?? ''))) {
          errors.push(`alternatives[${index}].amount must carry a numeric amount and a 3-letter currency`);
        }
        if (alternative.maxTotalGrams != null && (!Number.isFinite(alternative.maxTotalGrams) || alternative.maxTotalGrams <= 0)) {
          errors.push(`alternatives[${index}].maxTotalGrams must be a positive number when present`);
        }
      });
    }
  }
  if (!policy.evidence?.url || !policy.evidence?.retrievedAt) errors.push('evidence.url and evidence.retrievedAt are required');
  if (!policy.reviewBy || Number.isNaN(Date.parse(policy.reviewBy))) errors.push('reviewBy must be an ISO date');
  if (!policy.destination || !['country', 'localities'].includes(policy.destination.scope)) errors.push('destination.scope must be country or localities');
  if (policy.destination?.scope === 'localities' && !Array.isArray(policy.destination.localities)) {
    errors.push('a localities destination needs a localities array');
  }
  return { ok: errors.length === 0, errors };
}

export function validatePolicies(policies = SHIPPING_POLICIES) {
  const results = policies.map(policy => ({ id: policy?.id ?? null, ...validatePolicy(policy) }));
  return { ok: results.every(result => result.ok), results };
}

/**
 * Is this policy still inside its review window at `now`?
 *
 * The read-time evaluator and the vendor adapters both use this: a policy past
 * its `reviewBy` date must not enrich an old row and must not be stamped onto a
 * freshly parsed row either, so the offer falls back to explicit unknown
 * shipping instead of a stale unconditional rate until browser research renews
 * the evidence.
 */
export function policyIsCurrent(policy, now = Date.now()) {
  const reviewBy = Date.parse(policy?.reviewBy ?? '');
  return Number.isFinite(reviewBy) && reviewBy >= now;
}

/** Does this policy's scope cover the observation? */
function policyMatches(policy, observation) {
  if (!observation || !policy) return false;
  if (policy.vendorId && observation.vendor?.id !== policy.vendorId) return false;
  const productId = observation.product?.productId ?? null;
  if (policy.productIds?.length && !policy.productIds.includes(productId)) return false;
  if (policy.itemUrlPrefixes?.length) {
    const url = String(observation.itemUrl ?? '');
    if (!policy.itemUrlPrefixes.some(prefix => url.startsWith(prefix))) return false;
  }
  if (policy.service != null && observation.shipping?.service != null && observation.shipping.service !== policy.service) return false;
  return true;
}

function ruleKey(rule, alternatives = []) {
  const amount = rule?.amount ? `${rule.amount.amount}${rule.amount.currency}` : '-';
  const threshold = rule?.freeThreshold ? `${rule.freeThreshold.amount}${rule.freeThreshold.currency}` : '-';
  const thresholdScope = `${rule?.thresholdSemantics ?? '-'}/${rule?.freeThresholdOrigin ?? '-'}`;
  const conditionsKey = (rule?.freeCartConditions ?? [])
    .map(condition => `${condition.id}:${condition.units}x${condition.packCount}:${condition.itemSubtotalIls}`)
    .join(',');
  const alternativesKey = alternatives.map(alternative => `${alternative.id}:${alternative.amount?.amount ?? '-'}${alternative.amount?.currency ?? ''}`).join(',');
  return `${amount}/${threshold}/${thresholdScope}/${conditionsKey}/${rule?.minOrder?.amount ?? '-'}/${alternativesKey}`;
}

/**
 * Does this policy describe exactly the money/scope the row already carries?
 * Used before refreshing a stamped row's provenance: a newer policy version may
 * update evidence (coverage, retrieval time) without changing the rule, but a
 * version that changes any amount must not overwrite a parsed rate at read time.
 */
function policyRuleMatchesShipping(policy, shipping) {
  const rule = policy?.rule ?? {};
  const sameAmount = (a, b) => (a?.amount ?? null) === (b?.amount ?? null) && (a?.currency ?? null) === (b?.currency ?? null);
  if (!sameAmount(rule.amount, shipping?.amount)) return false;
  if (!sameAmount(rule.freeThreshold, shipping?.freeThreshold)) return false;
  if ((rule.thresholdSemantics ?? null) !== (shipping?.freeThresholdSemantics ?? null)) return false;
  if ((rule.freeThresholdOrigin ?? null) !== (shipping?.freeThresholdOrigin ?? null)) return false;
  if ((rule.minOrder?.amount ?? null) !== (shipping?.minOrder?.amount ?? null)) return false;
  if ((rule.maxTotalGrams ?? null) !== (shipping?.maxTotalGrams ?? null)) return false;
  const policyConditions = (rule.freeCartConditions ?? [])
    .map(condition => `${condition.id}:${condition.units}x${condition.packCount}:${condition.itemSubtotalIls}`).join(',');
  const rowConditions = (shipping?.freeCartConditions ?? [])
    .map(condition => `${condition.id}:${condition.units}x${condition.packCount}:${condition.itemSubtotalIls}`).join(',');
  if (policyConditions !== rowConditions) return false;
  const policyAlternatives = (policy?.alternatives ?? [])
    .map(alternative => `${alternative.id}:${alternative.amount?.amount ?? '-'}${alternative.amount?.currency ?? ''}`).join(',');
  const rowAlternatives = (shipping?.alternatives ?? [])
    .map(alternative => `${alternative.id}:${alternative.amount?.amount ?? '-'}${alternative.amount?.currency ?? ''}`).join(',');
  return policyAlternatives === rowAlternatives;
}

/**
 * Resolve which policy (if any) may enrich this observation.
 * Statuses: applied | already-known | unmatched | expired | invalid | inconsistent.
 */
export function resolveShippingPolicy({ observation, policies = SHIPPING_POLICIES, now = Date.now() } = {}) {
  const matching = policies.filter(policy => policyMatches(policy, observation));
  if (!matching.length) return { status: 'unmatched', policy: null };
  const valid = [];
  const expired = [];
  const invalid = [];
  for (const policy of matching) {
    const check = validatePolicy(policy);
    if (!check.ok) { invalid.push({ policy, errors: check.errors }); continue; }
    if (Date.parse(policy.reviewBy) < now) expired.push(policy);
    else valid.push(policy);
  }
  if (!valid.length) {
    if (expired.length) return { status: 'expired', policy: expired.sort((a, b) => b.version - a.version)[0] };
    return { status: 'invalid', policy: invalid[0]?.policy ?? null, errors: invalid[0]?.errors ?? [] };
  }
  // One effective rule per policy id: the highest version.
  const latestById = new Map();
  for (const policy of valid) {
    const current = latestById.get(policy.id);
    if (!current || policy.version > current.version) latestById.set(policy.id, policy);
  }
  const effective = [...latestById.values()];
  const keys = new Set(effective.map(policy => ruleKey(policy.rule, policy.alternatives ?? [])));
  if (keys.size > 1) return { status: 'inconsistent', policy: null, policies: effective };
  return { status: 'applied', policy: effective.sort((a, b) => b.version - a.version)[0] };
}

/**
 * Fill only the shipping fields the observation is missing from a matching
 * validated policy. Returns { observation, status, policy }; the original
 * observation is never mutated and its observedAt/price/stock stay untouched.
 */
export function enrichObservationShipping(observation, options = {}) {
  const resolved = resolveShippingPolicy({ observation, ...options });
  if (resolved.status !== 'applied') return { observation, status: resolved.status, policy: resolved.policy ?? null };
  const policy = resolved.policy;
  const shipping = { ...(observation.shipping ?? {}) };
  let changed = false;

  // A rule correction (not new knowledge): the v2 policy applied an
  // unconditional free threshold from ₪231, but the free carts were observed
  // exactly, not as a threshold. A row stamped by that older version of the
  // same policy must stop applying the superseded threshold at read time — the
  // threshold itself came from this policy id, so removing it is not
  // overwriting a fresher vendor parse. The published base amount, the price,
  // the stock and the observation time stay untouched.
  const stampBefore = shipping.policy;
  const superseded = policy.supersedes?.freeThreshold;
  const supersedesRow = Boolean(superseded
    && stampBefore?.id === policy.id
    && Number(stampBefore.version) < policy.version
    && shipping.freeThreshold != null
    && Number(shipping.freeThreshold.amount) === superseded.amount
    && (shipping.freeThreshold.currency ?? null) === superseded.currency
    && (shipping.freeThresholdSemantics ?? null) === superseded.semantics
    && (shipping.freeThresholdOrigin ?? null) === superseded.origin
    && policy.rule?.freeThreshold == null);
  let supersededNote = null;
  if (supersedesRow) {
    delete shipping.freeThreshold;
    delete shipping.freeThresholdSemantics;
    delete shipping.freeThresholdOrigin;
    delete shipping.freeThresholdEvidence;
    supersededNote = `The earlier cart-observed free threshold (from ${superseded.amount} ${superseded.currency}) was superseded by policy ${policy.id} v${policy.version}: free delivery now applies only to the exact carts observed free (${(policy.rule?.freeCartConditions ?? []).map(condition => condition.id).join(', ')}), and a cart that matches none of them keeps the published base rate.`;
    changed = true;
  }

  if ((shipping.certainty === 'unknown' || shipping.amount == null) && policy.rule?.amount?.amount != null) {
    shipping.amount = { ...policy.rule.amount };
    shipping.certainty = policy.certainty;
    changed = true;
  }
  if (shipping.freeThreshold == null && policy.rule?.freeThreshold?.amount != null) {
    shipping.freeThreshold = { ...policy.rule.freeThreshold };
    changed = true;

  }

  let shippingIls = null;
  if (shipping.certainty === 'unknown' || shipping.amount == null) {
    reasons.push(shipping.note
      ? `Shipping is not published before checkout, so it is treated as unknown, not free (${shipping.note})`
      : 'Shipping is not published before checkout, so it is treated as unknown, not free');
    return base;
  }
  const convertedShipping = toIls(shipping.amount.amount ?? shipping.amount, shipping.amount.currency ?? price.currency, fx);
  if (!convertedShipping.known) {
    reasons.push(`Shipping is quoted in ${shipping.amount.currency ?? 'an unknown currency'} with no stored reference rate`);
    return base;
  }
  shippingIls = convertedShipping.amount;
  if (convertedShipping.converted || shipping.certainty === 'estimated') base.estimate = true;

  if (shipping.freeThreshold != null) {
    const threshold = toIls(shipping.freeThreshold.amount, shipping.freeThreshold.currency, fx);
    // "above ₪100" means the ₪100 boundary itself is not free; only a strictly
    // larger item subtotal is. Never silently relax the vendor's wording.
    const semantics = base.shipping.freeThresholdSemantics;
    const met = threshold.known && (semantics === 'above'
      ? base.itemTotalIls > threshold.amount + 0.005
      : base.itemTotalIls >= threshold.amount - 0.005);
    if (met) {
      shippingIls = 0;
      const scope = base.shipping.freeThresholdOrigin === 'observed_cart' ? ', observed in the vendor\u2019s anonymous cart' : '';
      base.labels.push(`Free shipping threshold met (${semantics === 'above' ? 'above' : 'from'} ${formatAmount(threshold.amount, 'ILS')}${scope})`);
    }
  }

  // Scoped cart-observed free conditions: the vendor showed free delivery on
  // exact anonymous carts (listing, whole-pack count, grams and item subtotal),
  // but never published a threshold. Free delivery is applied only when the
  // current cart matches an observed free configuration exactly. A larger or
  // otherwise unobserved cart keeps the published base rate instead of
  // inheriting zero shipping from its subtotal alone.
  const freeConditions = base.shipping.freeCartConditions;
  if (freeConditions.length) {
    const matched = freeConditions.find(condition => freeCartConditionMatches(condition, observation, base));
    if (matched) {
      shippingIls = 0;
      base.shipping.freeCondition = {
        id: matched.id,
        units: matched.units ?? null,
        packCount: matched.packCount ?? null,
        orderedGrams: matched.orderedGrams ?? null,
        itemSubtotalIls: matched.itemSubtotalIls ?? null,
        discountPercent: matched.discountPercent ?? null,
        paidItemTotalIls: matched.paidItemTotalIls ?? null,
        methodLabel: matched.methodLabel ?? 'delivery',
        observedAt: matched.observedAt ?? null,
        evidence: matched.evidence ?? null
      };
      base.labels.push(`Free ${matched.methodLabel ?? 'delivery'} observed for this exact cart (${freeConditionCartLabel(matched)}) in the vendor's anonymous cart`);
    } else {
      const minObserved = freeConditions
        .map(condition => condition.itemSubtotalIls)
        .filter(amount => Number.isFinite(amount))
        .reduce((min, amount) => (min == null || amount < min ? amount : min), null);
      base.shipping.freeConditionUnmatched = true;
      base.shipping.freeConditionNote = `The vendor's anonymous cart showed free ${freeConditions[0].methodLabel ?? 'delivery'} only on ${freeConditions.map(freeConditionCartLabel).join(', ')}; this cart keeps the published ${formatAmount(shippingIls, 'ILS')} base rate.`;
      // Only surprise the shopper when the cart is at or above an observed free
      // subtotal yet still unverified: then the base fee is visibly conditional.
      if (minObserved != null && base.itemTotalIls >= minObserved - 0.005) {
        base.shipping.freeConditionUnmatchedAboveMin = true;
        base.labels.push('Free delivery was observed only on specific carts; this unobserved cart keeps the published base rate');
      }
    }
  }

  base.shipping.amountIls = round2(shippingIls);
  if (stale) {
    labels.push('Stale observation — the last successful check is too old to rank');
    base.group = 'stale_unavailable';
    return base;
  }

  base.totalIls = round2(base.itemTotalIls + shippingIls + feeSum.amount);
  base.ilsPerKg = round2((base.totalIls / base.orderedGrams) * 1000);
  base.rankable = true;
  base.group = 'ranked';
  if (base.estimate) labels.push('Estimate — includes a converted or estimated component');
  return base;
}

/** Shape the stored previous-check snapshot for the API without leaking raw payloads. */
function summarizePrevious(previous) {
  if (!previous || typeof previous !== 'object') return null;
  const availability = previous.availability ?? 'unknown';
  return {
    observedAt: previous.observedAt ?? null,
    priceAmount: previous.price?.amount ?? null,
    priceCurrency: previous.price?.currency ?? null,
    availability,
    availabilityLabel: AVAILABILITY_LABELS[availability] ?? AVAILABILITY_LABELS.unknown
  };
}

