// Throwaway: check the rendered locality select for a malformed dest query.
import { spawn } from 'node:child_process';
import { setTimeout as delay } from 'node:timers/promises';

const PORT = 9516;
const chrome = spawn('chromedriver', [`--port=${PORT}`, '--allowed-ips='], { stdio: ['ignore', 'pipe', 'pipe'] });
await delay(1200);

async function wd(method, path, body) {
  const res = await fetch(`http://127.0.0.1:${PORT}${path}`, {
    method,
    headers: { 'content-type': 'application/json' },
    body: body === undefined ? undefined : JSON.stringify(body)
  });
  const json = await res.json();
  if (!res.ok) throw new Error(`${res.status} ${JSON.stringify(json)}`);
  return json.value;
}

const cases = [
  'http://127.0.0.1:8791/product/lavazza-crema-e-gusto-vacuum-ground?grams=500&dest=bogus',
  'http://127.0.0.1:8791/product/lavazza-crema-e-gusto-vacuum-ground?grams=500&dest=eilat',
  'http://127.0.0.1:8791/product/lavazza-crema-e-gusto-vacuum-ground?grams=-5&dest=tel-aviv',
  'http://127.0.0.1:8791/product/lavazza-crema-e-gusto-vacuum-ground?grams=abc&dest=tel-aviv',
  'http://127.0.0.1:8791/product/lavazza-qualita-oro-vacuum-ground?product=lavazza-qualita-oro-vacuum-ground&grams=750&dest=bogus'
];

try {
  const session = await wd('POST', '/session', { capabilities: { alwaysMatch: { browserName: 'chrome', 'goog:chromeOptions': { args: ['--headless=new', '--no-sandbox', '--disable-gpu', '--window-size=390,844'] } } } });
  const id = session.sessionId;
  for (const url of cases) {
    await wd('POST', `/session/${id}/url`, { url });
    await delay(1500);
    const info = await wd('POST', `/session/${id}/execute/sync`, {
      script: `
        const s = document.getElementById('destination');
        return { value: s.value, selectedIndex: s.selectedIndex, text: s.options[s.selectedIndex]?.textContent ?? null, pressed: [...document.querySelectorAll('#quantity-group button')].filter(b=>b.getAttribute('aria-pressed')==='true').map(b=>b.textContent), search: location.search, total: document.querySelector('#best-offer .totals__cell--total .totals__value')?.textContent ?? null, notice: document.getElementById('retired-product-notice')?.textContent?.slice(0,60) ?? null };
      `,
      args: []
    });
    console.log(url.split('?')[1], '=>', JSON.stringify(info));
  }
  await wd('DELETE', `/session/${id}`);
} finally {
  chrome.kill('SIGTERM');
}

