import { spawn } from 'node:child_process';
import { setTimeout as delay } from 'node:timers/promises';

const PORT = 9515;
const chrome = spawn('chromedriver', [`--port=${PORT}`, '--allowed-ips='], { stdio: ['ignore', 'pipe', 'pipe'] });
const wd = async (method, path, body) => {
  const res = await fetch(`http://127.0.0.1:${PORT}${path}`, {
    method,
    headers: body ? { 'content-type': 'application/json' } : {},
    body: body ? JSON.stringify(body) : undefined,
    signal: AbortSignal.timeout(30_000)
  });
  const payload = await res.json().catch(() => ({}));
  if (!res.ok) throw new Error(`${method} ${path} -> ${res.status} ${JSON.stringify(payload).slice(0, 400)}`);
  return payload;
};
try {
  for (let i = 0; i < 40; i++) {
    try { await fetch(`http://127.0.0.1:${PORT}/status`); break; } catch { await delay(250); }
  }
  const session = await wd('POST', '/session', {
    capabilities: { alwaysMatch: { browserName: 'chrome', 'goog:chromeOptions': { binary: '/usr/bin/google-chrome', args: ['--headless=new', '--no-sandbox', '--disable-dev-shm-usage', '--disable-gpu'] } } }
  });
  const sid = session.sessionId ?? session.value?.sessionId;
  const call = (m, p, b) => wd(m, `/session/${sid}${p}`, b);
  await call('POST', '/timeouts', { implicit: 0, pageLoad: 30000, script: 20000 });
  await call('POST', '/window/rect', { width: 390, height: 844, x: 0, y: 0 });
  await call('POST', '/url', { url: 'data:text/html,<title>t</title><h1>hello</h1>' });
  const measure = async () => (await call('POST', '/execute/sync', { script: 'return {iw: window.innerWidth, ih: window.innerHeight, ow: window.outerWidth, oh: window.outerHeight, dpr: window.devicePixelRatio, sw: screen.width, sh: screen.height}', args: [] })).value;
  console.log('window/rect 390x844 =>', JSON.stringify(await measure()));
  let cdp = null;
  try {
    cdp = await call('POST', '/chromium/send_command', { cmd: 'Emulation.setDeviceMetricsOverride', params: { width: 390, height: 844, deviceScaleFactor: 1, mobile: true } });
    console.log('CDP send_command ok:', JSON.stringify(cdp).slice(0, 200));
  } catch (e) {
    console.log('CDP send_command failed:', e.message);
  }
  console.log('after CDP override =>', JSON.stringify(await measure()));
  // Screenshot size probe.
  const shot = await call('GET', '/screenshot');
  const buf = Buffer.from(shot.value, 'base64');
  // PNG width/height are bytes 16-23 big-endian.
  console.log('screenshot bytes:', buf.length, 'w=', buf.readUInt32BE(16), 'h=', buf.readUInt32BE(20));
  // Resize the window while the override is active.
  await call('POST', '/window/rect', { width: 1440, height: 1000, x: 0, y: 0 });
  console.log('after window/rect 1440x1000 with override =>', JSON.stringify(await measure()));
  // Clear override.
  try {
    const cleared = await call('POST', '/chromium/send_command', { cmd: 'Emulation.clearDeviceMetricsOverride', params: {} });
    console.log('CDP clear ok:', JSON.stringify(cleared).slice(0, 200));
  } catch (e) {
    console.log('CDP clear failed:', e.message);
  }
  console.log('after clear =>', JSON.stringify(await measure()));
  // Now try growing the outer window as a fallback.
  await call('POST', '/window/rect', { width: 390, height: 844, x: 0, y: 0 });
  const a = await measure();
  await call('POST', '/window/rect', { width: 390 + (390 - a.iw), height: 844 + (844 - a.ih), x: 0, y: 0 });
  const b = await measure();
  console.log('grow fallback =>', JSON.stringify(b));
  await call('DELETE', '');
} finally {
  chrome.kill('SIGTERM');
}

