 * extension so the layout viewport really is 390×844, verifies the measured
 * `window.innerWidth`/`innerHeight` and records them; it falls back to growing
 * the outer window when the CDP command is unavailable and throws when neither
 * path reaches the requested content size.
 */
async function setContentViewport(wd, width, height) {
  let cdp = 'ok';
  try {
    await wd('POST', '/chromium/send_command', {
      cmd: 'Emulation.setDeviceMetricsOverride',
      params: { width, height, deviceScaleFactor: 1, mobile: false }
    });
  } catch (error) {
    cdp = `unavailable (${error?.message ?? error})`;
  }
  let measured = await measureViewport(wd);
  if (measured.innerWidth >= width && measured.innerHeight >= height) {
    report.viewports.push({ requested: { width, height }, measured, via: 'cdp', cdp });
    return measured;
  }
  // Fallback: grow the outer window by the measured chrome delta.
  await wd('POST', '/window/rect', { width, height, x: 0, y: 0 });
  measured = await measureViewport(wd);
  if (measured.innerWidth < width || measured.innerHeight < height) {
    const deltaW = Math.max(0, width - measured.innerWidth);
    const deltaH = Math.max(0, height - measured.innerHeight);
    await wd('POST', '/window/rect', { width: width + deltaW, height: height + deltaH, x: 0, y: 0 });
    measured = await measureViewport(wd);
  }
  report.viewports.push({ requested: { width, height }, measured, via: 'outer-window', cdp });
  if (measured.innerWidth < width || measured.innerHeight < height) {
    throw new Error(`content viewport ${width}×${height} not reached: ${JSON.stringify(measured)}`);
  }
  return measured;
}
