import { spawn } from 'node:child_process';
import { setTimeout as delay } from 'node:timers/promises';

const PORT = 9516;
const url = 'https://attention-shoppers.igormaka.workers.dev/product/lavazza-crema-e-gusto-vacuum-ground?grams=2000&dest=tel-aviv';
const chrome = spawn('chromedriver', [`--port=${PORT}`, '--allowed-ips='], { stdio: ['ignore', 'pipe', 'pipe'] });
const wd = async (method, path, body) => {
  const res = await fetch(`http://127.0.0.1:${PORT}${path}`, {
    method,
    headers: body ? { 'content-type': 'application/json' } : {},
    body: body ? JSON.stringify(body) : undefined,
    signal: AbortSignal.timeout(30_000)
  });
  const payload = await res.json().catch(() => ({}));
  if (!res.ok) throw new Error(`${method} ${path} -> ${res.status}`);
  return payload;
};
try {
  for (let i = 0; i < 40; i++) {
    try { await fetch(`http://127.0.0.1:${PORT}/status`); break; } catch { await delay(250); }
  }
  const session = await wd('POST', '/session', { capabilities: { alwaysMatch: { browserName: 'chrome', 'goog:chromeOptions': { binary: '/usr/bin/google-chrome', args: ['--headless=new', '--no-sandbox', '--disable-dev-shm-usage', '--disable-gpu'] } } } });
  const sid = session.sessionId ?? session.value?.sessionId;
  const call = (m, p, b) => wd(m, `/session/${sid}${p}`, b);
  await call('POST', '/chromium/send_command', { cmd: 'Emulation.setDeviceMetricsOverride', params: { width: 390, height: 844, deviceScaleFactor: 1, mobile: false } });
  await call('POST', '/url', { url });
  for (let i = 0; i < 40; i++) {
    const ready = await call('POST', '/execute/sync', { script: "return document.body.dataset.boardState === 'ready'", args: [] });
    if (ready.value) break;
    await delay(250);
  }
  const result = await call('POST', '/execute/sync', { script: `return (() => {
    const rect = sel => { const n = document.querySelector(sel); if (!n) return null; const r = n.getBoundingClientRect(); const s = getComputedStyle(n); return { sel, top: Math.round(r.top), bottom: Math.round(r.bottom), height: Math.round(r.height), marginTop: s.marginTop, marginBottom: s.marginBottom, paddingTop: s.paddingTop, paddingBottom: s.paddingBottom }; };
    return {
      innerHeight: window.innerHeight,
      items: ['.skip', '.masthead', '.product-head', '#product-title', '#product-subtitle', '.controls', '#board', '#best-offer', '#best-offer .offer__head', '#best-offer .offer__pack', '#best-offer .totals', '#best-offer .qualifier--failure', '#best-offer .qualifier:not(.qualifier--failure)', '#best-offer details', '#best-offer .offer__links'].map(rect)
    };
  })()`, args: [] });
  console.log(JSON.stringify(result.value, null, 1));
  await call('DELETE', '');
} finally {
  chrome.kill('SIGTERM');
}

content.text:
  max-width: var(--page-max);
  margin: 0 auto;
  padding: 18px 24px 10px;
}
.product-head h1 {
  margin: 0;
  font-size: clamp(24px, 3vw, 34px);
  line-height: 1.08;
  letter-spacing: -.02em;
  font-weight: 700;
}
.product-head__meta { margin: 4px 0 0; font-size: 13.5px; color: var(--muted); }

/* ---------- controls ---------- */

.controls {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 16px 24px;
  max-width: var(--page-max);
  margin: 0 auto;
  padding: 4px 24px 16px;
  border-bottom: 1px solid var(--divider);
}
.controls__group { display: flex; flex-direction: column; gap: 8px; min-width: 0; }
.controls__label {
  font-size: 12px;
  font-weight: 700;
  letter-spacing: .06em;
  text-transform: uppercase;
  padding-bottom: 4px;
  border-bottom: 2px solid var(--ink);
}
.field__static {
  font-size: 15px;
  font-weight: 600;
  padding: 9px 0;
  border-bottom: 2px solid var(--ink);
}
.field__static[hidden] { display: none; }
.controls__group select {
  font: inherit;
  font-weight: 400;
  font-size: 15px;
  padding: 9px 10px;
  border: 1px solid var(--divider);
  border-left: 3px solid var(--ink);
  border-radius: 0;
  background: #fff;
  color: var(--ink);
  min-height: 44px;
  width: 100%;
  max-width: 100%;
}
.segmented { display: flex; flex-wrap: wrap; gap: 6px; }
.segmented button {
  font: inherit;
  font-weight: 600;
  padding: 9px 13px;
  min-height: 44px;
  border: 1px solid var(--divider);
  border-bottom: 3px solid var(--divider);
  border-radius: 0;
  background: #fff;
  color: var(--ink);
  cursor: pointer;
  font-variant-numeric: tabular-nums;
}
.segmented button:hover { border-color: var(--ink); }
.segmented button[aria-pressed="true"] {
  background: var(--blue);
  border-color: var(--blue);
  border-bottom-color: var(--cyan);
  color: #fff;
}
.check { display: flex; gap: 8px; align-items: center; font-size: 13.5px; min-height: 44px; }
.check input { width: 20px; height: 20px; accent-color: var(--blue); }

/* ---------- board ---------- */

.board {
  max-width: var(--page-max);
  margin: 0 auto;
  padding: 0 24px 48px;
}
.loading { padding: 32px 0; font-size: 16px; color: var(--muted); }

/* product-detail decision area: best offer first, everything else disclosed */
.decision { padding: 8px 0 28px; }
.decision > .meta-line { max-width: 96ch; }

/* section-level disclosures (compare, pickup, missing information) */
details.disclosure--compare,
details.disclosure--pickup,
details.disclosure--unknown {
  margin-top: 18px;
  border: 1px solid var(--divider);
  border-top: 3px solid var(--ink);
  background: #fff;
}
details.disclosure--compare > summary,
details.disclosure--pickup > summary,
details.disclosure--unknown > summary {
  cursor: pointer;
  padding: 12px 16px;
  font-size: 15px;
  font-weight: 700;
  letter-spacing: 0;
  text-transform: none;
  color: var(--ink);
}
details.disclosure--compare > summary:hover,
details.disclosure--pickup > summary:hover,
details.disclosure--unknown > summary:hover { color: var(--blue); }
details.disclosure--compare > .disclosure__body,
details.disclosure--pickup > .disclosure__body,
details.disclosure--unknown > .disclosure__body {
  padding: 0 16px 16px;
  font-size: 14px;
  color: var(--ink);
  gap: 10px;
}
details.disclosure--compare > .disclosure__body > p,
details.disclosure--pickup > .disclosure__body > p { color: var(--muted); }

/* a one-line amber qualification next to a conditional total */
.qualifier {
  margin: 10px 0 0;
  padding: 7px 10px;
  background: var(--amber-soft);

  gap: 20px 32px;
  max-width: var(--page-max);
  margin: 0 auto;
  padding: 20px 24px 36px;
  border-top: 2px solid var(--ink);
  font-size: 13px;
}
.site-footer p { margin: 6px 0 0; max-width: 72ch; color: var(--muted); }
.site-footer__status { font-variant-numeric: tabular-nums; color: var(--muted); }
.site-footer__status details.disclosure { margin-top: 10px; }
.noscript { padding: 16px 24px; background: var(--amber-soft); color: var(--amber); }

/* ---------- responsive ---------- */

@media (max-width: 1020px) {
  .controls { grid-template-columns: repeat(3, minmax(0, 1fr)); }
}

@media (max-width: 720px) {
  .controls { grid-template-columns: 1fr 1fr; gap: 12px 14px; }
  .controls__group:first-child { grid-column: 1 / -1; }
  /* The locality select takes the full row on small screens: in a half-column
     the selected locality text is clipped at 390 px, which hides the chosen
     destination. */
  .controls__group:last-child { grid-column: 1 / -1; }
  .totals { grid-template-columns: 1fr 1fr; }
  .totals__cell { padding: 10px 12px 10px 0; }
  .totals__cell + .totals__cell { padding-left: 12px; }
  .totals__cell--total { grid-column: 1 / -1; border-left: 0 !important; border-top: 1px solid var(--divider); padding-left: 0 !important; }
  .site-footer { grid-template-columns: 1fr; }
  .offer__top { flex-direction: column; align-items: flex-start; gap: 6px; }
}

