import { readFileSync } from 'node:fs';
import { decodePng } from './scripts/inspect-screenshot.mjs';

const files = process.argv.slice(2);
for (const file of files) {
  const img = decodePng(readFileSync(file));
  const bands = [];
  const bandH = Math.round(img.height / 10);
  for (let band = 0; band < 10; band += 1) {
    const y0 = band * bandH, y1 = Math.min(img.height, y0 + bandH);
    let dark = 0, total = 0;
    for (let y = y0; y < y1; y += 1) {
      for (let x = 0; x < img.width; x += 1) {
        const i = (y * img.width + x) * img.channels;
        const lum = 0.2126 * img.pixels[i] + 0.7152 * img.pixels[i + 1] + 0.0722 * img.pixels[i + 2];
        if (lum < 160) dark += 1;
        total += 1;
      }
    }
    bands.push(Number((dark / total).toFixed(4)));
  }
  console.log(file, `${img.width}x${img.height}`, JSON.stringify(bands));
}
