#!/usr/bin/env node
// Reproduce CoffeeMan's anonymous-cart free-delivery observations through the
// production quote engine and write the scope matrix as evidence.
//
//   node scripts/verify-coffeeman-free-scope.mjs [--out <path>]
//
// The carts below are the exact anonymous checkout configurations recorded in
// docs/evidence/browser-research/2026-10-12-coffeeman-cart-single-4pack.json
// (no order, login, account, street address or bot-challenge bypass). The rows
// are shaped like the persisted observations (unknown shipping) so the engine
// enriches them from the validated policy, and each result is compared with the
// fee the vendor actually displayed. The matrix also covers carts that were
// never observed (3 kg of singles, three 4-packs, a repriced 8-singles cart):
// those must keep the published ₪25 base rate instead of inheriting free
// delivery from a subtotal.

import { mkdir, writeFile } from 'node:fs/promises';
import { dirname, resolve } from 'node:path';
import { quoteBoard, findDestination } from '../src/lib/quote.js';

const args = process.argv.slice(2);
const outIndex = args.indexOf('--out');
const outPath = resolve(outIndex >= 0 ? args[outIndex + 1] : 'docs/evidence/coffeeman-free-condition-20261013.json');

const NOW = Date.parse('2026-10-13T02:30:00.000Z');
const SINGLE_URL = 'https://www.coffeeman.co.il/product/250-%D7%92%D7%A8%D7%9D-%D7%A7%D7%A4%D7%94-%D7%98%D7%97%D7%95%D7%9F-lavazza-crema-e-gusto-classico';
const FOUR_PACK_URL = 'https://www.coffeeman.co.il/product/4-%D7%90%D7%A8%D7%99%D7%96%D7%95%D7%AA-250-%D7%92%D7%A8%D7%9D-%D7%A7%D7%A4%D7%94-%D7%98%D7%97%D7%95%D7%9F-lavazza-crema-e-gusto-classico';
const EIGHT_PACK_URL = 'https://www.coffeeman.co.il/product/8-%D7%90%D7%A8%D7%99%D7%96%D7%95%D7%AA-250-%D7%92%D7%A8%D7%9D-%D7%A7%D7%A4%D7%94-%D7%98%D7%97%D7%95%D7%9F-lavazza-crema-e-gusto-classico';

const vendor = { id: 'coffeeman', name: 'CoffeeMan (אמיגו)', homepage: 'https://www.coffeeman.co.il' };

function persistedRow({ url, sku, name, packCount, totalGrams, price }) {
  return {
    key: `coffeeman:${sku}:ground:${totalGrams}g:x${packCount}`,
    vendor,
    itemUrl: url,
    product: {
      productId: 'lavazza-crema-e-gusto-vacuum-ground',
      name,
      sku,

    throw new Error(`content viewport ${width}×${height} not reached: ${JSON.stringify(measured)} via ${via}`);
  }
  return measured;
}

async function measureViewport(wd) {
  return evaluate(wd, `({
    innerWidth: window.innerWidth,
    innerHeight: window.innerHeight,
    outerWidth: window.outerWidth,
    outerHeight: window.outerHeight
  })`);
}

/** PNG dimensions from the IHDR chunk, for verifying a capture was not clipped. */
function pngSize(buffer) {
  if (buffer.length < 24) return { width: null, height: null };
  return { width: buffer.readUInt32BE(16), height: buffer.readUInt32BE(20) };
}

async function savedPngSize(name) {
  return pngSize(await readFile(`${OUT}/${name}`));
}

async function screenshot(wd, name) {
  const shot = await wd('GET', '/screenshot');
  const buffer = Buffer.from(shot.value, 'base64');
  await writeFile(`${OUT}/${name}`, buffer);
  return { name, ...pngSize(buffer) };
}

/**
 * Save a cropped screenshot of one rendered element (the affected offer card),
 * so the decision values are readable without a full-page capture. The element
 * is located by the given in-page expression, which must return a DOM node.
 * Returns the saved name and the PNG dimensions; a clipped element capture is
 * smaller than the element's own box, so callers can require a complete view.
 */
async function elementScreenshot(wd, expression, name) {
  const found = await evaluate(wd, expression);
  const id = found?.['element-6066-11e4-a52e-4f735466cecf'] ?? found?.ELEMENT;
  if (!id) return null;
  const shot = await wd('GET', `/element/${id}/screenshot`);
  const buffer = Buffer.from(shot.value, 'base64');
  await writeFile(`${OUT}/${name}`, buffer);
  return { name, ...pngSize(buffer) };
}

/**
 * Save a genuinely complete capture of an offer card even when the card is
 * taller than the first-screen viewport: raise the content viewport to fit the
 * card, scroll it into view, verify the whole card (including the failure
 * sentence) is inside the viewport and only then capture the element. A cropped
 * element screenshot is not evidence that its warning text was readable.
 * Afterwards the content viewport and the pre-capture scroll position are
 * restored, so a later capture is not accidentally a scrolled card view.
 * Returns { name, width, height, cardRect } or null when the card is absent.
 */
async function completeCardScreenshot(wd, expression, name, { width = 390, restoreHeight = 844 } = {}) {
  const rect = await evaluate(wd, `(() => {
    const node = ${expression};
    if (!node) return null;
    const r = node.getBoundingClientRect();
    return { top: Math.round(r.top), bottom: Math.round(r.bottom), width: Math.round(r.width), height: Math.round(r.height), scrollY: Math.round(window.scrollY) };
  })()`);
  if (!rect) return null;
  const needed = Math.max(restoreHeight, rect.height + 80);
  await setContentViewport(wd, width, needed);
  await evaluate(wd, `(() => {
    const node = ${expression};
    node?.scrollIntoView({ block: 'start', behavior: 'instant' });
    return true;
  })()`);
  await delay(250);
  const inside = await evaluate(wd, `(() => {
    const node = ${expression};
    if (!node) return null;
    const r = node.getBoundingClientRect();
    return { top: Math.round(r.top), bottom: Math.round(r.bottom), width: Math.round(r.width), height: Math.round(r.height), innerHeight: window.innerHeight };
  })()`);
  const shot = await elementScreenshot(wd, expression, name);
  await setContentViewport(wd, width, restoreHeight);
  // Restore the scroll position the page had before this capture. Without it a
  // subsequent "viewport" screenshot silently becomes a scrolled card view.
  await evaluate(wd, `(() => { window.scrollTo({ top: ${rect.scrollY}, left: 0, behavior: 'instant' }); return true; })()`);
  await delay(100);
  if (!shot || !inside || inside.top < 0 || inside.bottom > inside.innerHeight + 1) return { ...shot, cardRect: inside, complete: false };
  return { ...shot, cardRect: inside, complete: true };
}

/**
 * Save the unscrolled first screen of the current page at an exact
 * `width`×`height` content viewport.
 *
 * The 3-91 review found the saved "viewport" captures were taken after
 * completeCardScreenshot() had scrolled the offer card to the top, so they
 * showed the card instead of the first screen after loading the product URL
 * (page heading, quantity and locality controls missing). This helper resets
 * the scroll position explicitly, records the measured `scrollY`, `innerWidth`
 * and `innerHeight`, saves the PNG and requires the PNG to be exactly the
 * requested content size. Callers require `scrollY === 0`, so a capture taken

