1524:async function firstScreenScreenshot(wd, name, { width = 390, height = 844 } = {}) {

async function savedPngSize(name) {
  return pngSize(await readFile(`${OUT}/${name}`));
}

async function screenshot(wd, name) {
  const shot = await wd('GET', '/screenshot');
  const buffer = Buffer.from(shot.value, 'base64');
  await writeFile(`${OUT}/${name}`, buffer);
  return { name, ...pngSize(buffer) };
}

/**
 * Save a cropped screenshot of one rendered element (the affected offer card),
 * so the decision values are readable without a full-page capture. The element
 * is located by the given in-page expression, which must return a DOM node.
 * Returns the saved name and the PNG dimensions; a clipped element capture is
 * smaller than the element's own box, so callers can require a complete view.
 */
async function elementScreenshot(wd, expression, name) {
  const found = await evaluate(wd, expression);
  const id = found?.['element-6066-11e4-a52e-4f735466cecf'] ?? found?.ELEMENT;
  if (!id) return null;
  const shot = await wd('GET', `/element/${id}/screenshot`);
  const buffer = Buffer.from(shot.value, 'base64');
  await writeFile(`${OUT}/${name}`, buffer);
  return { name, ...pngSize(buffer) };
}

/**
 * Save a genuinely complete capture of an offer card even when the card is
 * taller than the first-screen viewport: raise the content viewport to fit the
 * card, scroll it into view, verify the whole card (including the failure
 * sentence) is inside the viewport and only then capture the element. A cropped
 * element screenshot is not evidence that its warning text was readable.
 * Afterwards the content viewport and the pre-capture scroll position are
 * restored, so a later capture is not accidentally a scrolled card view.
 * Returns { name, width, height, cardRect } or null when the card is absent.
 */
async function completeCardScreenshot(wd, expression, name, { width = 390, restoreHeight = 844 } = {}) {
  const rect = await evaluate(wd, `(() => {
    const node = ${expression};
    if (!node) return null;
    const r = node.getBoundingClientRect();
    return { top: Math.round(r.top), bottom: Math.round(r.bottom), width: Math.round(r.width), height: Math.round(r.height), scrollY: Math.round(window.scrollY) };
  })()`);
  if (!rect) return null;
  const needed = Math.max(restoreHeight, rect.height + 80);
  await setContentViewport(wd, width, needed);
  await evaluate(wd, `(() => {
    const node = ${expression};
    node?.scrollIntoView({ block: 'start', behavior: 'instant' });
    return true;
  })()`);
  await delay(250);
  const inside = await evaluate(wd, `(() => {
    const node = ${expression};
    if (!node) return null;
    const r = node.getBoundingClientRect();
    return { top: Math.round(r.top), bottom: Math.round(r.bottom), width: Math.round(r.width), height: Math.round(r.height), innerHeight: window.innerHeight };
  })()`);
  const shot = await elementScreenshot(wd, expression, name);
  await setContentViewport(wd, width, restoreHeight);
  // Restore the scroll position the page had before this capture. Without it a
  // subsequent "viewport" screenshot silently becomes a scrolled card view.
  await evaluate(wd, `(() => { window.scrollTo({ top: ${rect.scrollY}, left: 0, behavior: 'instant' }); return true; })()`);
  await delay(100);
  if (!shot || !inside || inside.top < 0 || inside.bottom > inside.innerHeight + 1) return { ...shot, cardRect: inside, complete: false };
  return { ...shot, cardRect: inside, complete: true };
}

/**
 * Save the unscrolled first screen of the current page at an exact
 * `width`×`height` content viewport.
 *
 * The 3-91 review found the saved "viewport" captures were taken after
 * completeCardScreenshot() had scrolled the offer card to the top, so they
 * showed the card instead of the first screen after loading the product URL
 * (page heading, quantity and locality controls missing). This helper resets
 * the scroll position explicitly, records the measured `scrollY`, `innerWidth`
 * and `innerHeight`, saves the PNG and requires the PNG to be exactly the
 * requested content size. Callers require `scrollY === 0`, so a capture taken
 * after card scrolling or viewport enlargement can never be presented as the
 * loaded first screen.
 */
async function firstScreenScreenshot(wd, name, { width = 390, height = 844 } = {}) {
  await setContentViewport(wd, width, height);
  await evaluate(wd, `(() => { window.scrollTo({ top: 0, left: 0, behavior: 'instant' }); return true; })()`);
  await delay(150);
  const state = await evaluate(wd, `({
    scrollY: Math.round(window.scrollY),
    innerWidth: window.innerWidth,
    innerHeight: window.innerHeight,
    url: location.pathname + location.search
  })`);
  const shot = await screenshot(wd, name);
  const record = {
    name,
    width: shot.width,
    height: shot.height,
    ...state,
    exact: shot.width === width && shot.height === height
      && state.scrollY === 0 && state.innerWidth === width && state.innerHeight === height
  };
  report.firstScreenCaptures.push(record);
  return record;
}

/**
 * Rendered-contrast walk required by the owner's Canton Zürich design direction:
 * compare every visible text element's computed color with the background
 * actually composited behind it (translucent layers are blended down to the
 * root, translucent text is blended with its background) and require 4.5:1 for
 * normal text and 3:1 for large text. Records the checked count, the lowest
 * ratio and any violations in the report; a violation fails the run.
 */
async function contrastReport(wd, scopeSelector, label) {
  const result = await evaluate(wd, `(() => {
    const parse = value => {
      const m = String(value ?? '').match(/rgba?\\(([^)]+)\\)/);
      if (!m) return null;
      const parts = m[1].split(',').map(Number);
      return { r: parts[0], g: parts[1], b: parts[2], a: parts[3] ?? 1 };
    };
    const toLinear = v => { v /= 255; return v <= 0.04045 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4); };
    const luminance = c => 0.2126 * toLinear(c.r) + 0.7152 * toLinear(c.g) + 0.0722 * toLinear(c.b);
    const blend = (fg, bg) => ({ r: fg.r * fg.a + bg.r * (1 - fg.a), g: fg.g * fg.a + bg.g * (1 - fg.a), b: fg.b * fg.a + bg.b * (1 - fg.a), a: 1 });
    const contrast = (a, b) => { const la = luminance(a); const lb = luminance(b); const hi = Math.max(la, lb); const lo = Math.min(la, lb); return (hi + 0.05) / (lo + 0.05); };
    const effectiveBackground = node => {
      const layers = [];
      for (let el = node; el; el = el.parentElement) {
        const bg = parse(getComputedStyle(el).backgroundColor);
        if (bg && bg.a > 0) layers.push(bg);
      }
      let out = { r: 255, g: 255, b: 255, a: 1 };
      for (let i = layers.length - 1; i >= 0; i -= 1) out = blend(layers[i], out);
      return out;
    };
    const root = document.querySelector(${JSON.stringify(scopeSelector)}) ?? document.body;
    const violations = [];
    let checked = 0;
    let minimum = null;
    let minimumText = null;
    for (const node of root.querySelectorAll('*')) {
      if (!node.offsetParent && node.tagName !== 'BODY') continue;
      if (['SCRIPT', 'STYLE', 'NOSCRIPT'].includes(node.tagName)) continue;
      const text = [...node.childNodes].filter(n => n.nodeType === 3).map(n => n.textContent.trim()).join(' ').trim();
      if (!text) continue;
      const style = getComputedStyle(node);
      if (style.visibility === 'hidden' || style.display === 'none') continue;
      const fg = parse(style.color);
      if (!fg || fg.a === 0) continue;
      const bg = effectiveBackground(node);
      const composited = fg.a < 1 ? blend(fg, bg) : fg;
      const value = contrast(composited, bg);
      const size = parseFloat(style.fontSize);
      const bold = Number(style.fontWeight) >= 700;
      const large = size >= 24 || (size >= 18.66 && bold);
      const required = large ? 3 : 4.5;
      checked += 1;
      if (minimum == null || value < minimum) { minimum = value; minimumText = text.slice(0, 50); }
      if (value + 0.01 < required) {
        violations.push({
          text: text.slice(0, 50),
          color: style.color,
          background: 'rgb(' + Math.round(bg.r) + ', ' + Math.round(bg.g) + ', ' + Math.round(bg.b) + ')',
          ratio: Math.round(value * 100) / 100,
          required,
          size
        });
      }
    }
    return { checked, minimum: minimum == null ? null : Math.round(minimum * 100) / 100, minimumText, violations: violations.slice(0, 8) };
  })()`);
  report.contrast[label] = result;
  check(`contrast: ${label} meets WCAG AA (4.5:1 normal, 3:1 large)`, result.violations.length === 0,
    `checked=${result.checked} elements, lowest ratio=${result.minimum} on "${result.minimumText}"${result.violations.length ? ` violations=${JSON.stringify(result.violations)}` : ''}`);
  return result;
}

